INSERT INTO public.post VALUES (1, '2025-11-20 16:58:13.190968', '2025-11-20 16:58:13.190968', 'hoanganh', 'hoanganh', false, 1, 7, 'Bún bò Huế', 'Món bún cay nồng, đặc trưng vị Huế', 'Huế', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQq6UpPrSe9eYszz1gC0GUFxGepOZvX5hKkIw&s', 30, 120, 'MEDIUM', 'Tô bún bò cay nồng chuẩn vị miền Trung');
INSERT INTO public.post VALUES (2, '2025-11-20 16:58:13.190968', '2025-11-20 16:58:13.190968', 'ngocmai', 'ngocmai', false, 2, 5, 'Cơm tấm Sài Gòn', 'Cơm tấm sườn bì chả', 'Hồ Chí Minh', 'https://file.hstatic.net/1000394081/article/com-tam_e03b4325c9914def9d66619930a73432.jpg', 25, 40, 'MEDIUM', 'Sườn nướng, bì, chả trứng thơm ngon');
INSERT INTO public.post VALUES (3, '2025-11-20 16:58:13.190968', '2025-11-20 16:58:13.190968', 'phuonglinh', 'phuonglinh', false, 3, 1, 'Phở bò Hà Nội', 'Món phở truyền thống Việt Nam', 'Hà Nội', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ5ffKuq9DTyRpBOg8ZGP01aszcSZcJ9fQXDw&s', 30, 120, 'MEDIUM', 'Nước dùng trong, thơm mùi quế hồi');
INSERT INTO public.post VALUES (4, '2025-11-20 16:58:13.190968', '2025-11-20 16:58:13.190968', 'quanghuy', 'quanghuy', false, 4, 2, 'Bánh mì trứng ốp la', 'Bánh mì kẹp đặc trưng', 'Hồ Chí Minh', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR_BEyGNxXtr_7w8z-sVo0SushqWzwSvB6xiQ&s', 15, 10, 'EASY', 'Bữa sáng nhanh gọn nhưng đủ chất');
INSERT INTO public.post VALUES (5, '2025-11-20 16:58:13.190968', '2025-11-20 16:58:13.190968', 'lananh', 'lananh', false, 5, 3, 'Gỏi cuốn tôm thịt', 'Cuốn tôm thịt với rau sống', 'Hồ Chí Minh', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT5kk3PGeI2UfstwOYq5tb15E1Bbsn53I6v_Q&s', 20, 0, 'EASY', 'Món ăn nhẹ, thanh mát, ít dầu mỡ');
INSERT INTO public.post VALUES (6, '2025-11-20 16:58:13.190968', '2025-11-20 16:58:13.190968', 'minhtri', 'minhtri', false, 6, 8, 'Chả giò miền Nam', 'Món chiên giòn rụm, nhân thịt băm thơm phức', 'Hồ Chí Minh', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTZt5emkGhgPt-K26Cq2oqT0HC0B4jtCm7xVQ&s', 25, 15, 'MEDIUM', 'Giòn rụm, nhân thịt băm thơm phức');
INSERT INTO public.post VALUES (7, '2025-11-20 16:58:13.190968', '2025-11-20 16:58:13.190968', 'hoangphuc', 'hoangphuc', false, 7, 9, 'Bánh xèo tôm thịt', 'Vỏ vàng giòn, nhân tôm thịt, ăn cùng rau sống', 'Bình Định', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTQ2xosMlmOO05CRIspcYSrhvll2HTwnRYBYw&s', 30, 20, 'MEDIUM', 'Vỏ vàng giòn, ăn cùng rau sống và nước mắm chua ngọt');
INSERT INTO public.post VALUES (8, '2025-11-20 16:58:13.190968', '2025-11-20 16:58:13.190968', 'thanhha', 'thanhha', false, 8, 10, 'Cao lầu Hội An', 'Mì vàng dai, thịt xá xíu đậm vị', 'Quảng Nam', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQNsIEhWInFKJj4j9XcMgtvL9LNYCWv_kIkLQ&s', 25, 35, 'MEDIUM', 'Mì vàng dai, thịt xá xíu đậm vị');
INSERT INTO public.post VALUES (9, '2025-11-20 16:58:13.190968', '2025-11-20 16:58:13.190968', 'kimthao', 'kimthao', false, 9, 11, 'Bánh cuốn Thanh Trì', 'Món bánh mềm mịn, nhân thịt mộc nhĩ', 'Hà Nội', 'https://static.vinwonders.com/production/banh-cuon-thanh-tri-banner.jpeg', 20, 20, 'MEDIUM', 'Bột gạo mỏng mịn, nhân thịt mộc nhĩ');
INSERT INTO public.post VALUES (10, '2025-11-20 16:58:13.190968', '2025-11-20 16:58:13.190968', 'tuananh', 'tuananh', false, 10, 12, 'Xôi xéo Hà Nội', 'Xôi nếp vàng ươm, thơm hành phi', 'Hà Nội', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTLXHCgHafFLTjysi9B5c1qDkgbYs_ef_qGvw&s', 15, 30, 'EASY', 'Xôi nếp vàng ươm, thơm hành phi');
INSERT INTO public.post VALUES (11, '2025-11-20 17:09:49.352548', '2025-11-20 17:09:49.352548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 24, 'Cách làm gà nổ muối hột', 'Với nguyên liệu và cách làm đơn giản, gà nổ muối hột da vàng ươm, thịt mọng nước, dậy hương thơm từ sả, gừng, lá chanh giúp thực đơn ngày Tết thêm phong phú.', 'Tây Ninh', 'https://i1-giadinh.vnecdn.net/2024/01/13/Thnhphm11-1705134733-9574-1705134870.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=DsuAhX98ciTXjrAdVfxtdw', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm gà nổ muối hột');
INSERT INTO public.post VALUES (18, '2025-11-20 17:09:49.352548', '2025-11-20 17:09:49.352548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 13, 'Cách gói giò mỡ - đặc sản Tết Thái Bình', 'Giò nây còn có tên gọi khác như giò mỡ, giò thúc là món ngon truyền thống dùng tiếp đãi khách quý vào dịp lễ Tết của người dân Thái Bình.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2024/02/02/Thnhphm11-1706868665-1900-1706868699.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=UPrU5yjoj6UhiIIo0TcGJQ', 240, 240, 'EASY', 'Cùng thử nấu Cách gói giò mỡ - đặc sản Tết Thái Bình');
INSERT INTO public.post VALUES (14, '2025-11-20 17:09:49.352548', '2025-11-20 17:09:49.352548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 22, 'Cách làm canh bóng thả Hà Nội nấu theo lối xưa', 'Bát canh bóng hài hòa sắc vị và hương với bóng bì mềm, nước dùng ngọt thanh, rau củ quả giòn, màu sắc tươi mới như bức tranh mùa xuân. Đây là một trong bốn món chính của cỗ Tết của người Hà Nội xưa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2024/01/21/Bc7Thnhphm7-1705824640-3331-1705824650.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=dnqx00iOdK4_Sa8SXUFfZA', 42, 43, 'MEDIUM', 'Cùng thử nấu Cách làm canh bóng thả Hà Nội nấu theo lối xưa');
INSERT INTO public.post VALUES (15, '2025-11-20 17:09:49.352548', '2025-11-20 17:09:49.352548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 26, 'Cách làm mực nấu rối - món ngon Tết xưa Hà Nội', 'Bát mực nấu rối đẹp như bông hoa ngũ sắc với mực nâu đỏ, trứng gà vàng ươm, su hào xanh giòn, cà rốt cam đỏ, giò lụa trắng thơm. Đây là món đặc trưng trong mâm cỗ chiều 30 Tết xưa của người Hà Nội.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2024/01/15/Bc7Thnhphm17-1705307692-6560-1705307895.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VkXNYt-Gz_bzIUsH8HEC6Q', 35, 35, 'MEDIUM', 'Cùng thử nấu Cách làm mực nấu rối - món ngon Tết xưa Hà Nội');
INSERT INTO public.post VALUES (12, '2025-11-20 17:09:49.352548', '2025-11-20 17:09:49.352548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 16, 'Cách làm thịt kho hột vịt truyền thống miền Tây', 'Đây là món ăn không thể thiếu trong cỗ Tết của người dân Nam Bộ và miền Tây. Thịt vuông kết hợp trứng tròn biểu tượng cho âm dương hài hòa, năm mới đủ đầy sung túc.', 'Tiền Giang', 'https://i1-giadinh.vnecdn.net/2024/02/01/Thnhphm11-1706758994-8941-1706759016.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=QAjtX7h1vAUTQAqB3Dpw7g', 50, 50, 'MEDIUM', 'Cùng thử nấu Cách làm thịt kho hột vịt truyền thống miền Tây');
INSERT INTO public.post VALUES (16, '2025-11-20 17:09:49.352548', '2025-11-20 17:09:49.352548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 19, 'Cách làm miến xào lòng mề gà', 'Miến dai mềm quyện với lòng gà sần sật, rau củ quả tươi giòn giúp đổi vị ngày Tết. Một vài mẹo dưới đây giúp món miến tơi sợi, thấm vị, không bị dính chùm hay vón cục.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2024/01/30/Thnhphm11-1706599845-3557-1706599882.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=whaIEit7TrarmweSPNNCaw', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm miến xào lòng mề gà');
INSERT INTO public.post VALUES (17, '2025-11-20 17:09:49.352548', '2025-11-20 17:09:49.352548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 23, 'Cách làm giò xào truyền thống kiểu Bắc', 'Giò xào trắng giòn sần sật từ tai, ngậy từ má, hồng nhạt từ thịt chân giò, đen óng từ mộc nhĩ, lấm tấm hạt tiêu the cay. Đây là món ngon thường thấy trong cỗ Tết cổ truyền miền Bắc.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2024/01/18/Thnhphm11-1705554357-5916-1705554715.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=UgONGCoKsMajOsx9dQyLqg', 37, 38, 'MEDIUM', 'Cùng thử nấu Cách làm giò xào truyền thống kiểu Bắc');
INSERT INTO public.post VALUES (13, '2025-11-20 17:09:49.352548', '2025-11-20 17:09:49.352548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 15, 'Cách làm chạo chân giò - món ngon Tết vùng Hà Nam Ninh', 'Đây là món ngon nổi tiếng giúp giải ngấy ngày Tết của vùng Hà Nam, Nam Định, Ninh Bình. Đĩa chạo chân giò cuốn hút bởi bì giòn thơm, thịt ngọt mềm, khế chua, thơm mùi riềng sả.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2024/02/07/Thnhphm11-1707282133-8561-1707282262.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9PKX7L-S88Hu0ns1SsxPkQ', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm chạo chân giò - món ngon Tết vùng Hà Nam Ninh');
INSERT INTO public.post VALUES (28, '2025-11-20 17:09:49.688429', '2025-11-20 17:09:49.688429', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 35, 'Cách làm bò cuốn cải xanh giải ngán ngày Tết', 'Thịt bò ngọt mềm kết hợp với vị cải xanh the cay, rau củ quả giòn, chấm với sốt mù tạt thơm thơm hăng hăng kích thích vị giác. Đây là món ngon được nhiều người yêu thích giúp giải ngán ngày Tết.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2023/01/17/Bc4Thnhphm14-1673942002-6084-1673942066.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=w6xYGQ1maMWcBi5kksMC5g', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm bò cuốn cải xanh giải ngán ngày Tết');
INSERT INTO public.post VALUES (38, '2025-11-20 17:09:49.766802', '2025-11-20 17:09:49.766802', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 42, 'Cách làm dưa món giòn ngon đón Tết', 'Không cần phơi nắng nhưng dưa góp (dưa món) vẫn giòn ngon, đậm vị mặn ngọt, để cả năm vẫn được. Đây là món ăn truyền thống ở miền Trung, miền Nam vào ngày Tết cùng bánh chưng, bánh tét giúp cân bằng vị.', 'Bình Định', 'https://i1-giadinh.vnecdn.net/2023/01/09/Bc6Thnhphm6-1673249183-8344-1673249223.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=8VuXRGnxr5zLfug6RLnyKA', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm dưa món giòn ngon đón Tết');
INSERT INTO public.post VALUES (45, '2025-11-20 17:09:49.83787', '2025-11-20 17:09:49.83787', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 48, 'Thịt ngâm mắm - món ngon miền Trung', 'Thịt đậm đà, hài hòa vị mặn ngọt, phần da giòn, càng thêm trọn vị khi ăn cùng bánh Tét hoặc cuốn các loại rau sống.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2022/02/05/Thnhphm3-1644044790-4263-1644044913.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=egw0ymfOyOpcZI7pjC6A1Q', 20, 20, 'MEDIUM', 'Cùng thử nấu Thịt ngâm mắm - món ngon miền Trung');
INSERT INTO public.post VALUES (64, '2025-11-20 17:09:51.013564', '2025-11-20 17:09:51.013564', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 66, 'Thịt kho tàu kiểu Bắc – món ngon Tết đến', 'Nếu như thịt kho tàu miền Nam nhiều nước, vị lạt, thịt mềm rục thì thịt kho tàu miền Bắc là nước sóng sánh màu hổ phách, vị đậm đà. Đây là món ăn quen thuộc trong mâm cơm ngày Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/22/Thnhphm3-1642851399-6760-1642851512.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=wcEa6ktevM7Dh0Sh7cSfZg', 30, 30, 'EASY', 'Cùng thử nấu Thịt kho tàu kiểu Bắc – món ngon Tết đến');
INSERT INTO public.post VALUES (22, '2025-11-20 17:09:49.658814', '2025-11-20 17:09:49.658814', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 18, 'Cách làm chả cá chép bách hoa', 'Một món ăn đang gây chú ý trên mạng xã hội là gợi ý cho mâm cỗ cúng ông Táo với hình ảnh cá chép ngậm trăng đẹp mắt bởi lớp da vàng ươm kết hợp trứng muối bùi thơm, rau củ tươi mát, mộc nhĩ sần sật.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2024/01/31/Bc6Thnhphm6-1706686724-3872-1706686728.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=RgzsyNdPFU194t-gPTqrTQ', 42, 43, 'MEDIUM', 'Cùng thử nấu Cách làm chả cá chép bách hoa');
INSERT INTO public.post VALUES (30, '2025-11-20 17:09:49.695507', '2025-11-20 17:09:49.695507', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 33, 'Cách làm hạnh nhân xào - vị Tết Hà Nội xưa', 'Tận dụng ''đầu thừa'' rau củ quả phụ nữ Hà Nội xưa đã biến tấu thành món ăn đa dạng sắc màu, thanh mát, giòn ngon giúp cân bằng vị trong mâm cỗ Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2023/01/21/Thnhphm11-1674286263-5165-1674286404.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=i1nw6cTE_RaukTHBKJC63Q', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm hạnh nhân xào - vị Tết Hà Nội xưa');
INSERT INTO public.post VALUES (32, '2025-11-20 17:09:49.731904', '2025-11-20 17:09:49.731904', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 31, 'Cách làm bê hấp gừng sả giải ngán ngày Tết', 'Thịt bê mềm ngọt, mọng nước, dậy mùi thơm của gừng sả. Khi ăn cuốn cùng rau củ quả tươi giòn, chấm tương bần rất tròn vị. Đây là món ăn giúp giải ngán ngày Tết.', 'Thanh Hóa', 'https://i1-giadinh.vnecdn.net/2023/01/23/Bc4Thnhphm4-1674481963-2704-1674482016.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=imPf79VUJWx7pYNoTKUzXA', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm bê hấp gừng sả giải ngán ngày Tết');
INSERT INTO public.post VALUES (39, '2025-11-20 17:09:49.785748', '2025-11-20 17:09:49.785748', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 41, 'Cách làm cánh gà chiên bơ tỏi giòn ngon đổi vị ngày Tết', 'Cánh gà giòn rôm rốp, bên trong thịt ngọt mềm, dậy mùi thơm bơ tỏi. Khi ăn chấm cùng tương ớt, tương cà. Món ăn này có trong thực đơn nhiều nhà hàng là gợi ý cho thực đơn ngày Tết thêm phong phú.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2023/01/08/Thnhphm11-1673168612-1894-1673168628.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=YX-LibhNfDTctb9zEe8HCg', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm cánh gà chiên bơ tỏi giòn ngon đổi vị ngày Tết');
INSERT INTO public.post VALUES (42, '2025-11-20 17:09:49.809657', '2025-11-20 17:09:49.809657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 43, 'Su hào xào mực - đặc sản Bát Tràng', 'Su hào khô ráo, ngọt tự nhiên quyện với mực giòn sần sật rất hấp dẫn. Đây là món ăn không thể thiếu trong ngày Tết, hiếu hỉ của người dân làng gốm.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/02/05/Thnhphm1-1644045502-7032-1644045625.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ROeZGLZGNns_vCKM7LgQ7g', 25, 25, 'MEDIUM', 'Cùng thử nấu Su hào xào mực - đặc sản Bát Tràng');
INSERT INTO public.post VALUES (49, '2025-11-20 17:09:49.863382', '2025-11-20 17:09:49.863382', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 52, 'Cá trắm đen kho riềng - món ngon Tết xưa Hà Nội', 'Cá trắm đen kho riềng ăn cùng bánh chưng xanh là nét đặc trưng trong mâm cỗ Tết truyền thống của người Hà Nội xưa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/27/Thnhphm2-1643217689-9711-1643217855.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ZtGiP-MxDcarU82UgGFAOQ', 120, 120, 'MEDIUM', 'Cùng thử nấu Cá trắm đen kho riềng - món ngon Tết xưa Hà Nội');
INSERT INTO public.post VALUES (51, '2025-11-20 17:09:49.914768', '2025-11-20 17:09:49.914768', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 51, 'Nộm đu đủ - món ngon giải ngán ngày Tết', 'Nộm đu đủ giòn ngon, thanh mát giúp cân bằng trong những mâm cỗ đầy thịt mỡ, bánh chưng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/28/Bc6-1643368615-3349-1643368724.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ERy35lgae4yP2XeLLM4a7g', 17, 18, 'EASY', 'Cùng thử nấu Nộm đu đủ - món ngon giải ngán ngày Tết');
INSERT INTO public.post VALUES (58, '2025-11-20 17:09:50.426055', '2025-11-20 17:09:50.426055', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 57, 'Bí quyết nấu canh khổ qua thơm ngon ngày Tết', 'Khổ qua mềm ngon vẫn giữ màu xanh, thịt và cá thác lác dẻo dai, dính vào trái, nước canh hài hòa vị ngọt, đắng rất hấp dẫn.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2022/01/27/Thnhphm1-1643216783-2842-1643216934.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=bFMjM4LdtS5RimFVfkuD3g', 20, 20, 'MEDIUM', 'Cùng thử nấu Bí quyết nấu canh khổ qua thơm ngon ngày Tết');
INSERT INTO public.post VALUES (59, '2025-11-20 17:09:50.469704', '2025-11-20 17:09:50.469704', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 61, 'Kẹo mít dẻo lạ cho ngày Tết', 'Hương mít dẻo khô không đậm mùi như lúc tươi mà thơm bùi, vị dẻo dai, ngọt tự nhiên, chắc chắn sẽ là một món kẹo tuyệt vời cho gia đình bạn.', 'Tiền Giang', 'https://i1-giadinh.vnecdn.net/2022/01/19/a9-1642570046-4267-1642570049.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5QalIZnBkxnFi3zs4iUvDQ', 22, 23, 'EASY', 'Cùng thử nấu Kẹo mít dẻo lạ cho ngày Tết');
INSERT INTO public.post VALUES (73, '2025-11-20 17:09:52.215607', '2025-11-20 17:09:52.215607', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 75, 'Cách làm gà khô lá chanh', 'Gà khô lá chanh tự làm vừa ngon vừa an toàn cho sức khỏe. Trong dịp Tết, đây sẽ là món sang để khách lẫn chủ lai rai trong lúc trò chuyện.', 'Tây Ninh', 'https://i1-giadinh.vnecdn.net/2022/01/06/1-1641444615-1641444628-9461-1641444647.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=TP3wGPnrZMWmi4LU5V2XZg', 90, 90, 'HARD', 'Cùng thử nấu Cách làm gà khô lá chanh');
INSERT INTO public.post VALUES (74, '2025-11-20 17:09:52.341349', '2025-11-20 17:09:52.341349', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 76, 'Cách làm bánh quy bơ Vanillekipferl đơn giản cho Giáng sinh', 'Vanillekipferl là bánh quy truyền thống của Đức. Với hình vầng trăng khuyết xinh xắn, giòn xốp, khi ăn như tan chảy trong miệng, dậy mùi thơm của bơ và vani mang tới sự ấm cúng dịp Giáng sinh.', 'Đà Lạt', 'https://i1-giadinh.vnecdn.net/2021/12/24/Thnhphm2-1640335659-2364-1640335822.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=XQ4O75fjixEUB6Ye266FMw', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm bánh quy bơ Vanillekipferl đơn giản cho Giáng sinh');
INSERT INTO public.post VALUES (83, '2025-11-20 17:09:53.353239', '2025-11-20 17:09:53.353239', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 85, 'Cách làm heo khô xé sợi', 'Heo khô xé sợi tự làm vừa sạch, vừa bắt mắt lại cay cay, ngọt dịu, thích hợp cho gia đình thưởng thức những ngày cuối đông, đầu xuân.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/01/09/1-1641706137-2567-1641706185.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=TsRWVCXXnzj6Z9O-UwtSIQ', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm heo khô xé sợi');
INSERT INTO public.post VALUES (98, '2025-11-20 17:09:56.157832', '2025-11-20 17:09:56.157832', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 100, 'Ốc bươu nướng tiêu xanh cho mùa World Cup 2022', 'Thịt ốc giòn dai quyện với vị the cay từ hạt tiêu xanh cùng vị mặn ngọt chua hài hòa, kích thích vị giác, làm không khí xem World Cup 2022 thêm sôi động.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/11/22/Thnhphm11-1669103865-6008-1669103895.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EeFWfmEsh0ZQKzHG_CRq8w', 15, 15, 'MEDIUM', 'Cùng thử nấu Ốc bươu nướng tiêu xanh cho mùa World Cup 2022');
INSERT INTO public.post VALUES (23, '2025-11-20 17:09:49.660517', '2025-11-20 17:09:49.660517', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 21, 'Cách làm miến nấu lòng mề gà kiểu Bắc Bộ', 'Miến chín tới mềm mà vẫn dai, lòng mề gà vừa vị, mộc nhĩ giòn sần sật, trứng non bùi bùi... nước dùng ngọt thanh. Một món ăn đơn giản lại dễ chiều vị giác vào dịp Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2024/01/20/Bc7Thnhphm17-1705735663-4864-1705735833.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=YMnOlFP7wYtPeuxNienfhA', 37, 38, 'MEDIUM', 'Cùng thử nấu Cách làm miến nấu lòng mề gà kiểu Bắc Bộ');
INSERT INTO public.post VALUES (35, '2025-11-20 17:09:49.753781', '2025-11-20 17:09:49.753781', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 28, 'Cách làm miến xào thập cẩm ngon mà dễ làm', 'Tận dụng các nguyên liệu còn dư sau Tết, món miến xào mềm dai, rau củ quả giòn được nhiều người yêu thích, lại giàu giá trị dinh dưỡng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2023/01/30/Thnhphm11-1675072983-8295-1675072986.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eMdqmsjcsZwKr_oxa-qf3A', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm miến xào thập cẩm ngon mà dễ làm');
INSERT INTO public.post VALUES (47, '2025-11-20 17:09:49.855161', '2025-11-20 17:09:49.855161', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 50, 'Nộm gà hoa chuối giòn ngon đổi vị ngày Tết', 'Món ăn dân dã này vừa tận dụng thịt gà luộc còn dư, vừa giúp giải ngấy và kích thích vị giác trong mâm cỗ ngày Tết.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/01/28/Thnhphm1-1643369217-7690-1643369320.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=HXtKrEG8Vg7uSANtqSZ6Cw', 20, 20, 'MEDIUM', 'Cùng thử nấu Nộm gà hoa chuối giòn ngon đổi vị ngày Tết');
INSERT INTO public.post VALUES (54, '2025-11-20 17:09:50.041948', '2025-11-20 17:09:50.041948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 56, 'Thịt kho tàu - món ăn đặc trưng Tết Nam Bộ', 'Từng miếng thịt mềm, màu nâu đỏ đẹp mắt, bì trong, nước sóng sánh, điểm xuyết hột vịt luộc ngấm hết tinh túy ngọt thơm từ nước kho rất hấp dẫn.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2022/01/27/Thnhphm1-1643219204-8402-1643219331.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gR9VzbDHwuWZKhAOI5ggZQ', 15, 15, 'MEDIUM', 'Cùng thử nấu Thịt kho tàu - món ăn đặc trưng Tết Nam Bộ');
INSERT INTO public.post VALUES (68, '2025-11-20 17:09:51.452852', '2025-11-20 17:09:51.452852', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 70, 'Cách làm mứt gừng đơn giản, thơm ngon đón Tết', 'Mứt màu vàng đẹp, phủ đều lớp đường trắng kết tinh, khô. Khi ăn, gừng cay nhẹ, thơm ngọt dễ ăn. Ăn mứt gừng nhâm nhi cùng ly trà khiến cho ngày Tết thêm ấm cúng.', 'Huế', 'https://i1-giadinh.vnecdn.net/2022/01/16/Thnhphm3-1642304507-8596-1642304577.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=WjlgjfS4aUHKUEba8tlNYw', 50, 50, 'EASY', 'Cùng thử nấu Cách làm mứt gừng đơn giản, thơm ngon đón Tết');
INSERT INTO public.post VALUES (76, '2025-11-20 17:09:52.577583', '2025-11-20 17:09:52.577583', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 78, 'Bánh thuyền hạt cho mùa Giáng sinh, Năm mới 2022', 'Từng chiếc bánh xinh xắn như cái thuyền nhỏ, chở đầy các loại hạt giòn tan, vị ngọt bùi béo, dậy mùi thơm của bơ. Dự kiến đây là món bánh hot trend mùa lễ hội 2022.', 'Đà Lạt', 'https://i1-giadinh.vnecdn.net/2021/12/21/Thnhphm2-1640078033-3923-1640078150.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ddZH-fQZ2L8rcaZFEF1Q_w', 17, 18, 'MEDIUM', 'Cùng thử nấu Bánh thuyền hạt cho mùa Giáng sinh, Năm mới 2022');
INSERT INTO public.post VALUES (85, '2025-11-20 17:09:53.735659', '2025-11-20 17:09:53.735659', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 87, 'Cách nấu xôi mặn thập cẩm dẻo rền', 'Xôi căng bóng, dẻo thơm gói vào lá chuối làm cho mọi thứ quyện lại: chút béo béo từ mỡ hành, mằn mặn từ xì dầu, ngọt nhẹ từ lạp xưởng, beo béo từ pate làm nên mỹ vị khó quên.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2023/02/22/Thnhphm21-1677040841-3005-1677040910.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ySrvwoIyX8YA9NW1t4dEqA', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách nấu xôi mặn thập cẩm dẻo rền');
INSERT INTO public.post VALUES (91, '2025-11-20 17:09:54.375795', '2025-11-20 17:09:54.375795', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 93, 'Cách làm trứng vịt lộn nướng muối ớt', 'Trứng vịt lộn mềm ngọt, vị chua cay mặn hài hòa, quyện với mỡ hành béo thơm, đậu phộng bùi bùi, rau răm dậy mùi thơm. Đây là món ăn vặt nổi tiếng ở Sài Gòn, được nhiều bạn trẻ yêu thích.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/12/13/Thnhphm11-1670916659-2801-1670916768.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=fL_F9a3Ofoe1dfvsuYfZgA', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm trứng vịt lộn nướng muối ớt');
INSERT INTO public.post VALUES (100, '2025-11-20 17:09:56.736483', '2025-11-20 17:09:56.736483', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 102, 'Cách làm lươn xào sả ớt thơm ngon, đậm đà', 'Món ăn hấp dẫn bởi sắc, hương và vị với thịt lươn săn đậm đà, dậy mùi thơm của sả, chút the cay từ ớt, lá lốt, hành hoa.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2022/11/16/Thnhphm11-1668588253-7708-1668588270.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=jqeQoxhhEgsurgzDjxcU3w', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm lươn xào sả ớt thơm ngon, đậm đà');
INSERT INTO public.post VALUES (103, '2025-11-20 17:09:57.464819', '2025-11-20 17:09:57.464819', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 105, 'Cách nấu canh cải cúc thịt băm đơn giản ngon miệng', 'Bát canh nóng hổi, rau cải cúc chín tới vừa giòn vừa mềm xanh, nước canh ngọt, thịt mềm, thoảng mùi cải cúc đặc trưng. Đây là món canh phổ biến vào mùa đông được nhiều người yêu thích.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/11/11/Thnhphm11-1668164720-5769-1668164747.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qbk_jMmu_JvPTsz0gX3BRg', 7, 8, 'EASY', 'Cùng thử nấu Cách nấu canh cải cúc thịt băm đơn giản ngon miệng');
INSERT INTO public.post VALUES (106, '2025-11-20 17:09:58.2011', '2025-11-20 17:09:58.2011', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 108, 'Cách làm thịt dải lợn nướng', 'Thịt chín vàng đều các mặt, hài hòa vị mặn ngọt, không bị khô, dậy mùi thơm của hạt tiêu, hạt dổi, mắc khén. Món này nhâm nhi hay ăn chơi đều ngon.', 'Lạng Sơn', 'https://i1-giadinh.vnecdn.net/2022/11/05/Bc4Thnhphm4-1667643428-8654-1667643487.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Hw2fTIqQ35Pej9SVdNAQuQ', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm thịt dải lợn nướng');
INSERT INTO public.post VALUES (113, '2025-11-20 17:09:59.533969', '2025-11-20 17:09:59.533969', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 115, 'Cách làm cá rô đồng kho khế - món ngon đồng quê', 'Thịt cá săn chắc, đậm vị chua mặn ngọt cay. Nước kho màu nâu vàng, chấm cùng rau muống luộc mùa mưa thì sơn hào hải vị cũng chẳng bằng.', 'Hà Nam', 'https://i1-giadinh.vnecdn.net/2022/10/20/-2305-1666252648.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ajpp6h5zHk3RysOQPW7LLw', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm cá rô đồng kho khế - món ngon đồng quê');
INSERT INTO public.post VALUES (115, '2025-11-20 17:09:59.860175', '2025-11-20 17:09:59.860175', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 117, 'Cách làm canh củ sắn nấu cá quả - món cổ của người Hà Nội', 'Nước canh ngọt thanh, cá giữ nguyên miếng trắng ngần, sắn dẻo bùi, dậy mùi thơm của thì là. Đây là món ăn của người Hà Nội xưa vào mùa thu đông.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/10/17/-8783-1665998716.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9SdKu5Eo9C6YbBqIT96aSg', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm canh củ sắn nấu cá quả - món cổ của người Hà Nội');
INSERT INTO public.post VALUES (19, '2025-11-20 17:09:49.352548', '2025-11-20 17:09:49.352548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 17, 'Cách làm bóng bì xào thập cẩm kiểu Bắc', 'Bóng bì mềm thấm đều vị, thịt thăn và tôm ngọt mềm, rau củ quả tươi giòn. Đây là món ngon trong cỗ Tết miền Bắc truyền thống.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2024/01/26/Thnhphm22-1706261480-3948-1706261484.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Zk8f_oeEomYqyvH4p5RYPg', 32, 33, 'MEDIUM', 'Cùng thử nấu Cách làm bóng bì xào thập cẩm kiểu Bắc');
INSERT INTO public.post VALUES (24, '2025-11-20 17:09:49.660517', '2025-11-20 17:09:49.660517', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 20, 'Cách làm món khâu nhục Lạng Sơn', 'Bát khâu nhục nóng hổi, tỏa hương thơm ngào ngạt. Khi ăn, thịt tan mềm trong miệng, quyện nhiều vị ngọt mềm bùi béo hấp dẫn. Đây là món đặc sản của người dân Lạng Sơn vào dịp Tết.', 'Lạng Sơn', 'https://i1-giadinh.vnecdn.net/2024/01/19/Bc9Thnhphm19-1705650163-7592-1705650639.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=prfrsdJAXBqOzeYDds-UZQ', 210, 210, 'MEDIUM', 'Cùng thử nấu Cách làm món khâu nhục Lạng Sơn');
INSERT INTO public.post VALUES (34, '2025-11-20 17:09:49.74924', '2025-11-20 17:09:49.74924', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 29, 'Cách làm gỏi cuốn thập cẩm phiên bản ''vét tủ lạnh''', 'Tận dụng thực phẩm dư thừa từ Tết, món gỏi cuốn thập cẩm nhiều màu sắc, tươi mát hấp dẫn nhiều sắc màu và giúp giản ngán hiệu quả.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2023/01/29/Thnhphm11-1674959897-6692-1674959915.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=7A_URKgV-1Ky6apV-6g5PQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm gỏi cuốn thập cẩm phiên bản ''vét tủ lạnh''');
INSERT INTO public.post VALUES (46, '2025-11-20 17:09:49.843261', '2025-11-20 17:09:49.843261', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 46, 'Cách làm chân gà sả tắc giòn ngon cho dịp Tết', 'Bài viết gợi ý cách làm chân gà sả tắc không đắng, không nhớt, lại giòn ngon để thực đơn nhâm nhi ngày Tết thêm phong phú.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/12/30/Thnhphm-1640855312-9575-1640855439.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9mkWLSApY0LSAIfKUVHPxA', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm chân gà sả tắc giòn ngon cho dịp Tết');
INSERT INTO public.post VALUES (57, '2025-11-20 17:09:50.421771', '2025-11-20 17:09:50.421771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 59, 'Cách làm mứt quả cóc dẻo thơm, lạ miệng đón Tết', 'Mứt cóc dẻo, ráo nước, hạt teo lại, vị chua ngọt hài hòa, thoảng mùi thơm của dứa rất hấp dẫn. Một món ngon đãi khách ngày Tết.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2022/01/14/Thnhphm11-1642154712-4155-1642154790.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eJ2rK_hhnW9-8hZKiBboog', 60, 60, 'EASY', 'Cùng thử nấu Cách làm mứt quả cóc dẻo thơm, lạ miệng đón Tết');
INSERT INTO public.post VALUES (70, '2025-11-20 17:09:51.729421', '2025-11-20 17:09:51.729421', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 72, 'Bắp bò ngâm xì dầu', 'Bắp bò ngâm xì dầu là món ăn vừa ngon miệng, đẹp mắt, rất xứng đặt trong mâm cỗ ngày Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/16/untitled1-1642302331-164230234-2907-6564-1642302507.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=afkffCQ5b6UjrEQ5P8fkRA', 90, 90, 'MEDIUM', 'Cùng thử nấu Bắp bò ngâm xì dầu');
INSERT INTO public.post VALUES (25, '2025-11-20 17:09:49.664434', '2025-11-20 17:09:49.664434', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 14, 'Cách làm nem rán kiểu truyền thống miền Bắc', 'Từng chiếc nem rán bên ngoài vàng ruộm, giòn tan mà nhân bên trong vẫn giữ vị mềm ngọt từ thịt, tươi giòn từ rau củ. Đây là món ăn truyền thống trong dịp Tết cổ truyền của dân tộc.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2024/02/06/Thnhphm11-1707205042-9085-1707205070.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=7_c7b2Wy59UL8TKPiNXdRA', 32, 33, 'HARD', 'Cùng thử nấu Cách làm nem rán kiểu truyền thống miền Bắc');
INSERT INTO public.post VALUES (33, '2025-11-20 17:09:49.748226', '2025-11-20 17:09:49.748226', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 32, 'Cách làm gà bóp hành răm kiểu miền Trung', 'Tận dụng gà luộc dư, thêm chút nguyên liệu sẵn có, món gà bóp hành đưa miệng, giải ngán hiệu quả. Đây là món ăn truyền thống vào dịp lễ Tết của người dân miền Trung.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2023/01/28/Thnhphm11-1674881647-1380-1674881658.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=FAowPdZLITHGzjFD3CGJ3Q', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm gà bóp hành răm kiểu miền Trung');
INSERT INTO public.post VALUES (43, '2025-11-20 17:09:49.831229', '2025-11-20 17:09:49.831229', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 44, 'Cách làm heo khô cháy tỏi - món nhâm nhi ngày Tết', 'Thịt heo dẻo dai, đậm vị và hơi the cay kết hợp cùng tỏi phi giòn rụm rất hấp dẫn. Món này được nhiều người yêu thích khi nhâm nhi cùng bạn bè, người thân vào dịp Tết.', 'Quảng Ngãi', 'https://i1-giadinh.vnecdn.net/2023/01/04/Thnhphm11-1672842113-6421-1672842232.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=py0HDRrYSTgu5NbKfLWTyg', 70, 70, 'MEDIUM', 'Cùng thử nấu Cách làm heo khô cháy tỏi - món nhâm nhi ngày Tết');
INSERT INTO public.post VALUES (53, '2025-11-20 17:09:49.977276', '2025-11-20 17:09:49.977276', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 55, 'Cách làm nem hải sản giòn rụm cho ngày Tết', 'Từng chiến nem vàng ruộm, giòn tan, nhân tôm ngọt mềm, mực sần sật, sốt béo ngậy. Đây là món nem có góp mặt nhiều trong mâm cỗ dịp lễ Tết.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2023/01/07/Thnhphm22-1673075836-1497-1673075878.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Gi4yKxKzjqkJm4AGqqadYA', 40, 40, 'MEDIUM', 'Cùng thử nấu Cách làm nem hải sản giòn rụm cho ngày Tết');
INSERT INTO public.post VALUES (67, '2025-11-20 17:09:51.336222', '2025-11-20 17:09:51.336222', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 69, 'Cách làm thịt ba chỉ một nắng', 'Thịt một nắng chiên rán, xào cần tây là món ngon khó cưỡng cho bữa cơm hàng ngày lẫn bữa tiệc đầu xuân.', 'Gia Lai', 'https://i1-giadinh.vnecdn.net/2022/01/22/ScreenShot20220122at21524AM-16-9122-7023-1642792573.png?w=0&h=0&q=100&dpr=2&fit=crop&s=MkWAn_h37Kda5oyXsTjq4Q', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm thịt ba chỉ một nắng');
INSERT INTO public.post VALUES (77, '2025-11-20 17:09:52.650791', '2025-11-20 17:09:52.650791', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 79, 'Cách làm khô gà lá chanh nhâm nhi ngày Tết', 'Thịt gà dẻo dai, gà đậm vị, dậy mùi thơm của lá chanh, ngũ vị hương rất hấp dẫn. Đây là món ăn nhâm nhi thú vị cho ngày Tết.', 'Tây Ninh', 'https://i1-giadinh.vnecdn.net/2022/01/14/Thnhphm11-1642155456-5396-1642155637.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=yej35DkqlASWCzDTQ-NyiQ', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm khô gà lá chanh nhâm nhi ngày Tết');
INSERT INTO public.post VALUES (86, '2025-11-20 17:09:53.832804', '2025-11-20 17:09:53.832804', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 88, 'Cách làm lợn quay kho dưa cải chua', 'Thịt lợn quay chín mềm còn nguyên miếng, dưa cải chua thấm vị béo ngọt. Nước kho đượm vị mặn ngọt chua cay kích thích vị giác. Đây là món ăn phổ biến được yêu thích ở miền Nam.', 'Vĩnh Long', 'https://i1-giadinh.vnecdn.net/2023/02/16/Thnhphm1-1676535308-7955-1676535334.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=2n-sWmRLHroHLS-9BPGa5g', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm lợn quay kho dưa cải chua');
INSERT INTO public.post VALUES (90, '2025-11-20 17:09:54.222875', '2025-11-20 17:09:54.222875', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 92, 'Cách làm mực chiên nước mắm giòn dai, đậm vị', 'Thịt mực dai mềm, đậm vị mặn ngọt cay. Món này ăn chơi, lai rai cùng bạn bè xem bóng đá hoặc ăn với cơm trắng đều ngon.', 'Phan Thiết', 'https://i1-giadinh.vnecdn.net/2022/12/11/Thnhphm11-1670752681-8889-1670752738.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=y6a4oUABDlesdIAIh8vVxw', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm mực chiên nước mắm giòn dai, đậm vị');
INSERT INTO public.post VALUES (92, '2025-11-20 17:09:54.521819', '2025-11-20 17:09:54.521819', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 94, 'Cách làm bò kho gừng kiểu Bắc ấm bụng ngày rét', 'Thịt bò nguyên miếng săn lại, khi ăn cảm nhận được vị mềm, đậm đà, dậy mùi thơm của gừng, nước sóng sánh, rất hợp tiết trời mùa đông.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/12/21/Thnhphm11-1671605513-5197-1671605586.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=oNySo1mpy3E5vDf7BxIIBw', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách làm bò kho gừng kiểu Bắc ấm bụng ngày rét');
INSERT INTO public.post VALUES (101, '2025-11-20 17:09:56.982394', '2025-11-20 17:09:56.982394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 103, 'Cách làm cá bống kho tương hao cơm ngày lạnh', 'Thịt cá săn đậm vị, thơm mùi tương bần đặc trưng. Nước kho sánh màu nâu đỏ, chấm cùng rau luộc, trở thành món ăn bình dân nhưng không thể quên với nhiều thế hệ.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2022/11/15/Thnhphm11-1668508822-8365-1668508912.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EFxQDNF9bJ9R5KB4qwv_HQ', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm cá bống kho tương hao cơm ngày lạnh');
INSERT INTO public.post VALUES (105, '2025-11-20 17:09:57.939948', '2025-11-20 17:09:57.939948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 107, 'Cách làm tép đồng rang ba chỉ', 'Với nguyên liệu và cách làm đơn giản, món tép đồng rang giòn ngon quyện với thịt ba chỉ béo ngậy giúp thực đơn cơm chiều thêm phong phú.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2022/11/09/Thnhphm11-1667979478-7518-1667979488.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VCsvHpg-3r4nK__PpdH1Rw', 15, 15, 'EASY', 'Cùng thử nấu Cách làm tép đồng rang ba chỉ');
INSERT INTO public.post VALUES (107, '2025-11-20 17:09:58.403282', '2025-11-20 17:09:58.403282', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 109, 'Cách nấu canh cá rau cần chuẩn vị Bắc', 'Một bát canh nóng hổi, thịt cá ngọt, rau cần chín tái giòn ngon, nước canh chua nhẹ giúp lấy lại năng lượng và xua tan cái lạnh đầu đông.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2022/11/01/-8443-1667294206.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Y-mKCQiO_-_4zPcYIGOFAQ', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách nấu canh cá rau cần chuẩn vị Bắc');
INSERT INTO public.post VALUES (111, '2025-11-20 17:09:59.209801', '2025-11-20 17:09:59.209801', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 113, 'Niễng xào thịt bò - đặc sản ''''trời ban'''' vào đông', 'Niễng xào chín tới giòn ngọt, thịt bò mềm ngon ăn cùng cơm gạo mới tháng mười thì ''nồi bảy quăng ra, nồi ba quăng vào''. Ai một lần thưởng thức đều nhớ mãi đặc sản Nam Định.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2022/10/21/-6216-1666342979.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5V6o6SLSEOkTotYxu41R9g', 12, 13, 'MEDIUM', 'Cùng thử nấu Niễng xào thịt bò - đặc sản ''''trời ban'''' vào đông');
INSERT INTO public.post VALUES (26, '2025-11-20 17:09:49.686131', '2025-11-20 17:09:49.686131', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 36, 'Cách làm thịt kho măng khô- món ngon Tết miền Trung', 'Thịt giữ nguyên miếng, ngả màu cánh gián đẹp mắt, măng dai giòn, thấm trọn vị ngọt ngon từ thịt. Đây là món ăn truyền thống trong dịp lễ Tết của nhiều gia đình miền Trung.', 'Quảng Trị', 'https://i1-giadinh.vnecdn.net/2023/01/16/Bc7Thnhphm7-1673841764-7536-1673841897.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=mUWOPkynsdMHKQAgaU64hA', 37, 38, 'MEDIUM', 'Cùng thử nấu Cách làm thịt kho măng khô- món ngon Tết miền Trung');
INSERT INTO public.post VALUES (36, '2025-11-20 17:09:49.757242', '2025-11-20 17:09:49.757242', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 38, 'Cách làm bò nướng kim tiền - món cổ truyền Tết xưa Hà Nội', 'Từng miếng bò tròn xoe bên trong cuộn lạp sườn, mỡ phần, gan lợn tựa như đồng tiền kim loại cổ, biểu trưng ước vọng năm mới sung túc. Đây là món ăn cổ được ưu ái trong cỗ ngày Tết người Hà Nội xưa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2023/01/13/Bc5Thnhphm5-1673594551-8365-1673594565.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uC3fR4EY9h0PXG62rBAg0Q', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm bò nướng kim tiền - món cổ truyền Tết xưa Hà Nội');
INSERT INTO public.post VALUES (44, '2025-11-20 17:09:49.83686', '2025-11-20 17:09:49.83686', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 47, 'Cách làm mọc vân ám - món thất truyền của Tết Hà Nội xưa', 'Từ món thịt đông, người Hà Nội đã nâng tầm thành món ăn tinh tế với 5 sắc màu tượng trưng cho ngũ hành, ước mong năm mới đủ đầy, vẹn tròn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2023/01/06/Thnhphm11-1672982576-1308-1672982709.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=NUiJ6wxHjfLVP_35-U6l-A', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm mọc vân ám - món thất truyền của Tết Hà Nội xưa');
INSERT INTO public.post VALUES (55, '2025-11-20 17:09:50.421771', '2025-11-20 17:09:50.421771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 60, 'Cách làm mứt dừa truyền thống đơn giản', 'Từng sợi mứt dừa kết tinh đường mịn trắng tinh, đẹp mắt là món đãi khách ngon trong dịp Tết.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2022/01/27/Thnhphm1-1643218414-6346-1643218537.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=I-7LW24NJLE0FDYQ69RIpA', 50, 50, 'EASY', 'Cùng thử nấu Cách làm mứt dừa truyền thống đơn giản');
INSERT INTO public.post VALUES (60, '2025-11-20 17:09:50.547471', '2025-11-20 17:09:50.547471', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 62, 'Hướng dẫn cách nấu xôi gấc ngon, dẻo, đẹp', 'Xôi gấc căng mẩy, bóng đẹp, màu đỏ tươi rực sáng như vầng dương với ý nghĩa mang lại sự cát tường, thịnh vượng cho năm mới.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/22/Thnhphm4-1642851947-5874-1642852018.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=WqBNJ4Lt8H7phGZ2RQhWHw', 30, 30, 'EASY', 'Cùng thử nấu Hướng dẫn cách nấu xôi gấc ngon, dẻo, đẹp');
INSERT INTO public.post VALUES (71, '2025-11-20 17:09:51.83491', '2025-11-20 17:09:51.83491', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 73, 'Cách làm bánh hành phô mai kéo sợi', 'Bánh mặn, giòn tan hòa cùng kẹo marshmallow dẻo, phô mai béo thơm dễ dàng ''''gây nghiện''''. Nguyên liệu và cách làm đơn giản, bạn sẽ có món bánh siêu hot cho dịp năm mới.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2022/01/09/Thnhphm-1641714274-3297-1641714341.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=P6xOF1yuk2OaKeFFiHCf2Q', 17, 18, 'EASY', 'Cùng thử nấu Cách làm bánh hành phô mai kéo sợi');
INSERT INTO public.post VALUES (75, '2025-11-20 17:09:52.455159', '2025-11-20 17:09:52.455159', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 77, 'Canh móng giò hầm măng khô kiểu Bắc', 'Thịt chân giò mềm ngon kết hợp với măng giòn sần sật ngấu nước dùng đậm vị. Đây là món ăn truyền thống mỗi khi Tết đến xuân về của các gia đình miền Bắc.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/16/Thnhphm2-1642306935-6061-1642306963.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=N-mqaTFFzcyXvCZOKcyfZQ', 45, 45, 'MEDIUM', 'Cùng thử nấu Canh móng giò hầm măng khô kiểu Bắc');
INSERT INTO public.post VALUES (78, '2025-11-20 17:09:52.719197', '2025-11-20 17:09:52.719197', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 80, 'Cách làm mứt cam dẻo đón Tết', 'Từng lát cam dẻo ánh vàng trong veo, vị chua chua ngọt ngọt đan xen tạo dư vị rất riêng.', 'Hà Giang', 'https://i1-giadinh.vnecdn.net/2022/01/12/Thnhphm11-1641962612-4933-1641962720.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=cYzxuDJqa4dJSxG10BTn1A', 45, 45, 'EASY', 'Cùng thử nấu Cách làm mứt cam dẻo đón Tết');
INSERT INTO public.post VALUES (80, '2025-11-20 17:09:52.908943', '2025-11-20 17:09:52.908943', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 82, 'Mứt dừa non - nét ẩm thực mới ngày Tết', 'Xa rồi thời mứt dừa khô cứng, nhiều xơ, vài năm gần đây trên bàn tiếp khách ngày Tết người dân ba miền thay thế bằng mứt dừa non, mềm ngon.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2022/01/12/m7-1641957844-7166-1641957848.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=z2Fr_8I05iBfBeCqouAZiA', 60, 60, 'EASY', 'Cùng thử nấu Mứt dừa non - nét ẩm thực mới ngày Tết');
INSERT INTO public.post VALUES (81, '2025-11-20 17:09:53.082397', '2025-11-20 17:09:53.082397', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 83, 'Cách làm bánh mì bông tuyết cho Giáng Sinh ấm áp', 'Bánh mỳ mềm xốp, nhân socola thơm, hình bông tuyết xinh xắn mang đậm không khí Giáng Sinh.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/12/21/Bc10-1640075573-5819-1640075695.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=WW-kLkObTRcJ3GYv6hom8w', 37, 38, 'MEDIUM', 'Cùng thử nấu Cách làm bánh mì bông tuyết cho Giáng Sinh ấm áp');
INSERT INTO public.post VALUES (84, '2025-11-20 17:09:53.527768', '2025-11-20 17:09:53.527768', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 86, 'Sườn tảng nướng cam cho tiệc Giáng sinh', 'Thịt sườn mềm ngon, nước sốt sánh quyện với hương thơm đặc trưng của cam góp phần tạo nên bữa tiệc Giáng sinh hoàn hảo.', 'Nha Trang', 'https://i1-giadinh.vnecdn.net/2021/12/24/Thnhphm2-1640336682-7890-1640336737.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MQWVuDrrcPbpM0JB9t64pQ', 45, 45, 'MEDIUM', 'Cùng thử nấu Sườn tảng nướng cam cho tiệc Giáng sinh');
INSERT INTO public.post VALUES (87, '2025-11-20 17:09:53.928527', '2025-11-20 17:09:53.928527', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 89, 'Cách làm lòng thuôn hành răm - Món đưa cơm ngày nồm ẩm', 'Lòng trắng giòn, thơm mùi hành răm, nước sốt sền sệt cam đỏ, ăn cùng cơm ngon. Một đĩa lòng thuôn hành răm nóng hổi nhanh chóng xua đi ưu phiền trong tiết trời nồm ẩm miền Bắc.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2023/02/10/Thnhphm11-1676022659-2178-1676022715.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Yk8F5x3ul1acvn5axkcZow', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm lòng thuôn hành răm - Món đưa cơm ngày nồm ẩm');
INSERT INTO public.post VALUES (88, '2025-11-20 17:09:54.027852', '2025-11-20 17:09:54.027852', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 90, 'Cách làm mứt vỏ cam đón Tết', 'Khi ăn cam đừng vứt vỏ, hãy gom lại cất vào ngăn mát tủ lạnh, đợi nhiều thái ra làm mứt, vừa có vị cay cay, lại thơm tinh dầu vỏ cam.', 'Hà Giang', 'https://i1-giadinh.vnecdn.net/2022/01/06/2-1641442064-1641442082-6895-1641442600.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=37GtMOT9hZBBiN65UOKEVw', 45, 45, 'EASY', 'Cùng thử nấu Cách làm mứt vỏ cam đón Tết');
INSERT INTO public.post VALUES (20, '2025-11-20 17:09:49.352548', '2025-11-20 17:09:49.352548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 27, 'Cách làm xôi vò chuẩn vị Hà Nội', 'Xôi vò được ví là đỉnh cao ẩm thực Tràng An chỉ có vào dịp Tết. Sự cầu kỳ, tỉ mỉ làm nên những hạt ''kim bao ngân'' (vàng bọc bạc) bùi thơm mà ai thưởng thức đều nhớ mãi.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2024/01/17/Thnhphm22-1705480115-6069-1705480335.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=d-A93fOkzzrDkPJlGFAwSg', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm xôi vò chuẩn vị Hà Nội');
INSERT INTO public.post VALUES (21, '2025-11-20 17:09:49.639485', '2025-11-20 17:09:49.639485', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 25, 'Cách nấu thịt đông kiểu truyền thống', 'Bát thịt đông trong veo, khi ăn cảm nhận thịt mềm thấm vị, phần nước trong như thạch tan dần ra cuốn vị. Đây là món ngon không thể thiếu vào mỗi dịp Tết cổ truyền.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2024/01/08/Thnhphm11-1704705371-9220-1704705453.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=OiPznwkKFkfwfFqiCTNaCQ', 35, 35, 'EASY', 'Cùng thử nấu Cách nấu thịt đông kiểu truyền thống');
INSERT INTO public.post VALUES (31, '2025-11-20 17:09:49.722254', '2025-11-20 17:09:49.722254', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 34, 'Cách làm nộm tai heo dưa chuột giải ngán ngày Tết', 'Tai lợn sần sật, dưa chuột giòn tươi, thanh mát, vị chua ngọt dịu dễ ăn và cân bằng vị cho thực đơn mâm cỗ ngày Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2023/01/14/Thnhphm11-1673683069-5943-1673683076.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=4FpnqrwSqfi2YGyQ-kACKg', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm nộm tai heo dưa chuột giải ngán ngày Tết');
INSERT INTO public.post VALUES (41, '2025-11-20 17:09:49.802544', '2025-11-20 17:09:49.802544', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 45, 'Cách làm mứt dừa dẻo kem tươi trà xanh', 'Khác với mứt dừa truyền thống, món mứt mới lạ này thu hút bởi từng sợi dừa dẻo, thoảng mùi kem tươi vị trà xanh và đặc biệt cách làm đơn giản.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2023/01/03/Thnhphm11-1672738036-8910-1672738186.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=lLK-SnWCfAsQd1b6y0fHCA', 50, 50, 'MEDIUM', 'Cùng thử nấu Cách làm mứt dừa dẻo kem tươi trà xanh');
INSERT INTO public.post VALUES (52, '2025-11-20 17:09:49.914768', '2025-11-20 17:09:49.914768', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 53, 'Cách muối hành trắng giòn, để được lâu', 'Một lọ dưa hành muối sẽ giúp cân bằng vị, chống ngấy trong mâm cỗ nhiều thịt mỡ, bánh chưng ngày Tết. Bí quyết để hành trắng giòn là ngâm nước vo gạo hoặc tro bếp.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2022/01/26/Thnhphm1-1643214995-3177-1643215093.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=tqZSoVjqo79Xpp8TZYzcRA', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách muối hành trắng giòn, để được lâu');
INSERT INTO public.post VALUES (56, '2025-11-20 17:09:50.421771', '2025-11-20 17:09:50.421771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 58, 'Nộm su hào giòn ngon, chống ngán ngày Tết', 'Món ăn này luôn đắt khách ngày Tết bởi sự thanh mát với su hào giòn sần sật, vị chua cay mặn ngọt hài hòa quyện với lạc rang bùi bùi hấp dẫn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/16/Thnhphm1-1642307659-9123-1642307766.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=BqswpJP4pHieaEOjFZUzjg', 20, 20, 'MEDIUM', 'Cùng thử nấu Nộm su hào giòn ngon, chống ngán ngày Tết');
INSERT INTO public.post VALUES (63, '2025-11-20 17:09:50.922928', '2025-11-20 17:09:50.922928', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 65, 'Cách chọn và luộc gà lễ đẹp mắt', 'Gà luộc vàng ươm, thế ngẩng cao đầu, cánh vươn lên, da căng bóng, không bị nứt đùi.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2022/01/24/Thnhphm11-1643014436-7634-1643014646.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3fBVREcp2Rbi14aNQ7gs_Q', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách chọn và luộc gà lễ đẹp mắt');
INSERT INTO public.post VALUES (65, '2025-11-20 17:09:51.09154', '2025-11-20 17:09:51.09154', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 67, 'Mứt cóc bao tử dẻo chua ngày Tết', 'Những năm gần đây mứt cóc bao tử trở nên phổ biến trong thực đơn ngày Tết, bởi mang đến hương vị chua ngọt, dẻo cay.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2022/01/12/m4-1641958505-4527-1641958510.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3j9sTwL0HCMToMjSoJLOrg', 45, 45, 'EASY', 'Cùng thử nấu Mứt cóc bao tử dẻo chua ngày Tết');
INSERT INTO public.post VALUES (66, '2025-11-20 17:09:51.188981', '2025-11-20 17:09:51.188981', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 68, 'Cách làm mứt quất không đắng, không dùng nước vôi', 'Mứt quất màu vàng cam trong veo, vị chua ngọt thanh nhẹ. Đây là món mứt tốt cho sức khỏe và giúp chống ngán trong ngày Tết.', 'Quảng Ninh', 'https://i1-giadinh.vnecdn.net/2022/01/16/Thnhphm1-1642305107-8337-1642305167.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=SIKSBT-NqvkUgUAZs5zDEg', 15, 15, 'EASY', 'Cùng thử nấu Cách làm mứt quất không đắng, không dùng nước vôi');
INSERT INTO public.post VALUES (69, '2025-11-20 17:09:51.527179', '2025-11-20 17:09:51.527179', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 71, 'Mứt me gọi Tết miền Tây', 'Tháng 12 mùa me bắt đầu già, các gia đình ở Bến Tre thường dùng me tươi để nấu canh chua, me ngâm chua ngọt và không thể thiếu mứt me trên bàn tiếp khách ngày Tết.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2022/01/12/u-1641956961-5606-1641956965.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=bPXod_aZt7Kv7tsggaWUcA', 60, 60, 'EASY', 'Cùng thử nấu Mứt me gọi Tết miền Tây');
INSERT INTO public.post VALUES (72, '2025-11-20 17:09:51.993233', '2025-11-20 17:09:51.993233', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 74, 'Bánh bông tuyết chà bông trứng muối cho năm mới', 'Sự kết hợp của trứng muối béo ngậy, chà cay nhẹ, bánh quy giòn và kẹo marshmallow dẻo tạo nên món bánh hấp dẫn, mới lạ dịp Tết 2022.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/01/02/Thnhphm3-1641111600-6418-1641111718.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=hYhAEw56uLBsdpVz1N7RJQ', 45, 45, 'MEDIUM', 'Cùng thử nấu Bánh bông tuyết chà bông trứng muối cho năm mới');
INSERT INTO public.post VALUES (27, '2025-11-20 17:09:49.686131', '2025-11-20 17:09:49.686131', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 37, 'Cách làm chả phượng - món tiến vua ngày Tết cung đình Huế', 'Chả phượng cùng với nem công là món ăn đứng đầu hàng bát trân (8 quý hiếm) khi tiến vua của cung đình Huế ngày xưa.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2023/01/15/Thnhphm11-1673767020-9997-1673767044.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=mmu5BMJ0pb9TjPoaZIBShw', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm chả phượng - món tiến vua ngày Tết cung đình Huế');
INSERT INTO public.post VALUES (37, '2025-11-20 17:09:49.761338', '2025-11-20 17:09:49.761338', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 39, 'Cách làm tré Huế - đặc sản cố đô vào dịp Tết', 'Tré ngả màu hồng nhạt, khi ăn có vị giòn sần sật, bùi béo, chua nhẹ lên men từ thịt, chút the cay từ ớt, thơm mùi riềng. Món ăn này được nhiều người miền Trung yêu thích nhâm nhi vào dịp Tết.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2023/01/11/Bc5Thnhphm5-1673410226-7182-1673410245.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EUIrI90QxJgDFCgjThmD8g', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách làm tré Huế - đặc sản cố đô vào dịp Tết');
INSERT INTO public.post VALUES (48, '2025-11-20 17:09:49.859812', '2025-11-20 17:09:49.859812', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 49, 'Miến nấu lòng gà - món ngon đơn giản ngày Tết', 'Đây là món ăn dễ ăn, tận dụng từ nước luộc và lòng gà trong các mâm cỗ ngày Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/26/Thnhphm1-1643216245-2426-1643216342.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kGn8BxBTAFbct2qDjx1S2A', 10, 10, 'MEDIUM', 'Cùng thử nấu Miến nấu lòng gà - món ngon đơn giản ngày Tết');
INSERT INTO public.post VALUES (61, '2025-11-20 17:09:50.633166', '2025-11-20 17:09:50.633166', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 63, 'Cách làm mứt cà rốt không cần nước vôi trong', 'Sợi mứt khô ráo, đường trắng bám đều hạt li ti, màu cam đỏ đẹp mắt, khi ăn dẻo ngon rất hấp dẫn. Mứt cà rốt sẽ làm thêm phong phú cho khay mứt vào ngày Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/16/Thnhphm1-1642303764-1475-1642303800.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=vQVOBfs0pQUyxiCTVSovzQ', 30, 30, 'EASY', 'Cùng thử nấu Cách làm mứt cà rốt không cần nước vôi trong');
INSERT INTO public.post VALUES (79, '2025-11-20 17:09:52.790632', '2025-11-20 17:09:52.790632', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 81, 'Cách nấu thịt đông trong veo, đẹp mắt đón Tết', 'Từng miếng thịt mềm mướt, mộc nhĩ sần sật quyện vào trong lớp đông trong veo như sương mai, vị tròn trịa vừa độ, tất cả tạo nên món ăn thanh mát cho ngày Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/16/Thnhphm2-1642305826-3439-1642305846.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=KLtwEKePTiO9ryX7gw77EQ', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách nấu thịt đông trong veo, đẹp mắt đón Tết');
INSERT INTO public.post VALUES (89, '2025-11-20 17:09:54.10603', '2025-11-20 17:09:54.10603', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 91, 'Cách làm món bí baby nhồi thịt hấp', 'Bí nhồi thịt ngọt mềm, giàu giá trị dinh dưỡng là món ăn ngon và đơn giản đổi vị trong dịp lễ Giáng sinh và Tết dương lịch.', 'Đà Lạt', 'https://i1-giadinh.vnecdn.net/2022/12/25/Bc5Thnhphm5-1671952780-2319-1671952865.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uuOxADN1Gehm1J3gWhm3qQ', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm món bí baby nhồi thịt hấp');
INSERT INTO public.post VALUES (94, '2025-11-20 17:09:54.970036', '2025-11-20 17:09:54.970036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 96, 'Cách làm lươn om chuối đậu nóng hổi ngày đông', 'Thịt lươn mềm ngon, thịt ba chỉ béo ngậy, đậu phụ bùi bùi, nước vàng mơ sóng sánh. Món này thích hợp ăn nóng cùng cơm trắng, bún nhất là vào tiết trời lạnh.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2022/12/07/Thnhphm11-1670402126-6474-1670402161.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5Uf23AW7TEt6G-OSg93fZQ', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm lươn om chuối đậu nóng hổi ngày đông');
INSERT INTO public.post VALUES (104, '2025-11-20 17:09:57.774086', '2025-11-20 17:09:57.774086', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 106, 'Cách làm miến lươn nước giòn ấm nồng ngày đông', 'Lươn nguyên miếng màu nâu sậm giòn rụm, nước dùng trong, có vị ngọt thanh, sợi miến dai mềm. Một bát miến lươn nóng hổi phù hợp cho tiết se lạnh.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2022/11/10/Bc6thnhphm6-1668073343-7078-1668073404.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=29QAk6rKco0iAhKVZFssEQ', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách làm miến lươn nước giòn ấm nồng ngày đông');
INSERT INTO public.post VALUES (109, '2025-11-20 17:09:58.797781', '2025-11-20 17:09:58.797781', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 111, 'Nấu canh cá dọc mùng ấm ngày se lạnh', 'Canh nóng hổi, thịt đầu cá mềm ngọt, dọc mùng sần sật, nước canh hài hòa vị chua cay. Món này ăn cùng cơm trắng hay bún đều ngon, nhất là trong thời tiết se lạnh.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/10/29/-4011-1667030592.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VFxwkeuZxknTSqxVIJeJDQ', 22, 23, 'MEDIUM', 'Cùng thử nấu Nấu canh cá dọc mùng ấm ngày se lạnh');
INSERT INTO public.post VALUES (112, '2025-11-20 17:09:59.406715', '2025-11-20 17:09:59.406715', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 114, 'Mực xào cần tỏi tây chỉ 15 phút', 'Đĩa mực xào cần tỏi tây nóng hổi, khô ráo, dậy mùi thơm và màu sắc bắt mắt. Mực chín tới giữ độ giòn dai sần sật, ngọt tự nhiên.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2022/10/22/-3836-1666423599.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0bT6Loxev-XqTJGlOfGMaQ', 7, 8, 'MEDIUM', 'Cùng thử nấu Mực xào cần tỏi tây chỉ 15 phút');
INSERT INTO public.post VALUES (114, '2025-11-20 17:09:59.740162', '2025-11-20 17:09:59.740162', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 116, 'Cách làm tim heo xào chua ngọt', 'Món ăn nóng hổi, tim dai giòn sần sật, rau củ quả chín tới ngọt mát. Món này ăn chơi hay ăn cùng cơm đều hợp.', 'Huế', 'https://i1-giadinh.vnecdn.net/2022/10/18/-6579-1666066222.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=m60Xfb7_jedVZX4C9MHAMQ', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm tim heo xào chua ngọt');
INSERT INTO public.post VALUES (116, '2025-11-20 17:10:00.041812', '2025-11-20 17:10:00.041812', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 118, 'Cách làm bò sốt tiêu đen ngon như nhà hàng', 'Thịt bò mềm, nước sốt hơi sánh, màu nâu đậm đặc trưng, vị mặn ngọt hài hòa, đặc biệt dậy mùi thơm và chút the cay từ hạt tiêu đen. Món này ăn cùng bánh bao chiên rất ngon.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/10/09/-8521-1665301792.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=HUSLhgo-CUPhZFTKlfvg0A', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm bò sốt tiêu đen ngon như nhà hàng');
INSERT INTO public.post VALUES (117, '2025-11-20 17:10:00.228813', '2025-11-20 17:10:00.228813', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 119, 'Cá kho trám xanh - thức quà mùa thu', 'Thịt cá thẩm thấu vị chua nhẹ từ trám, chút ngầy ngậy từ thịt, còn từng miếng trám bùi dẻo, đượm vị ngọt ngon từ cá và tương nếp.', 'Bắc Giang', 'https://i1-giadinh.vnecdn.net/2022/10/12/-9125-1665567378.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=jrdao2JzsWDToPTvI-QC3Q', 60, 60, 'MEDIUM', 'Cùng thử nấu Cá kho trám xanh - thức quà mùa thu');
INSERT INTO public.post VALUES (29, '2025-11-20 17:09:49.689943', '2025-11-20 17:09:49.689943', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 30, 'Cách làm gỏi ngũ sắc từ thịt gà thừa dịp Tết', 'Đĩa nộm khô ráo, thịt gà trắng thơm, đậm vị, rau củ quả giòn xen kẽ sắc xanh, cam, tím, trắng bắt mắt. Khi ăn cảm nhận vị chua ngọt mặn hài hòa, đưa miệng. Một món ăn tận dụng gà luộc dư giúp cân bằng vị cho ngày Tết.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2023/01/27/Bc5thnhphm5-1674788525-2458-1674788859.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Qzyf1Nbn6Rcnrd6yov35xA', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm gỏi ngũ sắc từ thịt gà thừa dịp Tết');
INSERT INTO public.post VALUES (40, '2025-11-20 17:09:49.79218', '2025-11-20 17:09:49.79218', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 40, 'Cách làm gà ủ muối hoa tiêu - món hot cho ngày Tết', 'Gà da giòn vàng, khi ăn thịt màu hồng đào mềm ngọt, mọng nước, vị vừa vặn. Đây là một trong những món ăn được nhiều người yêu thích vào dịp lễ Tết.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2023/01/12/Bc6thnhphm6-1673509660-3978-1673509677.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kmnGDgRQtRA1npJh_-xU3w', 45, 45, 'HARD', 'Cùng thử nấu Cách làm gà ủ muối hoa tiêu - món hot cho ngày Tết');
INSERT INTO public.post VALUES (50, '2025-11-20 17:09:49.914768', '2025-11-20 17:09:49.914768', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 54, 'Cách làm dưa góp giòn ngon cho ngày Tết', 'Món ăn này giúp giải ngấy và làm tròn vị cho nhiều món chính ngày Tết như bánh chưng, nem rán (chả giò).', 'Huế', 'https://i1-giadinh.vnecdn.net/2022/01/14/Thnhphm1-1642156045-8179-1642156114.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=RoB_Sux9qooTno894WPQbQ', 15, 15, 'EASY', 'Cùng thử nấu Cách làm dưa góp giòn ngon cho ngày Tết');
INSERT INTO public.post VALUES (62, '2025-11-20 17:09:50.832308', '2025-11-20 17:09:50.832308', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 64, 'Công thức và Cách làm nem rán Hà Nội chuẩn nhất', 'Nem rán có vỏ vàng giòn, nhân mềm ngọt từ thịt, tôm quyện cùng rau củ quả hài hòa. Đây là món ăn truyền thống trong mâm cỗ Tết của người Hà Nội.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/22/Thnhphm1-1642852604-8650-1642852743.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ErRySDFeRqFE4df32QKdTw', 37, 38, 'HARD', 'Cùng thử nấu Công thức và Cách làm nem rán Hà Nội chuẩn nhất');
INSERT INTO public.post VALUES (82, '2025-11-20 17:09:53.215218', '2025-11-20 17:09:53.215218', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 84, 'Bánh cây thông cho tiệc Giáng Sinh an lành', 'Bánh hình cây thông Noel đẹp mắt, bánh nở mềm xốp, nhân mứt dâu quyện cùng quả sấy rất hấp dẫn.', 'Đà Lạt', 'https://i1-giadinh.vnecdn.net/2021/12/21/Bc10-1640074826-7227-1640074989.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=RraMIh26T56Bq1fnZk2d_g', 45, 45, 'MEDIUM', 'Cùng thử nấu Bánh cây thông cho tiệc Giáng Sinh an lành');
INSERT INTO public.post VALUES (93, '2025-11-20 17:09:54.747854', '2025-11-20 17:09:54.747854', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 95, 'Cách làm cà ri bò bổ dưỡng cho ngày nồm ẩm', 'Cà ri nóng hổi với thịt bò mềm ngon, khoai giữ nguyên miếng, nước sốt sánh vàng, vị béo ngậy từ nước cốt dừa. Món này chấm cùng bánh mì hoặc ăn cùng cơm trắng rất ngon, nhất là trong tiết trời nồm ẩm se lạnh.', 'Vũng Tàu', 'https://i1-giadinh.vnecdn.net/2023/02/08/Thnhphm11-1675831139-6556-1675831142.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=l-G1OihkAc0fIy7rm2t98A', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm cà ri bò bổ dưỡng cho ngày nồm ẩm');
INSERT INTO public.post VALUES (95, '2025-11-20 17:09:55.158568', '2025-11-20 17:09:55.158568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 97, 'Cách làm chim câu bằm xúc phồng tôm', 'Thịt chim câu sần sật, đậm vị xào cùng hành răm dậy mùi thơm, ăn cùng phồng tôm giòn rụm. Đây là món ăn đắt hàng mùa bóng.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/12/02/Thnhphm11-1669957715-7329-1669957828.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=vi8RqvLAMbVdrhUBkWZ-3Q', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm chim câu bằm xúc phồng tôm');
INSERT INTO public.post VALUES (96, '2025-11-20 17:09:55.485717', '2025-11-20 17:09:55.485717', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 98, 'Cách làm lòng non dồi sụn cổ vũ bóng đá thêm rực lửa', 'Lòng sụn vỏ giòn dai, nhân mềm hài hòa nhiều vị: sần sật của sụn non, giòn giòn từ cuống họng, beo béo từ mỡ phần, bùi bùi của đậu xanh, rau thơm. Món này ăn nóng cùng bè bạn tề tựu mùa bóng đá rất hấp dẫn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/12/10/Thnhphm11-1670663470-2592-1670663476.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=YCgsjvHvtjXA12qOU0PQqQ', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách làm lòng non dồi sụn cổ vũ bóng đá thêm rực lửa');
INSERT INTO public.post VALUES (97, '2025-11-20 17:09:55.759701', '2025-11-20 17:09:55.759701', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 99, 'Cách làm món đuôi heo nấu rựa mận', 'Tiết trời trở lạnh, một bát rựa mận từ thịt heo nóng hổi với thịt mềm, đậm đà hương vị nồng nàn làm cho không khí cổ vũ bóng đá sôi động, ấm áp hơn.', 'An Giang', 'https://i1-giadinh.vnecdn.net/2022/12/06/Thnhphm11-1670304579-3994-1670304691.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0uwp0Z4zXaO3rmSjUsYAww', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách làm món đuôi heo nấu rựa mận');
INSERT INTO public.post VALUES (99, '2025-11-20 17:09:56.425753', '2025-11-20 17:09:56.425753', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 101, 'Cánh gà nướng mật ong da giòn, vàng óng', 'Cánh gà bên ngoài da giòn, bên trong thịt mềm ngọt mà không bị khô, vị mặn ngọt đậm đà.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/11/24/Thnhphm11-1669286949-5144-1669287068.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=71L-2xNM42Ivz5Qq4Pr6_Q', 25, 25, 'MEDIUM', 'Cùng thử nấu Cánh gà nướng mật ong da giòn, vàng óng');
INSERT INTO public.post VALUES (102, '2025-11-20 17:09:57.306546', '2025-11-20 17:09:57.306546', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 104, 'Cách nấu canh bún cá - món cổ ngon của người Hà Nội', 'Thịt cá mềm ngọt vị tự nhiên nguyên bản, tóp mỡ giòn rụm, rau xanh non, nước dùng thanh trong. Đây là món ăn của người Hà thành xưa', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/11/13/Bc5thnhphm5-1668312987-1898-1668313002.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=yq3IYYl77fxqQjibemZIyg', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách nấu canh bún cá - món cổ ngon của người Hà Nội');
INSERT INTO public.post VALUES (108, '2025-11-20 17:09:58.607903', '2025-11-20 17:09:58.607903', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 110, 'Cách làm món lòng xào nghệ chuẩn vị, giòn dai, thơm ngon khó cưỡng', 'Lòng giòn dai, có chút béo ngậy quyện vị hơi hăng của nghệ, vị the cay từ ớt, vị ngọt từ hành tây kích thích vị giác. Món ăn này tốt cho dạ dày và hỗ trợ chữa ho tốt vào ngày đông.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2022/10/24/-9709-1666597603.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=r3O671_t0GAzYPaWS-qoYA', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm món lòng xào nghệ chuẩn vị, giòn dai, thơm ngon khó cưỡng');
INSERT INTO public.post VALUES (110, '2025-11-20 17:09:59.058273', '2025-11-20 17:09:59.058273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 112, 'Cách làm xôi cá rô đồng - món ngon dân dã Nam Định', 'Xôi dẻo thơm mùi lúa mới, kết hợp thịt cá rô đồng ngọt mềm mà vẫn giữ chút dai dai, dậy mùi thơm của hành phi, rắc chút hạt tiêu cay ấm làm nên món đặc sản đất Thành Nam.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2022/10/30/-9099-1667120896.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kodecOh9rzpnNNoKuYcXXQ', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm xôi cá rô đồng - món ngon dân dã Nam Định');
INSERT INTO public.post VALUES (118, '2025-11-20 17:10:00.356433', '2025-11-20 17:10:00.356433', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 120, 'Cách làm bò thuôn hành răm món ''quốc dân'' đậm vị Hà Nội', 'Thịt bò mềm ngọt, nước canh chua dịu, dậy mùi thơm của hành răm, ăn cùng cơm trắng hay bún, là món ăn được yêu thích của người Hà Nội xưa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/10/16/-8016-1665908774.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=IFfIR-ITeYpg0oVaPKDIog', 10, 10, 'MEDIUM', 'Cùng thử nấu Cách làm bò thuôn hành răm món ''quốc dân'' đậm vị Hà Nội');
INSERT INTO public.post VALUES (133, '2025-11-20 17:10:03.451859', '2025-11-20 17:10:03.451859', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 135, 'Cách làm bún gạo xào chay mềm tơi, thấm vị hài hòa', 'Bún gạo mềm tơi, thấm vị hài hòa, các rau củ quả chín tới, màu sắc tươi mới, không bị ra nước. Một món ăn thanh đạm lại đầy đủ dinh dưỡng.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/08/08/Thnhphm33-1659943507-8301-1659943657.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=8faL2z52gttxS_VjqJDrcw', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm bún gạo xào chay mềm tơi, thấm vị hài hòa');
INSERT INTO public.post VALUES (148, '2025-11-20 17:10:06.887009', '2025-11-20 17:10:06.887009', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 150, 'Cách làm thịt ba chỉ rán húng lìu kiểu Bắc', 'Phần bì giòn, phần thịt mềm ngọt, dậy mùi thơm của húng lìu, hành, tỏi ăn kèm rau sống rất ‘đưa cơm’’ trong ngày hè.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2022/07/17/Bc4Thnhphm1-1658049315-4436-1658049415.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=b8kV60EyDhD3PxTdHhXzkA', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm thịt ba chỉ rán húng lìu kiểu Bắc');
INSERT INTO public.post VALUES (163, '2025-11-20 17:10:08.887378', '2025-11-20 17:10:08.887378', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 165, 'Cách làm canh cua khoai sọ rau muống - gợi nhớ hương vị xưa', 'Thịt cua đóng tảng, gạch cua thơm lừng, khoai bùi dẻo, rau muống giòn ngon. Món này ăn cùng cà pháo, thịt rang cháy cạnh thì bao ký ức hương xưa vị cũ về món ngon Hà thành ùa về.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/05/19/Thnhphm11-1652948004-6211-1652948136.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=nJarp4fR5QCbNkmiTEeTBQ', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm canh cua khoai sọ rau muống - gợi nhớ hương vị xưa');
INSERT INTO public.post VALUES (175, '2025-11-20 17:10:10.522138', '2025-11-20 17:10:10.522138', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 177, 'Cá nục kho nước dừa đậm vị, mềm ngon và béo ngậy', 'Cá săn chắc, mềm rục xương, đậm đà vịt mặn ngọt ăn cùng cơm hay cháo trắng rất ngon, nhất là trong mùa nóng. Món ăn dân dã, giản dị vậy thôi mà ''''gây thương nhớ'''' bao người.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2022/04/20/Thnhphm11-1650438758-9995-1650438870.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=yvPjcZ6U6zHB295wjiARYg', 60, 60, 'MEDIUM', 'Cùng thử nấu Cá nục kho nước dừa đậm vị, mềm ngon và béo ngậy');
INSERT INTO public.post VALUES (189, '2025-11-20 17:10:12.67629', '2025-11-20 17:10:12.67629', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 191, 'Cháo chim câu hạt sen', 'Cháo nở bung như hoa, thịt chim câu mềm ngọt tự nhiên mà không tanh, đậu xanh bùi bùi, hạt sen chín tới, hài hòa vị rất hấp dẫn.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2022/02/18/Thnhphm3-1645173826-7346-1645173899.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=n36bBqMx8jE2jgV4m7dkMg', 45, 45, 'MEDIUM', 'Cùng thử nấu Cháo chim câu hạt sen');
INSERT INTO public.post VALUES (204, '2025-11-20 17:10:14.588361', '2025-11-20 17:10:14.588361', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 206, 'Làm miến chim câu chặt ngon hơn ngoài tiệm', 'Nước dùng từ xương chim ngọt không kém nước dùng từ xương lợn, thịt chim chín tới thơm mềm đậm vị làm nên một món ngon khó lòng cưỡng lại dù đang giảm cân.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/12/05/1-1638713642-2026-1638713664.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=d6ZjSHgUrbwbl9r-N_xxmg', 60, 60, 'EASY', 'Cùng thử nấu Làm miến chim câu chặt ngon hơn ngoài tiệm');
INSERT INTO public.post VALUES (219, '2025-11-20 17:10:16.730991', '2025-11-20 17:10:16.730991', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 221, 'Cách làm trứng non, lòng gà cháy tỏi ngon như tiệm', 'Trứng non vàng ươm, tràng mềm có chút sần sật, dậy mùi thơm của tỏi, gia vị đậm đà rất hấp dẫn. Món này ăn chơi hay ăn cùng cơm nóng, bánh mì đều ngon.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/12/06/Thnhphm1-1638778157-3082-1638778241.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=upFuydypVDQYG9lXnVO-dQ', 15, 15, 'EASY', 'Cùng thử nấu Cách làm trứng non, lòng gà cháy tỏi ngon như tiệm');
INSERT INTO public.post VALUES (234, '2025-11-20 17:10:19.084575', '2025-11-20 17:10:19.084575', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 236, 'Những món ngon đậm đà vị mới', 'Với ba món nướng, hầm và salad, bạn đã có đủ hương vị phong phú cho bữa cơm gia đình. Cuối bữa tráng miệng với món chuối rim mật nước cốt dừa đơn giản nhưng cũng rất ngon.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/11/11/canhcucai-1636622786-2821-1636622815.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=czVp-RLbOGsP3q-rhV0ayw', 0, 0, 'EASY', 'Cùng thử nấu Những món ngon đậm đà vị mới');
INSERT INTO public.post VALUES (249, '2025-11-20 17:10:21.284505', '2025-11-20 17:10:21.284505', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 251, 'Bún xào rau cần - món ngon cổ truyền vùng Cổ Loa', 'Sợi bún dai, rau cần cọng xanh chín tới giòn thơm, vị thanh nhẹ. Đây là món ăn đãi khách của người dân Cổ Loa (Đông Anh, Hà Nội).', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/31/Thnhphm1-1635639444-4167-1635639450.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=mJ009sv-8PQNpkaby34oxg', 10, 10, 'EASY', 'Cùng thử nấu Bún xào rau cần - món ngon cổ truyền vùng Cổ Loa');
INSERT INTO public.post VALUES (264, '2025-11-20 17:10:23.451359', '2025-11-20 17:10:23.451359', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 266, '3 món salad mát lành', 'Salad là món ăn mát, thích hợp với những ngày nóng. Sau đây là các món salad rau; hoa quả và cà chua, dưa chuột.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/26/saladrauqua-1635240739-5476-1635240778.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=jc7qCkIcXNKNxFE1Kt7Bag', 0, 0, 'MEDIUM', 'Cùng thử nấu 3 món salad mát lành');
INSERT INTO public.post VALUES (279, '2025-11-20 17:10:26.049309', '2025-11-20 17:10:26.049309', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 281, 'Chả giò sen', 'Chả giò (nem) là món ăn được nhiều người rất thích. Bạn có thể làm để cả nhà thưởng thức món này nhưng với hương vị lạ khi cho thêm hạt sen, khoai môn... vào nguyên liệu.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2021/10/15/chagio-1634274000-2919-1634274012.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=xtllINRudh1PWpBENHoITQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Chả giò sen');
INSERT INTO public.post VALUES (294, '2025-11-20 17:10:28.780904', '2025-11-20 17:10:28.780904', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 296, 'Tôm nướng phô mai', 'Vẫn với nguyên liệu chính là tôm nhưng bạn có thể mang lại cho cả nhà một hương vị mới, rất thơm ngon, hấp dẫn với món tôm nướng phô mai.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/15/tomnuong-1634271886-9364-1634271999.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EkvMrcES08qb0LFA4bDimA', 0, 0, 'MEDIUM', 'Cùng thử nấu Tôm nướng phô mai');
INSERT INTO public.post VALUES (119, '2025-11-20 17:10:00.657786', '2025-11-20 17:10:00.657786', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 121, 'Cách làm xíu mại ăn bánh mì ngon', 'Xíu mại mềm, vị ngọt tự nhiên từ thịt quyện lẫn củ quả, nước sốt sánh màu au đỏ hấp dẫn, ăn cùng bánh mì giòn là bữa ăn sáng đủ chất, được nhiều người yêu thích.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/09/30/-7717-1664555235.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eSc2VZy-EupBVHOYAp1rYA', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm xíu mại ăn bánh mì ngon');
INSERT INTO public.post VALUES (134, '2025-11-20 17:10:03.674094', '2025-11-20 17:10:03.674094', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 136, 'Cách làm cá nục kho thơm đậm vị hao cơm', 'Thịt cá săn chắc, đậm vị mặn ngọt cay, dứa (thơm) chua chua quyện vị ngọt thơm từ cá ăn cùng cơm rất đưa miệng.', 'Phú Quốc', 'https://i1-giadinh.vnecdn.net/2022/08/17/Thnhphm22-1660724295-9931-1660724426.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=AeE_sNkOKC84eUmW7l48AQ', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm cá nục kho thơm đậm vị hao cơm');
INSERT INTO public.post VALUES (149, '2025-11-20 17:10:07.002805', '2025-11-20 17:10:07.002805', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 151, 'Cách làm thịt bò xào hoa thiên lý nhanh gọn, bổ dưỡng cho ngày hè', 'Thịt bò mềm ngọt, hoa thiên lý giữ màu xanh tươi, giòn ngon hấp dẫn. Một món ăn nhanh gọn, bổ dưỡng cho ngày hè.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/07/02/Thnhphm11-1656751008-7292-1656751071.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ph3RqLJhBa3m4ThEGqqktw', 10, 10, 'MEDIUM', 'Cùng thử nấu Cách làm thịt bò xào hoa thiên lý nhanh gọn, bổ dưỡng cho ngày hè');
INSERT INTO public.post VALUES (164, '2025-11-20 17:10:09.042911', '2025-11-20 17:10:09.042911', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 166, 'Cách làm cá kho cà pháo - món dân dã ngày hè xứ Nghệ', 'Thịt cá màu hổ phách đẹp mắt, chắc béo, thấm vị mằn mặn, chua chua từ cà pháo quyện với mật mía ngọt đượm, cộng chút the cay từ ớt rất đưa cơm ngày hè.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2022/05/16/Thnhphm11-1652690562-2927-1652690652.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=GVYTGsmIKnTkM2RuUoY9bw', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm cá kho cà pháo - món dân dã ngày hè xứ Nghệ');
INSERT INTO public.post VALUES (176, '2025-11-20 17:10:10.659991', '2025-11-20 17:10:10.659991', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 178, 'Cách làm rau muống xào tỏi bằng nồi trong 3 phút của miền Trung', 'Với bí quyết xào rau nhanh gọn bằng nồi của nhiều người dân miền Trung, đảm bảo đĩa rau muống xào để lâu vẫn xanh non, dậy mùi thơm quyến rũ.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2022/04/19/Thnhphm11-1650361101-8939-1650361176.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=wRpnjn42xH1aBfwSQXJW9A', 6, 7, 'MEDIUM', 'Cùng thử nấu Cách làm rau muống xào tỏi bằng nồi trong 3 phút của miền Trung');
INSERT INTO public.post VALUES (190, '2025-11-20 17:10:12.76226', '2025-11-20 17:10:12.76226', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 192, 'Cách làm cá bống kho tộ nước dừa kiểu miền Tây', 'Cá săn cứng, không bị gãy nát, đậm vị, nước kho sánh keo lại chấm cùng rau củ quả luộc như món kho quẹt rất ngon.', 'Vĩnh Long', 'https://i1-giadinh.vnecdn.net/2022/03/01/Bc6-1646125360-4257-1646125463.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=sFTR2iVkNCJPSz3uEhFueg', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm cá bống kho tộ nước dừa kiểu miền Tây');
INSERT INTO public.post VALUES (205, '2025-11-20 17:10:14.73093', '2025-11-20 17:10:14.73093', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 207, 'Bún riêu cua truyền thống Hà Nội', 'Thịt cua đóng thành tảng, nước riêu thơm mùi đặc trưng, màu váng óng đỏ tự nhiên, vị chua thanh nhẹ. Đây là món ăn được nhiều người lựa chọn sau Tết để đổi vị.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/12/17/Bc11-1639748576-8269-1639748607.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=GAsbq0l7EAnkTvngYdBsrQ', 27, 28, 'MEDIUM', 'Cùng thử nấu Bún riêu cua truyền thống Hà Nội');
INSERT INTO public.post VALUES (220, '2025-11-20 17:10:16.918184', '2025-11-20 17:10:16.918184', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 222, 'Cá kho chuối ''hao cơm'' ngày đông', 'Cá màu nâu sẫm chắc thịt, đậm đà ngậm tròn trịa các vị: bùi bùi của chuối, cay cay của ớt, thơm của riềng, lá gừng non làm nên bản giao hưởng đẹp trong mùa đông khi ăn cùng cơm nóng.', 'Thanh Hóa', 'https://i1-giadinh.vnecdn.net/2021/11/26/Thnhphm1-1637901065-3576-1637901078.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=I3E5t6EaAv4yRRAzgC6Sdw', 120, 120, 'MEDIUM', 'Cùng thử nấu Cá kho chuối ''hao cơm'' ngày đông');
INSERT INTO public.post VALUES (235, '2025-11-20 17:10:19.183377', '2025-11-20 17:10:19.183377', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 237, 'Hai món ngon chữa bệnh', 'Chè củ cải và rau cải xào nấm là hai món dễ làm lại lành tính, tăng cảm giác ngon miệng. Bạn hãy thử áp dụng công thức chế biến dưới đây nhé.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/17/checucai-1637138440-2959-1637138761.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Q8C436FCVYAKtbQkNA9Ijw', 0, 0, 'EASY', 'Cùng thử nấu Hai món ngon chữa bệnh');
INSERT INTO public.post VALUES (250, '2025-11-20 17:10:21.424464', '2025-11-20 17:10:21.424464', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 252, 'Trổ tài với các món rán nóng', 'Mùa lạnh, còn gì thú vị hơn cả nhà được quây quần bên những món ăn chiên nóng hổi, thơm ngào ngạt. Bạn thử bắt tay vào làm nhé.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/03/khoaitay-1635925643-8902-1635925655.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=t38xi-9X2PGHJnRdsoDdwQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Trổ tài với các món rán nóng');
INSERT INTO public.post VALUES (265, '2025-11-20 17:10:23.56726', '2025-11-20 17:10:23.56726', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 267, 'Món lạ từ dưa chuột', 'Có công dụng giải khát, dưa chuột là loại trái rất được ưa chuộng của mùa nóng. Dưới đây là những món ngon, lạ miệng từ loại quả này mà bạn có thể tham khảo để trổ tài cho cả nhà thưởng thức.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/26/duachuot-1635222456-1807-1635222538.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=dD69e0pQSO9hCWC1IGpY1w', 0, 0, 'MEDIUM', 'Cùng thử nấu Món lạ từ dưa chuột');
INSERT INTO public.post VALUES (280, '2025-11-20 17:10:26.258953', '2025-11-20 17:10:26.258953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 282, 'Dưa leo nhồi thịt sốt cà chua', 'Món dưa leo nhồi thịt sốt cà chua trình bày đẹp mắt, có vị giòn của vỏ dưa, nhân thịt hấp chín tới ăn nóng kèm cơm, canh.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/18/dualeoancungcachualabinhthuong-7147-2570-1634550748.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=zL2gtbOXzFIHgmXOG6IlcQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Dưa leo nhồi thịt sốt cà chua');
INSERT INTO public.post VALUES (295, '2025-11-20 17:10:28.909128', '2025-11-20 17:10:28.909128', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 297, 'Những món ngon chế biến từ sen', 'Sen là món vừa dễ kiếm vừa dễ ăn. Từ củ sen, ngó sen, thậm chí lá sen bạn có thể làm được những món ăn khá lạ miệng. Mời bạn cùng trổ tài từ những gợi ý dưới đây.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2021/10/11/kimchicusen-1633942134-1648-1633942341.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=NOYreyxJkzFt2tQ27_Mczg', 0, 0, 'EASY', 'Cùng thử nấu Những món ngon chế biến từ sen');
INSERT INTO public.post VALUES (120, '2025-11-20 17:10:00.878985', '2025-11-20 17:10:00.878985', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 122, 'Cách làm cá rô phi nướng riềng sả', 'Cá nướng da giòn dai, thịt bên trong mềm ngọt, không bị khô, dậy mùi thơm của sả, riềng cộng chút the cay từ ớt.', 'Thanh Hóa', 'https://i1-giadinh.vnecdn.net/2022/09/28/-2691-1664348796.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Jkb1heLzGRAGL_V8ZN4QNQ', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm cá rô phi nướng riềng sả');
INSERT INTO public.post VALUES (131, '2025-11-20 17:10:02.901536', '2025-11-20 17:10:02.901536', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 133, 'Cách làm đậu phụ nhồi thịt sốt cà chua đơn giản cho bữa cơm hàng ngày', 'Đậu phụ vỏ dai, bên trong dồn thịt mềm ngọt, nước sốt cà chua đỏ vàng sóng sánh, vị hài hòa dễ ''''bắt cơm'''' khi thời tiết chuyển mùa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/08/24/Thnhphm11-1661329394-5338-1661329711.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=--8omr8V02glmsKutrajPA', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm đậu phụ nhồi thịt sốt cà chua đơn giản cho bữa cơm hàng ngày');
INSERT INTO public.post VALUES (135, '2025-11-20 17:10:03.934138', '2025-11-20 17:10:03.934138', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 137, 'Cách làm bún ốc nóng - nét ẩm thực dân dã Hà thành', 'Dẫu ra đời muộn so với bún ốc nguội, nhưng bún ốc nóng lại được lòng người sành ăn bởi ốc giòn ngon, nước dùng chua thanh nhẹ.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/08/06/Thnhphm22-1659778295-5035-1659778478.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MNNda7JthI-SLOOhCpIq_A', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm bún ốc nóng - nét ẩm thực dân dã Hà thành');
INSERT INTO public.post VALUES (146, '2025-11-20 17:10:06.477132', '2025-11-20 17:10:06.477132', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 148, 'Cách làm gỏi bưởi tôm, mực khô - món ngon đãi tiệc', 'Món ăn là sự hài hòa sắc và vị với bưởi hồng mọng nước, vị chua the kết hợp mực ngọt thơm, đậu phộng giòn bùi chiếm trọn cảm tình trong thực đơn đãi tiệc ngày hè.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2022/07/20/Bc4Thnhphm3-1658313976-9349-1658314024.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=m7QQ1Go9lC6LTn7RD7A7fw', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm gỏi bưởi tôm, mực khô - món ngon đãi tiệc');
INSERT INTO public.post VALUES (150, '2025-11-20 17:10:07.141214', '2025-11-20 17:10:07.141214', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 152, 'Cách làm thịt ba chỉ kho trứng cút đậm đà', 'Thịt lên màu hổ phách, trứng cút thấm vị, nước kho sóng sánh chấm cùng rau củ quả luộc rất ''''hao cơm''''. Đây là món ăn phổ biến ở miền Nam.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/07/13/Bc5Thnhphm5-1657693893-1743-1657694025.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=z30xWW-3v64E6wJBfYLzgg', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm thịt ba chỉ kho trứng cút đậm đà');
INSERT INTO public.post VALUES (161, '2025-11-20 17:10:08.515802', '2025-11-20 17:10:08.515802', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 163, 'Cách làm canh măng mực - đặc sản truyền thống Bát Tràng', 'Món ăn là sự kết hợp của hương vị núi rừng và biển cả với nước canh thanh trong, mực mềm ngọt, măng giòn sần sật khiến ai một lần thưởng thức đều nhớ mãi.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/05/31/Thnhphm11-1653989144-6863-1653989241.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=XqDRs0sbTsj4MdISLM7MXA', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm canh măng mực - đặc sản truyền thống Bát Tràng');
INSERT INTO public.post VALUES (165, '2025-11-20 17:10:09.21004', '2025-11-20 17:10:09.21004', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 167, 'Cách làm sườn nướng ngon mềm, đẹp mắt mà không bị khô', 'Sườn lên màu bóng đẹp, thịt mềm thấm vị đậm đà mà không bị khô, dẻ sườn dễ róc.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2022/05/11/Thnhphm11-1652239252-3064-1652239357.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=X6AWvn3AffjIDj031AshEQ', 22, 23, 'EASY', 'Cùng thử nấu Cách làm sườn nướng ngon mềm, đẹp mắt mà không bị khô');
INSERT INTO public.post VALUES (173, '2025-11-20 17:10:10.315406', '2025-11-20 17:10:10.315406', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 175, 'Cách nấu súp gà ngô nấm thanh mát, bồi bổ sức khỏe', 'Thịt gà mềm, ngô ngọt xen kẽ nấm rơm thanh, trứng cút bùi bùi quyện trong nước súp sóng sánh vân mây trắng làm nên món ngon bổ dưỡng, thanh mát ngày hè.', 'Đà Lạt', 'https://i1-giadinh.vnecdn.net/2022/04/15/Thnhphm33-1650018485-5644-1650018610.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=LHFkLIn_S4WX7casNZSC2g', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách nấu súp gà ngô nấm thanh mát, bồi bổ sức khỏe');
INSERT INTO public.post VALUES (177, '2025-11-20 17:10:10.899212', '2025-11-20 17:10:10.899212', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 179, 'Cách làm canh cá Quỳnh Côi chuẩn vị đặc sản Thái Bình', 'Một bát canh cá dân dã, trọn hương - sắc - vị với thịt cá dai giòn, nước dùng thanh, trứng cá vàng ươm, rau xanh, bánh đa trắng... tựa bức họa đồng quê hấp dẫn. Đây là món ăn nổi tiếng Thái Bình.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2022/04/28/Bc88-1651133633-7405-1651133929.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=zBEJGLxBgIec8a6SxFfq9Q', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm canh cá Quỳnh Côi chuẩn vị đặc sản Thái Bình');
INSERT INTO public.post VALUES (187, '2025-11-20 17:10:12.379636', '2025-11-20 17:10:12.379636', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 189, 'Cách làm trai xào lá lốt cay cay, dai giòn dậy mùi thơm', 'Thịt trai dai giòn quyện trong lá lốt dậy mùi vị đồng quê, thêm chút the cay nơi đầu lưỡi của ớt.', 'Ninh Bình', 'https://i1-giadinh.vnecdn.net/2022/03/24/Thnhphm11-1648117449-1488-1648117542.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=J81ee8VFJSR4e78IqyqfNQ', 17, 18, 'EASY', 'Cùng thử nấu Cách làm trai xào lá lốt cay cay, dai giòn dậy mùi thơm');
INSERT INTO public.post VALUES (191, '2025-11-20 17:10:12.852322', '2025-11-20 17:10:12.852322', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 193, 'Cá kho su hào đưa cơm ngày lạnh', 'Món ăn này tưởng lạ nhưng mùi vị rất đỗi thân quen với cá đậm vị săn chắc, su hào giòn ngọt. Món ăn này phù hợp vào thời tiết lạnh khi su hào vào độ ngon nhất.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2022/02/25/Thnhphm1-1645780253-1845-1645780347.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=SuIDZyrLl06CuZtJkBDJJQ', 120, 120, 'MEDIUM', 'Cùng thử nấu Cá kho su hào đưa cơm ngày lạnh');
INSERT INTO public.post VALUES (202, '2025-11-20 17:10:14.272135', '2025-11-20 17:10:14.272135', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 204, 'Gà nướng Tây Bắc chấm chẩm chéo', 'Thịt gà ươm vàng, mềm ngọt, dậy mùi thơm mắc khén, hạt dổi chấm cùng chẩm chéo rất ngon, ai một lần thưởng thức đều nhớ mãi.', 'Sơn La', 'https://i1-giadinh.vnecdn.net/2022/02/11/Bc88-1644565204-2380-1644565411.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uML_V3Halk2msBKY_LFiTw', 57, 58, 'MEDIUM', 'Cùng thử nấu Gà nướng Tây Bắc chấm chẩm chéo');
INSERT INTO public.post VALUES (206, '2025-11-20 17:10:14.986936', '2025-11-20 17:10:14.986936', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 208, 'Cách nấu giả cầy Nghệ An chuẩn vị', 'Thịt giả cầy mềm mà không bở, có vị ngọt nhẹ từ mật mía, dậy mùi thơm của lá tắt, mắm tôm và sánh màu nâu đỏ đẹp mắt. Món ăn dân dã này thường ăn kèm bún hoặc bánh mướt rất ngon.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/12/28/Thnhphm1-1640678799-1891-1640679038.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=1kkpbyzs-6nDc-Kmu9HjSQ', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách nấu giả cầy Nghệ An chuẩn vị');
INSERT INTO public.post VALUES (121, '2025-11-20 17:10:01.122919', '2025-11-20 17:10:01.122919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 123, 'Cách làm bò kho kiểu Việt Nam', 'Thịt bò giữ nguyên miếng, có vị béo ngậy từ mỡ và chút giòn từ gân, nước sốt sóng sánh đẹp mắt, dậy mùi thơm hấp dẫn từ quế, hồi, sả. Món này ăn cùng cơm trắng, bánh mì, bún rất ngon.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/09/30/-1940-1664522303.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=j6Gm8LGhLSgOpMujzHRDUg', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm bò kho kiểu Việt Nam');
INSERT INTO public.post VALUES (136, '2025-11-20 17:10:04.201661', '2025-11-20 17:10:04.201661', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 138, 'Cách làm mồng tơi xào tỏi đơn giản, ngon như nhà hàng', 'Mồng tơi có tác dụng nhuận tràng, thanh nhiệt, trị đau xương khớp, chữa suy nhược, chữa đinh nhọt. Món mồng tơi xào tỏi bình dân nhưng được đưa vào thực đơn nhiều nhà hàng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/08/04/Thnhphm11-1659601393-9580-1659601472.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=nkdtkum0Q_6t1vm0z9zRUQ', 7, 8, 'EASY', 'Cùng thử nấu Cách làm mồng tơi xào tỏi đơn giản, ngon như nhà hàng');
INSERT INTO public.post VALUES (151, '2025-11-20 17:10:07.326104', '2025-11-20 17:10:07.326104', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 153, 'Bí quyết làm miến xào hải sản không bị dính', 'Sợi miến mềm ngon, hải sản khô ráo nước, rau củ quả chín tới giòn ngọt, vị hài hòa rất hấp dẫn.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2022/07/03/Thnhphm11-1656836818-4218-1656836830.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=r5YeTA-HZ05swtn9N8YuYQ', 15, 15, 'HARD', 'Cùng thử nấu Bí quyết làm miến xào hải sản không bị dính');
INSERT INTO public.post VALUES (178, '2025-11-20 17:10:11.000004', '2025-11-20 17:10:11.000004', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 180, 'Cách nấu canh cà bung thịt đậu dân dã mà bổ dưỡng miền Bắc', 'Cà tím mềm ngọt quyện thịt béo ngậy, đậu phụ bùi bùi, nước canh sóng sánh ánh vàng giúp bữa ăn ngày chớm hè trở nên ngon miệng, bổ dưỡng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/04/09/Thnhphm11-1649496090-7838-1649496117.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=soxjdhOfmrAXDWNp6SSOqQ', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách nấu canh cà bung thịt đậu dân dã mà bổ dưỡng miền Bắc');
INSERT INTO public.post VALUES (192, '2025-11-20 17:10:13.006496', '2025-11-20 17:10:13.006496', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 194, 'Cách làm cơm cháy kho quẹt giòn rụm ăn kèm rau củ quả', 'Cơm cháy giòn rụm, chấm kho quẹt sánh sệt đậm đà, thêm rau củ quả luộc thì bao cao sơn hào hải vị đều nhường chỗ.', 'Ninh Bình', 'https://i1-giadinh.vnecdn.net/2022/03/17/Bc77-1647495372-7797-1647495700.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=6raftNDqN4dBoyV11h4NkA', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách làm cơm cháy kho quẹt giòn rụm ăn kèm rau củ quả');
INSERT INTO public.post VALUES (207, '2025-11-20 17:10:15.056233', '2025-11-20 17:10:15.056233', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 209, 'Trứng cá chiên lá lốt - món ngon dân dã Thái Bình', 'Trứng cá vàng ươm, đượm vị, thoảng chút hương mộc từ lá lốt của làng quê. Đây là món ăn giàu omega 3 rất tốt cho trẻ em và phụ nữ.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2021/12/10/Thnhphm4a-1639113523-4681-1639113593.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3n4e2LaqgdzEpC6Cz3Jrgg', 10, 10, 'EASY', 'Cùng thử nấu Trứng cá chiên lá lốt - món ngon dân dã Thái Bình');
INSERT INTO public.post VALUES (222, '2025-11-20 17:10:17.270942', '2025-11-20 17:10:17.270942', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 224, 'Cách làm Phở heo quay Cao Bằng vị ngon đúng điệu', 'Sợi phở trắng mềm, ăn kèm thịt heo quay giòn rụm bên ngoài, bên trong mềm, gia vị đậm đà tạo nên vị ngon đúng điệu.', 'Cao Bằng', 'https://i1-giadinh.vnecdn.net/2021/11/14/phoheo-1636862212-7974-1636862512.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Gv5WFbvoMsJPqDrnI8Uznw', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm Phở heo quay Cao Bằng vị ngon đúng điệu');
INSERT INTO public.post VALUES (237, '2025-11-20 17:10:19.439948', '2025-11-20 17:10:19.439948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 239, 'Cách làm Niễng xào trứng vừa giòn vừa ngậy', 'Niễng trắng, vừa giòn vừa ngậy kết hợp với trứng làm nên đặc sản thành Nam khi vào đông.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2021/11/14/Thnhphm2-1636857715-6514-1636857723.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_9wwKw2Fdi3WYCeziLnXiA', 15, 15, 'EASY', 'Cùng thử nấu Cách làm Niễng xào trứng vừa giòn vừa ngậy');
INSERT INTO public.post VALUES (252, '2025-11-20 17:10:21.728526', '2025-11-20 17:10:21.728526', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 254, 'Các món từ cơm - quen mà lạ', 'Cũng món cơm thường ngày nhưng khi kết hợp với nhiều loại thực phẩm khác nhau, bữa ăn sẽ thịnh soạn và hấp dẫn hơn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/04/combatbuu-1635997563-9626-1635997570.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9cS5Q4lheJW1NTwOxNt9oA', 0, 0, 'MEDIUM', 'Cùng thử nấu Các món từ cơm - quen mà lạ');
INSERT INTO public.post VALUES (267, '2025-11-20 17:10:24.053618', '2025-11-20 17:10:24.053618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 269, 'Cơm dừa tôm rang Bến Tre', 'Thơm lừng, ngầy ngậy trong từng hạt cơm chính là cảm nhận của nhiều người về món cơm dừa - đặc sản Bến Tre. Cơm dừa thường được ăn kèm tôm rang.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/31/comdua-1635643814-1902-1635644329.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ZUBEAQGpFiqfaV5frXnsGA', 45, 45, 'MEDIUM', 'Cùng thử nấu Cơm dừa tôm rang Bến Tre');
INSERT INTO public.post VALUES (282, '2025-11-20 17:10:26.537119', '2025-11-20 17:10:26.537119', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 284, 'Canh mướp tôm', 'Món canh mướp tôm vừa ngon vừa mát, rất hợp trong những ngày hè nóng bức này.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/18/canhmuoptomtuoithumbnail-16345-5831-4132-1634551236.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=N3V9P-r04YaOSMLLeCa9IQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh mướp tôm');
INSERT INTO public.post VALUES (297, '2025-11-20 17:10:29.27567', '2025-11-20 17:10:29.27567', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 299, 'Sườn hầm rau củ', 'Món ăn dễ làm này không chỉ ngon miệng mà còn cung cấp khá đầy đủ các chất dinh dưỡng do thành phần nguyên liệu có cả đạm và nhiều loại rau củ.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/11/canhsuonnamraucuthumbnail-1633-5028-8225-1633941205.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=PIMlCYZrf-FdCMPKwUsMsw', 0, 0, 'EASY', 'Cùng thử nấu Sườn hầm rau củ');
INSERT INTO public.post VALUES (312, '2025-11-20 17:10:32.167378', '2025-11-20 17:10:32.167378', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 314, 'Cách nấu xôi xéo dẻo thơm bằng nồi cơm điện', 'Hạt xôi dẻo mềm, vàng ươm, căng bóng quyện với đậu xanh mịn màng, bùi bùi thêm hành phi giòn rụm, béo ngậy rất hấp dẫn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/08/nh1-1633673448-8968-1633673738.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=6pP5J0meHuVzEM4tCIJ1Fg', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách nấu xôi xéo dẻo thơm bằng nồi cơm điện');
INSERT INTO public.post VALUES (327, '2025-11-20 17:10:35.020201', '2025-11-20 17:10:35.020201', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 329, 'Gà xào hạnh nhân', 'Món thăn gà xào với hạnh nhân rất ngon, mùi thơm hấp dẫn.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2021/10/09/gaxaohanhnhan-1633751574-8897-1633751593.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=1DNuITUng_-XTukALvIKCw', 0, 0, 'MEDIUM', 'Cùng thử nấu Gà xào hạnh nhân');
INSERT INTO public.post VALUES (122, '2025-11-20 17:10:01.297065', '2025-11-20 17:10:01.297065', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 124, 'Cách làm bò xào sả ớt mềm ngon chỉ trong 15 phút', 'Thịt bò chín tới mềm ngọt tự nhiên, không bị khô, quyện vị the cay từ ớt, dậy mùi thơm từ sả rất hấp dẫn. Một món ăn đơn giản lại ngon miệng mà thời gian chế biến chỉ trong 15 phút.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2022/09/29/-3320-1664442768.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=OpbX6NGZUWfQX3fxjKPazw', 7, 8, 'MEDIUM', 'Cùng thử nấu Cách làm bò xào sả ớt mềm ngon chỉ trong 15 phút');
INSERT INTO public.post VALUES (137, '2025-11-20 17:10:04.355975', '2025-11-20 17:10:04.355975', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 139, 'Cách làm món thăn lợn rim tiêu ngon đậm đà hết sạch nồi cơm', 'Với nguyên liệu và cách làm đơn giản, thăn lợn rim tiêu là món ăn trân quý thời xưa, được ưu ái trong thực đơn cho bà đẻ, người ốm, người già.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/08/03/Thnhphm11-1659499459-6335-1659499555.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9jrJJWOwpWc-Q7n6utsk0A', 7, 8, 'EASY', 'Cùng thử nấu Cách làm món thăn lợn rim tiêu ngon đậm đà hết sạch nồi cơm');
INSERT INTO public.post VALUES (152, '2025-11-20 17:10:07.422097', '2025-11-20 17:10:07.422097', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 154, 'Cách nấu canh bầu tôm ngon ngọt thanh hương vị đồng quê', 'Tùy theo khẩu vị mà mỗi người, mỗi vùng miền băm hoặc nạo bầu nấu cùng tôm nõn hoặc giã đầu râu tôm, tép nấu riêu đều ngọt thơm.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2022/06/28/Canhbau-1656411884-8490-1656411891.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=AdJviCX9bH7gdyaWsWEuqg', 15, 15, 'EASY', 'Cùng thử nấu Cách nấu canh bầu tôm ngon ngọt thanh hương vị đồng quê');
INSERT INTO public.post VALUES (197, '2025-11-20 17:10:13.721967', '2025-11-20 17:10:13.721967', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 199, 'Cách làm cá trắm nướng riềng mẻ chuẩn vị', 'Lớp da cá giòn thơm, thịt mềm chua dịu từ mẻ, màu vàng ươm, thơm mùi riềng, cuốn cùng rau sống thêm bún, chấm ngập nước mắm chua ngọt rất ngon.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/02/18/Bc6-1645171205-3759-1645171450.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=m5Gcs0dkjOF3Q5oSvfExjA', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm cá trắm nướng riềng mẻ chuẩn vị');
INSERT INTO public.post VALUES (212, '2025-11-20 17:10:15.664937', '2025-11-20 17:10:15.664937', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 214, 'Xôi gà nước cốt dừa đậu phộng béo ngậy', 'Những hạt xôi dẻo thơm, quyện chút béo ngậy của nước cốt dừa và gà chiên mỡ hành sẽ là món ăn lý tưởng vào mùa đông.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/11/22/anhdaidien-1637556047-8013-1637556068.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=cKHBOk9dHqmjbonFwJ-7dA', 22, 23, 'MEDIUM', 'Cùng thử nấu Xôi gà nước cốt dừa đậu phộng béo ngậy');
INSERT INTO public.post VALUES (227, '2025-11-20 17:10:18.131061', '2025-11-20 17:10:18.131061', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 229, 'Những món ngon cho mùa heo may', 'Canh rong biển sườn non, bò kho ớt, bí đỏ xào nghêu và ếch tay cầm - những món ăn với hương vị đậm đà - sẽ làm cho bữa cơm gia đình bạn trong những ngày chớm thu thêm ấm cúng.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2021/11/18/echxao1-1637225037-3375-1637225105.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kCKG5pVlQtmvFYzjhNTy6Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Những món ngon cho mùa heo may');
INSERT INTO public.post VALUES (242, '2025-11-20 17:10:20.232133', '2025-11-20 17:10:20.232133', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 244, 'Hai món ngon mang vị ngọt cam thảo', 'Bề ngoài khô cứng, xù xì, chẳng có gì đẹp mắt, nhưng cam thảo lại có vị ngọt nhẹ, thanh nhưng thấm sâu vào tận cuống lưỡi. Dưới đây là 2 món ăn được chế biến cùng cam thảo đem lại hiệu quả tốt cho sức khỏe.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/11/changioham-1636623228-2201-1636623310.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=yhEHsbFOV0ToNnfYQTBMUA', 0, 0, 'MEDIUM', 'Cùng thử nấu Hai món ngon mang vị ngọt cam thảo');
INSERT INTO public.post VALUES (257, '2025-11-20 17:10:22.429761', '2025-11-20 17:10:22.429761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 259, 'Thực đơn lạ miệng mà bắt mắt', 'Một bữa ăn với nhiều màu rực rỡ, lại đem đến những hương vị mới sẽ làm cho gia đình bạn ngạc nhiên. Hãy cùng trổ tài vào dịp cuối tuần này nhé.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/03/gasotcachua-1635930220-2253-1635930322.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EFzAGPCD7Wfgv7YfyoAc9g', 0, 0, 'EASY', 'Cùng thử nấu Thực đơn lạ miệng mà bắt mắt');
INSERT INTO public.post VALUES (272, '2025-11-20 17:10:24.903967', '2025-11-20 17:10:24.903967', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 274, 'Mực xào tam sắc', 'Không mất nhiều thời gian, không quá cầu kỳ, món mực xào tam sắc ngon, đẹp mắt sẽ làm bữa ăn của gia đình bạn thêm đầm ấm.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/10/21/mucxao-1634791524-8363-1634791758.png?w=0&h=0&q=100&dpr=2&fit=crop&s=BNicm39jjtQeowSjjXRNWw', 0, 0, 'MEDIUM', 'Cùng thử nấu Mực xào tam sắc');
INSERT INTO public.post VALUES (287, '2025-11-20 17:10:27.425493', '2025-11-20 17:10:27.425493', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 289, 'Thịt thăn cuộn trái cây', 'Món thịt thăn cuộn trái cây nhìn bắt mắt với hương vị thơm ngon sẽ hấp dẫn cả nhà bạn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/17/thitcuon-1634447723-2670-1634447752.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ACokA8dWJKzP0e7pe_LzlQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Thịt thăn cuộn trái cây');
INSERT INTO public.post VALUES (302, '2025-11-20 17:10:30.308394', '2025-11-20 17:10:30.308394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 304, 'Canh chua giò heo', 'Bà nội trợ nào cũng thích những món ăn đơn giản, dễ làm mà lại ngon. Canh chua giò heo hội đủ các tiêu chuẩn đó.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2021/10/14/congthucnaucanhmangmonggiongon-9389-3841-1634186220.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=vM5Lgjy9xuJG0D-Q85BfoA', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh chua giò heo');
INSERT INTO public.post VALUES (317, '2025-11-20 17:10:33.139297', '2025-11-20 17:10:33.139297', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 319, 'Nộm măng chua', 'Nộm măng chua làm đơn giản, ăn giòn, có vị chua cay mặn ngọt rất ngon. Mời bạn tham khảo hướng dẫn để làm món này nhé.', 'Hà Giang', 'https://i1-giadinh.vnecdn.net/2021/10/10/nommang-1633836521-2481-1633836632.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=mlhgrdpgeWvwMoYpyq4vIQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Nộm măng chua');
INSERT INTO public.post VALUES (332, '2025-11-20 17:10:36.098754', '2025-11-20 17:10:36.098754', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 334, 'Đậu hũ chiên sốt tiêu', 'Từ thực phẩm này có thể chế biến thành nhiều món mặn rất ngon như đậu hũ hấp hải sản, canh rong biển đậu hũ và đậu hũ chiên sốt tiêu.', 'Bình Dương', 'https://i1-giadinh.vnecdn.net/2021/10/05/dauhu-1633424017-2963-1633424213.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9Fq0icVFGcnDcDrW4HfGmw', 0, 0, 'HARD', 'Cùng thử nấu Đậu hũ chiên sốt tiêu');
INSERT INTO public.post VALUES (347, '2025-11-20 17:10:38.760612', '2025-11-20 17:10:38.760612', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 349, 'Trứng đúc nấm rán', 'Món ăn đơn giản, chế biến rất nhanh nhưng lại rất "vào cơm". Mời bạn tham khảo hướng dẫn của Ezcooking để chế biến cho bữa cơm gia đình.', 'Hà Nam', 'https://i1-giadinh.vnecdn.net/2021/10/02/trungchien-1633167848-7000-1633167882.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=hMY5D2ygEYuOogPkj_TP0w', 0, 0, 'EASY', 'Cùng thử nấu Trứng đúc nấm rán');
INSERT INTO public.post VALUES (123, '2025-11-20 17:10:01.473037', '2025-11-20 17:10:01.473037', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 125, 'Cách làm cá kho củ cải đưa cơm', 'Cá săn chắc đậm vị, củ cải mềm thấm đượm vị ngọt từ cá, ăn cùng cơm trắng rất hao.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2022/09/25/-9013-1664091892.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=iFCzaO_YIJnVRMYexAUvww', 120, 120, 'MEDIUM', 'Cùng thử nấu Cách làm cá kho củ cải đưa cơm');
INSERT INTO public.post VALUES (125, '2025-11-20 17:10:02.31197', '2025-11-20 17:10:02.31197', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 127, 'Cách nấu xôi trám - thức quà mùa thu', 'Xôi trám màu hồng tím căng mẩy, hương thơm tỏa ra nồng nàn, quyện vị bùi béo từ trám đen, chấm với muối vừng gây thương nhớ cho bao người mỗi độ thu sang.', 'Bắc Giang', 'https://i1-giadinh.vnecdn.net/2022/09/21/-4907-1663758704.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_6-Jx7RLOBt8uUKMMFxvDA', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách nấu xôi trám - thức quà mùa thu');
INSERT INTO public.post VALUES (129, '2025-11-20 17:10:02.553814', '2025-11-20 17:10:02.553814', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 131, 'Cách làm thịt ba chỉ chiên mắm da giòn, thịt mềm', 'Món ăn dân dã này luôn đưa cơm bất kể vào mùa nào với thịt đẫm nước sốt màu hổ phách đậm đà, da giòn và thịt mềm.', 'Bình Thuận', 'https://i1-giadinh.vnecdn.net/2022/09/12/-7564-1662974673.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=KRY0dEHm_TAY93EvgTbZLg', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách làm thịt ba chỉ chiên mắm da giòn, thịt mềm');
INSERT INTO public.post VALUES (132, '2025-11-20 17:10:03.143708', '2025-11-20 17:10:03.143708', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 134, 'Cách làm ngan xào lăn, giòn ngon như nhà hàng', 'Thịt ngan chín vừa tới ngọt giòn mà không dai, dậy mùi thơm của sả, chút the cay từ ớt giúp cho bữa cơm gia đình thêm hấp dẫn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/08/15/Thnhphm11-1660554387-8894-1660554460.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=j5RCT6B0MmLuyxLOgffMYQ', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm ngan xào lăn, giòn ngon như nhà hàng');
INSERT INTO public.post VALUES (138, '2025-11-20 17:10:04.673282', '2025-11-20 17:10:04.673282', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 140, 'Cách làm tàu hủ khìa nước dừa đơn giản mà hao cơm', 'Tàu hủ lên màu vàng đỏ bắt mắt, đậu bên ngoài dẻo dai, bên trong mềm mại, nước sốt sánh sệt hài hòa vị mặn ngọt đẩy đưa vị giác rất ''hao cơm''.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2022/08/02/Thnhphm11-1659429644-6056-1659429677.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-OCPmSYpxru6lkD1zE6Zeg', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm tàu hủ khìa nước dừa đơn giản mà hao cơm');
INSERT INTO public.post VALUES (140, '2025-11-20 17:10:05.272953', '2025-11-20 17:10:05.272953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 142, 'Cách làm tôm chiên xù sốt me đổi vị cho bữa cơm gia đình', 'Tôm vỏ ngoài giòn rụm, bên trong ngọt mềm, sốt me chua ngọt hài hòa vị là món ăn dễ làm, có thể làm món đổi vị cho bữa cơm gia đình.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2022/07/25/Bc6Thnhphm1-1658735220-3434-1658735331.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eKq2aakdBEV8UxkcpbHLOw', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm tôm chiên xù sốt me đổi vị cho bữa cơm gia đình');
INSERT INTO public.post VALUES (144, '2025-11-20 17:10:06.138638', '2025-11-20 17:10:06.138638', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 146, 'Cách làm chim cút chiên bơ da giòn, mềm như nhà hàng', 'Thịt chim mềm ngọt, thấm vị, lớp da bên ngoài giòn thơm, màu lên bóng mướt, óng ả hấp dẫn.', 'Tây Ninh', 'https://i1-giadinh.vnecdn.net/2022/07/18/Bc55-1658130185-7241-1658130303.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=fOsPM5HHMXLOnpUq5o88vw', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm chim cút chiên bơ da giòn, mềm như nhà hàng');
INSERT INTO public.post VALUES (147, '2025-11-20 17:10:06.75691', '2025-11-20 17:10:06.75691', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 149, 'Cách làm bún dọc mùng Hà Nội', 'Bún dọc mùng Hà Nội còn có tên bún bung, bún ''''ngứa lưỡi'''' được nhiều người yêu thích bởi thịt chân giò mềm, móng giò sần sật, dọc mùng giòn, mọc mềm ngọt, nước thanh nhẹ.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/07/14/Bc88-1657791327-5742-1657791673.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=xbBbxrYHrt9QfVlVl3Rn4w', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm bún dọc mùng Hà Nội');
INSERT INTO public.post VALUES (153, '2025-11-20 17:10:07.498831', '2025-11-20 17:10:07.498831', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 155, 'Cách nấu canh hoa thiên lý giải nhiệt ngày hè', 'Hoa thiên lý màu xanh tươi, giò chín tới, tôm mềm, nước canh thanh ngọt hấp dẫn. Đây là món canh phổ biến của vùng đồng bằng Bắc Bộ giúp giải nhiệt trong những ngày hè.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/06/22/Thnhphm11-1655873576-2132-1655873588.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=TQ5nuHVxrw39ZkwufuBqyw', 12, 13, 'EASY', 'Cùng thử nấu Cách nấu canh hoa thiên lý giải nhiệt ngày hè');
INSERT INTO public.post VALUES (155, '2025-11-20 17:10:07.752284', '2025-11-20 17:10:07.752284', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 157, 'Cách làm nộm sứa xoài xanh thanh mát ngày hè', 'Món ăn là sự tổng hòa của sứa giòn, xoài chua thanh, rau thơm dậy mùi kích thích vị giác trong tiết trời nóng nực.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2022/06/01/Thnhphm11-1654074613-3746-1654074619.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qZ5MkwlO_qiZ51IkfpSNcg', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm nộm sứa xoài xanh thanh mát ngày hè');
INSERT INTO public.post VALUES (159, '2025-11-20 17:10:08.245121', '2025-11-20 17:10:08.245121', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 161, 'Cách làm sấu ngâm mắm tỏi ớt cay ngọt, ngon giòn để được lâu', 'Sấu giòn đượm vị chua cay mặn ngọt, thơm mùi riềng tỏi, ăn cùng thịt luộc, rau củ quả luộc thì cao lương mĩ vị cũng khó sánh bằng trong mùa hè oi bức.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/06/06/Thnhphm11-1654510497-3297-1654510582.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=idpIR33lJNIowWm7-4rdFQ', 10, 10, 'MEDIUM', 'Cùng thử nấu Cách làm sấu ngâm mắm tỏi ớt cay ngọt, ngon giòn để được lâu');
INSERT INTO public.post VALUES (162, '2025-11-20 17:10:08.736183', '2025-11-20 17:10:08.736183', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 164, 'Cách nấu cháo sườn gan ngô xào Đài Loan ngọt bùi, thơm ngon', 'Cháo ngọt thơm, hạt gạo nở bung, gan bùi bùi, sườn đậm vị, ngô giòn ngọt, tất cả quyện hòa đa màu sắc, cuốn hút tín đồ ẩm thực từ cái nhìn đầu tiên.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/06/04/Thnhphm11-1654330238-4869-1654330263.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=vBQtx0dWVu4RbgDEBUbqwA', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách nấu cháo sườn gan ngô xào Đài Loan ngọt bùi, thơm ngon');
INSERT INTO public.post VALUES (174, '2025-11-20 17:10:10.410023', '2025-11-20 17:10:10.410023', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 176, 'Cách nấu cá trắm kho mật mía đượm vị, không cần nước', 'Không dùng nước màu hay nước dừa nhưng khi kho mật mía quyện nước mắm thẩm thấu từng thớ cá, ra màu nâu đỏ đẹp tựa vân gỗ trắc. Thịt cá chắc nịch, đượm vị mặn ngọt làm nên món ngon xứ Nghệ.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2022/04/15/Thnhphm22-1650017101-9303-1650017295.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=R57l7nBRO0b6Jgs2yewasg', 120, 120, 'EASY', 'Cùng thử nấu Cách nấu cá trắm kho mật mía đượm vị, không cần nước');
INSERT INTO public.post VALUES (124, '2025-11-20 17:10:01.704651', '2025-11-20 17:10:01.704651', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 126, 'Cách làm món cà pháo ram thịt ba chỉ, lá lốt', 'Thịt ba rọi xém cạnh đậm vị quyện với cà pháo vị chua ngọt hài hòa, dậy mùi thơm của lá lốt kích thích vị giác. Món ăn bình dân này làm thực đơn ngày thu ngon miệng.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2022/09/27/-7662-1664264782.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-z1KlwbwRHel0JMFibF3Og', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm món cà pháo ram thịt ba chỉ, lá lốt');
INSERT INTO public.post VALUES (139, '2025-11-20 17:10:04.984881', '2025-11-20 17:10:04.984881', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 141, 'Cách nấu giả cầy An Phú - món ngon đặc sản Thái Bình', 'Khác với giả cầy Hà Nội đặc trưng bởi vị chua, giả cầy Nghệ An đượm vị ngọt mật mía, giả cầy miền Tây thơm mùi chao thì giả cầy An Phú (Thái Bình) hấp dẫn bằng sự mộc mạc.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2022/07/26/Thnhphm11-1658822402-6808-1658822507.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=B_BWM_XsSYPKNjpPkAxpDg', 25, 25, 'EASY', 'Cùng thử nấu Cách nấu giả cầy An Phú - món ngon đặc sản Thái Bình');
INSERT INTO public.post VALUES (154, '2025-11-20 17:10:07.593748', '2025-11-20 17:10:07.593748', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 156, 'Cách làm ốc kho sả ớt cay giòn, ngon ngọt đậm vị miền Tây', 'Ốc kho sả ớt dậy mùi thơm đặc trưng của sả, ốc giòn sần sật, vị mặn ngọt cay hài hòa, ăn cùng cơm trắng rất ngon.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2022/05/27/Thnhphm11-1653667242-4404-1653667355.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ZI1kJAjBzseS0b3E5ClSEQ', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm ốc kho sả ớt cay giòn, ngon ngọt đậm vị miền Tây');
INSERT INTO public.post VALUES (166, '2025-11-20 17:10:09.33422', '2025-11-20 17:10:09.33422', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 168, 'Cách nấu canh cua đóng tảng, không bị tanh trong ngày hè nóng bức', 'Bát canh với nước dùng ngon ngọt, thịt cua đóng tảng, rau xanh mướt ăn cùng cà pháo giòn, đậu phụ chiên vàng thì bao mệt mỏi đều tan biến trong mùa hè.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2022/05/12/Bc55-1652348830-7796-1652348956.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=fXxVq_TTPqCsd7Ty7kfdYQ', 20, 20, 'EASY', 'Cùng thử nấu Cách nấu canh cua đóng tảng, không bị tanh trong ngày hè nóng bức');
INSERT INTO public.post VALUES (179, '2025-11-20 17:10:11.100919', '2025-11-20 17:10:11.100919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 181, 'Cách làm canh riêu cá Bắc Bộ chua mát giải nhiệt ngày hè', 'Thịt cá ngọt mềm tự nhiên, có vị chua dịu từ mẻ, màu đỏ từ cà chua giúp bữa cơm ngày hè ngon miệng mà cách làm lại đơn giản.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2022/05/19/Thnhphm11-1652946808-7614-1652946948.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=aDpOJ9C6vujoS8g6IW76ww', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm canh riêu cá Bắc Bộ chua mát giải nhiệt ngày hè');
INSERT INTO public.post VALUES (193, '2025-11-20 17:10:13.110192', '2025-11-20 17:10:13.110192', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 195, 'Cách nấu xôi ngô đúng chuẩn', 'Hạt xôi căng bóng mềm dẻo quyện với ngô ngọt bùi, dừa nạo sần sật, nước cốt dừa béo ngậy rất ngon.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/02/25/Thnhphm1-1645781039-6596-1645781140.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Io7jWW-dXM08WWaTP3hGpg', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách nấu xôi ngô đúng chuẩn');
INSERT INTO public.post VALUES (208, '2025-11-20 17:10:15.178315', '2025-11-20 17:10:15.178315', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 210, 'Canh móng giò hầm đu đủ cho phụ nữ sau sinh', 'Móng giò mềm mà không ngậy, đu đủ ngọt mát làm nên món ngon bổ dưỡng cho phụ nữ sau sinh.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/12/10/Thnhphm1a-1639112294-5748-1639112308.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gTjMwKz_xIxUi2KxhO9-UA', 30, 30, 'EASY', 'Cùng thử nấu Canh móng giò hầm đu đủ cho phụ nữ sau sinh');
INSERT INTO public.post VALUES (223, '2025-11-20 17:10:17.499485', '2025-11-20 17:10:17.499485', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 225, 'Cách chế biến vài món Âu đơn giản', 'Các món ăn Âu dưới đây mang phong cách pha trộn Âu - Á, vừa không làm mất đi hương vị gốc của món ăn vừa không ngán.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/11/22/lauhaisan-1637550605-2072-1637551410.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_1uL-FK7SY7vE2DI_g5PRA', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách chế biến vài món Âu đơn giản');
INSERT INTO public.post VALUES (238, '2025-11-20 17:10:19.619799', '2025-11-20 17:10:19.619799', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 240, 'Cá chạch nấu hoa chuối - món ngon Thái Bình', 'Cá chạch mềm ngọt tự nhiên quyện trong hoa chuối chát nhẹ, nước canh sánh vàng, chua thanh, dậy mùi thơm của các rau gia vị lá lốt, tía tô rất hấp dẫn.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2021/11/12/Thnhphm3-1636727898-8669-1636728072.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Bi7HbleEeMe2ME-8i8e5mw', 30, 30, 'MEDIUM', 'Cùng thử nấu Cá chạch nấu hoa chuối - món ngon Thái Bình');
INSERT INTO public.post VALUES (253, '2025-11-20 17:10:21.865784', '2025-11-20 17:10:21.865784', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 255, 'Canh chua cá trê', 'Món canh chua cá trê giới thiệu với bạn dưới đây được nấu theo kiểu miền Trung. Món này dùng măng chua, khế... để tạo vị chua cho nước canh chứ không dùng me như người miền Nam hoặc thêm mẻ, tai chua, quả sấu... như miền Bắc.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/11/09/cachlamcanhchua-1636441165-8934-1636441370.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=iMGxjqkaUJinNk2rXhPGfg', 0, 0, 'EASY', 'Cùng thử nấu Canh chua cá trê');
INSERT INTO public.post VALUES (268, '2025-11-20 17:10:24.165108', '2025-11-20 17:10:24.165108', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 270, 'Chả giò tôm cuộn', 'Chả giò tôm cuộn là món ăn giàu dinh dưỡng, có vị thơm ngon, béo, có thể ăn kèm với dưa leo ướp lạnh.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/23/chagio-1634963519-3087-1634963630.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=8SQ03P9Rj4Ovu5wv_RaGBA', 0, 0, 'EASY', 'Cùng thử nấu Chả giò tôm cuộn');
INSERT INTO public.post VALUES (283, '2025-11-20 17:10:26.638847', '2025-11-20 17:10:26.638847', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 285, 'Càng cua đồng rang muối ớt', 'Càng cua đồng luộc sơ, rang chín bằng muối ớt. Càng cua chín vàng, chấm muối tiêu chanh rất hợp vị.', 'An Giang', 'https://i1-giadinh.vnecdn.net/2021/10/17/cangcua-1634448046-2763-1634448217.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eN_ToYda6R4VPRnba70_bQ', 0, 0, 'EASY', 'Cùng thử nấu Càng cua đồng rang muối ớt');
INSERT INTO public.post VALUES (298, '2025-11-20 17:10:29.508734', '2025-11-20 17:10:29.508734', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 300, 'Canh vịt nấu măng', 'Món này làm rất đơn giản, phù hợp với bữa cơm ngày thường của gia đình bạn. Bạn thử trổ tài nhé.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/12/1584527692190158452757570024th-5955-6721-1634030031.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=X-nXWHN6_jpF1xVUQyM7EQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh vịt nấu măng');
INSERT INTO public.post VALUES (313, '2025-11-20 17:10:32.373022', '2025-11-20 17:10:32.373022', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 315, 'Mực xào rối', 'Mực xào rối có mùi thơm hấp dẫn với vị ngọt đậm của thịt mực, hơi cay.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/10/08/muc-1633693183-5002-1633693218.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VfRC3K-sfnTTNbi92BkEtQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Mực xào rối');
INSERT INTO public.post VALUES (126, '2025-11-20 17:10:02.317987', '2025-11-20 17:10:02.317987', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 128, 'Cách nấu canh bầu nhồi thịt ngọt mát', 'Theo Đông y, quả bầu vị ngọt, tính hàn có tác dụng trừ độc, giải nhiệt, nhuận phổi... canh bầu nhồi thịt đơn giản lại bổ dưỡng rất tốt cho những ngày chuyển mùa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/09/17/-8521-1663409152.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=6zYagwtSmeuThNUMl59mew', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách nấu canh bầu nhồi thịt ngọt mát');
INSERT INTO public.post VALUES (130, '2025-11-20 17:10:02.760252', '2025-11-20 17:10:02.760252', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 132, 'Cách làm món cá nướng muối ớt đổi vị cuối tuần', 'Thịt cá da giòn, bên trong mềm ngọt, dậy mùi thơm của sả, tỏi, vị cay tê lưỡi từ ớt, vị mặn ngọt hài hòa. Món này khi ăn cuốn cùng bún, các loại rau củ chấm nước mắm chua ngọt rất hấp dẫn.', 'Phú Yên', 'https://i1-giadinh.vnecdn.net/2022/08/27/Thnhphm22-1661595206-1821-1661595348.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=viRQlXEm9gvyqxvjTluKXA', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm món cá nướng muối ớt đổi vị cuối tuần');
INSERT INTO public.post VALUES (141, '2025-11-20 17:10:05.435522', '2025-11-20 17:10:05.435522', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 143, 'Bí quyết cách làm bê tái chanh thịt mềm, bì giòn', 'Thịt bê mềm ngọt, bì giòn, dậy mùi thơm của sả, chút the cay của ớt, vị chua cay mặn ngọt hài hòa. Cuốn bánh tráng ăn cùng khế chua, chuối xanh, dứa rồi chấm tương bần rất ngon.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2022/07/29/Thnhphm11-1659083954-7258-1659084041.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=AQh_kn0Sntsdhvjm6zUSVw', 22, 23, 'MEDIUM', 'Cùng thử nấu Bí quyết cách làm bê tái chanh thịt mềm, bì giòn');
INSERT INTO public.post VALUES (145, '2025-11-20 17:10:06.317429', '2025-11-20 17:10:06.317429', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 147, 'Cách làm miến măng vịt thơm ngon tại nhà', 'Thịt vịt mềm ngọt, nước dùng hài hòa vị, măng tươi giòn sần sật, miến trong dai thu hút từ cái nhìn đầu tiên.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/07/16/Bc88-1657962765-7986-1657962796.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=BFkwJLDvY6yLP_Yt_5UupA', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm miến măng vịt thơm ngon tại nhà');
INSERT INTO public.post VALUES (156, '2025-11-20 17:10:07.902699', '2025-11-20 17:10:07.902699', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 158, 'Cách làm mướp xào lòng gà đơn giản mà hết cả nồi cơm', 'Chỉ 20 phút chế biến, bạn đã có món ăn thanh mát, đưa cơm ngày hè với mướp xanh giòn, ngọt thơm, giá đỗ chín vừa tới, lòng gà vị hài hòa.', 'Hà Nam', 'https://i1-giadinh.vnecdn.net/2022/06/13/Thnhphm11-1655101584-1536-1655101618.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=YfMKP-db9p_d_fw9K0ezXQ', 10, 10, 'MEDIUM', 'Cùng thử nấu Cách làm mướp xào lòng gà đơn giản mà hết cả nồi cơm');
INSERT INTO public.post VALUES (160, '2025-11-20 17:10:08.353824', '2025-11-20 17:10:08.353824', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 162, 'Cách nấu canh rau ngót riêu tép ngọt mát ngày nóng', 'Một bát canh với rau ngót xanh mềm, riêu tép ngọt thơm, thanh mát, nhanh chóng xua tan những mệt mỏi ngày nóng bức.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/06/16/Thnhphm11-1655367025-2668-1655367055.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=QxHw5tzJBFD9YkJD8jrdGQ', 15, 15, 'EASY', 'Cùng thử nấu Cách nấu canh rau ngót riêu tép ngọt mát ngày nóng');
INSERT INTO public.post VALUES (167, '2025-11-20 17:10:09.500277', '2025-11-20 17:10:09.500277', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 169, 'Cách làm thịt luộc chấm mắm tép ''đưa cơm'' ngày hè', 'Thịt luộc vừa chín tới mềm ngọt chấm mắm tép vàng đượm, vị mặn ngọt chua cay hài hòa rất đưa miệng. Đây là món ăn bình dân mà lại ''hao cơm'' ngày hè.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2022/05/06/Thnhphm1-1651830305-9830-1651830313.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eyCf3jcakcA4MMnsnQoKGQ', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm thịt luộc chấm mắm tép ''đưa cơm'' ngày hè');
INSERT INTO public.post VALUES (168, '2025-11-20 17:10:09.653458', '2025-11-20 17:10:09.653458', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 170, 'Cách làm cà bát muối xổi chua mặn chấm mắm tôm ăn kèm cơm nóng', 'Cà thơm mùi riềng tỏi ớt, chấm mắm tôm đánh nổi bông, ăn cùng cơm trắng, canh cua rau đay đặc biệt hấp dẫn trong bữa cơm ngày hè.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/05/27/Thnhphm11-1653666342-7360-1653666489.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MS9oV1_byPUtNJDvgNc2gw', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm cà bát muối xổi chua mặn chấm mắm tôm ăn kèm cơm nóng');
INSERT INTO public.post VALUES (171, '2025-11-20 17:10:09.902695', '2025-11-20 17:10:09.902695', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 173, 'Cách làm tôm rang thịt ba chỉ măn ngọt, béo ngậy ngon cơm', 'Tôm vỏ săn giòn tươm mỡ, màu đỏ au quyện với thịt ba chỉ béo ngậy, dậy mùi thơm của hành rất ''đưa cơm'' ngày hè.', 'Tiền Giang', 'https://i1-giadinh.vnecdn.net/2022/04/24/Thnhphm11-1650794591-8925-1650794631.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=WJWVUf5WAXnxZ0MWpX_yPw', 17, 18, 'EASY', 'Cùng thử nấu Cách làm tôm rang thịt ba chỉ măn ngọt, béo ngậy ngon cơm');
INSERT INTO public.post VALUES (172, '2025-11-20 17:10:10.1154', '2025-11-20 17:10:10.1154', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 174, 'Cách nấu ốc om chuối đậu ngậy bùi, thơm ngon chuẩn vị Bắc', 'Ốc giòn sần sật, chuối bùi bùi quyện thịt ba chỉ béo ngậy, nước sóng sánh vàng gây thương nhớ cho những người xa xứ.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/04/23/Thnhphm11-1650708457-7748-1650708542.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=HULca9Z8ZNKBeFlEDgO9Tg', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách nấu ốc om chuối đậu ngậy bùi, thơm ngon chuẩn vị Bắc');
INSERT INTO public.post VALUES (180, '2025-11-20 17:10:11.601735', '2025-11-20 17:10:11.601735', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 182, 'Cách làm gà quay tiêu đen kiểu KFC ngon hơn ngoài quán', 'Thịt gà da vàng óng, bên trong mềm ngọt, mọng nước quyện trong nước sốt sánh, dậy mùi thơm nồng, cay cay của tiêu đen rất hấp dẫn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/04/06/Thnhphm11-1649253955-6972-1649254024.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=tPU-5XZofCtppAVWV7iQpQ', 30, 30, 'HARD', 'Cùng thử nấu Cách làm gà quay tiêu đen kiểu KFC ngon hơn ngoài quán');
INSERT INTO public.post VALUES (184, '2025-11-20 17:10:11.996318', '2025-11-20 17:10:11.996318', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 186, 'Cách làm nộm rau muống giòn ngon, thanh mát', 'Rau muống xanh non, giòn sần sật quyện lạc rang bùi bùi, vị chua - cay - mặn - ngọt hài hòa tạo như một bức họa đồng quê với sắc màu thu hút.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/03/31/Thnhphm11-1648718365-3341-1648718458.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=BxECoTs7aNjg4zWLg1yd-g', 20, 20, 'EASY', 'Cùng thử nấu Cách làm nộm rau muống giòn ngon, thanh mát');
INSERT INTO public.post VALUES (186, '2025-11-20 17:10:12.257099', '2025-11-20 17:10:12.257099', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 188, 'Cách làm cá lóc kho tiêu kiểu Nam Bộ đậm đà hao cơm', 'Cá săn chắc bóng đẹp, vị đậm đà, nước kho sánh sệt, dậy mùi thơm của hạt tiêu, hành lá ăn rất hao cơm vào bất kể mùa nào.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2022/03/30/Thnhphm11-1648629123-3101-1648629260.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0-Fu_Goej0HKdQgiD6xHJg', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm cá lóc kho tiêu kiểu Nam Bộ đậm đà hao cơm');
INSERT INTO public.post VALUES (127, '2025-11-20 17:10:02.328168', '2025-11-20 17:10:02.328168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 129, 'Cách làm ếch xào măng - món chân quê vào nhà hàng', 'Thịt ếch dai ngon, măng chua giòn, thêm chút the cay từ ớt, thoảng mùi thơm từ hành lá, rau mùi tàu. Món dân dã này ăn chơi lai rai hay ăn cơm đều ngon.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2022/08/28/Thnhphm11-1661673426-3858-1661673463.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=lHDULZ7iUdztPxaJhBKw6A', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm ếch xào măng - món chân quê vào nhà hàng');
INSERT INTO public.post VALUES (142, '2025-11-20 17:10:05.728978', '2025-11-20 17:10:05.728978', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 144, 'Cách làm mì tôm xào bò đơn giản, ngon như nhà hàng', 'Sợi mì mềm dai, thịt bò ngọt tự nhiên, các rau củ quả xanh giòn, khô ráo. Món ăn đơn giản nhưng lại được nhiều người yêu thích.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/07/30/Thnhphm11-1659167224-6461-1659167238.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=SPXB9KKfbPV8te___7J5Vg', 10, 10, 'MEDIUM', 'Cùng thử nấu Cách làm mì tôm xào bò đơn giản, ngon như nhà hàng');
INSERT INTO public.post VALUES (157, '2025-11-20 17:10:08.000358', '2025-11-20 17:10:08.000358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 159, 'Cách làm cá mai ngào mắm tỏi giòn rụm thơm ngon', 'Món ăn thu hút bởi cá giòn rụm, bề mặt màu vàng nâu óng, vị chua cay mặn ngọt hài hòa, dậy mùi thơm của tỏi, cay của ớt, ăn cùng cơm hay làm mồi nhậu đều ngon.', 'Quảng Ngãi', 'https://i1-giadinh.vnecdn.net/2022/05/25/Thnhphm11-1653448592-9350-1653448623.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_-GkTXNIxHpu2Cs6m4rsew', 20, 20, 'EASY', 'Cùng thử nấu Cách làm cá mai ngào mắm tỏi giòn rụm thơm ngon');
INSERT INTO public.post VALUES (169, '2025-11-20 17:10:09.73987', '2025-11-20 17:10:09.73987', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 171, 'Cách làm cà pháo xào lá lốt đơn giản mà ngon cơm những ngày hè', 'Cà trắng, mềm dẻo, có chút cay nhẹ từ ớt, dậy mùi thơm đặc trưng của lá lốt, nước sóng sánh rất bắt mắt. Món ăn dân dã này được nhiều người yêu thích trong ngày hè.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2022/04/28/Thnhphm11-1651136431-8539-1651136623.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=KWvq3vy4IKsrA6vJ3bY0Sg', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm cà pháo xào lá lốt đơn giản mà ngon cơm những ngày hè');
INSERT INTO public.post VALUES (182, '2025-11-20 17:10:11.809376', '2025-11-20 17:10:11.809376', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 184, 'Cách làm mỳ Ý Spaghetti thịt bò bằm sốt cà chua đơn giản tại nhà', 'Tranh thủ cà chua đang vào mùa ngon và rẻ, bạn đổi vị cho các bé với món mỳ Ý thơm ngon như ngoài hàng.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/04/20/Bc99-1650439459-8855-1650439557.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=iatvSHr9fwWEuRdqPKJHRg', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm mỳ Ý Spaghetti thịt bò bằm sốt cà chua đơn giản tại nhà');
INSERT INTO public.post VALUES (196, '2025-11-20 17:10:13.545516', '2025-11-20 17:10:13.545516', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 198, 'Cách làm nem chim bồ câu đúng chuẩn', 'Món ăn này cùng với su hào xào mực, canh măng mực làm nên mâm cỗ làng gốm Bát Tràng (Hà Nội) mà nhiều người ngợi ca ''''Ăn một miếng, nhớ cả đời''''.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/02/24/Thnhphm3-1645694519-4527-1645694556.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-kLawlw2b26ctHZ1iCr4lA', 40, 40, 'HARD', 'Cùng thử nấu Cách làm nem chim bồ câu đúng chuẩn');
INSERT INTO public.post VALUES (211, '2025-11-20 17:10:15.530941', '2025-11-20 17:10:15.530941', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 213, 'Cá kho dưa đưa cơm ngày lạnh', 'Cá màu nâu đỏ đậm đà, chắc mà không khô, khi ăn thịt và xương như tan ra, ngấm trọn vị chua cay mặn ngọt; dưa chua ngậm tròn vị cá. Đây là món ăn được người già tới trẻ nhỏ đều yêu thích, nhất là vào mùa đông.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2021/12/10/Thnhphm2a-1639111442-7181-1639111636.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eLh9hqFgHjEj_HbH3FOoQg', 300, 300, 'MEDIUM', 'Cùng thử nấu Cá kho dưa đưa cơm ngày lạnh');
INSERT INTO public.post VALUES (226, '2025-11-20 17:10:17.980906', '2025-11-20 17:10:17.980906', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 228, 'Ba chỉ om chuối đậu', 'Thịt ba chỉ săn, béo ngậy, chuối chín mềm mà không bở, đậu giòn, nước sánh vàng ươm tự nhiên. Món này ăn cùng cơm nóng và bún đều rất ngon.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2021/11/26/Thnhphm1-1637899056-4442-1637899251.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Kyv15AJlub3_GPCE52a5eQ', 25, 25, 'MEDIUM', 'Cùng thử nấu Ba chỉ om chuối đậu');
INSERT INTO public.post VALUES (241, '2025-11-20 17:10:20.045502', '2025-11-20 17:10:20.045502', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 243, 'Cá ba sa bọc xôi', 'Nạc cá ba sa quết nhuyễn với mỡ heo, bọc xôi nếp hấp chín. Món ăn này rất thích hợp cho thực đơn cuối tuần của gia đình bạn.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2021/11/09/2cachlammuchaphanhthomlungdayv-1311-8935-1636441774.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=XKI6UVWfXdBVua8n-QeXhQ', 0, 0, 'EASY', 'Cùng thử nấu Cá ba sa bọc xôi');
INSERT INTO public.post VALUES (256, '2025-11-20 17:10:22.313685', '2025-11-20 17:10:22.313685', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 258, '3 món lạ miệng dễ làm', 'Canh gà lá giang, dưa leo trộn sò lông, bò viên sốt cà chua là 3 món hấp dẫn nhưng lại chế biến rất nhanh. Mời bạn cùng tham khảo cách làm và thưởng thức.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/10/25/bovien-1635137436-3154-1635137441.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ZXiWtTUEe-QWKbDEVmMw2w', 0, 0, 'MEDIUM', 'Cùng thử nấu 3 món lạ miệng dễ làm');
INSERT INTO public.post VALUES (271, '2025-11-20 17:10:24.655728', '2025-11-20 17:10:24.655728', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 273, 'Những món rau hấp dẫn bé', 'Những món ăn chế biến từ rau quả dưới đây trông rất bắt mắt với mùi thơm ngon sẽ rất hấp dẫn bé. Mời bạn cùng trổ tài.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/26/soupcachua-1635221078-2123-1635221157.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=8BT7CPnK91DVNeiBUliahw', 0, 0, 'EASY', 'Cùng thử nấu Những món rau hấp dẫn bé');
INSERT INTO public.post VALUES (286, '2025-11-20 17:10:27.224681', '2025-11-20 17:10:27.224681', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 288, 'Súp Miso của Nhật Bản', 'Súp Miso là một món ăn truyền thống của người Nhật, thường được dùng với cơm trắng trong bữa điểm tâm, làm món khai vị hoặc bữa trưa nhẹ.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/13/soupmiso-1634095790-7704-1634095911.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=y_TvhNT19ZgwlQLcoFmToQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Súp Miso của Nhật Bản');
INSERT INTO public.post VALUES (301, '2025-11-20 17:10:30.097585', '2025-11-20 17:10:30.097585', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 303, 'Sườn nấu bung', 'Vào những ngày đông giá rét, mâm cơm sẽ hấp dẫn hơn nhiều khi có bát sườn bung nóng hổi, thơm ngon. Bạn thử tham khảo để chế biến cho cả nhà thưởng thức nhé.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/12/11200x67642-1634029272-7928-1634029483.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gppvdeOND1OwAqMIQnI6qQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Sườn nấu bung');
INSERT INTO public.post VALUES (128, '2025-11-20 17:10:02.434202', '2025-11-20 17:10:02.434202', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 130, 'Cách làm ốc xào khế lá gừng - thức quà mùa thu Hà Nội', 'Ốc béo giòn quyện vị chua nhẹ từ khế, thoảng mùi thơm ngọt thanh từ lá gừng là món quà trong tiết Thu sang của ẩm thực Hà Nội.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/09/20/-7701-1663661887.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VPX0mxObZr7S0VqEhe2LgQ', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm ốc xào khế lá gừng - thức quà mùa thu Hà Nội');
INSERT INTO public.post VALUES (143, '2025-11-20 17:10:05.839153', '2025-11-20 17:10:05.839153', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 145, 'Cách làm cá rô đồng chiên giòn - món chân quê gây thương nhớ', 'Từng con cá rô đồng vàng ươm, giòn rụm, chấm nước mắm, ăn kèm rau luộc, cơm trắng đã trở thành nỗi nhớ của không ít người xa quê.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2022/07/24/Thnhphm1-1658631129-1156-1658631219.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=IFnzwYxNUhzarQViR7_OGA', 27, 28, 'EASY', 'Cùng thử nấu Cách làm cá rô đồng chiên giòn - món chân quê gây thương nhớ');
INSERT INTO public.post VALUES (158, '2025-11-20 17:10:08.078117', '2025-11-20 17:10:08.078117', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 160, 'Cách làm cá trích kho cà chua giá rẻ mà tốn cơm ngày đông', 'Thịt cá săn lại, đậm vị kèm chua nhẹ từ cà chua, cộng chút cay từ ớt đẩy đưa vị giác, màu đẹp mắt. Món này ăn cùng cơm nóng rất hao.', 'Quảng Bình', 'https://i1-giadinh.vnecdn.net/2022/06/02/Thnhphm11-1654165196-5154-1654165210.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eOQYbxu2IroN267e3ZjaFg', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm cá trích kho cà chua giá rẻ mà tốn cơm ngày đông');
INSERT INTO public.post VALUES (170, '2025-11-20 17:10:09.829342', '2025-11-20 17:10:09.829342', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 172, 'Cách làm canh trai nấu rau răm chua ngọt thanh mát ngày hè', 'Một bát canh với thịt trai giòn ngọt tự nhiên, thoảng chút chua nhẹ, thơm mùi hành răm. Món canh này vừa bổ dưỡng lại vừa giúp giải nhiệt ngày hè.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2022/04/28/Thnhphm22-1651135373-9956-1651135526.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=FzHcMgO0D5J1UHd6FrpAEg', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm canh trai nấu rau răm chua ngọt thanh mát ngày hè');
INSERT INTO public.post VALUES (183, '2025-11-20 17:10:11.923869', '2025-11-20 17:10:11.923869', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 185, 'Cách xào rau muống tỏi xanh giòn dậy mùi thơm', 'Rau muống xào xanh mướt, dậy mùi thơm của tỏi. Đây là món ăn quốc dân được nhiều người yêu thích từ Bắc vào Nam.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/03/28/Thnhphm1-1648467867-5910-1648467981.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=x3CHFu5LsLeRw94Mzp0DMg', 10, 10, 'MEDIUM', 'Cùng thử nấu Cách xào rau muống tỏi xanh giòn dậy mùi thơm');
INSERT INTO public.post VALUES (198, '2025-11-20 17:10:13.802282', '2025-11-20 17:10:13.802282', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 200, 'Gà rang gừng - món ngon mùa đông', 'Thịt gà săn đậm vị, dậy mùi thơm ấm nóng của gừng nhanh chóng xua tan cái lạnh của mùa đông.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/09/Thnhphm1-1641712797-8760-1641712808.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eE9cTWpEHwji2aGsn3W4uw', 22, 23, 'EASY', 'Cùng thử nấu Gà rang gừng - món ngon mùa đông');
INSERT INTO public.post VALUES (213, '2025-11-20 17:10:15.791236', '2025-11-20 17:10:15.791236', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 215, 'Chả ốc cuốn lá lốt - món ngon dân dã', 'Từng miếng chả ốc dai giòn sần sật, có vị ngọt tự nhiên, dậy mùi thơm của lá lốt rất hợp với thời tiết mùa lạnh.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/19/Thnhphm1-1637328551-5945-1637328564.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Blipj2ssI0-Ct_0hS6bsog', 25, 25, 'MEDIUM', 'Cùng thử nấu Chả ốc cuốn lá lốt - món ngon dân dã');
INSERT INTO public.post VALUES (228, '2025-11-20 17:10:18.250921', '2025-11-20 17:10:18.250921', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 230, 'Canh rau sắn chua nấu sườn - món ngon Phú Thọ', 'Rau sắn chua nhẹ hòa quyện cùng sườn mềm ngọt, dậy mùi thơm ngai ngái đặc trưng làm nên món đặc sản của người dân Phú Thọ.', 'Phú Thọ', 'https://i1-giadinh.vnecdn.net/2021/11/19/Thnhphm3-1637327786-1742-1637328000.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Ne2DZj7kCbxpAYBAIdiGSQ', 30, 30, 'EASY', 'Cùng thử nấu Canh rau sắn chua nấu sườn - món ngon Phú Thọ');
INSERT INTO public.post VALUES (243, '2025-11-20 17:10:20.366233', '2025-11-20 17:10:20.366233', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 245, 'Đậm đà hương vị món cay', 'Những ngày cuối năm, tiết trời se lạnh rất thích hợp với những món ăn cay nóng trong bữa cơm hằng ngày. Mời bạn cùng trổ tài để gia đình được thưởng thức những món ngon dưới đây.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/11/04/ca-1636010840-9184-1636010850.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=FDMDxrkpC2zOd3y7cLqxdg', 0, 0, 'MEDIUM', 'Cùng thử nấu Đậm đà hương vị món cay');
INSERT INTO public.post VALUES (258, '2025-11-20 17:10:22.492394', '2025-11-20 17:10:22.492394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 260, '3 món với nghêu', 'Nghêu thường được chế biến nhanh, nhưng cũng như các loại hải sản khác, thường có vị tanh đặc trưng. Phải khéo kết hợp với các loại gia vị nồng như ớt, sả, gừng, riềng hay lá chanh, nghêu mới thơm ngon và ngọt thịt.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/25/ngheuhap-1635135788-3218-1635135896.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=QA2NgjLF55MshSzoTWvstA', 0, 0, 'EASY', 'Cùng thử nấu 3 món với nghêu');
INSERT INTO public.post VALUES (273, '2025-11-20 17:10:25.050293', '2025-11-20 17:10:25.050293', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 275, 'Ếch xào măng', 'Mùa hè, thịt ếch thường béo chắc. Nhiều người vẫn chỉ biết tới những món chiên từ thịt ếch mà không biết tới món da ếch xào măng cũng rất ngon.', 'Tây Ninh', 'https://i1-giadinh.vnecdn.net/2021/10/17/echxao-1634448688-8680-1634448787.png?w=0&h=0&q=100&dpr=2&fit=crop&s=TqBnG-PYQscfeWNWxvrEeQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Ếch xào măng');
INSERT INTO public.post VALUES (288, '2025-11-20 17:10:27.654595', '2025-11-20 17:10:27.654595', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 290, 'Bò tái me', 'Bò tái me là món ăn có vị ngon đậm đà, rất đặc biệt. Bạn thử trổ tài chế biến qua những hướng dẫn dưới đây nhé.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/13/botai-1634094006-2007-1634094279.png?w=0&h=0&q=100&dpr=2&fit=crop&s=7SMM-KaiBuFfnmYUMjvHOg', 0, 0, 'MEDIUM', 'Cùng thử nấu Bò tái me');
INSERT INTO public.post VALUES (303, '2025-11-20 17:10:30.438572', '2025-11-20 17:10:30.438572', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 305, 'Tỏi gà rút xương nhồi thịt nướng', 'Bạn có thể trổ tài khéo tay như đầu bếp chuyên nghiệp với món ăn này, mà không cần nguyên liệu quá cầu kỳ.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/12/duitoiganhapkhaudonglanhtui1kg-2303-7918-1634028742.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=FUpw5Fl0Owy-EvQG9CddEA', 0, 0, 'EASY', 'Cùng thử nấu Tỏi gà rút xương nhồi thịt nướng');
INSERT INTO public.post VALUES (318, '2025-11-20 17:10:33.415845', '2025-11-20 17:10:33.415845', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 320, 'Tự làm Kim chi Hàn Quốc', 'Kim chi được làm từ bắp cải lên men với ớt đỏ, củ cải và rất nhiều tỏi, gừng. Dù yêu hay ghét món này, người ta cũng không thể quên được mùi vị đặc biệt của nó ngay lần đầu nếm thử.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/07/kimchi-1633599838-4841-1633599980.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=c3es59dwYiS5HHcV1mvhiQ', 0, 0, 'HARD', 'Cùng thử nấu Tự làm Kim chi Hàn Quốc');
INSERT INTO public.post VALUES (181, '2025-11-20 17:10:11.634743', '2025-11-20 17:10:11.634743', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 183, 'Cách làm ba chỉ rang cháy cạnh thơm ngon như ngoài quán', 'Món ăn bình dân này được nhiều nhà hàng ưu ái đưa vào thực đơn. Bí quyết là ở việc canh lửa và nêm nếm gia vị kiểu xưa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/04/02/Thnhphm11-1648896377-3160-1648896450.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-2lj4wpKTyLx9WDPHxuRlQ', 20, 20, 'EASY', 'Cùng thử nấu Cách làm ba chỉ rang cháy cạnh thơm ngon như ngoài quán');
INSERT INTO public.post VALUES (185, '2025-11-20 17:10:12.107529', '2025-11-20 17:10:12.107529', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 187, 'Cách làm bò lúc lắc rau củ quả giòn ngoài mềm trong ngon chuẩn vị', 'Thịt bò bên ngoài giòn, bên trong chín tái ngọt tự nhiên, rau của quả giòn ngon. Món này ăn kèm xà lách, khoai tây chiên rất hấp dẫn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/04/02/Thnhphm11-1648896965-5113-1648897030.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=BdzDUq1MsRTFUvHNT2fhdw', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm bò lúc lắc rau củ quả giòn ngoài mềm trong ngon chuẩn vị');
INSERT INTO public.post VALUES (188, '2025-11-20 17:10:12.500923', '2025-11-20 17:10:12.500923', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 190, 'Cách làm chả lá xương sông tiêu đờm trị ho cho F0', 'Theo Đông y, lá xương sông tính ấm có tác dụng chữa tiêu đờm, trị ho. Món chả lá xương sông thơm ngon rất tốt cho người đang bị bệnh.', 'Hà Nam', 'https://i1-giadinh.vnecdn.net/2022/03/30/Thnhphm22-1648630050-6817-1648630113.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=4i5Ipz_iH9_pDBfRgvjFJw', 22, 23, 'EASY', 'Cùng thử nấu Cách làm chả lá xương sông tiêu đờm trị ho cho F0');
INSERT INTO public.post VALUES (195, '2025-11-20 17:10:13.343031', '2025-11-20 17:10:13.343031', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 197, 'Cách làm bún giả cầy chuẩn vị', 'Bún giả cầy có thịt mềm đậm vị nhưng bì vẫn còn chút giòn, nước sóng sánh vàng, dậy mùi thơm của mắm tôm, riềng mẻ. Món này ăn cùng bún rất ngon nhất là trong tiết trời lạnh.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/02/18/Thnhphm3-1645173060-7712-1645173239.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=6kAmhVN3H8GPGRUlexW25A', 47, 48, 'MEDIUM', 'Cùng thử nấu Cách làm bún giả cầy chuẩn vị');
INSERT INTO public.post VALUES (200, '2025-11-20 17:10:14.022245', '2025-11-20 17:10:14.022245', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 202, 'Cách làm bún cá ngon như ngoài hàng', 'Ra Tết món bún cá với nước dùng thanh dịu, từng miếng cá vàng ươm, giòn ngon, giữ vị mộc luôn đắt khách.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2022/02/08/Bc11-1644312148-6575-1644312342.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kzv1W0fxjkJ5uKwEMvQS1A', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm bún cá ngon như ngoài hàng');
INSERT INTO public.post VALUES (203, '2025-11-20 17:10:14.441399', '2025-11-20 17:10:14.441399', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 205, 'Cháo trai - thức quà chiều đông Hà Nội', 'Bát cháo trai sánh mịn, thịt trai thơm ngon đậm vị, quẩy giòn tan, dậy mùi thơm của hành phi, rau răm, hành lá làm nên món đặc trưng chiều đông Hà Nội.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/30/Thnhphm4-1638255664-7292-1638255863.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=WBu-omgwe2kxJM9rfbktng', 25, 25, 'MEDIUM', 'Cùng thử nấu Cháo trai - thức quà chiều đông Hà Nội');
INSERT INTO public.post VALUES (210, '2025-11-20 17:10:15.396771', '2025-11-20 17:10:15.396771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 212, 'Cách làm sườn xào chua ngọt kiểu Hà Nội đơn giản', 'Sườn mềm, vị chua mặn ngọt hài hòa, nước sốt sánh lên màu nâu đỏ tự nhiên. Đặc biệt, nguyên liệu và cách làm đơn giản.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/12/17/Thnhphm2-1639750764-6880-1639751430.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_A5kbN57h-qUpoQxYFpMZw', 30, 30, 'EASY', 'Cùng thử nấu Cách làm sườn xào chua ngọt kiểu Hà Nội đơn giản');
INSERT INTO public.post VALUES (215, '2025-11-20 17:10:16.206058', '2025-11-20 17:10:16.206058', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 217, 'Bắp bò ngâm mắm', 'Bắp bò ngâm mắm thơm ngon, vừa sang chảnh vừa chống ngán cho bàn tiệc tại gia, phù hợp cho những mâm cơm ngày Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/12/05/5-1638711706-5290-1638711713.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_e6OmvpTTtK5R-SZAvBLJA', 30, 30, 'MEDIUM', 'Cùng thử nấu Bắp bò ngâm mắm');
INSERT INTO public.post VALUES (218, '2025-11-20 17:10:16.619177', '2025-11-20 17:10:16.619177', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 220, 'Bò sốt vang kiểu Hà Nội', 'Từ món ăn gốc của Pháp, người Hà Nội đã biến hóa món bò sốt vang, giúp món ăn trở nên thuần Việt và được nhiều người yêu thích.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/12/10/Thnhphm1-1639110599-7447-1639110897.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=zsAfgplP9kt_j-Wb4B8ijA', 45, 45, 'HARD', 'Cùng thử nấu Bò sốt vang kiểu Hà Nội');
INSERT INTO public.post VALUES (225, '2025-11-20 17:10:17.836013', '2025-11-20 17:10:17.836013', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 227, 'Các món ăn đậm hương quê', 'Mang hương vị đặc trưng của biển, những món ăn dân dã dưới đây không kém phần hấp dẫn và có thể khiến cả nhà phải trầm trồ về tài nấu nướng của bạn.', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2021/11/17/goisua-1637139469-7729-1637139535.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=o6aKrwyuaz9Pf-94yKJxRQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Các món ăn đậm hương quê');
INSERT INTO public.post VALUES (230, '2025-11-20 17:10:18.569003', '2025-11-20 17:10:18.569003', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 232, 'Biến tấu món gan', 'Không chỉ đơn điệu là xào và rán, các loại gan như gà, vịt, bò, lợn, ngỗng còn có thể chế biến thành nhiều món ngon miệng lại đẹp mắt.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/15/gan-1636950686-9630-1636950717.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=U7dxjmRGTiz8ZModJOGLUw', 0, 0, 'MEDIUM', 'Cùng thử nấu Biến tấu món gan');
INSERT INTO public.post VALUES (233, '2025-11-20 17:10:18.964884', '2025-11-20 17:10:18.964884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 235, 'Salad củ sen', 'Chỉ mất khoảng 10 phút, với những nguyên liệu đơn giản, bạn có thể làm món salad củ sen mát lành để đãi cả nhà.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2021/11/17/saladcusen-1637140940-9085-1637141050.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eUj_mqBT05UxeLzD1MA3AA', 0, 0, 'MEDIUM', 'Cùng thử nấu Salad củ sen');
INSERT INTO public.post VALUES (240, '2025-11-20 17:10:19.884093', '2025-11-20 17:10:19.884093', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 242, 'Dưa leo trộn cà chua', 'Đây là món salad rất hấp dẫn, vừa ngon vừa giúp các chị em có làn da thêm tươi tắn.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/11/15/dualeo-1636949961-5308-1636949998.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=DAmB1A3ILJ21SBo3Q0X7-g', 0, 0, 'MEDIUM', 'Cùng thử nấu Dưa leo trộn cà chua');
INSERT INTO public.post VALUES (245, '2025-11-20 17:10:20.606453', '2025-11-20 17:10:20.606453', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 247, 'Cách làm pate truyền thống thơm ngon', 'Pate mềm mịn, thơm ngon, không khô, không tanh mùi gan heo. Món này ăn cùng xôi nóng, bánh mì rất ngon.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/16/Pate-1637069563-2916-1637069640.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kqqi122B_ZZoZazc9iNQNg', 150, 150, 'MEDIUM', 'Cùng thử nấu Cách làm pate truyền thống thơm ngon');
INSERT INTO public.post VALUES (194, '2025-11-20 17:10:13.202499', '2025-11-20 17:10:13.202499', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 196, 'Cuốn hành - món ngon ''vạn người mê'' sau Tết', 'Sự kết hợp hài hòa tôm ngọt, thịt béo, trứng bùi, rau sống thanh mát tạo nên món ăn hấp dẫn sau Tết. Đây là món ăn đặc trưng của nhiều tỉnh như Thái Bình, Ninh Bình, Hải Phòng...', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2022/02/11/Thnhphm11-1644564621-2014-1644564724.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=RpthUDDyUSj8vmDTOJUnog', 45, 45, 'MEDIUM', 'Cùng thử nấu Cuốn hành - món ngon ''vạn người mê'' sau Tết');
INSERT INTO public.post VALUES (199, '2025-11-20 17:10:13.885722', '2025-11-20 17:10:13.885722', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 201, 'Cá kho trám đưa cơm ngày lạnh', 'Từng miếng cá săn chắc, đậm vị, trám đen bùi bùi, dậy mùi thơm của riềng rất ''hao cơm'' trong tiết trời lạnh.', 'Bắc Giang', 'https://i1-giadinh.vnecdn.net/2022/02/11/Thnhphm2-1644563015-1586-1644563182.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=dHBLYodeOfcoox49g6cQRA', 120, 120, 'MEDIUM', 'Cùng thử nấu Cá kho trám đưa cơm ngày lạnh');
INSERT INTO public.post VALUES (201, '2025-11-20 17:10:14.140502', '2025-11-20 17:10:14.140502', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 203, 'Cách làm nem lụi ngon chuẩn vị', 'Từng chiếc nem lụi bọc sả, mềm ngọt cuộn với rau sống, chuối xanh chấm nước mắm chua ngọt tạo nên một bản hòa tấu hấp dẫn.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2022/02/18/Bc6-1645174454-6720-1645174529.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Z5rlMTyFCs0iujlMSbScMw', 40, 40, 'MEDIUM', 'Cùng thử nấu Cách làm nem lụi ngon chuẩn vị');
INSERT INTO public.post VALUES (209, '2025-11-20 17:10:15.271394', '2025-11-20 17:10:15.271394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 211, 'Thịt gà nấu đông - món ngon miền Bắc', 'Thịt gà mềm, mộc nhĩ sần sật, nấm hương thơm bùi, phần đông trong mát mềm mướt, dậy mùi thơm của hạt tiêu, ăn như tan trong miệng.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/11/30/Buc7-1638257597-7490-1638257777.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uULiFzuTZiYLH4OdbCRreA', 45, 45, 'MEDIUM', 'Cùng thử nấu Thịt gà nấu đông - món ngon miền Bắc');
INSERT INTO public.post VALUES (214, '2025-11-20 17:10:16.065239', '2025-11-20 17:10:16.065239', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 216, 'Nem lụi từ ức gà cho người giảm cân', 'Không quá béo, lại dai ngon, thơm nức, nem lụi ức gà giúp những người đang giảm cân được thỏa đam mê ăn uống mà không phải lo vóc dáng.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2021/12/15/NemluiJPG-1639564838-9511-1639564844.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=N7Mp3wKPx6kxnTIgLpSjWw', 60, 60, 'MEDIUM', 'Cùng thử nấu Nem lụi từ ức gà cho người giảm cân');
INSERT INTO public.post VALUES (216, '2025-11-20 17:10:16.324109', '2025-11-20 17:10:16.324109', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 218, 'Xôi thịt Hải Phòng - món ngon trứ danh đất cảng', 'Thịt mềm, béo ngậy, thấm đượm gia vị mặn ngọt hài hòa, dậy mùi thơm rất riêng. Xôi căng bóng, mềm dẻo. Tất cả quyện vào làm nên món ngon mùa đông nơi đất cảng.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/11/19/Thnhphm3-1637330748-4609-1637333521.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=WgGMGLdoWlevRmu2seenjw', 90, 90, 'MEDIUM', 'Cùng thử nấu Xôi thịt Hải Phòng - món ngon trứ danh đất cảng');
INSERT INTO public.post VALUES (224, '2025-11-20 17:10:17.699964', '2025-11-20 17:10:17.699964', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 226, 'Bún thịt xiên nướng từ nồi chiên không dầu', 'Những ngày đầu đông, hãy thử đổi vị cho gia đình bằng những xiên thịt nướng thơm nồng, kèm bún rau và nước chấm đậm đà.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2021/12/01/5-1638331586-1638331600-6187-1638331719.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=hcbedpI10rK-mIWJN7rcVQ', 90, 90, 'MEDIUM', 'Cùng thử nấu Bún thịt xiên nướng từ nồi chiên không dầu');
INSERT INTO public.post VALUES (229, '2025-11-20 17:10:18.350598', '2025-11-20 17:10:18.350598', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 231, 'Cách làm Canh chua cá khoai mềm, ngọt tự nhiên', 'Thịt cá trắng mềm, ngọt tự nhiên, nước canh chua nhẹ, ngọt thanh, dậy mùi thơm của thì là, hành lá. Đây là món ăn quen thuộc của nhiều vùng biển trong cả nước.', 'Bà Rịa–Vũng Tàu', 'https://i1-giadinh.vnecdn.net/2021/11/14/thanhpham-1636859040-4020-1636859130.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=i304ZjyFXGMk-AR_YC7dHA', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm Canh chua cá khoai mềm, ngọt tự nhiên');
INSERT INTO public.post VALUES (231, '2025-11-20 17:10:18.708976', '2025-11-20 17:10:18.708976', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 233, 'Gà kho sả nghệ - món ngon miền Trung mùa đông', 'Thịt gà mềm vàng óng, đậm vị, dậy mùi thơm đặc trưng của sả, gừng, nước sốt sánh lại.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/11/19/Thnhphm1-1637329120-4505-1637329124.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=wNHO4dgCGZl7zGPwQdJsew', 25, 25, 'MEDIUM', 'Cùng thử nấu Gà kho sả nghệ - món ngon miền Trung mùa đông');
INSERT INTO public.post VALUES (239, '2025-11-20 17:10:19.725821', '2025-11-20 17:10:19.725821', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 241, 'Quen lạ với tôm', 'Tôm là món hải sản có vị ngọt tự nhiên rất được ưa chuộng. Bạn chỉ cần mươi phút là có thể chế biến xong ba món tôm rất ngon dưới đây.', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2021/11/15/tomhap-1636950327-8450-1636950394.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=QBGmRcryzbcGVVOja_uTTA', 0, 0, 'EASY', 'Cùng thử nấu Quen lạ với tôm');
INSERT INTO public.post VALUES (244, '2025-11-20 17:10:20.472433', '2025-11-20 17:10:20.472433', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 246, 'Hai món ngày thường ngon miệng', 'Chỉ với vài miếng đậu hũ, một trái bí hay đơn giản chỉ là một tàu lá chuối mà mâm cơm của gia đình bạn sẽ thêm phần hấp dẫn. Bí quyết ở đây là sự khéo léo trong cách gia giảm và trình bày.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/15/daunhoi-1636949806-9372-1636949818.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=4w3NHKJnSoqtFmH-Fw1LjQ', 0, 0, 'EASY', 'Cùng thử nấu Hai món ngày thường ngon miệng');
INSERT INTO public.post VALUES (246, '2025-11-20 17:10:20.751137', '2025-11-20 17:10:20.751137', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 248, 'Món ngon lạ miệng', 'Tôm càng cá ngừ cuộn rong biển, chả giò mực... sẽ giúp gia đình bạn đổi món. Bạn thử trổ tài sau khi tham khảo các công thức sau đây nhé.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/11/11/chagiomuc-1636621635-5539-1636621672.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=fjaK43BX0RE3nR8tdK7jjQ', 0, 0, 'EASY', 'Cùng thử nấu Món ngon lạ miệng');
INSERT INTO public.post VALUES (254, '2025-11-20 17:10:22.03823', '2025-11-20 17:10:22.03823', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 256, 'Cải mầm nấu nghêu', 'Đây là món canh ngon, bổ mà bạn không cần mất quá nhiều thời gian chế biến.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/11/09/unnamed-1636441451-1413-1636441531.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Od4NnbuQZDw6RUnMPIhglA', 0, 0, 'EASY', 'Cùng thử nấu Cải mầm nấu nghêu');
INSERT INTO public.post VALUES (259, '2025-11-20 17:10:22.646008', '2025-11-20 17:10:22.646008', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 261, 'Hấp dẫn từ những món quen', 'Bông cải xào thịt bò, canh măng chua cá lóc, cá rô kho khế chua là 3 món dễ "tốn cơm" nhất là trong những ngày đông lạnh giá này.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/03/caixao-1635926657-5305-1635926661.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=8_aZfVKJT6rLNKoY9-B2cg', 0, 0, 'MEDIUM', 'Cùng thử nấu Hấp dẫn từ những món quen');
INSERT INTO public.post VALUES (217, '2025-11-20 17:10:16.428691', '2025-11-20 17:10:16.428691', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 219, 'Măng xào tóp mỡ đưa cơm ngày lạnh', 'Măng mềm ngon, vàng óng, tóp mỡ vẫn giữ được độ giòn, dậy mùi thơm của tỏi, hành lá rất hấp dẫn. Món này ăn cùng cơm nóng rất ngon, xua tan giá lạnh mùa đông.', 'Tuyên Quang', 'https://i1-giadinh.vnecdn.net/2021/11/30/Thnhphm3-1638256332-9237-1638256468.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=WXqptFvmPSM1LqJw5CUfWA', 22, 23, 'EASY', 'Cùng thử nấu Măng xào tóp mỡ đưa cơm ngày lạnh');
INSERT INTO public.post VALUES (221, '2025-11-20 17:10:17.068208', '2025-11-20 17:10:17.068208', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 223, '3 món ngon dễ làm', 'Những món ăn hấp dẫn và đầy đủ dưỡng chất với thời gian chế biến nhanh là những gì các bà nội trợ thời hiện đại cần. Khoai tây xào thịt bò, cá hú kho tiêu xanh và mít non xào tỏi là các món đáp ứng được yêu cầu này của bạn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/18/mitnon-1637224760-8952-1637224766.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=oelU929_7hEitmW2gqUeLw', 0, 0, 'MEDIUM', 'Cùng thử nấu 3 món ngon dễ làm');
INSERT INTO public.post VALUES (232, '2025-11-20 17:10:18.770377', '2025-11-20 17:10:18.770377', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 234, 'Biến tấu với món canh', 'Canh bắp và canh mướp trứng đều vừa giàu dinh dưỡng vừa dễ chế biến và rất ngon. Bạn thử làm cho cả nhà thưởng thức ngay nhé.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/17/canhngo-1637140516-1362-1637140679.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ymdGqVa1Pgd392cWyRz9Sw', 0, 0, 'EASY', 'Cùng thử nấu Biến tấu với món canh');
INSERT INTO public.post VALUES (236, '2025-11-20 17:10:19.346592', '2025-11-20 17:10:19.346592', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 238, 'Món ngon với cà chua', 'Từ cà chua nhồi đến xào hay làm sốt... đều góp phần làm cho bữa ăn thêm đa dạng và phong phú. Ba món ngon, lạ miệng chế biến cùng cà chua dưới đây có thể là gợi ý hay cho bạn.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/11/11/bap-1636621859-8261-1636621948.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=aQG3Hmgm6fZFCdJxSU9rOg', 0, 0, 'EASY', 'Cùng thử nấu Món ngon với cà chua');
INSERT INTO public.post VALUES (247, '2025-11-20 17:10:20.887934', '2025-11-20 17:10:20.887934', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 249, 'Bữa cơm đậm màu sắc', 'Những món ăn dưới đây đều phong phú từ màu sắc, nguyên liệu đến cách chế biến nên rất hấp dẫn và ngon miệng. Bạn thử tham khảo và trổ tài nhé.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/11/muchap-1636621391-5245-1636621467.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=P_IyGgNBRmN762VL-MVy1w', 0, 0, 'EASY', 'Cùng thử nấu Bữa cơm đậm màu sắc');
INSERT INTO public.post VALUES (251, '2025-11-20 17:10:21.578906', '2025-11-20 17:10:21.578906', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 253, 'Gỏi rau muống chiên giòn', 'Gỏi rau muống chiên giòn là món ăn lạ, ngon và bạn cũng không phải mất nhiều thời gian chế biến.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2021/11/09/goiraumuongchiengion1200x676-1-5363-2655-1636441948.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5noO83-8uYyhMMWp-7va9Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Gỏi rau muống chiên giòn');
INSERT INTO public.post VALUES (262, '2025-11-20 17:10:23.109125', '2025-11-20 17:10:23.109125', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 264, 'Vài món ngon cho bữa cơm mùa lạnh', 'Lưỡi heo sốt chua ngọt, cá bống mú hấp hành lá và chim cút tiềm ngũ quả đều là những món ngon, lạ miệng và giúp bữa cơm nhà bạn thêm ấm cúng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/30/Cabong-1635596200-8816-1635596305.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=DoqMDMAk7-0zQ6-qt0_fgQ', 0, 0, 'EASY', 'Cùng thử nấu Vài món ngon cho bữa cơm mùa lạnh');
INSERT INTO public.post VALUES (266, '2025-11-20 17:10:23.826631', '2025-11-20 17:10:23.826631', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 268, 'Món trộn hỗn hợp', 'Đây là một loại salad cung cấp cả đạm động vật lẫn thực vật, cùng rất nhiều vitamin và nguyên tố vi lượng. Nó hấp dẫn ngay cả với người ngại ăn rau.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/25/saladthapcam-1635137040-7279-1635137076.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_9oWm5xL8yv1u0y7F4hvcQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Món trộn hỗn hợp');
INSERT INTO public.post VALUES (277, '2025-11-20 17:10:25.741491', '2025-11-20 17:10:25.741491', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 279, 'Hải sâm nấu gà', 'Hải sâm nấu thịt gà bằng nước dùng, thêm rau tươi. Đây là một món ăn rất ngon, không ngán.', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2021/10/21/haisam-1634804963-4899-1634805073.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0Uq5i0nsv_6mGHMd3U22RQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Hải sâm nấu gà');
INSERT INTO public.post VALUES (281, '2025-11-20 17:10:26.34936', '2025-11-20 17:10:26.34936', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 283, 'Hai món ngon làm đẹp da', 'Hai món tôm rán lúa mạch và atiso trộn dưới đây đều ngon và góp phần giúp bạn cải thiện làn da của mình. Bạn thử trổ tài chế biến nhé.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/15/tomchienyenmach-1634272387-4877-1634272685.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=H26H2WMSrmv90cOD1OCpXw', 0, 0, 'EASY', 'Cùng thử nấu Hai món ngon làm đẹp da');
INSERT INTO public.post VALUES (292, '2025-11-20 17:10:28.411347', '2025-11-20 17:10:28.411347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 294, 'Chả cua nướng tộ', 'Món chả cua nướng tộ thơm ngon, ăn với cơm trắng hay với đồ chua, nước mắm ớt như kiểu ăn cơm tấm cũng tuyệt.', 'Cà Mau', 'https://i1-giadinh.vnecdn.net/2021/10/14/chacuathittrungthumbnail-16341-3608-6230-1634184785.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=jsUeSnSUrPPmRATL0ajunQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Chả cua nướng tộ');
INSERT INTO public.post VALUES (296, '2025-11-20 17:10:29.112233', '2025-11-20 17:10:29.112233', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 298, 'Gà hầm nấm', 'Thịt gà có thể chế biến thành rất nhiều món ngon, trong đó có gà nấu nấm. Một chút thời gian, một chút tỉ mỉ là bạn sẽ có ngay món ăn hấp dẫn cả nhà.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/13/gaham-1634113378-2863-1634113386.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=A-D7Ikcf9BwvEoJPCV1W_w', 0, 0, 'MEDIUM', 'Cùng thử nấu Gà hầm nấm');
INSERT INTO public.post VALUES (307, '2025-11-20 17:10:31.159086', '2025-11-20 17:10:31.159086', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 309, 'Trứng hấp vân', 'Món trứng lạ miệng, rất dễ làm, dùng đổi món cho bữa trứng thường.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/11/trunghap-1633940875-5875-1633940991.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=HlfgGvAxPucdBjsN-M79yg', 0, 0, 'MEDIUM', 'Cùng thử nấu Trứng hấp vân');
INSERT INTO public.post VALUES (311, '2025-11-20 17:10:31.971147', '2025-11-20 17:10:31.971147', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 313, 'Thịt xào giá, ớt', 'Món ăn này rất đơn giản, không tốn kém mà lại ngon miệng. Nên ăn nóng.', 'Đồng Nai', 'https://i1-giadinh.vnecdn.net/2021/10/11/cachdungmonthitboxaogiado-1633-3641-9851-1633940180.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=bui5xFMndzXonlcaDcfDtQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Thịt xào giá, ớt');
INSERT INTO public.post VALUES (322, '2025-11-20 17:10:34.282354', '2025-11-20 17:10:34.282354', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 324, 'Canh tôm nấu bí', 'Bổ sung tôm khô là một cách hay để mới món canh bí quen thuộc, tạo độ ngọt dịu.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/10/10/canhbi-1633837066-3045-1633837109.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_NLvzH9uZZCR1Dted996bQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh tôm nấu bí');
INSERT INTO public.post VALUES (248, '2025-11-20 17:10:21.138997', '2025-11-20 17:10:21.138997', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 250, 'Gỏi cua thanh long', 'Món gỏi cua thanh long ngon, lạ miệng, bạn có thể làm để chiêu đãi cả nhà vào những ngày cuối tuần này.', 'Bình Thuận', 'https://i1-giadinh.vnecdn.net/2021/11/09/tl11200x676-1636442388-5813-1636442393.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MIg-ReQeKHzqaKy4l2YGKw', 0, 0, 'MEDIUM', 'Cùng thử nấu Gỏi cua thanh long');
INSERT INTO public.post VALUES (255, '2025-11-20 17:10:22.17159', '2025-11-20 17:10:22.17159', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 257, '4 món ngon từ khoai', 'Từ nguyên liệu dân dã là sắn (khoai mỳ), khoai sọ hay khoai lang, với một chút khéo tay, bạn sẽ khiến người thân và bạn bè trầm trồ với các món bánh và chả hấp dẫn dịp cuối tuần.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/26/chakhoai-1635222871-3462-1635222927.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=cptfpxVucJgNFdP56pCnkQ', 0, 0, 'MEDIUM', 'Cùng thử nấu 4 món ngon từ khoai');
INSERT INTO public.post VALUES (260, '2025-11-20 17:10:22.809247', '2025-11-20 17:10:22.809247', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 262, 'Thực đơn cho người bận rộn', 'Những món ăn dưới đây thích hợp với các bà nội trợ bận đi làm, không có nhiều thời gian nấu nướng. Thời gian thực hiện chỉ mất khoảng 30 phút nếu bạn nấu trên 2 bếp một lúc.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/03/canhcachep-1635926736-2812-1635926740.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=onU0ZKjB166v7VuxNDlNgg', 0, 0, 'EASY', 'Cùng thử nấu Thực đơn cho người bận rộn');
INSERT INTO public.post VALUES (263, '2025-11-20 17:10:23.214694', '2025-11-20 17:10:23.214694', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 265, 'Cá rô phi sốt cà chua', 'Màu đỏ của cà chua và màu vàng của cá sẽ hấp dẫn ngay các nhóc nhà bạn khi nhìn thấy món cá rô phi sốt cà chua. Đây là món ăn thường ngày rất dễ làm và được nhiều người ưa thích.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/21/casot-1634790042-8283-1634790115.png?w=0&h=0&q=100&dpr=2&fit=crop&s=OybIjfn_qC3ufBKFnACkUw', 0, 0, 'EASY', 'Cùng thử nấu Cá rô phi sốt cà chua');
INSERT INTO public.post VALUES (270, '2025-11-20 17:10:24.547148', '2025-11-20 17:10:24.547148', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 272, 'Cách làm bún cá rô rau ngót thơm ngon', 'Cá chiên vàng giòn bên ngoài, mềm bên trong, rau ngót xanh mềm, nước dùng ngọt thanh nóng hổi, tròn vị, rất kích thích vị giác.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2021/10/17/bun1-1634458043-3075-1634458215.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=F1PKLLhGuNIgjvG77iYa0g', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm bún cá rô rau ngót thơm ngon');
INSERT INTO public.post VALUES (275, '2025-11-20 17:10:25.359438', '2025-11-20 17:10:25.359438', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 277, 'Gan xào dưa leo', 'Dưa leo thường được các bà nội trợ làm món dưa góp, ăn sống hay trộn sa lát nhưng khi kết hợp với gan heo cho món xào, bạn sẽ có món ăn với hương vị hoàn toàn mới và rất thơm ngon.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/18/BeFunkycollage20210503T1539019-9261-6105-1634551343.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=w-RnYWQqqt_gvkzxMi_AsA', 0, 0, 'MEDIUM', 'Cùng thử nấu Gan xào dưa leo');
INSERT INTO public.post VALUES (278, '2025-11-20 17:10:25.855979', '2025-11-20 17:10:25.855979', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 280, '5 món om hâm nóng ngày lạnh', 'Bằng cách tẩm ướp gia vị thấm đều trên các nguyên liệu, đun nhỏ lửa cho món ăn thấm và có chút nước dùng sền sệt, những món om làm bữa cơm trong ngày lạnh trở nên thật ấm cúng và ngon lành.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/16/Suonnon-1634376844-5308-1634376932.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3Fsz7iEydKIT5OJ4necx5A', 0, 0, 'EASY', 'Cùng thử nấu 5 món om hâm nóng ngày lạnh');
INSERT INTO public.post VALUES (285, '2025-11-20 17:10:26.966371', '2025-11-20 17:10:26.966371', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 287, 'Bầu hấp tôm thịt', 'Trái bầu không chỉ được nấu với tôm để tạo nên món canh ngon, mát mùa hè. Với công thức mới sau, bạn sẽ có thêm món ăn thơm ngon, hấp dẫn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/17/hap-1634448610-6570-1634448619.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=F9DA83hQYrhcXY8-tqyV0g', 0, 0, 'MEDIUM', 'Cùng thử nấu Bầu hấp tôm thịt');
INSERT INTO public.post VALUES (290, '2025-11-20 17:10:27.957639', '2025-11-20 17:10:27.957639', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 292, 'Canh nghêu nấu bầu', 'Đây là kinh nghiệm nấu món canh nghêu với bầu vừa bổ vừa mát của một bà nội trợ. Bạn có thể tham khảo để đãi cả nhà một bữa thật ngon.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/15/thumb1200x67610-1634297383-4078-1634297453.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=19hS8PfhzKgEl6NWjx8hrg', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh nghêu nấu bầu');
INSERT INTO public.post VALUES (293, '2025-11-20 17:10:28.528162', '2025-11-20 17:10:28.528162', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 295, 'Salad trộn dầu giấm', 'Hỗn hợp các loại rau quả mát chua ngọt sẽ giúp bữa ăn chóng ngán, dễ tiêu.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/13/saladtron-1634096027-8296-1634096305.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=d3zbQDNjOZxTwEN_nKoRnw', 0, 0, 'MEDIUM', 'Cùng thử nấu Salad trộn dầu giấm');
INSERT INTO public.post VALUES (300, '2025-11-20 17:10:29.861381', '2025-11-20 17:10:29.861381', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 302, 'Thịt ba chỉ kho dừa', 'Những ngày đông se lạnh, được thưởng thức miếng thịt ba chỉ hòa quyện với vị béo béo, thơm thơm của cơm dừa thì thật tuyệt. Bạn thử trổ tài để chiêu đãi cả nhà nhé.', 'Trà Vinh', 'https://i1-giadinh.vnecdn.net/2021/10/12/thitbachikho12103471-163403018-3906-6154-1634030220.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=WeUEC3ve5KXU4jmHntd6gQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Thịt ba chỉ kho dừa');
INSERT INTO public.post VALUES (305, '2025-11-20 17:10:30.865462', '2025-11-20 17:10:30.865462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 307, 'Miến xào lươn', 'Món ăn đổi vị cho những bữa cơm quen thuộc, lạ mà vẫn dễ làm. Các bà nội trợ thử tài xem nhé.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/10/11/unnamed1-1633941277-9465-1633941393.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=O8PniRem0gxmJ28W13RffQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Miến xào lươn');
INSERT INTO public.post VALUES (308, '2025-11-20 17:10:31.371626', '2025-11-20 17:10:31.371626', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 310, 'Miến trộn kiểu Hàn', 'Đây là món ăn đặc trưng của xứ sở kim chi (Hàn Quốc) có sử dụng nấm tươi, rất thơm ngon và phù hợp với khẩu vị người Việt. Bạn có thể tham khảo cách làm dưới đây để trổ tài cho cả nhà thưởng thức.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/11/201806151529066941h01-16339418-2197-4583-1633941993.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=rfs8xMTLnwNywwkNtiI4CQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Miến trộn kiểu Hàn');
INSERT INTO public.post VALUES (315, '2025-11-20 17:10:32.85201', '2025-11-20 17:10:32.85201', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 317, 'Bò sốt nấm', 'Đầu tuần, bạn có thể cải thiện cho gia đình bằng món bò sốt nấm không quá cầu kỳ mà nóng sốt, lạ miệng.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/10/bosotnam-1633837160-7530-1633837277.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=TJsPMXUpuv5T82sQLn2-1w', 0, 0, 'MEDIUM', 'Cùng thử nấu Bò sốt nấm');
INSERT INTO public.post VALUES (261, '2025-11-20 17:10:22.990732', '2025-11-20 17:10:22.990732', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 263, 'Bữa ăn ấm cúng với 4 món dễ làm', 'Cá trứng nướng xốt me chua ngọt lạ miệng kết hợp với canh khoai môn nóng, cải thảo xào dễ ăn. Cuối bữa tráng miệng với chè trôi nước tự làm, thêm vài lát gừng ấm bụng có tác dụng kích thích tiêu hóa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/03/caithaoxao-1635927242-7976-1635927313.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=S9jT0DRnUhQiI6S6UZOE4w', 0, 0, 'EASY', 'Cùng thử nấu Bữa ăn ấm cúng với 4 món dễ làm');
INSERT INTO public.post VALUES (269, '2025-11-20 17:10:24.426993', '2025-11-20 17:10:24.426993', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 271, 'Ếch sốt chua ngọt', 'Món ếch sốt chua ngọt hấp dẫn mà không mất nhiều thời gian. Bạn đừng ngại việc chế biến vì hiện nay, ếch mua rất dễ và làm sẵn cũng có.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2021/10/21/ech-1634790613-4231-1634790732.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=XVV8vtDyGiRAQxXooK30_Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Ếch sốt chua ngọt');
INSERT INTO public.post VALUES (274, '2025-11-20 17:10:25.236092', '2025-11-20 17:10:25.236092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 276, 'Chả thịt bò nướng lá lốt', 'Miếng chả màu hơi vàng, bóng, nổi mùi thơm của lá lốt, có vị ngọt tự nhiên, vừa ăn. Chỉ với một chút thay đổi trong cách nấu, bạn có thể tạo nên món ăn có vị lạ và ngon hơn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/19/bonuonglalot-1634617802-8304-1634617926.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=JUp08deJ4hj2LjKZioBaEA', 0, 0, 'MEDIUM', 'Cùng thử nấu Chả thịt bò nướng lá lốt');
INSERT INTO public.post VALUES (276, '2025-11-20 17:10:25.54021', '2025-11-20 17:10:25.54021', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 278, 'Salad thịt bò', 'Thịt bò xào tái, trộn salad với cải xoong và cà chua. Món này có thể dùng khai vị.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/19/thitbo-1634616933-9521-1634617133.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=NjMOcYJL4tRu2TmKAWlwzA', 0, 0, 'MEDIUM', 'Cùng thử nấu Salad thịt bò');
INSERT INTO public.post VALUES (284, '2025-11-20 17:10:26.782974', '2025-11-20 17:10:26.782974', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 286, 'Cá tẩm bột rán', 'Món cá tẩm bột rán sẽ đem đến cho bữa ăn của gia đình bạn một hương vị mới.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/17/caran-1634448857-3933-1634448962.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=RkyhQRMzOyP0leAvtvWvXA', 0, 0, 'MEDIUM', 'Cùng thử nấu Cá tẩm bột rán');
INSERT INTO public.post VALUES (289, '2025-11-20 17:10:27.773064', '2025-11-20 17:10:27.773064', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 291, 'Tôm rang thịt ba chỉ', 'Tôm rang thịt ba chỉ là món ăn dễ chế biến, lại ngon miệng và rất "vào" cơm. Bạn có thể thực hiện ngay hôm nay cho bữa ăn gia đình mình.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/10/15/tomrang08490520-1634296161-4666-1634296235.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=nI6Wv_UGSyYp90en1bkPFw', 0, 0, 'EASY', 'Cùng thử nấu Tôm rang thịt ba chỉ');
INSERT INTO public.post VALUES (291, '2025-11-20 17:10:28.164648', '2025-11-20 17:10:28.164648', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 293, 'Gỏi sách bò', 'Thay vì món sách bò xào thường ngày, món gỏi sách bò bạn làm chắc chắn sẽ nhận được sự hưởng ứng nhiệt tình và lời khen tặng của ông xã.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/14/thum11200x67611-1634185984-4774-1634186073.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=g1rnS7EZMvYv4_XigH15Uw', 0, 0, 'MEDIUM', 'Cùng thử nấu Gỏi sách bò');
INSERT INTO public.post VALUES (299, '2025-11-20 17:10:29.645426', '2025-11-20 17:10:29.645426', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 301, 'Vịt kho nước dừa', 'Món ăn này đơn giản, dễ làm mà cũng không kém phần hấp dẫn, lại rất phù hợp trong bữa cơm thường ngày của gia đình bạn.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/12/ee06dcdd8baf4656aeb4666b9a89a5-3890-4501-1634029662.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-pbMHNhXj-tQidi1RxokDw', 0, 0, 'MEDIUM', 'Cùng thử nấu Vịt kho nước dừa');
INSERT INTO public.post VALUES (304, '2025-11-20 17:10:30.622746', '2025-11-20 17:10:30.622746', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 306, 'Mỳ xào giòn', 'Từ nguyên liệu chính là mỳ tôm và thịt bò, một chút khéo tay sẽ giúp bạn có bữa sáng lạ miệng cho cả nhà.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/11/recipecoverr29410-1633939940-2787-1633939994.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9R4-EVprv-zy_4DJaykH1A', 0, 0, 'MEDIUM', 'Cùng thử nấu Mỳ xào giòn');
INSERT INTO public.post VALUES (306, '2025-11-20 17:10:30.947287', '2025-11-20 17:10:30.947287', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 308, 'Thịt bò lúc lắc', 'Món thịt bò xào vàng cạnh còn tái không dai, không khô, vị ngọt đậm đà, dậy mùi thơm.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/11/12001200x67684-1633940748-6192-1633940831.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=K4Cy8gjrFk288s6zPemmWg', 0, 0, 'MEDIUM', 'Cùng thử nấu Thịt bò lúc lắc');
INSERT INTO public.post VALUES (314, '2025-11-20 17:10:32.583897', '2025-11-20 17:10:32.583897', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 316, 'Cá chép om dưa', 'Món canh dưa chua rất phù hợp cho tiết trời nóng nực vừa vào hè, dễ đưa cơm lại dễ làm.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/11/cachepomduathumbnail-163393964-6504-5319-1633939713.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=YjKQ89XCp8RRdrIMBIbK8A', 0, 0, 'MEDIUM', 'Cùng thử nấu Cá chép om dưa');
INSERT INTO public.post VALUES (319, '2025-11-20 17:10:33.705272', '2025-11-20 17:10:33.705272', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 321, 'Thịt bò xào khoai tây', 'Thịt bò xào khoai tây là món ăn được chế biến từ những nguyên liệu quen thuộc nhưng vẫn rất hấp dẫn nhờ hương vị thơm ngon của nó.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/10/11/maxresdefault-1633939458-5537-1633939495.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=JX6olTdYKgCcUbmBkSQYDA', 0, 0, 'MEDIUM', 'Cùng thử nấu Thịt bò xào khoai tây');
INSERT INTO public.post VALUES (321, '2025-11-20 17:10:34.207864', '2025-11-20 17:10:34.207864', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 323, 'Nộm rau muống', 'Với những nguyên liệu quen thuộc như rau muống, rau rút, giá đỗ..., món nộm này giòn, nổi vị chua cay mặn ngọt, thơm mùi vừng rang.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/08/nom-1633659826-3819-1633659901.png?w=0&h=0&q=100&dpr=2&fit=crop&s=9sDYu6nckX8g6xnNA7H2Bg', 0, 0, 'MEDIUM', 'Cùng thử nấu Nộm rau muống');
INSERT INTO public.post VALUES (329, '2025-11-20 17:10:35.279104', '2025-11-20 17:10:35.279104', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 331, 'Cá hồi bỏ lò sốt bơ chanh', 'Món này nghe có vẻ cầu kỳ nhưng chế biến lại rất đơn giản mà ngon miệng. Mời bạn tham khảo cách làm từ các đầu bếp của Ezcooking.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/07/cahoi-1633578514-4956-1633578541.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0jBHR19dO6WVQxSgnhc_Kg', 0, 0, 'MEDIUM', 'Cùng thử nấu Cá hồi bỏ lò sốt bơ chanh');
INSERT INTO public.post VALUES (334, '2025-11-20 17:10:36.593283', '2025-11-20 17:10:36.593283', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 336, 'Cá chim xốt nấm linh chi', 'Với một ít nấm linh chi, ớt chuông vàng, tỏi món cá chim sẽ trở nên hấp dẫn hơn rất nhiều.', 'Phú Yên', 'https://i1-giadinh.vnecdn.net/2021/10/03/cachlamcachimhapxidau-16332676-9111-6865-1633269299.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ABatKmheRyRgZxRf0djnMQ', 0, 0, 'HARD', 'Cùng thử nấu Cá chim xốt nấm linh chi');
INSERT INTO public.post VALUES (309, '2025-11-20 17:10:31.49168', '2025-11-20 17:10:31.49168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 311, 'Thịt kho cơm dừa', 'Những miếng thịt kho màu nâu cánh gián thấm đượm gia vị càng thơm và mềm hơn khi được kết hợp với những miếng dừa giòn tan. Món ăn này cùng cơm trắng rất ngon và dễ làm.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/09/thitkho-1633752637-1678-1633752774.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0vJXcuNGAWdbyJrpcofpYA', 0, 0, 'MEDIUM', 'Cùng thử nấu Thịt kho cơm dừa');
INSERT INTO public.post VALUES (324, '2025-11-20 17:10:34.595408', '2025-11-20 17:10:34.595408', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 326, 'Gà rang muối', 'Vẫn nguyên liệu là thịt gà nhưng món gà rang muối đậm đà, lạ miệng, rất hấp dẫn. Mời bạn thử làm món này dưới sự hướng dẫn của các chuyên gia Ezcooking.', 'Quảng Ngãi', 'https://i1-giadinh.vnecdn.net/2021/10/05/ga-1633424288-6109-1633424437.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=s15vX_PollJRiZ4BprGRxg', 0, 0, 'HARD', 'Cùng thử nấu Gà rang muối');
INSERT INTO public.post VALUES (339, '2025-11-20 17:10:37.514416', '2025-11-20 17:10:37.514416', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 341, '3 món cho người nghén', 'Những món ăn được nêm nhạt, ít gia vị, hạn chế chiên xào và thêm chút gừng sẽ giúp thai phụ dễ ăn và bớt nghén hơn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/05/soup-1633405755-6113-1633405840.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=JzcbBVRWDaB0gq83lc2ksg', 0, 0, 'EASY', 'Cùng thử nấu 3 món cho người nghén');
INSERT INTO public.post VALUES (354, '2025-11-20 17:10:39.807155', '2025-11-20 17:10:39.807155', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 356, 'Bắt mắt và ngon miệng với ớt chuông', 'Không chỉ có màu sắc xanh, đỏ, vàng làm tươi đẹp thêm cho món ăn mà vị nồng nồng và lượng vitamin dồi dào từ những trái ớt chuông sẽ đem đến những món ngon lạ miệng cho thực đơn của gia đình bạn.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/02/otchuong-1633145223-5983-1633145346.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Zvu90k4iF4k_2DMZfz336g', 0, 0, 'EASY', 'Cùng thử nấu Bắt mắt và ngon miệng với ớt chuông');
INSERT INTO public.post VALUES (369, '2025-11-20 17:10:42.447807', '2025-11-20 17:10:42.447807', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 371, 'Tôm sú hấp thuốc bắc', 'Cách làm cực kỳ đơn giản nhưng tôm sú hấp thuốc bắc lại rất ngon và bổ dưỡng.', 'Cà Mau', 'https://i1-giadinh.vnecdn.net/2021/09/30/Tomsu-1633002536-4724-1633002566.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=pk4C2pZUa15ADnNZKGwxLA', 0, 0, 'EASY', 'Cùng thử nấu Tôm sú hấp thuốc bắc');
INSERT INTO public.post VALUES (384, '2025-11-20 17:10:45.328842', '2025-11-20 17:10:45.328842', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 386, 'Cách làm bánh gối đơn giản', 'Món bánh gối sẽ là một gợi ý hay cho những buổi tiệc liên hoan nhỏ trong gia đình.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/08/Banhgoi-1631101460-7129-1631101465.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3PMOphC6SlkSRt3_c3mbYA', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm bánh gối đơn giản');
INSERT INTO public.post VALUES (399, '2025-11-20 17:10:48.232964', '2025-11-20 17:10:48.232964', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 401, 'Ngao xào húng quế', 'Chút vị cay của ớt, mùi thơm của rau húng, vị ngọt đậm đà của ngao sẽ làm không khí bữa ăn của gia đình bạn thêm ấm cúng trong ngày cuối tuần.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2021/07/31/Ngaoxaohungque-1627729382-7844-1627729414.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=15GUb1ElBrSvQYhBI9JZCw', 0, 0, 'MEDIUM', 'Cùng thử nấu Ngao xào húng quế');
INSERT INTO public.post VALUES (414, '2025-11-20 17:10:50.646119', '2025-11-20 17:10:50.646119', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 416, 'Bao tử bóp rau dăm', 'Món này chế biến rất đơn giản mà lại lạ và ngon miệng, đặc biệt rất được cánh mày râu chuộng trong những bữa lai rai.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2009/11/26/day-1351676157.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=4JIB_xgQOeDZqMEnp_RIlw', 0, 0, 'EASY', 'Cùng thử nấu Bao tử bóp rau dăm');
INSERT INTO public.post VALUES (310, '2025-11-20 17:10:31.754456', '2025-11-20 17:10:31.754456', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 312, 'Tôm xào ớt khô', 'Bản thân tôm không có hương vị đặc biệt, nhưng các loại gia vị sẽ làm đậm đà món ăn quen thuộc này.', 'Quảng Ninh', 'https://i1-giadinh.vnecdn.net/2021/10/11/6cachlamtomxaootchuong-1633940-6436-4163-1633940367.png?w=0&h=0&q=100&dpr=2&fit=crop&s=nLH_yFOfm2qzPAoqQ3uPMQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Tôm xào ớt khô');
INSERT INTO public.post VALUES (325, '2025-11-20 17:10:34.747891', '2025-11-20 17:10:34.747891', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 327, 'Sa lát gà', 'Sa lát gà là món ăn lạ miệng, dễ làm lại rất bổ dưỡng. Mời bạn tham khảo cách làm dưới đây để đãi cả nhà trong dịp cuối tuần này nhé.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/08/saladga-1633657805-1132-1633657967.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=NYR8MgdbZGkaQlLveE_HYw', 0, 0, 'MEDIUM', 'Cùng thử nấu Sa lát gà');
INSERT INTO public.post VALUES (340, '2025-11-20 17:10:37.759909', '2025-11-20 17:10:37.759909', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 342, 'Canh khoai mỡ tôm tươi', 'Vị ngậy mát của khoai mỡ, màu tím bắt mắt từ món canh dưới đây sẽ hấp dẫn cả nhà bạn. Mời bạn trổ tài dưới sự hướng dẫn của Ezcooking.', 'Sóc Trăng', 'https://i1-giadinh.vnecdn.net/2021/10/05/canhkhoai-1633423162-3135-1633423387.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9niiOYNk4wnadZlsl8-epA', 0, 0, 'HARD', 'Cùng thử nấu Canh khoai mỡ tôm tươi');
INSERT INTO public.post VALUES (355, '2025-11-20 17:10:39.960491', '2025-11-20 17:10:39.960491', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 357, 'Ốc nấu chuối đậu', 'Bát chuối đậu vàng ươm, bốc khói với mùi thơm hấp dẫn sẽ khiến bữa cơm ngày đông của gia đình bạn ấm cúng hơn. Mời bạn tham khảo cách làm từ các đầu bếp của Ezcooking.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/01/oc-1633073761-8598-1633075027.png?w=0&h=0&q=100&dpr=2&fit=crop&s=P05ixKAUX4x84dYDW5pDQA', 0, 0, 'MEDIUM', 'Cùng thử nấu Ốc nấu chuối đậu');
INSERT INTO public.post VALUES (370, '2025-11-20 17:10:42.621029', '2025-11-20 17:10:42.621029', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 372, 'Chả cá thì là', 'Vào dịp nghỉ lễ 30/4 này, bạn có thể đãi cả nhà bằng món chả cá tự làm, vừa giàu dinh dưỡng lại lạ miệng, dễ ăn và cũng rất dễ làm.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/01/chacathaclacchienthilathumbnai-1213-8654-1633060389.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=6V8LZ7jtWsX23Edt7TiZ-Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Chả cá thì là');
INSERT INTO public.post VALUES (385, '2025-11-20 17:10:45.630252', '2025-11-20 17:10:45.630252', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 387, 'Thơm ngon chả cá lá chanh', 'Vị lá chanh trong miếng chả rất thơm, thêm nước chấm nhiều tỏi nữa là bạn có món chả cá tuyệt vời cho bữa ăn hôm nay.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/08/04/chacalachanh-1628077155-2875-1628077199.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=vspNljDci-9uS0FfBqiUtQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Thơm ngon chả cá lá chanh');
INSERT INTO public.post VALUES (400, '2025-11-20 17:10:48.387946', '2025-11-20 17:10:48.387946', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 402, 'Lạ miệng với sườn hấp bia', 'Sườn chua ngọt hay canh sườn đã quá quen thuộc với gia đình, bạn chỉ cần sáng tạo một chút là có món sườn hấp bia mang lại cảm giác ngon, lạ miệng và rất giàu dinh dưỡng.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/08/02/snhpbia-1627900808-7203-1627900848.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=24NyUQMFcKIaCOArqNSWHA', 0, 0, 'MEDIUM', 'Cùng thử nấu Lạ miệng với sườn hấp bia');
INSERT INTO public.post VALUES (415, '2025-11-20 17:10:50.941294', '2025-11-20 17:10:50.941294', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 417, 'Thịt bò hầm nước dừa', 'Món ăn này có hương vị rất hấp dẫn, đặc biệt thích hợp trong tiết trời giá lạnh. Mời bạn trổ tài để bữa cơm gia đình thêm ấm cúng.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2009/11/24/ham1-1351676163.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=AbcCdmPg7Z_3sp5GhISpbw', 0, 0, 'MEDIUM', 'Cùng thử nấu Thịt bò hầm nước dừa');
INSERT INTO public.post VALUES (316, '2025-11-20 17:10:32.946712', '2025-11-20 17:10:32.946712', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 318, 'Cá quả nấu ám - món ngon dân dã Thái Bình', 'Cá quả nấu ám nước màu vàng sóng sánh, thịt cá dai ngọt tự nhiên, cá viên đậm vị, chuối mềm bùi, vị chua cay mặn chát tròn vị, dễ ăn.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2021/10/08/canauam-1633671940-8477-1633671964.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=zy-2smRE5LtbKGzRsD7mXg', 45, 45, 'MEDIUM', 'Cùng thử nấu Cá quả nấu ám - món ngon dân dã Thái Bình');
INSERT INTO public.post VALUES (331, '2025-11-20 17:10:35.774135', '2025-11-20 17:10:35.774135', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 333, 'Món ăn độc đáo với gạo nếp và dâu tây', 'Món ăn này cực kỳ hấp dẫn nên dù có mất nhiều thời gian một chút, bạn cũng sẽ thấy xứng đáng.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/07/Dautay-1633603009-7497-1633603088.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=80Ri7JVp7K-RpYIskExFFQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Món ăn độc đáo với gạo nếp và dâu tây');
INSERT INTO public.post VALUES (346, '2025-11-20 17:10:38.657076', '2025-11-20 17:10:38.657076', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 348, 'Thịt bò xào thập cẩm', 'Món ăn này không mới nhưng vẫn rất hấp dẫn, giàu dinh dưỡng và ngon miệng. Mời bạn tham khảo cách làm từ các đầu bếp Ezcooking.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/03/boxao-1633238434-8009-1633238444.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=KQeJoVVzbCkPv4SgBEW5hg', 0, 0, 'HARD', 'Cùng thử nấu Thịt bò xào thập cẩm');
INSERT INTO public.post VALUES (361, '2025-11-20 17:10:40.973821', '2025-11-20 17:10:40.973821', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 363, 'Món lạ hải sản', 'Những món hải sản dưới đây không những ngon mà còn cực kỳ bắt mắt, chắc chắn sẽ rất hấp dẫn đối với các bé.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/10/01/Chmcchinx-1633060877-9015-1633060889.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=LHnV5OBF-WNAfhoScMN39g', 0, 0, 'EASY', 'Cùng thử nấu Món lạ hải sản');
INSERT INTO public.post VALUES (376, '2025-11-20 17:10:43.502556', '2025-11-20 17:10:43.502556', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 378, 'Cá nục kho keo - món ''hao cơm'' ngày mưa', 'Cá kho săn lại quyện với nước sốt keo đậm vị và tóp mỡ giòn béo ngậy ăn cùng cơm nóng, rau luộc vừa đơn giản lại thơm ngon.', 'Phú Yên', 'https://i1-giadinh.vnecdn.net/2021/09/17/cakho-1631877167-2189-1631877272.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=yd3IinzYOIyJrjE8C0W0NQ', 60, 60, 'MEDIUM', 'Cùng thử nấu Cá nục kho keo - món ''hao cơm'' ngày mưa');
INSERT INTO public.post VALUES (391, '2025-11-20 17:10:47.050201', '2025-11-20 17:10:47.050201', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 393, 'Cách làm món củ cải trắng nhồi thịt đơn giản', 'Món ăn đơn giản nhưng đậm đà, ngon miệng. Bạn có thể nấu món này cho bữa cơm ngày thường của gia đình.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2021/08/23/Cucainhoithit-1629709720-3645-1629709759.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3cod1aEa2LjgAP9M9Ym4yw', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm món củ cải trắng nhồi thịt đơn giản');
INSERT INTO public.post VALUES (406, '2025-11-20 17:10:49.245997', '2025-11-20 17:10:49.245997', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 408, 'Sườn hầm ngô non', 'Thời tiết hanh nắng dễ mệt mỏi, bát canh ngô sườn ngọt dịu sẽ giúp bạn thấy dễ chịu và ăn ngon miệng hơn.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/07/27/Suonngo-1627377962-3363-1627378019.png?w=0&h=0&q=100&dpr=2&fit=crop&s=O2DpJD9uSI5TchpV5-Hvfw', 0, 0, 'EASY', 'Cùng thử nấu Sườn hầm ngô non');
INSERT INTO public.post VALUES (421, '2025-11-20 17:10:52.057097', '2025-11-20 17:10:52.057097', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 423, 'Mướp đắng nhồi thịt sốt dầu hào', 'Món mướp đắng (khổ qua) nhồi thịt sốt dầu hào giúp bữa cơm ngày hè vừa ngon miệng lại có tác dụng giải nhiệt cơ thể.', 'Tây Ninh', 'https://i1-ngoisao.vnecdn.net/2021/06/22/194680461-529072358124393-7601-7202-4251-1624349176.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=tHDIjrJP3FXkZekjrI_8eQ', 0, 0, 'EASY', 'Cùng thử nấu Mướp đắng nhồi thịt sốt dầu hào');
INSERT INTO public.post VALUES (320, '2025-11-20 17:10:34.028799', '2025-11-20 17:10:34.028799', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 322, 'Đậu chiên trứng muối', 'Từ các nguyên liệu quen thuộc như đậu phụ, trứng muối, bạn có thể tạo ra một món ăn ngon, lạ miệng. Hướng dẫn của đầu bếp Ezcooking class dưới đây sẽ giúp bạn thực hiện thành công món này.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/07/dauchientrungmuoi-1633581372-8984-1633581500.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Dkn_rb4ayM2P80eLaV8S3A', 0, 0, 'HARD', 'Cùng thử nấu Đậu chiên trứng muối');
INSERT INTO public.post VALUES (323, '2025-11-20 17:10:34.418542', '2025-11-20 17:10:34.418542', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 325, 'Lòng non xào dưa chua', 'Món này làm đơn giản nhưng ăn lại rất ngon, đặc biệt hấp dẫn với các ông xã.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/10/11/Longnonxaoduachuaancungcom-163-2034-2534-1633939319.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=oUkYVoYP14p5WEFyGSJ6uQ', 0, 0, 'EASY', 'Cùng thử nấu Lòng non xào dưa chua');
INSERT INTO public.post VALUES (330, '2025-11-20 17:10:35.511315', '2025-11-20 17:10:35.511315', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 332, 'Cách làm Sườn xào chua ngọt ngon lành, đậm đà chuẩn vị', 'Sườn có thể dai ngoách, nhạt nhẽo hoặc mặn ngọt nửa mùa nếu bạn không biết cách chế biến khéo. Hãy tham khảo công thức dưới đây của trung tâm Ezcooking class.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2021/10/07/suonchuangot-1633580691-4648-1633580799.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qRxf_h_mpcwMq2HG9EM79Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm Sườn xào chua ngọt ngon lành, đậm đà chuẩn vị');
INSERT INTO public.post VALUES (335, '2025-11-20 17:10:36.863432', '2025-11-20 17:10:36.863432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 337, 'Phô mai trứng cuộn', 'Phô mai trứng cuộn là một món điểm tâm giàu dinh dưỡng vào mỗi buổi sáng. Món ăn này vừa ngon, hấp dẫn lại dễ thực hiện, các quý ông có thể vào bếp để chuẩn bị bữa ăn cho mình và con khi vợ vắng nhà.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/07/trungcuon-1633580308-7254-1633580358.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=37K7qO3uipVb6SvkBELOzA', 0, 0, 'MEDIUM', 'Cùng thử nấu Phô mai trứng cuộn');
INSERT INTO public.post VALUES (338, '2025-11-20 17:10:37.442469', '2025-11-20 17:10:37.442469', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 340, 'Cách làm chả cốm mộc - món ngon mùa thu Hà Nội', 'Chả cốm có vỏ ngoài giòn, bên trong mềm dẻo, thấm vị, dậy hương thơm khiến ai một lần thưởng thức đều nhớ mãi.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/02/Anh3-1633157693-9116-1633157707.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ngXQPP4-rviEORljbfKEEg', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm chả cốm mộc - món ngon mùa thu Hà Nội');
INSERT INTO public.post VALUES (345, '2025-11-20 17:10:38.525284', '2025-11-20 17:10:38.525284', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 347, 'Tôm rang muối', 'Thay đổi một chút trong cách chế biến, bạn sẽ mang lại một món ăn có hương vị mới, rất hấp dẫn cho cả nhà từ tôm. Dưới đây là những hướng dẫn từ các chuyên gia Ezcooking.', 'Ninh Thuận', 'https://i1-giadinh.vnecdn.net/2021/10/04/tom-1633330339-8919-1633330508.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EpLfbOxcwIddsxxDSTme6g', 0, 0, 'HARD', 'Cùng thử nấu Tôm rang muối');
INSERT INTO public.post VALUES (350, '2025-11-20 17:10:39.304329', '2025-11-20 17:10:39.304329', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 352, 'Salad trứng và dưa chuột muối', 'Món salad này có vị lạ, chế biến khá đơn giản. Dưới đây là hướng dẫn của các đầu bếp Ezcooking giúp các bạn thực hiện.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/02/salad1-1633167378-1534-1633167481.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=F7bMVHqPUfyUDpD5ah_D1Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Salad trứng và dưa chuột muối');
INSERT INTO public.post VALUES (353, '2025-11-20 17:10:39.680532', '2025-11-20 17:10:39.680532', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 355, 'Đùi gà rán mềm', 'Cùng với khoai tây, cà rốt và một chút hương liệu bạn sẽ làm cho món gà rán trở nên hấp dẫn hơn. Dưới đây là gợi ý dành cho bạn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/02/duigai-1633164541-7430-1633164692.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=bWmF9C7qUKhsjOMQhw-DEg', 0, 0, 'MEDIUM', 'Cùng thử nấu Đùi gà rán mềm');
INSERT INTO public.post VALUES (360, '2025-11-20 17:10:40.870662', '2025-11-20 17:10:40.870662', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 362, 'Gà xối mỡ', 'Gà có màu vàng đẹp, thịt mềm thấm gia vị, món này vừa giàu dinh dưỡng, vừa rất thơm ngon. Mời bạn tham khảo cách làm từ Rosa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/01/Gxim-1633061096-8197-1633061138.png?w=0&h=0&q=100&dpr=2&fit=crop&s=Y3qOqWRKdZ88_B4j8a116Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Gà xối mỡ');
INSERT INTO public.post VALUES (365, '2025-11-20 17:10:41.709248', '2025-11-20 17:10:41.709248', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 367, 'Làm phở gà trộn thơm ngon', 'Phở trộn hài hòa vị chua ngọt mặn, thịt gà ngọt mềm, thơm mùi hành phi, lạc rang bùi tạo nên món ngon giàu dinh dưỡng cho bữa sáng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/11/nh4-1631343189-6272-1631343329.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=HfFNvcZ7jYY0KsinTcvgvA', 20, 20, 'MEDIUM', 'Cùng thử nấu Làm phở gà trộn thơm ngon');
INSERT INTO public.post VALUES (368, '2025-11-20 17:10:42.294522', '2025-11-20 17:10:42.294522', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 370, 'Gỏi tôm củ sen hạnh nhân', 'Món gỏi có vị giòn, ngọt của củ sen tươi, vị thơm của chanh và gia vị. Món này có thể dùng chung với bánh phồng tôm hoặc bánh tráng mè.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2021/09/24/Gitmcsenhnhnhn-1632479333-9642-1632479369.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=a7ooBVlydGWwDUS6RZcKSA', 0, 0, 'HARD', 'Cùng thử nấu Gỏi tôm củ sen hạnh nhân');
INSERT INTO public.post VALUES (375, '2025-11-20 17:10:43.318802', '2025-11-20 17:10:43.318802', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 377, 'Cách làm món thịt nướng kiểu Thái', 'Món thịt nướng luôn hấp dẫn và ngon miệng. Bạn hãy trổ tài với món nướng kiểu Thái này, chắc chắn mọi người trong nhà sẽ rất thích.', 'Bình Dương', 'https://i1-giadinh.vnecdn.net/2021/09/22/thtnngkiuThi-1632308695-1484-1632308708.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-MsoU3fKKyYe9CzQHgW1MA', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm món thịt nướng kiểu Thái');
INSERT INTO public.post VALUES (380, '2025-11-20 17:10:44.12809', '2025-11-20 17:10:44.12809', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 382, 'Cách làm phở gà đơn giản mà thơm ngon ngay tại nhà', 'Với nguyên liệu đơn giản, phở gà nhà làm có nước dùng ngọt thanh, thịt gà thơm, mọng nước hấp dẫn như nhà hàng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/11/Phoga1-1631342846-8318-1631342910.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=lGvobJhbawgiJL4uvOjDYw', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm phở gà đơn giản mà thơm ngon ngay tại nhà');
INSERT INTO public.post VALUES (383, '2025-11-20 17:10:45.178917', '2025-11-20 17:10:45.178917', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 385, 'Bánh đa đỏ trộn thịt gà chua ngọt', 'Món ăn mát, giàu vitamin, không quá béo nhưng vẫn đủ chất. Bạn có thể làm món ăn nhanh này để đãi cả nhà vào bữa sáng hoặc buổi tối đều được.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/08/05/banhdado-1628156746-3356-1628156807.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=fHwZXJPYhJ--jQ2Bgsq7lA', 0, 0, 'MEDIUM', 'Cùng thử nấu Bánh đa đỏ trộn thịt gà chua ngọt');
INSERT INTO public.post VALUES (326, '2025-11-20 17:10:34.835471', '2025-11-20 17:10:34.835471', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 328, 'Các món ngon từ thịt ếch', 'Thịt ếch thơm ngon, dai và giàu dinh dưỡng. Rất đơn giản nhưng lại hấp dẫn, bạn thử tham khảo những hướng dẫn dưới đây nhé.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2008/07/11/echdua-1351754857.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=wE1mJFtnJmTRUgED6VVzUg', 0, 0, 'EASY', 'Cùng thử nấu Các món ngon từ thịt ếch');
INSERT INTO public.post VALUES (337, '2025-11-20 17:10:37.324658', '2025-11-20 17:10:37.324658', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 339, 'Canh bò nấu khế', 'Khế chua có thể kết hợp với nhiều loại thực phẩm khác để tạo nên các món ăn ngon. Canh bò nấu khế là món chế biến nhanh, khá đơn giản và rất lạ miệng.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/10/03/canhkhe-1633237237-4875-1633237416.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-LneK74tmkISQtyMNVGLlg', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh bò nấu khế');
INSERT INTO public.post VALUES (341, '2025-11-20 17:10:37.924094', '2025-11-20 17:10:37.924094', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 343, 'Nấm rơm xào sa tế', 'Thơm ngon, lạ miếng, món ăn này chắc chắn sẽ làm bữa cơm gia đình bạn thêm đầm ấm. Mời bạn tham khảo hướng dẫn của Ezcooking để làm món này.', 'Tiền Giang', 'https://i1-giadinh.vnecdn.net/2021/10/04/namrom-1633329783-4223-1633329789.png?w=0&h=0&q=100&dpr=2&fit=crop&s=9FNxjqNrfRl-GSPDKwrnow', 0, 0, 'HARD', 'Cùng thử nấu Nấm rơm xào sa tế');
INSERT INTO public.post VALUES (352, '2025-11-20 17:10:39.549092', '2025-11-20 17:10:39.549092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 354, 'Gỏi bò chua cay', 'Thịt bò mềm, đậm đà, các loại rau giòn... khiến món ăn có đủ vị mặn ngọt chua cay dưới đây rất hấp dẫn. Mời bạn thử chế biến theo hướng dẫn của các đầu bếp Ezcooking.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/02/goibo-1633166112-9663-1633166116.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=V6PRUf4Kzq-pfTLcxyFmbA', 0, 0, 'MEDIUM', 'Cùng thử nấu Gỏi bò chua cay');
INSERT INTO public.post VALUES (356, '2025-11-20 17:10:40.066195', '2025-11-20 17:10:40.066195', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 358, 'Bắp bò luộc mắm', 'Món ăn ngon, dễ làm, rất thích hợp để bạn trổ tài cho bữa nhậu của ông xã hay bữa cơm họp mặt gia đình.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/10/01/bapbo-1633064294-6665-1633064425.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=emxklu7Zq-hlVCCfYOQGlA', 0, 0, 'EASY', 'Cùng thử nấu Bắp bò luộc mắm');
INSERT INTO public.post VALUES (367, '2025-11-20 17:10:42.020483', '2025-11-20 17:10:42.020483', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 369, 'Chả giò mực', 'Món chả giò từ mực này sẽ cho bạn cảm giác mới lạ. Đây cũng là một món ăn chế biến rất đơn giản.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/09/30/Chgimc-1632996528-7025-1632996588.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VDMf4gGFzu55ziKZNjdF3Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Chả giò mực');
INSERT INTO public.post VALUES (371, '2025-11-20 17:10:42.734265', '2025-11-20 17:10:42.734265', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 373, 'Cách nấu xôi đậu đen cấp tốc bằng nồi cơm điện', 'Hạt xôi dẻo mềm, đậu đen bên trong mềm bở mà vẫn giữ nguyên hạt, ăn kèm muối lạc làm nên bữa sáng vừa nhanh gọn lại thơm ngon.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/11/nh22-1631341990-3721-1631342087.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3-vHKV_Yt7-LyGsl1UXAaw', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách nấu xôi đậu đen cấp tốc bằng nồi cơm điện');
INSERT INTO public.post VALUES (382, '2025-11-20 17:10:44.687798', '2025-11-20 17:10:44.687798', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 384, 'Nui xào thịt bò', 'Hình dáng, màu sắc của những sợi nui quện lẫn thịt bò viên chắc chắc sẽ khiến bé thích thú và ăn ngon miệng.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/09/09/nuixaobo-1631157302-5832-1631157339.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5dN9zxrdX7D6pPo1q9ghFw', 0, 0, 'MEDIUM', 'Cùng thử nấu Nui xào thịt bò');
INSERT INTO public.post VALUES (386, '2025-11-20 17:10:45.85326', '2025-11-20 17:10:45.85326', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 388, 'Gà chiên húng quế kiểu Đài Loan giòn rụm', 'Vỏ ngoài giòn rụm, thịt gà bên trong mềm ngọt, hài hòa các vị cay mặn ngọt, dậy mùi thơm của lá húng quế rất hấp dẫn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/08/27/nh4-1630055395-1759-1630055494.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=iL2eBZYoiPBav1NizIUtBg', 25, 25, 'MEDIUM', 'Cùng thử nấu Gà chiên húng quế kiểu Đài Loan giòn rụm');
INSERT INTO public.post VALUES (397, '2025-11-20 17:10:47.944295', '2025-11-20 17:10:47.944295', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 399, 'Cánh gà nấu nấm', 'Món canh nấu từ cánh gà và nấm này rất hấp dẫn từ mùi vị đến màu sắc và rất giàu dinh dưỡng.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/07/27/Canhga-1627319485-3995-1627319532.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=I_spyXHZDRlDjosCHcmxlg', 0, 0, 'MEDIUM', 'Cùng thử nấu Cánh gà nấu nấm');
INSERT INTO public.post VALUES (401, '2025-11-20 17:10:48.604695', '2025-11-20 17:10:48.604695', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 403, 'Cách làm kim chi dưa leo đơn giản tại nhà', 'Kim chi dưa leo (dưa chuột) vị chua ngọt hài hòa, dậy mùi thơm đặc trưng của kim chi, ăn cùng cơm nóng hoặc thịt nướng rất ''''hao cơm''''.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/07/28/nh3-1627440243-5713-1627440289.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=1UxKdapW87cAbVGsiQR6sQ', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm kim chi dưa leo đơn giản tại nhà');
INSERT INTO public.post VALUES (412, '2025-11-20 17:10:50.41988', '2025-11-20 17:10:50.41988', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 414, 'Chả giò khoai môn', 'Có nhiều loại chả giò nhưng ăn đỡ ngán và lạ miệng hơn cả có lẽ là món chả giò khoai môn.', 'Sóc Trăng', 'https://i1-giadinh.vnecdn.net/2021/07/26/Chagiokhoaimon-1627292572-5260-1627292652.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EGzUhEgVDm31ilGUhLq1HQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Chả giò khoai môn');
INSERT INTO public.post VALUES (416, '2025-11-20 17:10:51.229074', '2025-11-20 17:10:51.229074', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 418, 'Gỏi đu đủ tôm đất', 'Ngoài việc dùng làm món tráng miệng giúp cho đường ruột dễ dàng tiêu hóa, đu đủ còn được các đầu bếp chế biến thành nhiều món ăn ngon và bổ dưỡng.', 'Bình Định', 'https://i1-giadinh.vnecdn.net/2009/11/25/du-1351676165.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=2UyNFcmgCSf7rlRTt3GzRg', 0, 0, 'MEDIUM', 'Cùng thử nấu Gỏi đu đủ tôm đất');
INSERT INTO public.post VALUES (328, '2025-11-20 17:10:35.171725', '2025-11-20 17:10:35.171725', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 330, 'Cá quả kho tương', 'Đơn giản khi chế biến, cá quả kho tương là món ăn mang đậm chất dân dã của đồng bằng bắc bộ rất ngon.', 'Bắc Giang', 'https://i1-giadinh.vnecdn.net/2021/10/07/caqua-1633577031-8834-1633577050.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=yXJwH8zfgwEerCcBZcyCWw', 0, 0, 'MEDIUM', 'Cùng thử nấu Cá quả kho tương');
INSERT INTO public.post VALUES (343, '2025-11-20 17:10:38.244098', '2025-11-20 17:10:38.244098', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 345, 'Mực chiên giòn', 'Món ăn rất hấp dẫn từ mực này làm khá đơn giản và không tốn nhiều thời gian. Mời bạn trổ tài dưới sự hướng dẫn của các đầu bếp Ezcooking.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/10/05/muc-1633402669-6844-1633402828.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Y2MCu2qWLHSAYd_IS68Uhw', 0, 0, 'HARD', 'Cùng thử nấu Mực chiên giòn');
INSERT INTO public.post VALUES (358, '2025-11-20 17:10:40.371688', '2025-11-20 17:10:40.371688', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 360, 'Nem công chả phượng', 'Một chút sáng tạo sẽ biến món chả Sài Gòn thành món ăn mới, lạ và rất ngon miệng. Lớp bánh tráng mỏng quấn bên ngoài được thay bằng bánh đa. Đây sẽ là món khai vị hấp dẫn cho bữa Tất niên.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/02/cha-1633146229-9079-1633146253.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=fIo3oR3BnUGeXttCZmyBYQ', 0, 0, 'EASY', 'Cùng thử nấu Nem công chả phượng');
INSERT INTO public.post VALUES (373, '2025-11-20 17:10:43.021869', '2025-11-20 17:10:43.021869', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 375, 'Cánh gà nhồi cốm', 'Món này vừa ngon, vừa có mùi thơm đặc biệt, rất hấp dẫn mà làm không hề mất nhiều công.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/23/Canhganhoicom-1632396313-3410-1632396380.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=AGoOM_pjFwCWbO-0NaIWmw', 0, 0, 'MEDIUM', 'Cùng thử nấu Cánh gà nhồi cốm');
INSERT INTO public.post VALUES (388, '2025-11-20 17:10:46.24594', '2025-11-20 17:10:46.24594', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 390, 'Cá chép kho riềng kiểu miền Bắc', 'Mùi thơm của riềng gừng, vị đậm đà của cá sẽ khiến món ăn đơn giản này "tốn" cơm nhà bạn lắm đấy. Mời bạn trổ tài theo hướng dẫn dưới đây.', 'Hà Nam', 'https://i1-giadinh.vnecdn.net/2021/08/02/Cchpkhoring-1627901968-1318-1627902150.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0wvo_sZHuqALrtBBfNJyfA', 0, 0, 'EASY', 'Cùng thử nấu Cá chép kho riềng kiểu miền Bắc');
INSERT INTO public.post VALUES (403, '2025-11-20 17:10:48.989527', '2025-11-20 17:10:48.989527', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 405, 'Thăn heo rôti', 'Món ăn rất bắt mắt, vị lạ này sẽ hấp dẫn cả gia đình bạn. Mời bạn trổ tài đãi cả nhà vào bữa cuối tuần này.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/07/28/thanheo-1627464943-1856-1627464957.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VL7ZD2nCuzkicJ3JRsEY7A', 0, 0, 'MEDIUM', 'Cùng thử nấu Thăn heo rôti');
INSERT INTO public.post VALUES (418, '2025-11-20 17:10:51.478002', '2025-11-20 17:10:51.478002', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 420, 'Cháo trai cho bữa sáng', 'Một bát cháo trai nóng hổi, thơm mùi tiêu và hành răm, ngọt đậm đà rất thích hợp để làm món ăn sáng cho gia đình bạn.', 'Nam Định', 'https://i1-ngoisao.vnecdn.net/2021/07/04/207302257-532510757899751-6560-9524-4708-1625392493.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=2pCd57qmJ2uHMTeAGNvlmA', 0, 0, 'MEDIUM', 'Cùng thử nấu Cháo trai cho bữa sáng');
INSERT INTO public.post VALUES (333, '2025-11-20 17:10:36.3258', '2025-11-20 17:10:36.3258', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 335, 'Rau xào bát vị chay', 'Vẫn là một món rau nhưng rau xào bát vị chay sẽ mang lại cho bạn một cảm giác lạ miệng rất đặc biệt. Mời bạn thử làm dưới sự hướng dẫn của Ezcooking.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/05/rau-1633402373-7485-1633402481.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0ZixYPSyE9u8ou82U9FPRA', 0, 0, 'HARD', 'Cùng thử nấu Rau xào bát vị chay');
INSERT INTO public.post VALUES (348, '2025-11-20 17:10:38.916686', '2025-11-20 17:10:38.916686', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 350, 'Nộm tôm miến', 'Món này không cầu kỳ lại ăn rất ngon, không ngán, đủ các thành phần từ tinh bột, chất đạm, rau xanh.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2021/10/01/Nomtommien-1633083878-3483-1633083931.png?w=0&h=0&q=100&dpr=2&fit=crop&s=PhCsXA8wLuFCT6SgAPPTVQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Nộm tôm miến');
INSERT INTO public.post VALUES (363, '2025-11-20 17:10:41.283883', '2025-11-20 17:10:41.283883', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 365, 'Cơm Âm phủ', 'Cái tên nghe rất lạ, tạo cho thực khách vẻ “sờ sợ” nhưng lại là một món ngon độc đáo trong nghệ thuật ẩm thực Huế. Món này vừa mang tính thôn dã của dân gian vừa phảng phất phong cách cung đình rất Huế.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/01/ComAmPhu-1633084276-2094-1633084348.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3uEWEImF5PhB0Rwnt2bH8w', 0, 0, 'MEDIUM', 'Cùng thử nấu Cơm Âm phủ');
INSERT INTO public.post VALUES (378, '2025-11-20 17:10:43.768568', '2025-11-20 17:10:43.768568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 380, 'Canh thịt bò nấm hương', 'Ngon miệng, bổ dưỡng, dễ thực hiện là những ưu điểm của món canh này. Mời bạn làm ngay để gia đình thưởng thức.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/09/09/canhthitbonamdongco-1631149596-8672-1631149652.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=sBvvU5zJqBqah8A-r3ZbKg', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh thịt bò nấm hương');
INSERT INTO public.post VALUES (393, '2025-11-20 17:10:47.294638', '2025-11-20 17:10:47.294638', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 395, 'Tôm xào mướp hương', 'Mướp, tôm và gừng, những nguyên liệu rẩt phố biến này kết hợp với nhau sẽ cho bạn một món xào thơm phức, ngọt mát và rất tốt cho sức khỏe.', 'Hưng Yên', 'https://i1-giadinh.vnecdn.net/2021/08/05/muopnonxaotomtuoi-1628156357-8606-1628156419.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=GHqnxxGxWnN_3-2KSN3b_g', 0, 0, 'EASY', 'Cùng thử nấu Tôm xào mướp hương');
INSERT INTO public.post VALUES (408, '2025-11-20 17:10:49.574997', '2025-11-20 17:10:49.574997', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 410, 'Nộm gà hoa chuối', 'Nộm gà hoa chuối làm không quá cầu kỳ nhưng để để món ăn có được nhiều hương vị phong phú, bạn cần chuẩn bị nhiều loại nguyên liệu khác nhau.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/07/26/Nomga-1627295493-6993-1627295550.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=utjrj9aFUg7UaUEtlqRy9g', 0, 0, 'MEDIUM', 'Cùng thử nấu Nộm gà hoa chuối');
INSERT INTO public.post VALUES (423, '2025-11-20 17:10:52.288271', '2025-11-20 17:10:52.288271', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 425, 'Cơm chiên Dương Châu hải sản', 'Hạt cơm chiên chín tơi, không quá khô, kết hợp cùng rau củ, thịt tôm ngọt, râu mực giòn giòn, hấp dẫn.', 'Hồ Chí Minh', 'https://i1-ngoisao.vnecdn.net/2021/06/25/198504848-2622790214680794-479-6512-9877-1624624050.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3cC_9JYllGl6_MPejUIjIw', 0, 0, 'MEDIUM', 'Cùng thử nấu Cơm chiên Dương Châu hải sản');
INSERT INTO public.post VALUES (336, '2025-11-20 17:10:37.01265', '2025-11-20 17:10:37.01265', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 338, 'Canh sườn non nha đam và đậu xanh', 'Món canh này rất lạ miệng, vừa có tác dụng phát triển cơ bắp đồng thời tốt cho tóc nhờ các nguyên liệu như nha đam, đậu xanh...', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2021/10/07/canhsuon-1633578074-3624-1633578183.png?w=0&h=0&q=100&dpr=2&fit=crop&s=83O-x6C04JuFzk3CsaxkUg', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh sườn non nha đam và đậu xanh');
INSERT INTO public.post VALUES (344, '2025-11-20 17:10:38.392938', '2025-11-20 17:10:38.392938', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 346, 'Bò sốt tiêu đen', 'Vẫn từ nguyên liệu quen thuộc là thịt bò, món ăn này đơn giản, dễ làm mà lại rất ngon miệng.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/03/Cchlmbsttiuenthmngonncmi1200x9-3304-1456-1633270164.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=U8suR7rELoTQhi1G6KSzag', 0, 0, 'MEDIUM', 'Cùng thử nấu Bò sốt tiêu đen');
INSERT INTO public.post VALUES (349, '2025-11-20 17:10:39.08346', '2025-11-20 17:10:39.08346', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 351, 'Tôm chiên xốp', 'Vẫn từ các nguyên liệu đơn giản, quen thuộc, bạn sẽ tạo ra được một món ăn rất ngon và lạ miệng với tôm.', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2021/10/03/chienxu11497409154001-16332669-1499-6841-1633266984.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=S1INFEz1vA_5xxfgkyquoQ', 0, 0, 'EASY', 'Cùng thử nấu Tôm chiên xốp');
INSERT INTO public.post VALUES (351, '2025-11-20 17:10:39.403707', '2025-11-20 17:10:39.403707', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 353, '4 món ngon từ hoa thiên lý', 'Thiên lý là loại hoa có tính giải nhiệt cao, không chỉ trồng để làm cảnh, mà còn được sử dụng để chế biến những món ăn ngon và bổ. 4 món dưới đây đều dễ làm và có hương vị rất hấp dẫn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/02/thienly-1633144845-7913-1633144889.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kt2x9Us1Cxp1VRUd7wlTKg', 0, 0, 'MEDIUM', 'Cùng thử nấu 4 món ngon từ hoa thiên lý');
INSERT INTO public.post VALUES (359, '2025-11-20 17:10:40.519656', '2025-11-20 17:10:40.519656', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 361, 'Vịt nấu chao', 'Không phải cao lương mỹ vị, rất dân dã, mang đặc trưng Nam Bộ nhưng vịt nấu chao trở thành món khoái khẩu của nhiều người bởi hương vị thơm ngon rất riêng. Mời bạn tham khảo cách làm từ các đầu bếp Rosa.', 'Sóc Trăng', 'https://i1-giadinh.vnecdn.net/2021/10/01/vit-1633063947-5897-1633064154.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=LIfIMW4tqDZPy6LXI9PZnA', 0, 0, 'MEDIUM', 'Cùng thử nấu Vịt nấu chao');
INSERT INTO public.post VALUES (364, '2025-11-20 17:10:41.513707', '2025-11-20 17:10:41.513707', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 366, 'Cá quả chiên xù', 'Cách chế biến đơn giản, hương vị thơm ngon... món này sẽ giúp bạn ghi điểm với cả nhà vào dịp cuối tuần này. Mời bạn tham khảo hướng dẫn từ các đầu bếp Ezcooking.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/30/Cquchinx-1633002821-8039-1633002877.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=oV_Rvh4vIZz-pjwW921F3w', 0, 0, 'MEDIUM', 'Cùng thử nấu Cá quả chiên xù');
INSERT INTO public.post VALUES (366, '2025-11-20 17:10:41.830713', '2025-11-20 17:10:41.830713', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 368, 'Cách làm miến vịt măng khô đơn giản tại nhà', 'Thịt vịt mềm ngọt, măng khô dai dai, nước dùng ngọt tự nhiên sẽ là món ngon đơn giản trong những ngày giãn cách.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/26/nh2-1632628963-4309-1632629156.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9klvFJElaV-SCdo5DTglCw', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm miến vịt măng khô đơn giản tại nhà');
INSERT INTO public.post VALUES (374, '2025-11-20 17:10:43.186774', '2025-11-20 17:10:43.186774', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 376, 'Lẩu cua đồng', 'Món này lạ miệng, mát bổ nhưng lại rất dễ chế biến, hợp cho bữa tối của mùa hè. Mời bạn trổ tài theo những hướng dẫn dưới đây.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2021/09/09/laucuadong-1631150218-1756-1631150276.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=WqBwVyovIeemzP_KICap7Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Lẩu cua đồng');
INSERT INTO public.post VALUES (379, '2025-11-20 17:10:44.009337', '2025-11-20 17:10:44.009337', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 381, 'Salad Nga rau củ', 'Món ăn được nhiều người yêu thích này làm rất đơn giản. Mời bạn trổ tài đãi gia đình vào cuối tuần.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/09/09/SaladNga-1631149185-5057-1631149227.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=wFrXHSzX9HzsSJ2ho2iH6A', 0, 0, 'MEDIUM', 'Cùng thử nấu Salad Nga rau củ');
INSERT INTO public.post VALUES (381, '2025-11-20 17:10:44.34295', '2025-11-20 17:10:44.34295', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 383, 'Gà cuộn sốt cam sành', 'Màu sắc, mùi thơm hấp dẫn với hương vị chua ngọt thơm ngon, món ăn lạ miệng này sẽ giúp bạn ghi điểm với cả nhà đấy.', 'Hòa Bình', 'https://i1-giadinh.vnecdn.net/2021/09/08/Gasotcam-1631100591-3381-1631100645.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=C64ACQOYZhHw7GGzZppcow', 0, 0, 'MEDIUM', 'Cùng thử nấu Gà cuộn sốt cam sành');
INSERT INTO public.post VALUES (389, '2025-11-20 17:10:46.504914', '2025-11-20 17:10:46.504914', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 391, 'Bánh khoai tây nhân thịt', 'Đây là một món ngon, lạ miệng dành cho các bé. Món này dễ chế biến và rất giàu dinh dưỡng, mời bạn cùng tham khảo cách làm.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/08/02/Bnhkhoaitynhntht-1627901662-4260-1627901694.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MrjIi5FQbd1jWtwIVnsy7g', 0, 0, 'MEDIUM', 'Cùng thử nấu Bánh khoai tây nhân thịt');
INSERT INTO public.post VALUES (394, '2025-11-20 17:10:47.626928', '2025-11-20 17:10:47.626928', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 396, 'Cơm gà nấu thố', 'Món ăn có hương vị hấp dẫn và rất lạ miệng này đòi hỏi bạn phải chế biến hơi công phu một chút. Mời bạn tham khảo cách làm dưới đây.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/07/28/Comga-1627464502-6511-1627464530.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=hGVQb6lMTjyw1jQXMBj22g', 0, 0, 'HARD', 'Cùng thử nấu Cơm gà nấu thố');
INSERT INTO public.post VALUES (396, '2025-11-20 17:10:47.81762', '2025-11-20 17:10:47.81762', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 398, 'Cách làm món sườn non rang muối', 'Đã chán sườn xào chua ngọt, sườn rim mặn thì bạn hãy làm sườn rang muối, vừa có thể ăn chơi hoặc ăn cùng cơm đều ngon.', 'Hồ Chí Minh', 'https://i1-ngoisao.vnecdn.net/2017/03/16/topsrm1-1489676663.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=x57beTEBadBHK3QiMi8pEg', 0, 0, 'EASY', 'Cùng thử nấu Cách làm món sườn non rang muối');
INSERT INTO public.post VALUES (404, '2025-11-20 17:10:49.092006', '2025-11-20 17:10:49.092006', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 406, 'Gà cuộn hấp', 'Món ăn rất bắt mắt với hương vị thơm ngon này sẽ giúp bữa ăn nhà bạn thêm đầm ấm. Các chuyên gia Ezcooking sẽ hướng dẫn bạn cách nấu món này.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/07/26/gacuon-1627292352-9024-1627292413.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9vhnWqIy5VNY4txrQueKBg', 0, 0, 'EASY', 'Cùng thử nấu Gà cuộn hấp');
INSERT INTO public.post VALUES (409, '2025-11-20 17:10:49.709483', '2025-11-20 17:10:49.709483', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 411, 'Gà lăn bột chiên xù', 'Những món giòn giòn luôn tạo cảm giác ngon miệng. Lớp bột xù mỏng tang bọc quanh phần thịt gà vàng thơm béo ngậy sẽ hấp dẫn cả gia đình bạn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/07/26/gachienxu-1627293090-1293-1627293123.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kufbsdivpIwqv_cxtU5oPQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Gà lăn bột chiên xù');
INSERT INTO public.post VALUES (342, '2025-11-20 17:10:38.071826', '2025-11-20 17:10:38.071826', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 344, 'Thịt bò thưng', 'Những dịp lễ Tết, giỗ chạp, ngoài các món như nem, bì, chạo, chả… làm từ thịt heo, bò, người miền Trung còn hay nấu "thịt bò thưng", rất đậm đà, lạ miệng.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/10/02/Bothung21280x720-1633164774-2847-1633164880.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qqZDyCqnzpNCijq8cZI9EQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Thịt bò thưng');
INSERT INTO public.post VALUES (357, '2025-11-20 17:10:40.238813', '2025-11-20 17:10:40.238813', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 359, 'Tôm sốt hạt thông', 'Món này làm khá đơn giản lại có hương vị đặc biệt. Mời bạn trổ tài dưới hướng dẫn của các đầu bếp Ezcooking.', 'Ninh Thuận', 'https://i1-giadinh.vnecdn.net/2021/10/01/tom-1633063495-4061-1633063530.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qEJcYR50MvOCFpowko4Y-Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Tôm sốt hạt thông');
INSERT INTO public.post VALUES (372, '2025-11-20 17:10:42.907897', '2025-11-20 17:10:42.907897', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 374, 'Canh cá giấm mẻ', 'Canh cá là món ăn dân dã thơm ngon và bổ dưỡng. Món canh sẽ làm bữa cơm ngày hè của gia đình bạn ngon hơn nhờ vị thanh mát và ngọt đậm vị cá.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2021/09/09/canhcanaume500-1631188718-5660-1631188785.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5yDWdT69ygS20M6K1q7jhw', 0, 0, 'EASY', 'Cùng thử nấu Canh cá giấm mẻ');
INSERT INTO public.post VALUES (387, '2025-11-20 17:10:46.110954', '2025-11-20 17:10:46.110954', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 389, 'Bò nướng chao', 'Vẫn từ nguyên liệu quen thuộc nhưng bò nướng chao sẽ đem đến cho bạn một hương vị hoàn toàn mới lạ. Mời bạn trổ tài theo hướng dẫn của các đầu bếp.', 'Tây Ninh', 'https://i1-giadinh.vnecdn.net/2021/09/08/botonuongchao-1631103188-3833-1631103242.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=xa2-C-z9yuAxF-0rgsxW8Q', 0, 0, 'HARD', 'Cùng thử nấu Bò nướng chao');
INSERT INTO public.post VALUES (402, '2025-11-20 17:10:48.771843', '2025-11-20 17:10:48.771843', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 404, 'Chả giò mực bánh đa', 'Bánh đa được tráng lớp mè đen khi chiên phồng sẽ rất giòn và thơm. Ngoài ra, lớp nhân mực bên trong cũng tạo cảm giác lạ miệng khi ăn.', 'Quảng Ninh', 'https://i1-giadinh.vnecdn.net/2021/07/28/chagiomuc-1627465337-4903-1627465495.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=mFjIkaR1zp6dPBe7Xf-OhQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Chả giò mực bánh đa');
INSERT INTO public.post VALUES (417, '2025-11-20 17:10:51.302882', '2025-11-20 17:10:51.302882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 419, 'Làm trứng hấp mềm như bánh pudding bằng nồi chiên không dầu', 'Trứng hấp mềm mịn, vị béo thơm ăn với thịt heo băm, điểm vài miếng hành lá trở thành món điểm tâm đủ chất.', 'Hồ Chí Minh', 'https://iv1.vnecdn.net/ngoisao/images/web/2021/07/02/lam-trung-hap-mem-nhu-banh-pudding-bang-noi-chien-khong-dau-1625217060.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=LYaKfCQL8wNeyZ-oKGWBWg', 15, 15, 'EASY', 'Cùng thử nấu Làm trứng hấp mềm như bánh pudding bằng nồi chiên không dầu');
INSERT INTO public.post VALUES (362, '2025-11-20 17:10:41.073682', '2025-11-20 17:10:41.073682', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 364, 'Tôm chiên dừa khô', 'Tôm chiên giòn hòa với những miếng dừa non lựt xựt tan trong miệng sẽ là món đưa cơm ấn tượng trong bữa ăn sum họp của gia đình.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/01/tomchiendua1200x676-1633060592-9376-1633060715.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=QYnv9vPrjPsa_QBKnX0SuA', 0, 0, 'EASY', 'Cùng thử nấu Tôm chiên dừa khô');
INSERT INTO public.post VALUES (377, '2025-11-20 17:10:43.582784', '2025-11-20 17:10:43.582784', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 379, 'Trứng chiên lá lốt - món ăn dân dã tuổi thơ', 'Không chỉ là món ăn thơm ngon, trứng chiên lá lốt còn có tác dụng chữa bệnh xương khớp, rất tốt cho người già.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/09/17/trungchien-1631878355-8510-1631878417.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=QJdhpINHmDQAn3dWLkFShw', 10, 10, 'EASY', 'Cùng thử nấu Trứng chiên lá lốt - món ăn dân dã tuổi thơ');
INSERT INTO public.post VALUES (392, '2025-11-20 17:10:47.150034', '2025-11-20 17:10:47.150034', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 394, 'Mực dồn thịt', 'Một cách làm mới cho món ăn vốn khá quen thuộc sẽ đem đến cho bạn hương vị khá lạ, hấp dẫn. Mời bạn tham khảo để làm món ăn ngon từ mực nhé.', 'Quảng Ninh', 'https://i1-giadinh.vnecdn.net/2021/07/31/mucnhoithit-1627728595-8692-1627728631.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gltenJymKaz15fvnG4WEAw', 0, 0, 'EASY', 'Cùng thử nấu Mực dồn thịt');
INSERT INTO public.post VALUES (407, '2025-11-20 17:10:49.353927', '2025-11-20 17:10:49.353927', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 409, 'Giò heo muối chiên giòn', 'Giò heo muối chiên giòn không khó như bạn tưởng, món này làm đơn giản mà lại rất hấp dẫn. Bạn có thể trổ tài để đãi khách hay ăn trong bữa cơm gia đình.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/07/26/changio-1627293993-9519-1627294045.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=AOX-ddeU7aGz0jkZxx5evA', 0, 0, 'MEDIUM', 'Cùng thử nấu Giò heo muối chiên giòn');
INSERT INTO public.post VALUES (422, '2025-11-20 17:10:52.165577', '2025-11-20 17:10:52.165577', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 424, 'Chả giò khoai môn thịt heo', 'Chả giò (nem) giòn rụm bên ngoài, bên trong thịt ẩm mềm hoà với vị béo bùi của khoai môn hấp dẫn.', 'Sóc Trăng', 'https://i1-ngoisao.vnecdn.net/2021/06/24/201894824-822823701977401-3165-9076-5804-1624526997.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=dQFSakcsjEdq3qsVpZ6yIg', 0, 0, 'EASY', 'Cùng thử nấu Chả giò khoai môn thịt heo');
INSERT INTO public.post VALUES (390, '2025-11-20 17:10:46.792499', '2025-11-20 17:10:46.792499', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 392, 'Vịt om bia bổ dưỡng', 'Vịt om bia mềm, thơm và bổ dưỡng, tuy chế biến hơi mất thời gian một chút nhưng ăn ngon và lạ miệng. Đang mùa thịt vịt bạn hãy chọn món này để cả nhà cùng thưởng thức nhé.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/08/23/Vitombiaboduong-1629710882-6420-1629710925.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=fWBR-b6lLJpXFsDEmIJCBw', 0, 0, 'MEDIUM', 'Cùng thử nấu Vịt om bia bổ dưỡng');
INSERT INTO public.post VALUES (395, '2025-11-20 17:10:47.727826', '2025-11-20 17:10:47.727826', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 397, 'Cánh gà xào ớt chuông', 'Thịt gà chín mềm, đậm đà vị mặn ngọt, món ăn đầy màu sắc với mùi thơm hấp dẫn này sẽ khiến bữa cơm nhà bạn thêm ấm áp.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/08/04/Canhgaxaootchuong-1628077969-5033-1628078014.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=YuTbfiiqCt3xWM6HdLbVFg', 0, 0, 'MEDIUM', 'Cùng thử nấu Cánh gà xào ớt chuông');
INSERT INTO public.post VALUES (398, '2025-11-20 17:10:48.0496', '2025-11-20 17:10:48.0496', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 400, 'Thịt kho nấm rơm', 'Món ăn đơn giản nhưng có hương vị thơm ngon, đặc biệt là rất "vào" cơm. Bạn có thể làm nhanh món này để gia đình thưởng thức hôm nay.', 'Long An', 'https://i1-giadinh.vnecdn.net/2021/08/02/Thtkhonmrm-1627902641-1934-1627902674.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=4-PRKkFFEHZj6j-RLwt_Kg', 0, 0, 'EASY', 'Cùng thử nấu Thịt kho nấm rơm');
INSERT INTO public.post VALUES (405, '2025-11-20 17:10:49.184543', '2025-11-20 17:10:49.184543', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 407, 'Rạm kho lá lốt – món ngon Thái Bình', 'Rạm giòn, đậm vị, gạch đỏ vàng ươm, dậy mùi thơm lá lốt khiến ai một lần ăn đều nhớ mãi món ăn dân dã này của Thái Bình.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2021/07/28/nh3-1627439898-5732-1627439986.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Jjoyx49gr3a69AiwXuhkuQ', 20, 20, 'EASY', 'Cùng thử nấu Rạm kho lá lốt – món ngon Thái Bình');
INSERT INTO public.post VALUES (410, '2025-11-20 17:10:49.911487', '2025-11-20 17:10:49.911487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 412, 'Bún bò cà chua', 'Món bún dễ làm này bạn có thể trổ tài để cả nhà được thưởng thức vào bữa sáng, rất ngon và đảm bảo dinh dưỡng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/07/26/Bunbocachua-1627293654-4189-1627293697.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=xX2z0ofZMKH22gq-adJYjg', 0, 0, 'MEDIUM', 'Cùng thử nấu Bún bò cà chua');
INSERT INTO public.post VALUES (413, '2025-11-20 17:10:50.53541', '2025-11-20 17:10:50.53541', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 415, 'Khoai tây om thịt gà', 'Những ngày trời lạnh các món hầm và om rất được ưa chuộng. Gà om khoai tây là món ăn có hương vị thơm ngon, lại rất giàu dinh dưỡng, mời bạn bổ sung vào thực đơn nhà mình hôm nay.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2009/11/14/khoai-1351676190.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=hd23bHxAJF7tIRyiRMMUTw', 0, 0, 'EASY', 'Cùng thử nấu Khoai tây om thịt gà');
INSERT INTO public.post VALUES (420, '2025-11-20 17:10:51.892229', '2025-11-20 17:10:51.892229', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 422, 'Củ cải đường nấu thịt băm', 'Món canh ngọt, mát này cực kỳ dễ làm, khâu chuẩn bị cũng rất nhanh. Bạn cũng có thể nấu món này cho các bé, vừa dễ ăn vừa tốt cho sức khỏe.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/07/26/cucaiduong-1627293318-6911-1627293351.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=QUlzvI4unMcHsENq3WHypQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Củ cải đường nấu thịt băm');
INSERT INTO public.post VALUES (411, '2025-11-20 17:10:50.249541', '2025-11-20 17:10:50.249541', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 413, 'Cá ba sa tẩm mè', 'Món ăn có màu sắc bắt mắt, vị ngọt của cá có thêm vị thơm, bùi của mè trắng sẽ khiến bạn thêm ngon miệng. Mời các bạn tham khảo công thức nấu.', 'An Giang', 'https://i1-giadinh.vnecdn.net/2021/07/26/Cabasa-1627292872-4574-1627292913.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0at3VboqJ1Bz3pUvpiEuuw', 0, 0, 'HARD', 'Cùng thử nấu Cá ba sa tẩm mè');
INSERT INTO public.post VALUES (419, '2025-11-20 17:10:51.678846', '2025-11-20 17:10:51.678846', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 421, 'Cá hồi ngâm tương - món ''gây sốt'' mùa hè', 'Cá hồi mềm béo, quyện với nước tương chua, cay, mặn, ngọt thích hợp ăn với cơm trắng.', 'Lâm Đồng', 'https://iv1.vnecdn.net/ngoisao/images/web/2021/06/21/ca-hoi-ngam-tuong-1624268334.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=9gOi3fHZgltXm0bunxV30g', 0, 0, 'MEDIUM', 'Cùng thử nấu Cá hồi ngâm tương - món ''gây sốt'' mùa hè');
INSERT INTO public.post VALUES (424, '2025-11-20 17:10:52.461833', '2025-11-20 17:10:52.461833', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 426, 'Chân gà rút xương trộn cóc non', 'Chân gà mềm thấm sốt chua ngọt cay cay, cóc giòn giòn chua chua. Đây sẽ là món ăn vặt ngon cho những đêm thức cùng Euro.', 'Hồ Chí Minh', 'https://i1-ngoisao.vnecdn.net/2021/06/27/200930792-1275429246193422-393-3210-6878-1624790293.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gQViLyx8uwT-fxzoXaZTiw', 0, 0, 'MEDIUM', 'Cùng thử nấu Chân gà rút xương trộn cóc non');
INSERT INTO public.post VALUES (425, '2025-11-20 17:10:52.691694', '2025-11-20 17:10:52.691694', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 427, 'Cách làm dẻ sườn bò om dưa cải chua', 'Thịt bò mềm mà không khô, dưa cải chua giòn, nước dùng vị chua dịu rất hao cơm trong mùa nóng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/07/19/nh3-1626689540-5567-1626689683.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=YSliAvOgO4Bqi0Rei84UmQ', 32, 33, 'MEDIUM', 'Cùng thử nấu Cách làm dẻ sườn bò om dưa cải chua');
INSERT INTO public.post VALUES (426, '2025-11-20 17:10:52.984153', '2025-11-20 17:10:52.984153', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 428, 'Cách làm món cá lóc nấu măng chua đơn giản mà cực ngon', 'Để làm món cá xào măng, cần dùng loại cá thịt chắc như cá lóc (miền Bắc gọi là cá quả), trong quá trình xào tuyệt đối không cho nước, tránh làm thịt cá vỡ nát.', 'Đồng Tháp', 'https://iv1.vnecdn.net/giadinh/images/web/2021/06/07/ca-loc-xao-mang-1623056900.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=7i1hVfpC9Zz2nxALOSWu_g', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm món cá lóc nấu măng chua đơn giản mà cực ngon');
INSERT INTO public.post VALUES (427, '2025-11-20 17:10:53.305017', '2025-11-20 17:10:53.305017', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 429, 'Cách làm cá trích kho rục', '''Cá trích kho rục, xúc đầy chén cơm'', đây là món ăn dân dã, rẻ tiền, gắn liền với tuổi thơ nhiều người.', 'Kiên Giang', 'https://iv1.vnecdn.net/giadinh/images/web/2021/07/09/cach-lam-ca-trich-kho-ruc-1625798844.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=JaJuiR7kh3tlD8bXva7UDw', 75, 75, 'MEDIUM', 'Cùng thử nấu Cách làm cá trích kho rục');
INSERT INTO public.post VALUES (428, '2025-11-20 17:10:53.630266', '2025-11-20 17:10:53.630266', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 430, 'Cách làm cá diếc kho tương chuẩn vị, đậm đà thơm ngon', 'Cá kho còn nguyên con, thịt ngọt đậm đà và dậy mùi thơm đặc trưng của tương bần.', 'Hưng Yên', 'https://iv1.vnecdn.net/giadinh/images/web/2021/06/07/cach-lam-ca-diec-kho-tuong-dam-vi-1623062062.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=JEAoT0FCaI2Drj7dwtjOGA', 90, 90, 'MEDIUM', 'Cùng thử nấu Cách làm cá diếc kho tương chuẩn vị, đậm đà thơm ngon');
INSERT INTO public.post VALUES (429, '2025-11-20 17:10:53.847324', '2025-11-20 17:10:53.847324', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 431, 'Cách làm canh don mồng tơi ngọt mát', 'Thịt don ngọt thanh tự nhiên xen lẫn màu xanh mướt của rau mồng tơi làm nên món canh nổi tiếng vùng Tiền Hải, Thái Bình.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2021/07/14/nh1-1626258034-6352-1626258204.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=oe_1OexGyoUtSMAJ8vcCAw', 20, 20, 'EASY', 'Cùng thử nấu Cách làm canh don mồng tơi ngọt mát');
INSERT INTO public.post VALUES (430, '2025-11-20 17:10:54.097652', '2025-11-20 17:10:54.097652', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 432, 'Cách làm lườn gà rang lá cà ri ngon như nhà hàng', 'Lườn gà rang với ớt khô và lá cà ri là món ăn rất phù hợp cho những ngày thời tiết mát mẻ hoặc hơi se lạnh. Nếu không mua được lá cà ri, bạn có thay bằng lá mắc mật.', 'Bình Phước', 'https://iv1.vnecdn.net/giadinh/images/web/2021/06/10/luon-ga-rang-la-ca-ri-1623325165.png?w=0&h=0&q=100&dpr=1&fit=crop&s=t8u2aXLXwJS0iBVquakqWw', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm lườn gà rang lá cà ri ngon như nhà hàng');
INSERT INTO public.post VALUES (431, '2025-11-20 17:10:54.216554', '2025-11-20 17:10:54.216554', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 433, 'Cách làm cánh gà chiên nước mắm ngon tuyệt vời', 'Cánh gà vàng óng, da giòn, thịt mềm ngọt, hương vị đậm đà. Món này ăn cùng cơm nóng và xôi đều rất ngon.', 'Hồ Chí Minh', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/30/cach-lam-canh-ga-chien-nuoc-mam-dam-da-1622342840.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=VgJosn4fEz2uBMxgNbpCFg', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm cánh gà chiên nước mắm ngon tuyệt vời');
INSERT INTO public.post VALUES (432, '2025-11-20 17:10:54.434596', '2025-11-20 17:10:54.434596', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 434, 'Cách đơn giản làm xôi mít hoa đậu biếc ngon lành', 'Món xôi lạ mắt với màu tím của đậu biếc, màu vàng của mít, lại khá đơn giản để bạn trổ tài.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/07/02/4298548-1625218471-4829-1625218475.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=FYTOrAfLqQOjubgqGsH_Hw', 30, 30, 'EASY', 'Cùng thử nấu Cách đơn giản làm xôi mít hoa đậu biếc ngon lành');
INSERT INTO public.post VALUES (433, '2025-11-20 17:10:54.554762', '2025-11-20 17:10:54.554762', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 435, 'Xôi cá khô Nha Trang', 'Xôi cá cơm là món ăn dân dã nhưng không kém phần hấp dẫn ở Nha Trang, xôi thơm dẻo, ăn kèm cá rim chua cay mặn ngọt.', 'Khánh Hòa', 'https://i1-ngoisao.vnecdn.net/2021/06/30/201804771-1974619062688916-236-6222-7898-1625043886.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=RyZUEiVuxEUR4yMHi8GjQQ', 0, 0, 'EASY', 'Cùng thử nấu Xôi cá khô Nha Trang');
INSERT INTO public.post VALUES (434, '2025-11-20 17:10:54.723147', '2025-11-20 17:10:54.723147', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 436, 'Canh chua đầu cá diêu hồng nấu đậu rồng', 'Canh chua đầu cá diêu hồng nấu đậu rồng vị chua ngọt thanh mát, thịt cá tươi dai kèm đậu rồng giòn giòn lạ miệng.', 'Đồng Tháp', 'https://i1-ngoisao.vnecdn.net/2021/06/26/201771999-217923010165626-5355-9910-8965-1624713096.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=OuX0a08XXErF41YNI5E9wQ', 0, 0, 'EASY', 'Cùng thử nấu Canh chua đầu cá diêu hồng nấu đậu rồng');
INSERT INTO public.post VALUES (435, '2025-11-20 17:10:54.814557', '2025-11-20 17:10:54.814557', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 437, 'Cách làm thịt kho măng đơn giản mà siêu ngon tại nhà', 'Thịt mềm, đậm đà, măng ngon giòn thấm vị mặn ngọt hài hòa, màu sắc hấp dẫn rất đưa cơm ngày hè.', 'Tuyên Quang', 'https://iv1.vnecdn.net/giadinh/images/web/2021/06/04/cach-lam-thit-kho-mang-dam-da-dua-com-1622795681.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=lBVJom32aVZWyLQeMLmtyw', 25, 25, 'EASY', 'Cùng thử nấu Cách làm thịt kho măng đơn giản mà siêu ngon tại nhà');
INSERT INTO public.post VALUES (436, '2025-11-20 17:10:54.956892', '2025-11-20 17:10:54.956892', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 438, 'Cách làm bồ câu hầm thuốc bắc, ngải cứu', 'Món ăn giàu dinh dưỡng này giúp bồi bổ sức khỏe cho người già, trẻ em và phụ nữ mang thai.', 'Hà Nội', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/21/cach-lam-bo-cau-ham-thuoc-bac-ngai-cuu-1621565647.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=-xiHnj4x4PQYo_VyXzUdBQ', 30, 30, 'EASY', 'Cùng thử nấu Cách làm bồ câu hầm thuốc bắc, ngải cứu');
INSERT INTO public.post VALUES (437, '2025-11-20 17:10:55.090143', '2025-11-20 17:10:55.090143', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 439, 'Cách nầu canh moi nấu dưa chua - món đưa cơm ngày hè', 'Dưa cải mềm, tép moi đậm đà săn ngọt, nước canh chua dịu, vị hài hòa. Món canh này rất hợp với bữa cơm gia đình trong tiết trời nóng bức.', 'Nghệ An', 'https://iv1.vnecdn.net/giadinh/images/web/2021/06/04/canh-moi-nau-dua-chua-dua-com-ngay-he-1622794675.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=i9JTIPl8MBXn21R-p3GiEA', 15, 15, 'EASY', 'Cùng thử nấu Cách nầu canh moi nấu dưa chua - món đưa cơm ngày hè');
INSERT INTO public.post VALUES (438, '2025-11-20 17:10:55.247868', '2025-11-20 17:10:55.247868', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 440, 'Cách nấu xôi chim bồ câu nấm hương thơm ngon và đơn giản', 'Xôi mềm dẻo, căng bóng quyện với thịt chim bồ câu béo, mùi hành phi thơm lừng nhanh chóng cuốn hút người thưởng thức từ cái nhìn đầu tiên.', 'Bắc Ninh', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/15/cach-lam-xoi-chim-bo-cau-nam-huong-thom-ngon-1621069128.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=qO_wjwLRUw_sj8572lvlbg', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách nấu xôi chim bồ câu nấm hương thơm ngon và đơn giản');
INSERT INTO public.post VALUES (451, '2025-11-20 17:10:57.933006', '2025-11-20 17:10:57.933006', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 453, 'Cách làm bò kho mật mía – đặc sản xứ Nghệ siêu ngon', 'Món ăn như kết tinh của các dư vị mặn – ngọt – đắng – cay như chính nét tảo tần, nồng đượm tình người của người dân xứ Nghệ.', 'Nghệ An', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/17/bo-kho-mat-mia---dac-san-xu-nghe-1621236548.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=vK72B67IZiI5tyFy2HGGOA', 45, 45, 'HARD', 'Cùng thử nấu Cách làm bò kho mật mía – đặc sản xứ Nghệ siêu ngon');
INSERT INTO public.post VALUES (452, '2025-11-20 17:10:58.113699', '2025-11-20 17:10:58.113699', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 454, 'Cách làm dưa chuột cuộn lườn gà tại nhà mà đơn giản', 'Đây là món cuốn hợp miệng, thanh mát cho những ngày hè nóng bức. Không những thế, dưa chuột cuộn lườn gà còn bổ dưỡng, ít béo, giúp giải ngấy hiệu quả.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/04/29/Untitled-1619664601-5652-1619665123.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=cqbVi6DbkRsTbN6kKmumhg', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm dưa chuột cuộn lườn gà tại nhà mà đơn giản');
INSERT INTO public.post VALUES (453, '2025-11-20 17:10:58.312807', '2025-11-20 17:10:58.312807', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 455, 'Cách làm đậu hũ bao bố - món ngon miệng, vui mắt', 'Món ăn quen thuộc, rẻ tiền sẽ chinh phục mọi thành viên trong gia đình nhờ vẻ ngoài lạ mắt bằng vài thao tác đơn giản.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/05/05/7-1620211250-5064-1620211336.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qaWq9BeHcjgO2f3gUC-HXQ', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm đậu hũ bao bố - món ngon miệng, vui mắt');
INSERT INTO public.post VALUES (466, '2025-11-20 17:11:02.605213', '2025-11-20 17:11:02.605213', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 468, 'Bí quyết làm cà pháo ngâm chua ngọt không bị đen', 'Bát cà pháo giòn tan, dậy mùi thơm riềng, tỏi, đậm đà vị chua mặn ngọt, thêm bát canh cua rau mồng tơi rất "đưa cơm" trong mùa hè.', 'Bắc Ninh', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/17/ca-phao-ngam-chua-ngot-gion-ngon-khong-bi-den-1618626687.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=9UHX83HBD-XvvtFQOwjtyw', 30, 30, 'MEDIUM', 'Cùng thử nấu Bí quyết làm cà pháo ngâm chua ngọt không bị đen');
INSERT INTO public.post VALUES (467, '2025-11-20 17:11:02.913861', '2025-11-20 17:11:02.913861', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 469, 'Cách làm xáo gà Thanh Chương nổi tiếng xứ Nghệ', 'Xáo gà Thanh Chương được chế biến từ các gia vị dân dã nhưng lại tạo nên hương vị đậm đà, tinh tế, ngọt thơm riêng.', 'Nghệ An', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/17/cach-lam-xao-ga-thanh-chuong-noi-tieng-xu-nghe-1618625859.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=lcBdiE1reHO5vq60XVMung', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm xáo gà Thanh Chương nổi tiếng xứ Nghệ');
INSERT INTO public.post VALUES (468, '2025-11-20 17:11:03.109134', '2025-11-20 17:11:03.109134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 470, 'Cách làm Đậu tẩm hành dễ làm mà ngon hết ý', 'Món ăn quen thuộc thời bao cấp nhưng hiện vẫn xuất hiện trong bữa cơm của các gia đình hiện đại bởi sự đơn giản mà hấp dẫn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/04/08/Dauphutamhanhchung-1617869966-1166-1617869995.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=8JAxNfuKWwgEViEayhCNZQ', 15, 15, 'EASY', 'Cùng thử nấu Cách làm Đậu tẩm hành dễ làm mà ngon hết ý');
INSERT INTO public.post VALUES (481, '2025-11-20 17:11:09.157377', '2025-11-20 17:11:09.157377', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 483, 'Chia sẻ bí quyết làm sườn ram mặn mềm ngon, màu đẹp', 'Thịt sườn mềm nhưng vẫn bám vào xương, nước sốt sánh màu hổ phách đẹp mắt, vị mặn ngọt hài hòa khiến ai cũng thích.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/03/25/com2-1616658985-4537-1616659187.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=l1gP8oZGbQTZCJYgibmv6w', 37, 38, 'HARD', 'Cùng thử nấu Chia sẻ bí quyết làm sườn ram mặn mềm ngon, màu đẹp');
INSERT INTO public.post VALUES (482, '2025-11-20 17:11:09.505633', '2025-11-20 17:11:09.505633', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 484, 'Hướng dẫn làm món Cá chiên xù NGON - GIÒN chỉ trong 30 phút', 'Cá chiên xù bên ngoài vàng ươm, giòn rụm, bên trong mềm ngọt tự nhiên, được nhiều trẻ em yêu thích.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/03/05/ca1-1614934321-2662-1614934330.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=TXUQQhXKutcUxz6w_XNGMA', 15, 15, 'HARD', 'Cùng thử nấu Hướng dẫn làm món Cá chiên xù NGON - GIÒN chỉ trong 30 phút');
INSERT INTO public.post VALUES (483, '2025-11-20 17:11:09.831317', '2025-11-20 17:11:09.831317', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 485, 'Hướng dẫn nấu Thịt đông thơm ngon, đậm vị kiểu miền Bắc', 'Món thịt đông mềm với bì (hoặc tai lợn), mộc nhĩ giòn sần sật, nằm gọn trong lớp nước trong veo là món ăn không thể thiếu trong ngày Tết ở miền Bắc.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/02/04/thit2-1612414588-5011-1612414921.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=62_Cyyx8rwPZ_TOA2qWJ8w', 20, 20, 'HARD', 'Cùng thử nấu Hướng dẫn nấu Thịt đông thơm ngon, đậm vị kiểu miền Bắc');
INSERT INTO public.post VALUES (493, '2025-11-20 17:11:14.321415', '2025-11-20 17:11:14.321415', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 495, 'Cách làm vịt om sấu đơn giản', 'Vịt om sấu có thịt mềm béo đậm đà, nước dùng chua thanh từ sấu quyện mùi thơm của sả như "bản giao hưởng đẹp" trong thực đơn ngày hè.', 'Hà Nội', 'https://iv1.vnecdn.net/giadinh/images/web/2021/06/18/cach-lam-vit-om-sau-don-gian-1624007889.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=GIZ8rmZiqQB_WiRMhVfb3w', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm vịt om sấu đơn giản');
INSERT INTO public.post VALUES (439, '2025-11-20 17:10:55.335885', '2025-11-20 17:10:55.335885', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 441, 'Xôi gấc dẻo ngọt', 'Xôi gấc chín dẻo thơm, hạt nếp căng mọng, vị ngọt nhẹ và có màu đỏ đẹp, hấp dẫn.', 'Hà Nội', 'https://i1-ngoisao.vnecdn.net/2021/07/02/205039701-526251145476854-8722-3502-3692-1625212714.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Eg3I9tbIW7-IsFgi1z0Rtg', 0, 0, 'MEDIUM', 'Cùng thử nấu Xôi gấc dẻo ngọt');
INSERT INTO public.post VALUES (441, '2025-11-20 17:10:55.792093', '2025-11-20 17:10:55.792093', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 443, 'Cách làm canh bí ngòi nấu tôm theo công thức của Chef Tuyết Phạm', 'Canh bí ngòi cuộn tôm là món ăn mà Chef Tuyết Phạm nhớ nhất mỗi khi hè về và thường mang ra chiêu đãi gia đình, bạn bè mỗi dịp tụ tập.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/06/01/hnh4-1622501732-8712-1622501872.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=y4SwP6gnUZiSHRyABdfAxQ', 0, 0, 'EASY', 'Cùng thử nấu Cách làm canh bí ngòi nấu tôm theo công thức của Chef Tuyết Phạm');
INSERT INTO public.post VALUES (449, '2025-11-20 17:10:57.385834', '2025-11-20 17:10:57.385834', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 451, 'Cách làm chân gà trộn xì dầu - món ngon lạ miệng', 'Chân gà trộn xì dầu có hương vị hấp dẫn, cung cấp lượng lớn collagen, hỗ trợ xương chắc khỏe và cải thiện hệ miễn dịch.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/07/02/4298523-1625216387-5474-1625216397.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VtFPW0692W6acJ3L_-DsOA', 20, 20, 'EASY', 'Cùng thử nấu Cách làm chân gà trộn xì dầu - món ngon lạ miệng');
INSERT INTO public.post VALUES (454, '2025-11-20 17:10:58.494954', '2025-11-20 17:10:58.494954', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 456, 'Cách làm kho quẹt đậm đà ngon đúng chuẩn Nam Bộ', 'Kho quẹt là món đơn giản, dễ làm và mang hương vị ký ức tuổi thơ nghèo khó nhưng đã trở thành đặc sản trong nhiều nhà hàng.', 'Đồng Tháp', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/29/cach-lam-kho-quet-dam-da-1619658033.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=7gPYUUU3Ty4En0d-JrTZ_Q', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm kho quẹt đậm đà ngon đúng chuẩn Nam Bộ');
INSERT INTO public.post VALUES (456, '2025-11-20 17:10:59.130898', '2025-11-20 17:10:59.130898', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 458, 'Cách làm gà hấp lá sen ngọt thơm cho dịp lễ', 'Thịt gà mềm, mọng nước; hạt sen bở, nấm hương thơm, thoảng mùi thơm từ lá sen. Món gà hấp lá sen có thể ăn chơi, ăn kèm xôi hoặc cơm đều hấp dẫn.', 'Hà Nội', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/30/cach-lam-ga-hap-la-sen-ngot-thom-cho-dip-le-1619775327.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=RMnUTwwSM7b90hDa7RXtHA', 35, 35, 'HARD', 'Cùng thử nấu Cách làm gà hấp lá sen ngọt thơm cho dịp lễ');
INSERT INTO public.post VALUES (464, '2025-11-20 17:11:02.101832', '2025-11-20 17:11:02.101832', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 466, 'Hướng dẫn làm Lòng heo khìa nước dừa đậm đà vị mặn ngọt', 'Từng miếng lòng thơm lừng, đậm đà vị mặn ngọt làm món nhậu hay ăn cơm, bánh mì đều ngon.', 'Bến Tre', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/25/long-khia-nuoc-dua---mon-nhau-cuoi-tuan-1619341624.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=QnAYF6Kf_lu6ktyecm2OoA', 40, 40, 'HARD', 'Cùng thử nấu Hướng dẫn làm Lòng heo khìa nước dừa đậm đà vị mặn ngọt');
INSERT INTO public.post VALUES (469, '2025-11-20 17:11:03.449044', '2025-11-20 17:11:03.449044', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 471, 'Cách làm canh cá Quỳnh Côi tại nhà', 'Canh cá Quỳnh Côi được ghi vào danh sách các món ngon đặc trưng của Thái Bình từ khoảng thế kỷ 17.', 'Thái Bình', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/15/cach-lam-canh-ca-quynh-coi-tai-nha-1618482014.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=nXTPsDSveWYLQOLI-4EAcQ', 75, 75, 'MEDIUM', 'Cùng thử nấu Cách làm canh cá Quỳnh Côi tại nhà');
INSERT INTO public.post VALUES (471, '2025-11-20 17:11:04.652483', '2025-11-20 17:11:04.652483', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 473, 'Cách nấu món cá nục kho đậm đà, không bị tanh', '''''Cá nục kho rục xương'''' là món ăn dân dã, quen thuộc. Với một vài bí quyết khử mùi tanh, bạn sẽ có một món ăn ngon cho cả gia đình với công thức dưới đây.', 'Phú Yên', 'https://i1-giadinh.vnecdn.net/2021/03/25/ca1-1616657674-7649-1616658058.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=OzLD7sjphEkfeqicdNhr4w', 80, 80, 'HARD', 'Cùng thử nấu Cách nấu món cá nục kho đậm đà, không bị tanh');
INSERT INTO public.post VALUES (479, '2025-11-20 17:11:08.157219', '2025-11-20 17:11:08.157219', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 481, 'Cách làm món tai heo cuốn ngũ vị thơm ngon, lạ miệng', 'Tai heo cuộn ngũ vị là món ăn không chỉ tốt cho sức khỏe khi mang lại nguồn dinh dưỡng cao, mà còn đẹp mắt, lạ miệng, đặc biệt hấp dẫn cánh mày râu.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/03/10/1-1615364625-2647-1615364711.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uWAzdAoh__M02g24buvw-w', 0, 0, 'HARD', 'Cùng thử nấu Cách làm món tai heo cuốn ngũ vị thơm ngon, lạ miệng');
INSERT INTO public.post VALUES (485, '2025-11-20 17:11:11.075518', '2025-11-20 17:11:11.075518', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 487, 'Chia sẻ bí quyết làm món Gà roti THƠM NGON, ĐẸP MẮT', 'Thịt gà mềm ngon, màu bóng đẹp, vị đậm đà ăn với cơm trắng, xôi và bánh mì đều rất ngon.', 'Vũng Tàu', 'https://i1-giadinh.vnecdn.net/2021/02/26/ga3-1614309749-4554-1614310247.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=XWkvb4bIj4oMjtI7D1WPbQ', 30, 30, 'HARD', 'Cùng thử nấu Chia sẻ bí quyết làm món Gà roti THƠM NGON, ĐẸP MẮT');
INSERT INTO public.post VALUES (491, '2025-11-20 17:11:13.898374', '2025-11-20 17:11:13.898374', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 493, 'Hướng dẫn làm sa tế sả ớt cho tín đồ món cay', 'Sa tế là loại gia vị không thể thiếu trong các món như bún bò, lẩu hoặc ướp đồ nướng. Thực ra công thức và cách làm sa tế rất đơn giản với nguyên liệu sẵn có.', 'Huế', 'https://i1-giadinh.vnecdn.net/2020/07/13/sa-te-3-1594629775-9620-1594629840.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=pqY6vTsDQcMRYrpEsJpADA', 0, 0, 'MEDIUM', 'Cùng thử nấu Hướng dẫn làm sa tế sả ớt cho tín đồ món cay');
INSERT INTO public.post VALUES (495, '2025-11-20 17:11:14.741673', '2025-11-20 17:11:14.741673', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 497, 'Cách làm sườn nướng ngũ vị cho đêm Giáng sinh ấm áp', 'Sườn đẫm nướng sốt lên màu nâu đỏ, khi ăn róc xương, thịt mềm mọng nước mà không bị khô, nổi bật mùi thơm từ các gia vị.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2022/12/23/Bc5Thnhphm5-1671785824-1707-1671785850.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_KejlUcz-ub2MWOI3DC-qQ', 40, 40, 'MEDIUM', 'Cùng thử nấu Cách làm sườn nướng ngũ vị cho đêm Giáng sinh ấm áp');
INSERT INTO public.post VALUES (499, '2025-11-20 17:11:15.572487', '2025-11-20 17:11:15.572487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 501, 'Canh cá nấu su hào ngọt ấm ngày lạnh', 'Thịt cá mềm thơm, su hào ngọt, nước canh thanh nhẹ, điểm xuyết màu đỏ từ cà chua khiến ai cũng thích thú. Đây là món ăn dân dã của nhiều nơi Thái Bình, Hà Nam, Hải Phòng...', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2021/12/27/Thnhphm1-1640610067-9516-1640610180.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-qOOgh02G0y4n-b_qI6IUw', 22, 23, 'MEDIUM', 'Cùng thử nấu Canh cá nấu su hào ngọt ấm ngày lạnh');
INSERT INTO public.post VALUES (440, '2025-11-20 17:10:55.64817', '2025-11-20 17:10:55.64817', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 442, 'Cách nấu chân giò giả cầy kiểu Bắc', 'Thịt chân giò đậm vị, nước sánh vàng rượi, dậy mùi đặc trưng của riềng mẻ mắm tôm, xen kẽ hành răm, rau ngổ xanh tươi rất hấp dẫn.', 'Hà Nam', 'https://i1-giadinh.vnecdn.net/2021/07/14/nh3-1626255002-1459-1626255147.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=mfUVkxxf_eZinppn_0_iGQ', 37, 38, 'HARD', 'Cùng thử nấu Cách nấu chân giò giả cầy kiểu Bắc');
INSERT INTO public.post VALUES (443, '2025-11-20 17:10:56.217909', '2025-11-20 17:10:56.217909', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 445, 'Cách làm chả cánh hoa sen', 'Chả thơm thoang thoảng hương sen, thịt ngọt tự nhiên đan xen chút sần sật của mộc nhĩ, nấm hương, chả không khô mà rất đượm vị.', 'Huế', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/28/cach-lam-cha-canh-hoa-sen-thom-ngon-1622167582.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=PFEGfoHegzQ8XiiNiKcdaw', 20, 20, 'HARD', 'Cùng thử nấu Cách làm chả cánh hoa sen');
INSERT INTO public.post VALUES (450, '2025-11-20 17:10:57.560382', '2025-11-20 17:10:57.560382', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 452, 'Cách làm tóp mỡ chưng cà chua ngon lành tại nhà', 'Vào những ngày thời tiết nóng nực món tóp mỡ chưng cà chua chấm rau sống luôn được các bà nội trợ ưu tiên đưa vào thực đơn.', 'Thái Bình', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/07/ca-chua-chung-top-mo-cham-rau-song-1620350286.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=k75HDiAcsojK2sUx9Rs1Zw', 22, 23, 'EASY', 'Cùng thử nấu Cách làm tóp mỡ chưng cà chua ngon lành tại nhà');
INSERT INTO public.post VALUES (455, '2025-11-20 17:10:58.658002', '2025-11-20 17:10:58.658002', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 457, 'Cách làm Cá lòng tong chiên giòn, chấm mắm tỏi', 'Cá lòng tong, còn có các tên khác là cá mương, tép dầu, mài mại... chiên giòn, cuốn với lá mơ hoặc lá lốt, chấm với nước mắm tỏi là món được nhiều người yêu thích.', 'An Giang', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/01/ca-tep-dau-chien-gion-cham-mam-toi-1619836543.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=nGQ3Umrl-2JbrnfspKpa_Q', 20, 20, 'EASY', 'Cùng thử nấu Cách làm Cá lòng tong chiên giòn, chấm mắm tỏi');
INSERT INTO public.post VALUES (458, '2025-11-20 17:10:59.525374', '2025-11-20 17:10:59.525374', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 460, 'Cách làm trứng ngâm xì dầu bắt mắt, lạ miệng lại dễ làm tại nhà', 'Trứng ngâm xì dầu bắt mắt, lạ miệng, nguyên liệu dễ tìm, dễ thực hiện, lại không tốn công chế biến.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/04/15/2-1618495980-6773-1618496141.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Un9arguQxLdfd57VdCp7xA', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm trứng ngâm xì dầu bắt mắt, lạ miệng lại dễ làm tại nhà');
INSERT INTO public.post VALUES (465, '2025-11-20 17:11:02.232373', '2025-11-20 17:11:02.232373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 467, 'Cách làm Canh cua đồng - Món khoái khẩu cho ngày nóng', 'Món ăn này được ưu tiên trong thực đơn mùa hè, thời tiết nóng nực nhờ vị thanh mát giúp giải nhiệt và kích thích vị giác các thành viên trong gia đình.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2021/04/15/cuadong1-1618482565-5628-1618482820.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=L97EqZkC6ob0D5AT08c4Ow', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm Canh cua đồng - Món khoái khẩu cho ngày nóng');
INSERT INTO public.post VALUES (470, '2025-11-20 17:11:04.149537', '2025-11-20 17:11:04.149537', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 472, 'Cách làm gà xiên nướng kiểu Thái', 'Gà xiên nướng (Thai Chicken Satay) là món khai vị nổi tiếng trong các nhà hàng ở Thái Lan. Món này cũng có nhiều phiên bản ở Malaysia và Philippines.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/03/31/ga1-1617180055-5039-1617180892.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=DNhAWJykzILnrQEqVQKHBw', 15, 15, 'HARD', 'Cùng thử nấu Cách làm gà xiên nướng kiểu Thái');
INSERT INTO public.post VALUES (473, '2025-11-20 17:11:05.150649', '2025-11-20 17:11:05.150649', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 475, 'Hướng dẫn cách làm Gà rang gừng - Món đơn giản nhưng ''hao cơm''', 'Gà rang gừng là món ăn quen thuộc của người dân miền Bắc thời bao cấp. Với nguyên liệu đơn giản và cách chế biến nhanh, món ăn này được nhiều người yêu thích.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/03/31/nh1-1617179311-7462-1617179649.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=X20yLRoq8aYF60xvMcKw0Q', 17, 18, 'MEDIUM', 'Cùng thử nấu Hướng dẫn cách làm Gà rang gừng - Món đơn giản nhưng ''hao cơm''');
INSERT INTO public.post VALUES (480, '2025-11-20 17:11:08.826572', '2025-11-20 17:11:08.826572', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 482, 'Hướng dẫn tự làm bún thịt nướng mềm, thơm tại nhà', 'Thịt nướng thơm, mềm ngọt tự nhiên hòa quyện với rau xanh, bún sợi và nước mắm chua ngọt tạo nên một bức tranh nhiều sắc màu hấp dẫn.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/03/05/nh5-1614933205-3705-1614933598.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=7WE7vpa-g5P9HhASq8hRKA', 52, 53, 'HARD', 'Cùng thử nấu Hướng dẫn tự làm bún thịt nướng mềm, thơm tại nhà');
INSERT INTO public.post VALUES (484, '2025-11-20 17:11:10.73942', '2025-11-20 17:11:10.73942', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 486, 'Cùng làm món Nem ốc - Thơm ngon, Hấp dẫn và Độc đáo', 'Vỏ nem giòn rụm, nhân ngọt thơm và có chút dai sần sật từ ốc, kết hợp với nước chấm mắm chua ngọt sẽ khiến bạn ngỡ ngàng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/02/04/Oc2-1612412688-4877-1612413014.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=e1rHbvWPWV83QT_gomuPNw', 45, 45, 'HARD', 'Cùng thử nấu Cùng làm món Nem ốc - Thơm ngon, Hấp dẫn và Độc đáo');
INSERT INTO public.post VALUES (486, '2025-11-20 17:11:11.620626', '2025-11-20 17:11:11.620626', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 488, 'Hướng dẫn làm món Bò nướng lá lốt VẠN NGƯỜI MÊ', 'Bò nướng lá lốt là một món dễ gây nghiện trong thực đơn ''''Bò 7 món'''' nổi tiếng một thời ở miền Nam', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/02/01/bo2-1611895634-7806-1612167669.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0HGvyEZ1-tbVJmXjlj-rVg', 30, 30, 'HARD', 'Cùng thử nấu Hướng dẫn làm món Bò nướng lá lốt VẠN NGƯỜI MÊ');
INSERT INTO public.post VALUES (492, '2025-11-20 17:11:14.098619', '2025-11-20 17:11:14.098619', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 494, 'Cách làm cá diêu hồng hấp gừng hành', 'Cá hấp nóng hổi, thịt cá mềm ngọt, dậy mùi thơm của hành lá, gừng, thì là. Món này cuốn bánh tráng cùng bún, rau sống chấm nước mắm chua ngọt rất ngon.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2022/12/29/Bc4Thnhphm4-1672298218-7464-1672298342.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qgqPWdbahcLwcE2c_RgNSw', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm cá diêu hồng hấp gừng hành');
INSERT INTO public.post VALUES (497, '2025-11-20 17:11:15.260873', '2025-11-20 17:11:15.260873', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 499, 'Cách làm lẩu Thái chua cay ấm áp ngày đông', 'Nước dùng màu đỏ cam, vị chua từ dứa, vị ngọt từ nước dừa, nước hầm xương, vị cay tê đầu lưỡi từ ớt, dậy mùi thơm của sả, lá chanh. Món lẩu này làm ấm người trong tiết trời lạnh giá.', 'Nha Trang', 'https://i1-giadinh.vnecdn.net/2022/12/17/Thnhphm11-1671269522-6863-1671269525.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=iJScjAghkb9tCgiA3xgIqQ', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm lẩu Thái chua cay ấm áp ngày đông');
INSERT INTO public.post VALUES (442, '2025-11-20 17:10:55.933512', '2025-11-20 17:10:55.933512', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 444, 'Cách làm canh ngao chua nấu dứa - món đưa cơm mùa hè', 'Một bát canh thanh mát với thịt ngao mềm, đan xen vị ngọt thanh từ dứa và vị chua từ sấu nhanh chóng giải nhiệt mùa hè.', 'Quảng Ninh', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/29/cach-lam-canh-ngao-nau-dua-dua-com-mua-he-1622272767.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=GPibZ2vSjIfrQsB1ReG-zg', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm canh ngao chua nấu dứa - món đưa cơm mùa hè');
INSERT INTO public.post VALUES (446, '2025-11-20 17:10:56.912126', '2025-11-20 17:10:56.912126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 448, 'Cách làm cá cơm sữa rim đậu phộng đậm đà - món ngon hao cơm', 'Cá cơm rim đậu phộng là món ăn thuở nghèo khó được yêu thích và phổ biến ở nhiều nước như Việt Nam, Hàn Quốc, Lào, Singapore, Indonesia...', 'Phú Yên', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/01/ca-com-sua-rim-dau-phong-dam-da-1619837741.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=7b0V4RPXYIMIg1d-O5T7IA', 17, 18, 'EASY', 'Cùng thử nấu Cách làm cá cơm sữa rim đậu phộng đậm đà - món ngon hao cơm');
INSERT INTO public.post VALUES (457, '2025-11-20 17:10:59.241284', '2025-11-20 17:10:59.241284', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 459, 'Cách làm khoai tây chiên giòn đơn giản, dễ làm tại nhà', 'Vỏ khoai giòn tan nhưng bên trong vẫn mềm thơm, chấm với chút tương ớt, hoặc lắc phô mai - món ăn vặt khoái khẩu của nhiều trẻ em.', 'Đà Lạt', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/28/cach-lam-khoai-tay-chien-gion-don-gian-1619601762.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=rg2WkCVVgBuKWPIfkqRs8g', 20, 20, 'EASY', 'Cùng thử nấu Cách làm khoai tây chiên giòn đơn giản, dễ làm tại nhà');
INSERT INTO public.post VALUES (461, '2025-11-20 17:11:01.056558', '2025-11-20 17:11:01.056558', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 463, 'Cách làm Ngan nấu giả cầy kiểu Nghệ An', 'Món đặc sản Nghệ An này không thể thiếu mật mía, lá tắt (lá quýt hôi), mắm tôm và nước chè xanh.', 'Nghệ An', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/06/cach-lam-ngan-nau-gia-cay-kieu-nghe-an-1617695010.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=dQkgyrm_JOHRDsqwQDO3Hg', 45, 45, 'HARD', 'Cùng thử nấu Cách làm Ngan nấu giả cầy kiểu Nghệ An');
INSERT INTO public.post VALUES (472, '2025-11-20 17:11:04.91056', '2025-11-20 17:11:04.91056', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 474, 'Cách làm Mắm tép chưng thịt - Món ăn đơn giản mà ''hao cơm''', 'Mắm tép chưng thịt là món ăn quen thuộc của đồng bằng Bắc bộ. Với nguyên liệu đơn giản, dễ làm, món này được nhiều người nội trợ chế biến dự trữ dùng dần.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2021/04/08/nh4-1617869303-9803-1617869331.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=fKndzhR_u0iZd1oVrvTiCA', 37, 38, 'MEDIUM', 'Cùng thử nấu Cách làm Mắm tép chưng thịt - Món ăn đơn giản mà ''hao cơm''');
INSERT INTO public.post VALUES (476, '2025-11-20 17:11:06.512309', '2025-11-20 17:11:06.512309', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 478, 'Cách làm Bắp bò ngâm mắm - Món ăn Truyền thống khi Tết về', 'Thịt bò giòn ngọt tự nhiên, hài hòa các vị chua, cay, mặn, ngọt, thoảng mùi thơm của tỏi, ớt, quế… được nhiều người yêu thích.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2021/02/23/nh2-1614076047-9327-1614076478.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=6LcorRpLLAW6XBfKtm-Upg', 0, 0, 'HARD', 'Cùng thử nấu Cách làm Bắp bò ngâm mắm - Món ăn Truyền thống khi Tết về');
INSERT INTO public.post VALUES (488, '2025-11-20 17:11:12.936679', '2025-11-20 17:11:12.936679', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 490, 'Hướng dẫn cách làm tôm chiên giòn sốt mật ong NGON MÊ LY', 'Những con tôm bên ngoài giòn tan, bên trong mềm ngọt được phủ trong lớp sốt kem mật ong thơm ngon.', 'Nha Trang', 'https://i1-giadinh.vnecdn.net/2020/12/17/tom1-1608195774-6648-1608196069.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=OTBCt75K6JvPEyU1XTXstQ', 0, 0, 'HARD', 'Cùng thử nấu Hướng dẫn cách làm tôm chiên giòn sốt mật ong NGON MÊ LY');
INSERT INTO public.post VALUES (498, '2025-11-20 17:11:15.483884', '2025-11-20 17:11:15.483884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 500, 'Cách làm món cà ri gà - món ấm áp cho ngày lạnh', 'Thịt gà mềm ngon, khoai giữ nguyên miếng bên ngoài hơi giòn bên trong mềm mịn, nước sốt sánh màu vàng óng, vị beo béo từ cốt dừa. Đây là món bổ dưỡng, tăng cường sức khỏe trong mùa lạnh.', 'Tây Ninh', 'https://i1-giadinh.vnecdn.net/2022/12/15/Thnhphm11-1671086819-5787-1671086922.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=JlHqBpAEqCnrxZ7dQIgAcg', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm món cà ri gà - món ấm áp cho ngày lạnh');
INSERT INTO public.post VALUES (503, '2025-11-20 17:11:16.276306', '2025-11-20 17:11:16.276306', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 505, 'Xôi sắn - món quà của mùa đông', 'Hạt xôi dẻo mềm, sắn bùi bùi, mỡ hành thơm lừng béo ngậy nhanh chóng xua tan gió lạnh đầu mùa. Một món ăn gắn liền với tuổi thơ của nhiều người.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/10/25/xoisan-1635172028-9827-1635172043.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=g0ypktZ-CC_yP-lALvd5lw', 25, 25, 'MEDIUM', 'Cùng thử nấu Xôi sắn - món quà của mùa đông');
INSERT INTO public.post VALUES (513, '2025-11-20 17:11:18.978694', '2025-11-20 17:11:18.978694', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 515, 'Cách làm lẩu gà nấm đổi vị cuối tuần', 'Lẩu nóng hổi, dậy mùi thơm và ngọt tự nhiên từ gà, nấm, màu sắc bắt mắt. Món này giàu chất bổ dưỡng giúp tăng cường sức khỏe.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2023/02/11/Bc4Thnhphm11-1676087253-2518-1676087399.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gu969fEJUtv1PEPuUeTZzw', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm lẩu gà nấm đổi vị cuối tuần');
INSERT INTO public.post VALUES (518, '2025-11-20 17:11:21.25884', '2025-11-20 17:11:21.25884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 520, 'Cách làm lẩu cá chép chua thanh cho ngày du xuân', 'Trong tiết trời mưa xuân rả rích, một nồi lẩu cá chép chua thanh là món ăn được nhiều người yêu thích.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2023/02/03/Bc5thnhphm1-1675416493-5672-1675416498.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=RCj6ilntS_ZKAIRhInoTpA', 32, 33, 'MEDIUM', 'Cùng thử nấu Cách làm lẩu cá chép chua thanh cho ngày du xuân');
INSERT INTO public.post VALUES (528, '2025-11-20 17:11:25.121765', '2025-11-20 17:11:25.121765', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 530, 'Cơm chiên cua', 'Cơm trắng chiên cùng thịt nạc cua và lòng đỏ trứng muối rất ngon. Món cơm có kèm đậu Hà Lan cho đỡ ngán.', 'Cà Mau', 'https://i1-giadinh.vnecdn.net/2021/10/21/comchiencua-1634789802-4785-1634789818.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=i_YCCjw-ekYWg9wbYVz-Xw', 0, 0, 'MEDIUM', 'Cùng thử nấu Cơm chiên cua');
INSERT INTO public.post VALUES (533, '2025-11-20 17:11:26.691758', '2025-11-20 17:11:26.691758', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 535, 'Hai món ngon từ bưởi', 'Nước ép bưởi và gỏi bưởi chanh dây là hai món ngon và giàu chất dinh dưỡng nhất trong số các món ăn có thành phần chế biến từ bưởi. Bạn hãy cùng thực hiện hai món ăn này với sự hướng dẫn dưới đây nhé.', 'Vĩnh Long', 'https://i1-giadinh.vnecdn.net/2021/11/15/goibuoi-1636950088-3938-1636950190.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=nkvyvY_gy0DJQCFGBuiNcg', 0, 0, 'EASY', 'Cùng thử nấu Hai món ngon từ bưởi');
INSERT INTO public.post VALUES (444, '2025-11-20 17:10:56.597097', '2025-11-20 17:10:56.597097', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 446, 'Cách làm trứng cút lộn xào me cực kỳ đơn giản mà ngon', 'Trứng cút phủ quanh là nước sốt me sánh vàng óng, hài hòa vị chua - cay - mặn - ngọt rất hấp dẫn cho các tín đồ ăn vặt.', 'Hồ Chí Minh', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/08/cach-lam-trung-cut-lon-xao-me-thom-ngon-1620467409.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=jVonxFUxhh_0hgUT9PP_zQ', 12, 13, 'MEDIUM', 'Cùng thử nấu Cách làm trứng cút lộn xào me cực kỳ đơn giản mà ngon');
INSERT INTO public.post VALUES (459, '2025-11-20 17:11:00.067481', '2025-11-20 17:11:00.067481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 461, 'Cách làm gà rán KFC thành công từ lần đầu tiên', 'Gà rán kiểu KFC hấp dẫn người ăn ở lớpvỏ giòm rụm, thịt mềm ngon, các gia vị hài hòa. Không cần phải ra nhà hàng, bạn có thể làm được món này ngay tại nhà.', 'Hồ Chí Minh', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/26/cach-lam-ga-kfc-thanh-cong-lan-dau-tien-1619420528.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=_JgufWnXUAuq85Jz58sisQ', 30, 30, 'HARD', 'Cùng thử nấu Cách làm gà rán KFC thành công từ lần đầu tiên');
INSERT INTO public.post VALUES (474, '2025-11-20 17:11:05.349936', '2025-11-20 17:11:05.349936', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 476, 'Bí quyết làm món trứng hấp vân ĐẸP MẮT - NGON MIỆNG', 'Món trứng hấp vân có màu sắc bắt mắt, dễ làm, tốt cho sức khỏe, đặc biệt dễ dụ các bé lười ăn.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/03/15/2-1615781564-1379-1615781672.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_W7aXsFSnAj83ZFgldzG4g', 0, 0, 'MEDIUM', 'Cùng thử nấu Bí quyết làm món trứng hấp vân ĐẸP MẮT - NGON MIỆNG');
INSERT INTO public.post VALUES (487, '2025-11-20 17:11:12.393364', '2025-11-20 17:11:12.393364', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 489, 'Hướng dẫn cách làm tôm xóc bơ tỏi thơm ngon AI CŨNG MÊ', 'Món tôm xóc bơ tỏi khá nổi tiếng của một nhà hàng Thái Lan ở Las Vegas, Mỹ có cách làm khá đơn giản và là gợi ý thú vị cho cả gia đình vào dịp cuối tuần.', 'Nha Trang', 'https://i1-giadinh.vnecdn.net/2021/01/21/tom1-1611219545-6560-1611219855.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=DsmdtwrIQEonRrHKMmbVVA', 0, 0, 'HARD', 'Cùng thử nấu Hướng dẫn cách làm tôm xóc bơ tỏi thơm ngon AI CŨNG MÊ');
INSERT INTO public.post VALUES (502, '2025-11-20 17:11:16.106556', '2025-11-20 17:11:16.106556', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 504, 'Cách làm cá thu sốt cà chua - món ăn quốc dân cho ngày đông', 'Thịt cá thu chắc thịt, sốt cà chua sánh, vị đậm đà. Món này ăn cùng rau sống, cơm nóng vào mùa đông rất hợp.', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2023/01/02/Thnhphm11-1672638713-3458-1672638737.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MAV-98yATj4R1Ttil9p5xg', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm cá thu sốt cà chua - món ăn quốc dân cho ngày đông');
INSERT INTO public.post VALUES (517, '2025-11-20 17:11:20.775215', '2025-11-20 17:11:20.775215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 519, 'Cách làm tôm nướng sốt phô mai cho Giáng sinh', 'Thịt tôm mềm ngọt quyện với phô mai béo ngậy tan chảy, nhanh chóng đánh thức vị giác trong mùa Giáng sinh thêm phần ấm áp.', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2022/12/24/Bc6Thnhphm6-1671873462-8321-1671873498.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=w0Vc5GO0DMmnRA1lC2cowg', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm tôm nướng sốt phô mai cho Giáng sinh');
INSERT INTO public.post VALUES (532, '2025-11-20 17:11:26.615049', '2025-11-20 17:11:26.615049', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 534, 'Các món ngon đãi khách', 'Từ những nguyên liệu quen thuộc, bạn có thể tạo ra những món ăn hấp dẫn với vị lạ trên bàn tiệc đãi khách của mình.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/17/garutxuong-1637138957-3257-1637139042.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=TI35i8YnH1zzifnDAdzE0g', 0, 0, 'EASY', 'Cùng thử nấu Các món ngon đãi khách');
INSERT INTO public.post VALUES (547, '2025-11-20 17:11:30.305503', '2025-11-20 17:11:30.305503', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 549, 'Mọc cua bể', 'Nạc vai xay nhuyễn, trộn thịt cua bể hấp. Món mọc ăn nóng rất ngon.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/10/15/moccuabemonannoitiengocualo-16-2044-9491-1634296527.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=e4sxrnCocWzzfJ-kjLQtxQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Mọc cua bể');
INSERT INTO public.post VALUES (562, '2025-11-20 17:11:34.232766', '2025-11-20 17:11:34.232766', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 564, 'Cánh gà nhồi cốm', 'Món gà rán thơm phức mùi cốm, ăn ngon mà không quá ngậy.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/09/S65455ef726fb45618a30794362bb3-3866-9670-1633777374.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=7d843J0clJL1kFlYi-Q6_Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Cánh gà nhồi cốm');
INSERT INTO public.post VALUES (577, '2025-11-20 17:11:39.118749', '2025-11-20 17:11:39.118749', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 579, 'Ngao nướng mỡ hành', 'Ngao nướng chín tới thơm sực, ăn rất ngon. Mời bạn cùng làm món này dưới sự hướng dẫn của các đầu bếp Ezcooking.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2021/10/05/ngao-1633423835-1207-1633423929.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=dUiDMUxT30yuM-Q-QcUGjg', 0, 0, 'MEDIUM', 'Cùng thử nấu Ngao nướng mỡ hành');
INSERT INTO public.post VALUES (592, '2025-11-20 17:11:42.605751', '2025-11-20 17:11:42.605751', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 594, 'Canh giò heo hầm bắp chuối', 'Với nguyên liệu giò heo, bạn có thể chế biến một món canh rất ngon, không quá ngán mà lại dễ làm.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/01/gioheohambapchuoithumbnail-163-3510-4779-1633103175.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qvUPbviwjBXv8jDFyValYw', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh giò heo hầm bắp chuối');
INSERT INTO public.post VALUES (607, '2025-11-20 17:11:47.37215', '2025-11-20 17:11:47.37215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 609, 'Cách nấu Bún ốc nguội Hà Nội đơn giản, dễ làm', 'Bún ốc nguội là món ăn dân dã nhưng "đạt được tới cái đích nghệ thuật ăn ngon của người Hà Nội" như nhà văn Vũ Bằng từng ca ngợi.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/03/31/bun1-1617181296-7786-1617181829.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EDpVNSUAGVfMG8m_KQqApw', 85, 85, 'HARD', 'Cùng thử nấu Cách nấu Bún ốc nguội Hà Nội đơn giản, dễ làm');
INSERT INTO public.post VALUES (445, '2025-11-20 17:10:56.760921', '2025-11-20 17:10:56.760921', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 447, 'Dọc mùng muối chua xứ Nghệ', 'Dọc mùng muối chua trộn lá chanh cùng tỏi, ớt, đường, ăn kèm bánh đa và thịt luộc là món ngon ''đưa cơm'' ngày hè của người dân xứ Nghệ.', 'Nghệ An', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/21/doc-mung-muoi-chua-xu-nghe-1621564407.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=Pu9dYTWpCK10v00X5rRq_g', 30, 30, 'EASY', 'Cùng thử nấu Dọc mùng muối chua xứ Nghệ');
INSERT INTO public.post VALUES (460, '2025-11-20 17:11:00.397011', '2025-11-20 17:11:00.397011', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 462, 'Cách làm Canh cá tràu nấu khế giải nhiệt mùa hè', 'Canh cá tràu (cá quả, cá chuối) nấu khế là món ăn dân dã thuộc top ''hương vị thương nhớ'' của người miền Trung xa quê.', 'Quảng Ngãi', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/08/cach-lam-canh-ca-trau-nau-khe-giai-nhiet-mua-he-1617870510.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=i20ClX08H7iYOR8-ahOsig', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm Canh cá tràu nấu khế giải nhiệt mùa hè');
INSERT INTO public.post VALUES (475, '2025-11-20 17:11:05.951692', '2025-11-20 17:11:05.951692', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 477, 'Chia sẻ bí quyết nấu canh chua cá thơm ngon chỉ trong 30 phút', 'Canh cá nấu chua hấp dẫn bởi nước canh trong, ngọt thanh, chua nhẹ, thịt cá trắng mềm mà không bở, thơm mùi đặc trưng của tỏi phi, ngò om, ngò gai.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2021/03/19/ca2-1616122035-2163-1616122469.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=8PTOflZJZdwzP68MSUhLhg', 15, 15, 'HARD', 'Cùng thử nấu Chia sẻ bí quyết nấu canh chua cá thơm ngon chỉ trong 30 phút');
INSERT INTO public.post VALUES (501, '2025-11-20 17:11:15.951012', '2025-11-20 17:11:15.951012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 503, 'Chè xoài ngọt thơm ngày đông', 'Chè vàng ươm, dậy mùi thơm từ xoài, quyện với nước cốt dừa béo ngậy, dừa sợi sần sật rất hấp dẫn. Một món ngon khi đang vào mùa xoài chín.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2021/12/24/Bc4-1640337276-6184-1640337382.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-lMYd2a_q4UbC7V3paZ4ow', 17, 18, 'EASY', 'Cùng thử nấu Chè xoài ngọt thơm ngày đông');
INSERT INTO public.post VALUES (516, '2025-11-20 17:11:20.430668', '2025-11-20 17:11:20.430668', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 518, 'Cách làm bún thang kiểu Hà Nội cổ', 'Bún thang hội tụ tròn trịa sắc - hương - vị với thịt gà vàng ươm, trứng mềm mỏng, giò lụa hồng nhạt, ruốc sỏi nâu rám nắng, trứng muối tựa mặt trời.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2023/02/02/Thnhphm11-1675330050-6458-1675331024.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=FV7teH1ZHpYoDGSyt5vQQw', 42, 43, 'HARD', 'Cùng thử nấu Cách làm bún thang kiểu Hà Nội cổ');
INSERT INTO public.post VALUES (531, '2025-11-20 17:11:26.263137', '2025-11-20 17:11:26.263137', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 533, 'Các món ăn chế biến với me', 'Me là loại nguyên liệu mang lại cho món ăn một hương vị lạ. Một chút chua chua, ngọt ngọt cũng đủ làm cho món ăn thêm phần hấp dẫn. Những món chế biến với me thường dễ thực hiện nhưng hiệu quả rất đặc biệt.', 'Sóc Trăng', 'https://i1-giadinh.vnecdn.net/2021/11/18/cuarangme-1637224487-9931-1637224552.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=T7f21QHQik042onXx2X-aA', 0, 0, 'EASY', 'Cùng thử nấu Các món ăn chế biến với me');
INSERT INTO public.post VALUES (546, '2025-11-20 17:11:30.061981', '2025-11-20 17:11:30.061981', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 548, 'Bò nướng kiệu', 'Thịt bò filê cuốn nạc xay và củ kiệu, nướng vàng. Món này ăn kèm bún rất ngon.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/15/Nuongthitbotrenbepthandohong-1-9972-5109-1634297948.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=dXn6m8vs0Htv7ry8nvgXeQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Bò nướng kiệu');
INSERT INTO public.post VALUES (561, '2025-11-20 17:11:34.08009', '2025-11-20 17:11:34.08009', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 563, 'Gà nấu rượu nếp', 'Gà nấu rượu nếp là món ăn rất đặc biệt của miền quê Nam bộ. Món ăn này không chỉ ngon miệng mà còn rất bổ dưỡng và có tác dụng kích thích tiêu hóa.', 'Long An', 'https://i1-giadinh.vnecdn.net/2021/10/10/ganauruou-1633836753-8121-1633836862.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uk_EkRDiGolRiETUGC5o0g', 0, 0, 'MEDIUM', 'Cùng thử nấu Gà nấu rượu nếp');
INSERT INTO public.post VALUES (576, '2025-11-20 17:11:38.988844', '2025-11-20 17:11:38.988844', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 578, 'Gỏi rau nhút hải sản', 'Dễ làm, nguyên liệu dễ kiếm, có thể ngồi nhâm nhi bất kỳ nơi nào... là lý do món gỏi được nhiều người ưa thích. Dưới đây là hướng dẫn của Rosa về cách làm món gỏi đậm chất Nam bộ này.', 'An Giang', 'https://i1-giadinh.vnecdn.net/2021/10/05/goi-1633423504-5608-1633423701.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Yz51J8Krrk77282u05k7vQ', 0, 0, 'HARD', 'Cùng thử nấu Gỏi rau nhút hải sản');
INSERT INTO public.post VALUES (591, '2025-11-20 17:11:42.400052', '2025-11-20 17:11:42.400052', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 593, 'Sườn bò hầm lá lốt', 'Món canh này ngon, lạ miệng, có thể cất để ăn dần.', 'Thanh Hóa', 'https://i1-giadinh.vnecdn.net/2021/10/02/thitbolalotosm-1633165115-3243-1633165126.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=KJ-wsiuhYWUspKxUZju_eg', 0, 0, 'MEDIUM', 'Cùng thử nấu Sườn bò hầm lá lốt');
INSERT INTO public.post VALUES (606, '2025-11-20 17:11:46.767665', '2025-11-20 17:11:46.767665', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 608, 'Công thức làm kim chi dưa chuột chuẩn như của người Hàn', 'Kim chi dưa chuột dễ làm hơn so với cải thảo, hương vị thơm ngon, giòn ngọt, xen lẫn vị chua.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/03/15/dachut-1615783654-5365-1615798008.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Iss39psrzoLwea2w1SObSg', 30, 30, 'HARD', 'Cùng thử nấu Công thức làm kim chi dưa chuột chuẩn như của người Hàn');
INSERT INTO public.post VALUES (447, '2025-11-20 17:10:57.117891', '2025-11-20 17:10:57.117891', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 449, 'Cách làm chả cá ngần - đặc sản sông Đà', 'Chả cá ngần ngọt, thịt có độ dai vừa phải, dậy mùi lá lốt, rau răm, thì là... chấm cùng tương ớt hoặc nước mắm chua ngọt rất hấp dẫn.', 'Hòa Bình', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/13/cach-lam-cha-ca-ngan-dac-san-song-da-1620901046.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=loxLcIXNF062CBC2rVcFTw', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm chả cá ngần - đặc sản sông Đà');
INSERT INTO public.post VALUES (462, '2025-11-20 17:11:01.410881', '2025-11-20 17:11:01.410881', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 464, 'Cách làm Mực xào chua ngọt ngon tuyệt mà đơn giản', 'Mực xào chua ngọt là món ăn dễ làm, không chỉ ''''đưa cơm'''' mà còn là món nhậu được cánh mày râu yêu thích.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/03/31/muc1-1617182767-1435-1617182779.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=FdHmQ6rHCzxiABML1INN1A', 10, 10, 'HARD', 'Cùng thử nấu Cách làm Mực xào chua ngọt ngon tuyệt mà đơn giản');
INSERT INTO public.post VALUES (477, '2025-11-20 17:11:07.02712', '2025-11-20 17:11:07.02712', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 479, 'Cách nấu Ốc chuối đậu chuẩn vị, thơm ngon mà dễ làm', 'Ốc nấu chuối đậu là món ăn dân dã, quen thuộc của người dân Bắc bộ, mang tới bữa ăn ngon cho gia đình vào ngày thường hoặc dịp sum vầy.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/03/16/nh3-1615863425-5115-1615864230.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qi3QAO7ks1MthzGKbvQgbw', 20, 20, 'HARD', 'Cùng thử nấu Cách nấu Ốc chuối đậu chuẩn vị, thơm ngon mà dễ làm');
INSERT INTO public.post VALUES (489, '2025-11-20 17:11:13.446025', '2025-11-20 17:11:13.446025', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 491, 'Công thức món thịt kho trứng, cùi dừa THƠM NGON, ĐẬM ĐÀ', 'Lớp thịt mềm mượt thấm đẫm trong làn nước màu hổ phách kết hợp với cùi dừa sần sật, miếng trứng đậm vị khiến bữa cơm thêm đậm đà.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2020/11/29/Anh3-1606619513-6851-1606619920.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3vCIZ9ElaFBj-mHfU5d61A', 0, 0, 'HARD', 'Cùng thử nấu Công thức món thịt kho trứng, cùi dừa THƠM NGON, ĐẬM ĐÀ');
INSERT INTO public.post VALUES (504, '2025-11-20 17:11:16.411192', '2025-11-20 17:11:16.411192', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 506, 'Cơm rang tóp mỡ dưa chua - món gợi nhớ tuổi thơ', 'Hạt cơm đậm vị quyện với tóp mỡ giòn giòn, béo ngậy cùng dưa cải chua chua rất hấp dẫn. Đây là món ăn thuở nghèo khó, gắn liền tuổi thơ nhiều người.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/25/nh1-1635170791-4676-1635171165.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ehoYqdNl8gF217PDGrtGeg', 20, 20, 'MEDIUM', 'Cùng thử nấu Cơm rang tóp mỡ dưa chua - món gợi nhớ tuổi thơ');
INSERT INTO public.post VALUES (519, '2025-11-20 17:11:21.872686', '2025-11-20 17:11:21.872686', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 521, 'Cách làm lẩu riêu cua bắp bò cho ngày thu se lạnh', 'Nước dùng có vị chua dịu từ giấm bỗng, dậy mùi thơm của riêu cua và thịt bò ngọt mềm, sườn sụn sần sật, rau quả xanh tươi... dễ ăn và phù hợp với tiết trời vào thu.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/10/14/-9709-1665740517.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VtSKiWh9PEap44bmFz4OjA', 45, 45, 'HARD', 'Cùng thử nấu Cách làm lẩu riêu cua bắp bò cho ngày thu se lạnh');
INSERT INTO public.post VALUES (534, '2025-11-20 17:11:26.973405', '2025-11-20 17:11:26.973405', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 536, 'Cuốn tôm', 'Những món ăn nguội và mát như phở cuốn, cuốn tôm, nem cuốn... rất thích hợp trong tiết trời mùa hè. Cuốn tôm là món ngon, dễ làm, bạn có thể thực hành ngay để chiêu đãi cả nhà.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/17/goicuontom-1634449215-9345-1634449333.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=1EoixAwcXsd4YaCI35JLZw', 0, 0, 'HARD', 'Cùng thử nấu Cuốn tôm');
INSERT INTO public.post VALUES (549, '2025-11-20 17:11:30.830064', '2025-11-20 17:11:30.830064', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 551, 'Lẩu gà nấu nấm', 'Món lẩu gà nấu nấm không những giúp bạn thay đổi khẩu vị mà còn rất mát và bổ dưỡng.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/17/launam-1634447187-3578-1634447331.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=LnVKClbGG9MKKKbpceauMg', 0, 0, 'MEDIUM', 'Cùng thử nấu Lẩu gà nấu nấm');
INSERT INTO public.post VALUES (564, '2025-11-20 17:11:34.618983', '2025-11-20 17:11:34.618983', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 566, 'Nộm miến hải sản', 'Món trộn dễ làm này sẽ giúp bạn cải thiện bữa ăn cuối tuần cho gia đình.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/10/09/nommienhaisan-1633752288-9132-1633752487.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=UPtN3jB9NkjMAcPKCJ1Ruw', 0, 0, 'HARD', 'Cùng thử nấu Nộm miến hải sản');
INSERT INTO public.post VALUES (579, '2025-11-20 17:11:39.639687', '2025-11-20 17:11:39.639687', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 581, 'Bê tái chanh', 'Bạn có thể thử làm món bê tái chanh ngay cuối tuần này để đổi món cho cả nhà. Dưới đây là hướng dẫn của các đầu bếp Ezcooking.', 'Ninh Bình', 'https://i1-giadinh.vnecdn.net/2021/10/03/betaichanh-1633226544-4897-1633226717.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Pj8f7zr3NWIt6Y2VcNN5DA', 0, 0, 'HARD', 'Cùng thử nấu Bê tái chanh');
INSERT INTO public.post VALUES (594, '2025-11-20 17:11:43.229995', '2025-11-20 17:11:43.229995', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 596, 'Bắp bò nhúng mẻ', 'Vị chua chua, thanh thanh của mẻ cùng những loại rau vườn, khế chua, chuối chát tạo cảm giác ngon miệng cho món ăn này. Đây là món dễ làm, dễ ăn và có thể dùng vào nhiều dịp khác nhau, từ ăn chơi hay đãi tiệc đều được.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/07/22/Bapbo-1626939764-8767-1626939937.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3Kkf6dDIvDPLVqFR6w0Mhg', 0, 0, 'HARD', 'Cùng thử nấu Bắp bò nhúng mẻ');
INSERT INTO public.post VALUES (609, '2025-11-20 17:11:48.772903', '2025-11-20 17:11:48.772903', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 611, 'Hướng dẫn làm món Cơm gà Hải Nam - Cả nhà đều thích', 'Cơm gà Hải Nam là một biến thể của cơm gà Văn Xương, đảo Hải Nam, Trung Quốc. Món này hiện có nhiều "phiên bản" ở Malaysia, Singapore, Thái Lan, Việt Nam.', 'Hội An, Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/03/25/comga1-1616657214-9192-1616657331.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=f2ZLOnApPqmyMStDPWbd_Q', 75, 75, 'HARD', 'Cùng thử nấu Hướng dẫn làm món Cơm gà Hải Nam - Cả nhà đều thích');
INSERT INTO public.post VALUES (448, '2025-11-20 17:10:57.314466', '2025-11-20 17:10:57.314466', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 450, 'Cách làm canh rau sắn nấu cá – đặc sản Phú Thọ', 'Canh rau sắn có vị hơi chua thanh của rau sắn, vị ngọt tự nhiên của cá… Một món ăn hấp dẫn trong những ngày hè nóng nực.', 'Phú Thọ', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/08/cach-lam-canh-rau-san-nau-ca---dac-san-phu-tho-1620468363.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=R4LF31BOhML-6b1t42oC1w', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm canh rau sắn nấu cá – đặc sản Phú Thọ');
INSERT INTO public.post VALUES (463, '2025-11-20 17:11:01.829798', '2025-11-20 17:11:01.829798', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 465, 'Cách làm cua rang me đơn giản mà ngon tại nhà', 'Các tín đồ ẩm thực trên thế giới mê mẩn hai món cua xốt ở châu Á là cua rang me (Tamarind Crab) của Việt Nam và cua xốt ớt (Chilli Crab) của Singapore.', 'Cà Mau', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/23/cach-lam-cua-rang-me-dai-tiec-1619170824.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=IT-JuUPMDUgzz-bqrGtMMw', 22, 23, 'HARD', 'Cùng thử nấu Cách làm cua rang me đơn giản mà ngon tại nhà');
INSERT INTO public.post VALUES (478, '2025-11-20 17:11:07.544729', '2025-11-20 17:11:07.544729', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 480, '[Chia sẻ] Bí quyết làm bún gà nướng sả chỉ trong 30 phút', 'Thịt gà mềm đậm đà hương vị tỏa ra từ sả, đủ vị mặn ngọt hài hòa khiến cho món ăn trở nên hấp dẫn.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/03/16/bun1-1615864983-3774-1615865746.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qi8a_gdMIbqKa7BP0WmZfA', 15, 15, 'HARD', 'Cùng thử nấu [Chia sẻ] Bí quyết làm bún gà nướng sả chỉ trong 30 phút');
INSERT INTO public.post VALUES (490, '2025-11-20 17:11:13.75808', '2025-11-20 17:11:13.75808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 492, 'Cách làm chả giò rế miền Nam giòn rụm, ngon KHÓ CƯỠNG', 'Sự kết hợp của thịt lợn, tôm, sợi miến, các loại rau củ cuốn cùng bánh tráng rế làm nên những cuốn chả giò vàng thơm, giòn rụm.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2020/09/16/fb-img-1600181082409-160022480-1894-6385-1600230971.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Im1uYSzF3nJtNOKk2ap28g', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm chả giò rế miền Nam giòn rụm, ngon KHÓ CƯỠNG');
INSERT INTO public.post VALUES (505, '2025-11-20 17:11:16.568643', '2025-11-20 17:11:16.568643', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 507, 'Cách làm chân gà sốt kiểu Thái giòn, ngon, trọn vị đơn giản tại nhà', 'Chân gà giòn, thấm trọn vị chua cay mặn ngọt, dậy mùi thơm của sả, tắc, ớt, tỏi hòa quyện làm nên bản giao hưởng đậm đà chất Thái.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/12/10/Thnhphm21-1639112983-6014-1639113016.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=omRUwIYF3Spgq55vJDWI2A', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm chân gà sốt kiểu Thái giòn, ngon, trọn vị đơn giản tại nhà');
INSERT INTO public.post VALUES (520, '2025-11-20 17:11:22.172325', '2025-11-20 17:11:22.172325', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 522, 'Cách làm nọng heo nướng ngon bất bại', 'Phần thịt nọng heo được nhiều người yêu thích bởi vừa giòn, vừa mềm mà không ngấy, không bị khô.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/10/15/-2852-1665806919.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=wWeCdBUzMgi8-BW1U9pxIA', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách làm nọng heo nướng ngon bất bại');
INSERT INTO public.post VALUES (535, '2025-11-20 17:11:27.308285', '2025-11-20 17:11:27.308285', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 537, 'Hải sản chiên nướng chấm tương chua', 'Một món ăn lạ, ngon miệng sẽ giúp cho bữa ăn của gia đình bạn đầm ấm hơn. Hải sản chiên nướng khi ăn cùng nước tương là món ăn rất hấp dẫn.', 'Kiên Giang', 'https://i1-giadinh.vnecdn.net/2021/10/21/xiennuong-1634805934-1321-1634805939.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ttUHTTKUZx_DQ8YLbnAqpg', 0, 0, 'HARD', 'Cùng thử nấu Hải sản chiên nướng chấm tương chua');
INSERT INTO public.post VALUES (550, '2025-11-20 17:11:30.983899', '2025-11-20 17:11:30.983899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 552, 'Mực nhồi xôi', 'Xôi trộn nấm hương, nhồi thân mực chiên giòn, ăn nóng. Món này ngon, vị lạ lại chế biến đơn giản.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/10/13/mucnhoixoi-1634113644-2489-1634113737.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-a-qQca2YWHDMVJuYLD5cw', 0, 0, 'EASY', 'Cùng thử nấu Mực nhồi xôi');
INSERT INTO public.post VALUES (565, '2025-11-20 17:11:34.93969', '2025-11-20 17:11:34.93969', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 567, 'Bắp bò ngâm mắm tỏi', 'Món ăn dễ làm này có thể dùng trong bữa cơm bình thường hay là đồ nhắm khoái khẩu trong tiệc rượu.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/11/unnamed-1633940623-8032-1633940694.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=8xJnheh_EhxYch8QogXkZw', 0, 0, 'MEDIUM', 'Cùng thử nấu Bắp bò ngâm mắm tỏi');
INSERT INTO public.post VALUES (580, '2025-11-20 17:11:39.753281', '2025-11-20 17:11:39.753281', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 582, 'Sò điệp nướng mỡ hành', 'Sò chín tái, không khô xác, thơm mùi nướng với vị hành. Món này sẽ hấp dẫn cả nhà bạn. Mời bạn tham khảo cách nấu của Ezcooking.', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2021/10/03/sodiep-1633238755-4304-1633238817.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=rY3xHX63dadh9ufeAZ1vcw', 0, 0, 'MEDIUM', 'Cùng thử nấu Sò điệp nướng mỡ hành');
INSERT INTO public.post VALUES (595, '2025-11-20 17:11:43.57006', '2025-11-20 17:11:43.57006', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 597, 'Cách làm pizza không cần lò nướng', 'Với vài nguyên liệu cơ bản và một chiếc chảo chống dính, bạn có thể làm pizza ngon như ngoài tiệm trong thời kỳ giãn cách.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/07/30/nh4-1627636653-5227-1627636837.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Zpt2-3YTzpDpjr_I5uBd-A', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm pizza không cần lò nướng');
INSERT INTO public.post VALUES (610, '2025-11-20 17:11:50.158854', '2025-11-20 17:11:50.158854', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 612, 'Hướng dẫn nấu phở bò tại nhà chuẩn vị mà đơn giản', 'Một bát phở ngon là sự tổng hòa của nhiều yếu tố kết hợp, đặc biệt là phần nước dùng - linh hồn của bát phở.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/03/07/nhngang1-1615086549-6552-1615087048.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=tQu2eyLkzZ-UVBGNtLA00Q', 360, 360, 'HARD', 'Cùng thử nấu Hướng dẫn nấu phở bò tại nhà chuẩn vị mà đơn giản');
INSERT INTO public.post VALUES (494, '2025-11-20 17:11:14.559799', '2025-11-20 17:11:14.559799', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 496, 'Cách làm món bò nhúng giấm ấm áp dịp Tết', 'Nước nhúng giấm ngọt dịu, chua thanh, khi nhúng thịt bò vào thì thịt mềm ngọt mà không dai. Nước chấm mắm nêm vừa vị.', 'Đà Lạt', 'https://i1-giadinh.vnecdn.net/2022/12/30/Bc6Thnhphm16-1672385654-4202-1672385713.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3erFlGboAeK5rVALaEFQtA', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm món bò nhúng giấm ấm áp dịp Tết');
INSERT INTO public.post VALUES (509, '2025-11-20 17:11:17.500154', '2025-11-20 17:11:17.500154', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 511, 'Bắp xào tép khô - món ăn vặt ''thần thánh''', 'Từng hạt ngô nếp dẻo mềm, tép khô thơm giòn, đậm vị, dậy mùi thơm quyến rũ từ bơ, hành lá khiến cho các tín đồ ẩm thực đường phố đều mê mẩn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/11/26/Thnhphm1-1637900227-5877-1637900253.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=a5KxAwW2CM5lei0exBy7xw', 20, 20, 'MEDIUM', 'Cùng thử nấu Bắp xào tép khô - món ăn vặt ''thần thánh''');
INSERT INTO public.post VALUES (524, '2025-11-20 17:11:23.172231', '2025-11-20 17:11:23.172231', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 526, 'Các món ngon làm từ nha đam', 'Nha đam (lô hội) là thành phần khá quen thuộc trong nhiều loại mỹ phẩm, bài thuốc trị bệnh. Ngoài ra, những món ăn được làm từ nha đam dưới đây cũng giúp chị em thể hiện tài nội trợ của mình.', 'Ninh Thuận', 'https://i1-giadinh.vnecdn.net/2021/11/18/goinhadam-1637225487-3561-1637225618.png?w=0&h=0&q=100&dpr=2&fit=crop&s=IFck9yg-1PwlYAcA7waoCw', 0, 0, 'EASY', 'Cùng thử nấu Các món ngon làm từ nha đam');
INSERT INTO public.post VALUES (539, '2025-11-20 17:11:28.267643', '2025-11-20 17:11:28.267643', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 541, 'Gỏi da bò', 'Gỏi da bò có thể coi là món ăn đặc trưng của thị trấn Phú Phong, huyện Sơn Tây, tỉnh Bình Định. Da bò non mềm, trộn gỏi chua ngọt với gừng, chanh, ăn kèm bánh tráng mè đen rất ngon và bổ.', 'Bình Định', 'https://i1-giadinh.vnecdn.net/2021/10/19/goidabo-1634617253-8714-1634617517.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Wyq_B0m-FCGZw1OqoVPZ3Q', 0, 0, 'EASY', 'Cùng thử nấu Gỏi da bò');
INSERT INTO public.post VALUES (554, '2025-11-20 17:11:32.022765', '2025-11-20 17:11:32.022765', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 556, 'Canh móng giò hầm củ sen', 'Đây là món ăn bổ dưỡng của người Hoa, giúp giảm căng thẳng lo âu dành cho các đôi vợ chồng sắp cưới.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/14/thumb1200x6767-1634185862-2345-1634185945.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=KNIeZdIE-s0AgHPugjy2EQ', 0, 0, 'EASY', 'Cùng thử nấu Canh móng giò hầm củ sen');
INSERT INTO public.post VALUES (569, '2025-11-20 17:11:36.310338', '2025-11-20 17:11:36.310338', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 571, 'Sườn nướng BBQ', 'Món này không mới nhưng vẫn rất hấp dẫn với bạn và mọi người trong gia đình. Mời bạn thử chế biến dưới sự hướng dẫn của các chuyên gia Ezcooking.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/05/suon-1633402893-6121-1633403006.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ioVA7YiDC1MKdJefK6qizg', 0, 0, 'MEDIUM', 'Cùng thử nấu Sườn nướng BBQ');
INSERT INTO public.post VALUES (584, '2025-11-20 17:11:40.715913', '2025-11-20 17:11:40.715913', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 586, 'Gỏi khô bò đu đủ xanh', 'Thường, gỏi khô bò là món ăn vặt ngoài đường phố. Tuy nhiên, bạn có thể tự tay làm món này đãi cả nhà lai rai vào dịp cuối tuần qua hướng dẫn của các đầu bếp Rosa.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/02/nombokho-1633181623-3764-1633182268.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-CLHP1MZ-wuNYyYzK4_pTg', 0, 0, 'EASY', 'Cùng thử nấu Gỏi khô bò đu đủ xanh');
INSERT INTO public.post VALUES (599, '2025-11-20 17:11:44.571129', '2025-11-20 17:11:44.571129', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 601, 'Cách nấu miến ngan chuẩn vị và ''ngon như ngoài tiệm''', 'Trong mùa hè, món miến ngan măng khô được nhiều bà nội trợ lựa chọn bởi nguyên liệu và cách làm đơn giản, ngon miệng.', 'Hà Nội', 'https://iv1.vnecdn.net/giadinh/images/web/2021/06/12/cach-lam-mien-ngan-mang-kho-ngon-nhu-ngoai-tiem-1623483426.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=KEBunUVq_LcCZPFpIRWLiA', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách nấu miến ngan chuẩn vị và ''ngon như ngoài tiệm''');
INSERT INTO public.post VALUES (614, '2025-11-20 17:11:52.088437', '2025-11-20 17:11:52.088437', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 616, 'Hướng dẫn cách làm món Salad "Hổ khóc" kiểu Thái độc đáo', 'Thịt bò ngọt mềm quyện trong nước sốt thơm mùi thính, hài hòa vị chua cay mặn ngọt từ ớt, đường... Món salad thịt bò này có tên là Crying Tiger Beef (hổ khóc).', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/02/26/Bo2-1614307162-6880-1614308134.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0uX_Hac1swWr_auwkUk3CA', 10, 10, 'HARD', 'Cùng thử nấu Hướng dẫn cách làm món Salad "Hổ khóc" kiểu Thái độc đáo');
INSERT INTO public.post VALUES (496, '2025-11-20 17:11:15.034109', '2025-11-20 17:11:15.034109', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 498, 'Cách làm bánh mì hot dog đơn giản tại nhà', 'Vỏ bánh mềm mịn, vàng ươm, thơm mùi bơ và vừng, xúc xích thơm ngon. Món này được các bạn nhỏ yêu thích.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/11/26/Thnhphm1-1637916893-8417-1637916919.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=vG1NbZ4Zv8bX9YeQojBLCQ', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm bánh mì hot dog đơn giản tại nhà');
INSERT INTO public.post VALUES (511, '2025-11-20 17:11:18.017733', '2025-11-20 17:11:18.017733', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 513, 'Cá còm kho nghệ - đặc sản Nghệ An', 'Cá săn lại, bên trong thịt thơm, xương mềm, nước sánh vàng ươm, dậy mùi thơm lá nghệ, vị mặn ngọt cay hài hòa.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/10/31/nh1-1635640274-4588-1635640353.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=oh7_DxYwEyp8MDcOWzS4oQ', 45, 45, 'MEDIUM', 'Cùng thử nấu Cá còm kho nghệ - đặc sản Nghệ An');
INSERT INTO public.post VALUES (526, '2025-11-20 17:11:23.634007', '2025-11-20 17:11:23.634007', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 528, 'Vị ngọt từ ngô non', 'Những hạt ngô non thơm ngọt, bùi bùi không chỉ tốt cho sức khỏe mà còn giúp bạn tạo nên hương vị và màu sắc mới lạ cho rất nhiều món ăn.', 'Sơn La', 'https://i1-giadinh.vnecdn.net/2021/11/15/supngo-1636950962-3930-1636951020.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0ux8sKJJO5LdMqXV7jVQnA', 0, 0, 'EASY', 'Cùng thử nấu Vị ngọt từ ngô non');
INSERT INTO public.post VALUES (541, '2025-11-20 17:11:28.778062', '2025-11-20 17:11:28.778062', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 543, 'Món mặn từ hoa quả', 'Thử biến tấu một chút, bạn sẽ ngạc nhiên bởi mùi thơm và vị mát từ các loại quả sẽ làm cho các món ăn hấp dẫn và mới lạ hơn nhiều.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/25/lau-1635154698-2173-1635154807.png?w=0&h=0&q=100&dpr=2&fit=crop&s=n7NB6PgCOslqj_Mt1huLgw', 0, 0, 'MEDIUM', 'Cùng thử nấu Món mặn từ hoa quả');
INSERT INTO public.post VALUES (556, '2025-11-20 17:11:32.850217', '2025-11-20 17:11:32.850217', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 558, 'Gà hấp muối', 'Món ăn ngon, lạ miệng này sẽ giúp bạn ghi điểm trước cả nhà và có thể làm các vị khách mời tấm tắc.', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2021/10/13/gahap-1634096401-3217-1634096518.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VRfeqx-UfHbrf7lzS9vdNg', 0, 0, 'MEDIUM', 'Cùng thử nấu Gà hấp muối');
INSERT INTO public.post VALUES (571, '2025-11-20 17:11:36.989374', '2025-11-20 17:11:36.989374', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 573, 'Ba rọi nướng riềng mẻ', 'Món ăn có màu vàng sẫm, nổi mùi vị đặc trưng của giềng mẻ, mắm tôm và béo ngậy của thịt ba rọi với nước cốt dừa. Mời bạn thử chế biến qua sự hướng dẫn của các chuyên gia Ezcooking.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/04/thitnuong-1633329999-7321-1633330176.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=AV4R_bmCvwNacfx741PNxw', 0, 0, 'HARD', 'Cùng thử nấu Ba rọi nướng riềng mẻ');
INSERT INTO public.post VALUES (586, '2025-11-20 17:11:41.347285', '2025-11-20 17:11:41.347285', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 588, 'Ốc hương hấp hèm', 'Món ăn hấp dẫn, thơm ngon này rất đặc trưng cho khẩu vị Nam bộ dân dã. Mời bạn thử trổ tài dưới sự hướng dẫn của các đầu bếp Rosa.', 'Bà Rịa – Vũng Tàu', 'https://i1-giadinh.vnecdn.net/2021/10/03/ochuong-1633238108-5594-1633238138.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=JmophtbmJy2_fL1Vel1dcQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Ốc hương hấp hèm');
INSERT INTO public.post VALUES (601, '2025-11-20 17:11:45.229335', '2025-11-20 17:11:45.229335', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 603, 'Cách làm Bún bung hoa chuối Thái Bình đặc trưng người dân quê lúa', 'Cùng với canh cá Quỳnh Côi, bún bung là món ăn dân dã làm nên đặc trưng ẩm thực riêng của người dân quê lúa Thái Bình.', 'Thái Bình', 'https://iv1.vnecdn.net/giadinh/images/web/2021/04/22/cach-lam-bun-bung-hoa-chuoi-thai-binh-1619083804.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=ELp4LWLzvgEEO9H5Jl7Nyw', 65, 65, 'MEDIUM', 'Cùng thử nấu Cách làm Bún bung hoa chuối Thái Bình đặc trưng người dân quê lúa');
INSERT INTO public.post VALUES (500, '2025-11-20 17:11:15.798802', '2025-11-20 17:11:15.798802', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 502, 'Bắp cải cuốn thịt mềm ngon, đậm vị', 'Bắp cải thanh ngọt, thịt đậm đà, cà chua sánh đỏ quyện lại tạo nên món ăn bổ dưỡng ngày đông.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/12/10/Thnhphm1-1639109882-4858-1639110016.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=7ijAwryVco39HAAz7-UbbQ', 25, 25, 'MEDIUM', 'Cùng thử nấu Bắp cải cuốn thịt mềm ngon, đậm vị');
INSERT INTO public.post VALUES (507, '2025-11-20 17:11:16.902399', '2025-11-20 17:11:16.902399', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 509, 'Xôi cốm - món ăn đượm vị thu Hà Nội', 'Hạt xôi dẻo mềm mà vẫn tơi, ngọt dịu, quyện vị bùi bùi của đậu xanh, hạt sen, béo ngậy của dừa xào làm nên món ăn tinh tế của mùa thu Hà thành.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/12/xoicom-1634025195-9392-1634025300.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=TGixHSTZc0ajoCT2sUjScA', 15, 15, 'MEDIUM', 'Cùng thử nấu Xôi cốm - món ăn đượm vị thu Hà Nội');
INSERT INTO public.post VALUES (512, '2025-11-20 17:11:18.525237', '2025-11-20 17:11:18.525237', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 514, 'Cách làm sườn nướng tảng ngon như ngoài tiệm', 'Sườn mềm, thấm vị đậm đà mà không bị khô, dẻ sườn dễ róc. Một món ngon cho các bạn nhỏ sau những giờ học online.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/12/nh1-1634025642-6006-1634025738.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=xcmIv_fyV0iIq4XS08WPkA', 35, 35, 'HARD', 'Cùng thử nấu Cách làm sườn nướng tảng ngon như ngoài tiệm');
INSERT INTO public.post VALUES (515, '2025-11-20 17:11:19.794757', '2025-11-20 17:11:19.794757', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 517, 'Cách nấu lẩu gà lá é - món ngon nổi tiếng Đà Lạt', 'Thịt gà mềm ngọt, lá é nhúng nước lẩu nóng làm dậy vị the the, bùi bùi, ăn cùng măng củ giòn, nấm tươi ngọt làm thực khách ''''xiêu lòng'''' khi tới xứ sở ngàn hoa.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2022/12/08/Bc7Thnhphm7-1670471420-8501-1670471747.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=6-XdvK-KkKIiSDZjVBu54g', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách nấu lẩu gà lá é - món ngon nổi tiếng Đà Lạt');
INSERT INTO public.post VALUES (522, '2025-11-20 17:11:22.636849', '2025-11-20 17:11:22.636849', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 524, 'Cách làm mực chiên giòn như nhà hàng 5 sao', 'Vỏ mực khi ăn giòn rụm, bên trong mềm ngọt, giữ độ sần sật, mùi thơm đặc trưng từ mực. Món này ăn kèm rau sống, chấm hỗn hợp tương ớt và sốt mayonnaise hấp dẫn.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2022/10/08/-5704-1665207649.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Ro4qnk8E-SyBIPE6bHqDlQ', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm mực chiên giòn như nhà hàng 5 sao');
INSERT INTO public.post VALUES (527, '2025-11-20 17:11:24.48202', '2025-11-20 17:11:24.48202', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 529, 'Cánh gà nhồi nấm chiên', 'Cánh gà và nấm là 2 loại nguyên liệu rất bổ dưỡng và có thể chế biến được nhiều món ăn, vừa có giá trị dinh dưỡng vừa là những bài thuốc tốt cho sức khỏe.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/21/canhganhoi-1634805348-1128-1634805515.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=KiQbpxzYED0Qv6hoMmm5ig', 0, 0, 'MEDIUM', 'Cùng thử nấu Cánh gà nhồi nấm chiên');
INSERT INTO public.post VALUES (530, '2025-11-20 17:11:26.00123', '2025-11-20 17:11:26.00123', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 532, 'Nghêu sốt dầu hào', 'Nghêu sốt dầu hào là món hải sản lạ mắt, hấp dẫn lại rất giàu dinh dưỡng. Bạn không phải bỏ nhiều công sức và thời gian khi chế biến món này.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/18/8eca1c04af9d14bfd2f452b2ad3790-6917-8742-1634550914.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=l-XfW_2vInpTbLQBIgXXiA', 0, 0, 'MEDIUM', 'Cùng thử nấu Nghêu sốt dầu hào');
INSERT INTO public.post VALUES (537, '2025-11-20 17:11:27.829075', '2025-11-20 17:11:27.829075', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 539, 'Chả sen tôm', 'Đây là món ăn lạ miệng lại không mất nhiều thời gian chế biến. Bạn có thể thử làm ngay để cả nhà cùng thưởng thức cuối tuần này.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/18/Untitled31200x6763-1634551109-4123-1634551115.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MbRMD0wsOLC1LWE80t39qw', 0, 0, 'MEDIUM', 'Cùng thử nấu Chả sen tôm');
INSERT INTO public.post VALUES (542, '2025-11-20 17:11:29.041099', '2025-11-20 17:11:29.041099', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 544, 'Lươn nướng lá nếp', 'Thịt lươn cắt khúc, ướp sơ với riềng mẻ. Lươn cuốn lá nếp nướng trên than hoa dậy mùi thơm hấp dẫn.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/10/17/luon-1634446627-5289-1634446863.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=J5eCIDQv8c74Apn1I7VAyg', 0, 0, 'MEDIUM', 'Cùng thử nấu Lươn nướng lá nếp');
INSERT INTO public.post VALUES (545, '2025-11-20 17:11:29.879637', '2025-11-20 17:11:29.879637', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 547, 'Nghêu cuốn', 'Tuy hơi kỳ công nhưng món nghêu cuốn bạn làm sẽ khiến cả nhà trầm trồ vì vị thơm ngon và lạ miệng của nó.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/18/unnamed1-1634549689-2719-1634549790.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=J4OuzsMQNvtPhhiC7LjA1g', 0, 0, 'HARD', 'Cùng thử nấu Nghêu cuốn');
INSERT INTO public.post VALUES (552, '2025-11-20 17:11:31.555354', '2025-11-20 17:11:31.555354', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 554, 'Giò heo om mía', 'Những miếng giò heo chín mềm, quyện với vị bùi của đậu phộng và thơm mát của hạt sen là những gì bạn cảm nhận được khi thưởng thức món om này.', 'Sóc Trăng', 'https://i1-giadinh.vnecdn.net/2021/10/15/unnamed2-1634296310-4177-1634296389.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=khzTyJI_52HwaV9edAQnxg', 0, 0, 'MEDIUM', 'Cùng thử nấu Giò heo om mía');
INSERT INTO public.post VALUES (557, '2025-11-20 17:11:33.092046', '2025-11-20 17:11:33.092046', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 559, 'Ốc móng tay xào cay', 'Ốc móng tay có thể chế biến thành nhiều món và được nhiều người rất thích vì thịt nhiều và ngọt. Bạn thử trổ tài nội trợ qua món ốc móng tay xào cay được giới thiệu dưới đây.', 'Quảng Ninh', 'https://i1-giadinh.vnecdn.net/2021/10/13/ocmongtay-1634113548-9973-1634113573.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3bfzzknoQCqEysBWIu_OqQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Ốc móng tay xào cay');
INSERT INTO public.post VALUES (560, '2025-11-20 17:11:33.774113', '2025-11-20 17:11:33.774113', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 562, 'Nem cuốn tôm thịt', 'Bạn có thể làm mới bữa ăn hàng ngày bằng một món cuốn tráng miệng nhẹ nhàng, dễ ăn và ngon miệng.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/11/nemcuon-1633941537-8849-1633941642.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=iSrgr5ApOUY0hqzwDhPUjA', 0, 0, 'MEDIUM', 'Cùng thử nấu Nem cuốn tôm thịt');
INSERT INTO public.post VALUES (567, '2025-11-20 17:11:35.714499', '2025-11-20 17:11:35.714499', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 569, 'Vịt nấu cam', 'Món ăn có vị lạ, thơm ngon, bạn có thể làm ngay để đãi cả nhà. Công thức dưới đây được sử dụng cho 10 người ăn.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2021/10/11/vtnucam-1633940926-6249-1633941030.png?w=0&h=0&q=100&dpr=2&fit=crop&s=L65_FcQtIBweTkNlerSKdA', 0, 0, 'MEDIUM', 'Cùng thử nấu Vịt nấu cam');
INSERT INTO public.post VALUES (506, '2025-11-20 17:11:16.719501', '2025-11-20 17:11:16.719501', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 508, 'Xôi hạt dẻ - ấm lòng ngày đầu đông', 'Hạt xôi căng mẩy, dẻo mềm quyện hạt dẻ bở bùi, ngọt dịu như lan dần ra hương vị rất đỗi mộc mạc của đất trời.', 'Lạng Sơn', 'https://i1-giadinh.vnecdn.net/2021/10/31/Thnhphm4-1635642835-9650-1635642960.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_jssKMAmbZYfFcFh0SrNVw', 25, 25, 'EASY', 'Cùng thử nấu Xôi hạt dẻ - ấm lòng ngày đầu đông');
INSERT INTO public.post VALUES (510, '2025-11-20 17:11:17.710033', '2025-11-20 17:11:17.710033', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 512, 'Chè sắn nóng - ấm lòng ngày se lạnh', 'Chè có vị dịu ngọt ấm nóng của gừng, màu nâu vàng sánh mịn quyện với từng miếng sắn dẻo mềm xua đi cái se lạnh khi gió mùa về.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/17/chesan-1634458539-3111-1634458643.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=WL41mkHILBAejl6v6UFX_Q', 22, 23, 'MEDIUM', 'Cùng thử nấu Chè sắn nóng - ấm lòng ngày se lạnh');
INSERT INTO public.post VALUES (514, '2025-11-20 17:11:19.417761', '2025-11-20 17:11:19.417761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 516, 'Lẩu bò ớt xiêm xanh', 'Nước lẩu được nấu từ tỏi ớt và nạm, xương bò mang đến vị chua cay hấp dẫn được nhiều người yêu thích, nhất là khi trời se lạnh.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2021/10/26/laubo-1635238366-6236-1635238389.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=UjZ5O7NBmeyK6g-Clzk-rA', 25, 25, 'MEDIUM', 'Cùng thử nấu Lẩu bò ớt xiêm xanh');
INSERT INTO public.post VALUES (521, '2025-11-20 17:11:22.52128', '2025-11-20 17:11:22.52128', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 523, 'Cách làm lẩu ốc mùa thu', 'Lẩu ốc hấp dẫn bởi ốc giòn, thịt bò chín tới ngọt mềm, đậu phụ vàng giòn. Nước dùng đủ sắc - hương - vị với vị chua thanh từ dấm bỗng, ngọt nhẹ từ ngao ốc, the cay từ ớt... như bản hòa tấu đẹp.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/09/16/-5348-1663318159.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VGMa_wsp-K7Vc8RQhg380g', 37, 38, 'MEDIUM', 'Cùng thử nấu Cách làm lẩu ốc mùa thu');
INSERT INTO public.post VALUES (525, '2025-11-20 17:11:23.462307', '2025-11-20 17:11:23.462307', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 527, 'Hàu đút lò', 'Hàu đút lò dùng nóng với muối tiêu chanh pha ớt băm.', 'Quảng Ninh', 'https://i1-giadinh.vnecdn.net/2021/10/23/hau-1634963062-3854-1634963133.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=paGKuasyUvk0TES67UCE8Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Hàu đút lò');
INSERT INTO public.post VALUES (529, '2025-11-20 17:11:25.826456', '2025-11-20 17:11:25.826456', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 531, 'Lẩu trăm hoa', 'Vẫn là món lẩu nhưng không dùng với rau sống mà kèm các loại hoa. Món lẩu này rất đặc biệt với nhiều hương vị khác nhau lại rất dễ trình bày đẹp mắt. Bạn thử trổ tài nhé.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/11/18/lauhoa-1637225289-1753-1637225402.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=YT8ueYnaNbr5Wxt1X-MD_A', 0, 0, 'MEDIUM', 'Cùng thử nấu Lẩu trăm hoa');
INSERT INTO public.post VALUES (536, '2025-11-20 17:11:27.470652', '2025-11-20 17:11:27.470652', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 538, 'Hai món cá nướng dễ làm', 'Tiết trời lạnh rất hợp với các món nướng giòn, thơm mùi gia vị, với nguyên liệu chính là cá, hoặc tôm, mực...', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2021/10/26/cahoinuong-1635240474-6900-1635240506.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=hnYc9XDlQjANzjstfZjruA', 0, 0, 'EASY', 'Cùng thử nấu Hai món cá nướng dễ làm');
INSERT INTO public.post VALUES (540, '2025-11-20 17:11:28.502496', '2025-11-20 17:11:28.502496', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 542, 'Canh bí đỏ cả quả', 'Canh bí là món ngon, bổ dưỡng. Với cách chế biến hơi lạ, không xắt miếng mà để cả quả, hấp lên, bạn sẽ làm cả nhà bất ngờ.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/10/18/photo1571218066911157121806692-7026-4355-1634549533.png?w=0&h=0&q=100&dpr=2&fit=crop&s=2pa6dNY3XOLsEGHl4pSYlQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh bí đỏ cả quả');
INSERT INTO public.post VALUES (544, '2025-11-20 17:11:29.586185', '2025-11-20 17:11:29.586185', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 546, 'Bánh mỳ gà xé', 'Bạn có thể làm thử món "Tây" này để giúp cả nhà thay đổi khẩu vị hoặc có thể chuẩn bị vài bước từ tối trước để mọi người có bữa sáng ngon miệng, giàu dinh dưỡng.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/15/banhmi-1634272764-1554-1634272894.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=zOxBVAxdIRRMcWT1B0nJwA', 0, 0, 'MEDIUM', 'Cùng thử nấu Bánh mỳ gà xé');
INSERT INTO public.post VALUES (551, '2025-11-20 17:11:31.206408', '2025-11-20 17:11:31.206408', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 553, 'Cá rô đồng kho nước dừa', 'Nếu đã thưởng thức món cá rô kho tộ chế biến theo kiểu Miền Nam thì bạn cũng đừng bỏ qua món cá rô đồng kho nước dừa theo kiểu miền Bắc. Đây là món ăn ngon, mang đậm hương vị quê nhà.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/14/maxresdefault5-1634184492-6796-1634184558.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=GoSJQbS9ciF9TacdUxS_XA', 0, 0, 'MEDIUM', 'Cùng thử nấu Cá rô đồng kho nước dừa');
INSERT INTO public.post VALUES (555, '2025-11-20 17:11:32.581028', '2025-11-20 17:11:32.581028', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 557, 'Khéo tay với thịt bò sốt vang', 'Những ngày mùa đông lạnh giá này, được thưởng thức món bò sốt vang đậm đà, thơm ngon, nóng sốt thì còn gì bằng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/11/bosotvang-1633941778-6627-1633941931.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=36SA5RmLj7R0Q278yswyaA', 0, 0, 'HARD', 'Cùng thử nấu Khéo tay với thịt bò sốt vang');
INSERT INTO public.post VALUES (559, '2025-11-20 17:11:33.629895', '2025-11-20 17:11:33.629895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 561, 'Nộm thập cẩm', 'Món này rất ngon, lại không ngán. Bạn có thể trổ tài để giúp bữa ăn ngày Tết thêm hấp dẫn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/11/nom1-1633942819-1391-1633942859.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=wtCqKhbkEjk1LzLbU2fx7Q', 0, 0, 'HARD', 'Cùng thử nấu Nộm thập cẩm');
INSERT INTO public.post VALUES (566, '2025-11-20 17:11:35.407848', '2025-11-20 17:11:35.407848', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 568, 'Lẩu cua đồng', 'Cua đồng không chỉ dùng để nấu canh mà có thể chế biến thành nhiều món rất ngon và lạ miệng như: cua rang khế, gạch cua xào hay lẩu cua đồng thơm ngon được giới thiệu dưới đây.', 'Hải Dương', 'https://i1-giadinh.vnecdn.net/2021/10/10/laucuadong-1633836268-4368-1633836390.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uxvmPR4EDDiE7NAaE2lMiQ', 0, 0, 'HARD', 'Cùng thử nấu Lẩu cua đồng');
INSERT INTO public.post VALUES (570, '2025-11-20 17:11:36.535232', '2025-11-20 17:11:36.535232', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 572, 'Nộm tai heo', 'Món nộm giòn, nổi vị chua, cay, ngọt, thơm bùi của lạc sẽ mang lại hương vị mới mẻ cho bữa ăn trong gia đình cũng như khi bạn bè quây quần.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/08/nom2-1633692906-3082-1633693013.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=yI1r2U6VA0J9iA7orGo8SA', 0, 0, 'MEDIUM', 'Cùng thử nấu Nộm tai heo');
INSERT INTO public.post VALUES (574, '2025-11-20 17:11:38.445963', '2025-11-20 17:11:38.445963', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 576, 'Cá tầm hấp gừng hành và xốt xì dầu', 'Cá tầm thịt trắng, dai, vị béo ngậy và thơm. Món cá hấp gừng hành và xốt xì dầu có hương vị thơm ngon rất hấp dẫn.', 'Lào Cai', 'https://i1-giadinh.vnecdn.net/2021/10/08/catam-1633658654-6115-1633658935.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=lBQvPuVpm5wk6El6wR7mPQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Cá tầm hấp gừng hành và xốt xì dầu');
INSERT INTO public.post VALUES (508, '2025-11-20 17:11:17.27851', '2025-11-20 17:11:17.27851', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 510, 'Cách làm thịt xiên nướng ngon như ngoài hàng', 'Thịt xiên mềm, bóng đẹp, mùi thơm các gia vị đầy ''''mê hoặc'''', dùng ăn chơi hay ăn kèm bún đều rất phù hợp trong tiết trời lạnh.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/31/Thnhphm-1635640986-7936-1635641025.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=hNSCiL0q-k9PLEwSZH0o8Q', 90, 90, 'HARD', 'Cùng thử nấu Cách làm thịt xiên nướng ngon như ngoài hàng');
INSERT INTO public.post VALUES (523, '2025-11-20 17:11:22.928907', '2025-11-20 17:11:22.928907', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 525, 'Cà ri tôm càng', 'Món cà ri tôm càng vừa có hương vị quen thuộc của cà ri, vừa có vị chua, cay, ngọt. Những nguyên liệu đậu bắp, dừa nạo nấu chung với tôm càng rất ngon mà lại đặc sắc.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/23/cari-1634963886-9198-1634964026.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uhMsZLMt4Q9qF5AuUE1_Bw', 0, 0, 'MEDIUM', 'Cùng thử nấu Cà ri tôm càng');
INSERT INTO public.post VALUES (538, '2025-11-20 17:11:28.041126', '2025-11-20 17:11:28.041126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 540, 'Chạch trấu kho trám', 'Cá chạch kho trám, rưới thêm ít tương. Món kho ăn kèm cơm trắng.', 'Bắc Giang', 'https://i1-giadinh.vnecdn.net/2021/10/15/download-1634296623-8064-1634296753.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uMD6Ce_G7O1rXTKIaZKhfw', 0, 0, 'EASY', 'Cùng thử nấu Chạch trấu kho trám');
INSERT INTO public.post VALUES (553, '2025-11-20 17:11:31.817927', '2025-11-20 17:11:31.817927', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 555, 'Đùi ếch nhồi thịt', 'Không mất nhiều thời gian, bạn có thể trổ tài khéo tay để cả nhà được thưởng thức món đùi ếch nhồi thịt rất hấp dẫn.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2021/10/14/cachlamechchienbo-1634185658-9401-1634185810.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=XzRcBfs_9IKD2B287sIt_w', 0, 0, 'MEDIUM', 'Cùng thử nấu Đùi ếch nhồi thịt');
INSERT INTO public.post VALUES (568, '2025-11-20 17:11:35.928226', '2025-11-20 17:11:35.928226', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 570, 'Sa lát táo và khoai tây', 'Món ăn thơm ngậy nhưng không ngán, rất hợp cho cả nhà bạn thưởng thức vào dịp cuối tuần. Mời bạn trổ tài dưới sự hướng dẫn của các đầu bếp Ezcooking.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/05/salad-1633404745-3183-1633405239.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=lKBTa74lNROYnZ6qjcuOVg', 0, 0, 'MEDIUM', 'Cùng thử nấu Sa lát táo và khoai tây');
INSERT INTO public.post VALUES (583, '2025-11-20 17:11:40.546129', '2025-11-20 17:11:40.546129', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 585, 'Chạo dê', 'Ông xã chắc chắn sẽ tấm tắc khen tài nội trợ của bạn sau khi thưởng thức món này, nhất là khi dùng chạo dê trong bữa nhậu cùng chiến hữu. Mời bạn tham khảo cách làm từ các đầu bếp Ezcooking.', 'Ninh Bình', 'https://i1-giadinh.vnecdn.net/2021/10/02/chaode-1633166304-9328-1633166536.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=IPVs4msSsXoG4vxgM4dbdg', 0, 0, 'MEDIUM', 'Cùng thử nấu Chạo dê');
INSERT INTO public.post VALUES (598, '2025-11-20 17:11:44.38191', '2025-11-20 17:11:44.38191', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 600, 'Bánh canh khoai xắt vịt xiêm', 'Bánh canh vịt kết hợp giữa thịt vịt dai ngon, nước dùng thanh ngọt, sợi bánh canh khoai lang dai dẻo, phù hợp ngày hè nóng bức.', 'Trà Vinh', 'https://i1-ngoisao.vnecdn.net/2021/07/01/202051075-167431308740772-4892-9794-8887-1625135320.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=hCRl9QmkfT24bMmiXJ1mHg', 60, 60, 'MEDIUM', 'Cùng thử nấu Bánh canh khoai xắt vịt xiêm');
INSERT INTO public.post VALUES (613, '2025-11-20 17:11:51.548428', '2025-11-20 17:11:51.548428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 615, 'Hướng dẫn làm món Phở cuốn tại nhà - VnExpress Cooking', 'Phở cuốn là món ăn được nhiều người yêu thích vì sự đơn giản, tiết kiệm thời gian chế biến lại dễ ăn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/02/26/nh1-1614323508-1456-1614326656.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Np8wJdFjzyCxD-7rPDoC-Q', 0, 0, 'HARD', 'Cùng thử nấu Hướng dẫn làm món Phở cuốn tại nhà - VnExpress Cooking');
INSERT INTO public.post VALUES (543, '2025-11-20 17:11:29.208866', '2025-11-20 17:11:29.208866', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 545, 'Sườn nấu nho', 'Sườn nấu mềm với vang đỏ và nho tươi là một món ăn rất ngon. Bạn có thể chuẩn bị món này để ăn cùng với bánh mì và muối tiêu, rất hợp vị.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/21/suonnaunho-1634790220-4596-1634790339.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VQFTu2SY2dKQbY5M9DZatQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Sườn nấu nho');
INSERT INTO public.post VALUES (548, '2025-11-20 17:11:30.472974', '2025-11-20 17:11:30.472974', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 550, 'Lạ miệng với nấm', 'Vừa ngon lại dễ chế biến, các món ăn làm từ nấm sẽ đem đến cho gia đình bạn một cảm giác mới lạ. Bạn thử trổ tài qua những gợi ý dưới đây nhé.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/13/namkimcham-1634112719-2918-1634112859.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ngFmp2GQ_cS60EUdSXCy6g', 0, 0, 'EASY', 'Cùng thử nấu Lạ miệng với nấm');
INSERT INTO public.post VALUES (558, '2025-11-20 17:11:33.358341', '2025-11-20 17:11:33.358341', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 560, 'Giò gà', 'Đây là món ăn rất hấp dẫn mà các bà nội trợ có thể chuẩn bị cho mâm cơm ngày Tết nhà mình.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/12/12001200x67684-1634029094-7058-1634029183.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=bGC1qlYzWLx9takcDqJoJw', 0, 0, 'MEDIUM', 'Cùng thử nấu Giò gà');
INSERT INTO public.post VALUES (563, '2025-11-20 17:11:34.402345', '2025-11-20 17:11:34.402345', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 565, 'Gà quay mềm', 'Thịt gà ăn mềm có mùi thơm đặc biệt hấp dẫn. Bạn thử tham khảo hướng dẫn của các đầu bếp Ezcooking để làm món ngon này đãi cả nhà nhé.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2021/10/07/gaquay-1633577466-5313-1633577673.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=tVuWxvQMMrAbP5cI0PmlYg', 0, 0, 'HARD', 'Cùng thử nấu Gà quay mềm');
INSERT INTO public.post VALUES (573, '2025-11-20 17:11:37.855865', '2025-11-20 17:11:37.855865', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 575, 'Thịt bò nướng xả ớt', 'Không chế biến cầu kỳ nhưng thịt bò nướng xả ớt lại rất ngon, hương vị hấp dẫn. Những hướng dẫn dưới đây sẽ giúp bạn thực hiện thành công món này.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/08/bonuong-1633659571-9796-1633659588.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5TaKzxY3hGBQZw8yJWZvKQ', 0, 0, 'HARD', 'Cùng thử nấu Thịt bò nướng xả ớt');
INSERT INTO public.post VALUES (578, '2025-11-20 17:11:39.332266', '2025-11-20 17:11:39.332266', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 580, 'Cay cay món ốc', 'Nấu các món ốc, phải có chút cay cay từ sả, ớt mới ngon. Xét ở góc độ ẩm thực, đó là sự quân bình âm dương nhưng với người thưởng thức, có tí xuýt xoa, hít hà thì càng thêm đã miệng.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/04/ocmongtay-1633322015-8766-1633322156.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=J7s3HQYSZ5k5uttbvIeHHg', 0, 0, 'EASY', 'Cùng thử nấu Cay cay món ốc');
INSERT INTO public.post VALUES (588, '2025-11-20 17:11:41.818607', '2025-11-20 17:11:41.818607', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 590, 'Cách làm bún thang đơn giản', 'Hương vị đậm đà, cách làm đơn giản, bún thang sẽ là lựa chọn lý tưởng cho bữa sáng của gia đình bạn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/08/Bunthang-1631100866-7169-1631100895.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=KiJyvE0sPaazx6s2dINOYw', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm bún thang đơn giản');
INSERT INTO public.post VALUES (593, '2025-11-20 17:11:42.832246', '2025-11-20 17:11:42.832246', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 595, 'Sườn cừu nướng bia đen', 'Bia không chỉ là thức uống cả thế giới say mê mà còn làm cho món ăn thêm hương vị đậm đà, khác lạ.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/02/Suoncuunuong1-1633165445-6391-1633165487.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=k8qA3wNquQH4UHT8uaJmwQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Sườn cừu nướng bia đen');
INSERT INTO public.post VALUES (603, '2025-11-20 17:11:45.9422', '2025-11-20 17:11:45.9422', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 605, 'Cách làm Miến trộn kiểu Hàn Quốc dễ làm và phù hợp với những người đang ăn kiêng', 'Miến trộn Hàn Quốc là món ăn lạ miệng, dễ làm và phù hợp với những người đang ăn kiêng.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/04/13/2-1618324946-2967-1618325333.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=oGG5Byr18PrYW5TWlOf8lQ', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm Miến trộn kiểu Hàn Quốc dễ làm và phù hợp với những người đang ăn kiêng');
INSERT INTO public.post VALUES (608, '2025-11-20 17:11:48.033654', '2025-11-20 17:11:48.033654', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 610, 'Nem tai thính - Món nhậu cho cuối tuần KHÔNG NÊN bỏ lỡ', 'Tai heo giòn sần sật, dậy mùi thơm đặc trưng của thính gạo, cuốn với rau thơm chấm nước mắm chua ngọt rất thu hút cánh mày râu.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2021/03/19/nh3-1616120542-9361-1616121343.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=bR7nDRwC-VL79IdtQfqxCg', 20, 20, 'HARD', 'Cùng thử nấu Nem tai thính - Món nhậu cho cuối tuần KHÔNG NÊN bỏ lỡ');
INSERT INTO public.post VALUES (572, '2025-11-20 17:11:37.394443', '2025-11-20 17:11:37.394443', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 574, 'Dồi lươn nướng', 'Món này rất bình dị nhưng lại có hương vị độc đáo, giúp nhà bạn thay đổi khẩu vị.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/10/09/doinuong2scaled-1633776275-3834-1633776400.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Z8OPJOq-OtIaaSpaqa07bw', 0, 0, 'HARD', 'Cùng thử nấu Dồi lươn nướng');
INSERT INTO public.post VALUES (575, '2025-11-20 17:11:38.533357', '2025-11-20 17:11:38.533357', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 577, 'Khoai tây nghiền', 'Khoai tây nghiền chế biến rất đơn giản nhưng lại ngon miệng, giàu dinh dưỡng và chắc chắn sẽ rất hấp dẫn bé yêu của bạn.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/08/khoaitay-1633657549-9352-1633657656.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=CPX6N4kTIP8gebrXAt_1Ww', 0, 0, 'EASY', 'Cùng thử nấu Khoai tây nghiền');
INSERT INTO public.post VALUES (582, '2025-11-20 17:11:40.295972', '2025-11-20 17:11:40.295972', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 584, 'Khoai môn lệ phố', 'Không phải đến nhà hàng mới thưởng thức được món khoái khẩu, bạn có thể tự làm khoai môn lệ phố để đãi bản thân và gia đình. Dưới đây là hướng dẫn của Ezcooking.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/05/khoaimon1-1633401975-5086-1633402108.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3ZAxAfDi-B-gzgIkKXckuw', 0, 0, 'HARD', 'Cùng thử nấu Khoai môn lệ phố');
INSERT INTO public.post VALUES (587, '2025-11-20 17:11:41.586431', '2025-11-20 17:11:41.586431', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 589, 'Bún ốc', 'Vào những ngày đông lạnh giá này mà cả gia đình được quây quần thưởng thức bát bún ốc nóng hổi, thơm ngon thì còn gì bằng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/02/Cachnaubunoccayngonngotlamieng-5395-6232-1633166124.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=nQlokFRBzhSYkBAynS5FJA', 0, 0, 'MEDIUM', 'Cùng thử nấu Bún ốc');
INSERT INTO public.post VALUES (590, '2025-11-20 17:11:42.240343', '2025-11-20 17:11:42.240343', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 592, 'Cá điêu hồng nướng giấy bạc', 'Từ những nguyên liệu dễ tìm, với bàn tay khéo léo, bạn có thể nấu món cá ngon này đãi gia đình.', 'Đồng Nai', 'https://i1-giadinh.vnecdn.net/2021/10/02/Cadieuhongnuongsate1200x676-16-6980-6213-1633165648.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3iTu7ajf1Q1MpI87UOdiFQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Cá điêu hồng nướng giấy bạc');
INSERT INTO public.post VALUES (597, '2025-11-20 17:11:44.159323', '2025-11-20 17:11:44.159323', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 599, 'Cách làm món gà quay da giòn', 'Một món ăn Trung Hoa, hòa quyện nhiều loại gia vị, thịt gà mềm nhưng da lại rất giòn. VnExpress sẽ giúp bạn khám phá công thức làm món này.', 'Lạng Sơn', 'https://i1-giadinh.vnecdn.net/2021/08/23/gaquay2-1629710481-4264-1629710534.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=OEpz__4hfVVmDXNZ6sZAzQ', 0, 0, 'HARD', 'Cùng thử nấu Cách làm món gà quay da giòn');
INSERT INTO public.post VALUES (602, '2025-11-20 17:11:45.606657', '2025-11-20 17:11:45.606657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 604, 'Cách làm cơm chiên dứa kiểu Thái đơn giản mà ngon tuyệt', 'Cơm chiên dứa là một trong những món ăn nổi tiếng và phổ biến ở Thái Lan cùng với gỏi đu đủ, súp tôm chua cay.', 'Hồ Chí Minh', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/17/com-chien-dua-kieu-thai-la-mieng-cho-mua-he-1621235735.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=5Prh274M5wxua0RV5CufAw', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách làm cơm chiên dứa kiểu Thái đơn giản mà ngon tuyệt');
INSERT INTO public.post VALUES (605, '2025-11-20 17:11:46.390246', '2025-11-20 17:11:46.390246', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 607, 'Cách nấu món bò kho thơm ngon, đậm đà, ai cũng khen ngon', 'Đây là món ăn quen thuộc của người miền Nam, gần giống món bò sốt vang của miền Bắc, có thể thưởng thức cùng gia đình vào cuối tuần.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/03/15/1-1615818742-7067-1615818945.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qTpPIAaLuSXkhPYeES3eZg', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách nấu món bò kho thơm ngon, đậm đà, ai cũng khen ngon');
INSERT INTO public.post VALUES (612, '2025-11-20 17:11:50.968991', '2025-11-20 17:11:50.968991', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 614, 'Đổi món cuối tuần với Nộm đu đủ bò nướng - VnExpress Cooking', 'Nộm đu đủ bò nướng là món ăn kết hợp giữa hai nền ẩm thực Á - Âu, vừa dễ ăn, thanh mát vừa sang trọng, hợp với thời tiết ấm áp của thời tiết cuối mùa Xuân.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/02/26/mnu-1614308828-4636-1614311228.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=daJAZHElVFxqwwh_-EPMbw', 15, 15, 'MEDIUM', 'Cùng thử nấu Đổi món cuối tuần với Nộm đu đủ bò nướng - VnExpress Cooking');
INSERT INTO public.post VALUES (581, '2025-11-20 17:11:40.092501', '2025-11-20 17:11:40.092501', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 583, 'Salad bơ trộn hải sản', 'Salad không chỉ là món ăn dễ chế biến mà còn rất giàu vitamin và chất dinh dưỡng. Dưới đây là cách làm món Salad bơ trộn hải sản theo kiểu Đức rất thơm ngon do độc giả có nickname Bé Su gửi tới.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/02/saladbo-1633182439-2141-1633182584.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Et4ZjHqiDbwO7mjzX-HasQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Salad bơ trộn hải sản');
INSERT INTO public.post VALUES (585, '2025-11-20 17:11:40.977531', '2025-11-20 17:11:40.977531', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 587, 'Khoai môn bọc tôm chiên', 'Cách điệu từ các món tôm chiên, món ăn này tuy làm hơi cầu kỳ nhưng có mùi vị rất độc đáo, hấp dẫn. Các đầu bếp của Công ty Gia chánh Rosa sẽ hướng dẫn bạn làm món này.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2021/10/04/khoai-1633329350-6050-1633329501.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3udxikVyCMtbL3-lcIighA', 0, 0, 'HARD', 'Cùng thử nấu Khoai môn bọc tôm chiên');
INSERT INTO public.post VALUES (589, '2025-11-20 17:11:41.957462', '2025-11-20 17:11:41.957462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 591, 'Thịt gà sốt uyên ương', 'Đây là món ăn rất hấp dẫn nhưng cách làm lại đơn giản. Bạn có thể trổ tài nấu món này đãi gia đình trong những ngày cuối tuần hay dịp Tết này.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/03/canhgasotmechuangothapdan0f354-2677-9430-1633266831.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-ZYYYn1Q89DBXH_I7C6EmA', 0, 0, 'MEDIUM', 'Cùng thử nấu Thịt gà sốt uyên ương');
INSERT INTO public.post VALUES (596, '2025-11-20 17:11:43.780851', '2025-11-20 17:11:43.780851', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 598, 'Cách làm cá chép hấp lá sấu non - món đổi vị cho mùa hè', 'Quả sấu khá quen thuộc với nhiều món ăn mùa hè thì lá sấu non với vị chua thanh, được dùng chế biến món ăn lạ miệng mà hấp dẫn: Cá chép hấp lá sấu non.', 'Hà Nội', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/28/ca-chep-hap-la-sau-non-doi-vi-mua-he-1622166489.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=vHiRgSwyJy536N9t2DeYPg', 22, 23, 'EASY', 'Cùng thử nấu Cách làm cá chép hấp lá sấu non - món đổi vị cho mùa hè');
INSERT INTO public.post VALUES (600, '2025-11-20 17:11:44.923304', '2025-11-20 17:11:44.923304', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 602, 'Cách làm Cơm trộn Hàn Quốc đơn giản, ngon hơn ngoài hàng', 'Cơm trộn Hàn Quốc (Bibimbap) là món ăn phổ biến của người Hàn Quốc, khá hợp với khẩu vị của người Việt.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/04/22/1-1619106960-5671-1619107076.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=SWoOclwgbg-hROB16QnDKQ', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm Cơm trộn Hàn Quốc đơn giản, ngon hơn ngoài hàng');
INSERT INTO public.post VALUES (604, '2025-11-20 17:11:46.143126', '2025-11-20 17:11:46.143126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 606, 'Cách nấu bún bò Huế từ tương cà chua và nước dừa', 'Bún bò Huế không phải một món dễ làm, nhưng cũng không quá khó nếu chị em làm theo công thức dưới đây.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/04/04/bun1-1617529209-3243-1617529644.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=m1OHaiv8HO4KUnaQnS3kiQ', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách nấu bún bò Huế từ tương cà chua và nước dừa');
INSERT INTO public.post VALUES (611, '2025-11-20 17:11:50.638347', '2025-11-20 17:11:50.638347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 613, 'Phở cuốn cá hồi ướp muối chanh - Ngon miệng mà DỄ LÀM', 'Phở cuốn là một món ăn được ưa chuộng bởi dễ thực hiện, dễ ăn, sẽ càng hấp dẫn, tốt cho sức khỏe hơn nếu nguyên liệu chính là cá hồi sống.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/03/05/1-1614930777-3498-1614931082.png?w=0&h=0&q=100&dpr=2&fit=crop&s=Q84UCZ8M2IhcjJNMj9rjHA', 0, 0, 'HARD', 'Cùng thử nấu Phở cuốn cá hồi ướp muối chanh - Ngon miệng mà DỄ LÀM');
INSERT INTO public.post VALUES (615, '2025-11-20 17:11:52.705435', '2025-11-20 17:11:52.705435', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 617, 'Cách làm món Há cảo hấp hình cá vàng Ngon miệng - Đẹp mắt', 'Tạo hình đơn giản, nhanh gọn, món há cảo hình cá không chỉ ngon mà còn khiến bàn ăn nhà bạn sinh động và đẹp mắt hơn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/02/21/18-1613871685-2846-1613871795.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=YRXCdCN_fBx0QByyeW_RKA', 0, 0, 'HARD', 'Cùng thử nấu Cách làm món Há cảo hấp hình cá vàng Ngon miệng - Đẹp mắt');
INSERT INTO public.post VALUES (616, '2025-11-20 17:11:53.56657', '2025-11-20 17:11:53.56657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 618, '[Gợi ý] Món BÚN THANG ngon lành, đơn giản cho mùng 4 Tết', 'Dù khá cầu kỳ trong chế biến nhưng bún thang được nhiều gia đình lựa chọn ''giải ngấy'' vào mồng 4 Tết khi hóa vàng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/02/04/bun3-1612413569-1132-1612414136.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=B_GqKnHTr6IS_6VXdTZqgQ', 105, 105, 'HARD', 'Cùng thử nấu [Gợi ý] Món BÚN THANG ngon lành, đơn giản cho mùng 4 Tết');
INSERT INTO public.post VALUES (617, '2025-11-20 17:11:54.242394', '2025-11-20 17:11:54.242394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 619, 'Hướng dẫn làm Bánh tôm Hồ Tây tại nhà Ngon - Giòn - Hấp dẫn', 'Bánh tôm Hồ Tây có vị ngọt tự nhiên của tôm, giòn rụm của vỏ bánh, kết hợp nước chấm chua cay mặn ngọt khiến nhiều thực khách "không thể quên".', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/02/18/tom2-1613644532-2023-1613645498.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=S1dz9CJq_6euKMxXZRgRiQ', 45, 45, 'HARD', 'Cùng thử nấu Hướng dẫn làm Bánh tôm Hồ Tây tại nhà Ngon - Giòn - Hấp dẫn');
INSERT INTO public.post VALUES (618, '2025-11-20 17:11:54.786864', '2025-11-20 17:11:54.786864', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 620, 'Chế biến một con gà thành 10 món kiểu Á-Âu', 'Bạn có thể chế biến một con gà thành nhiều món khác nhau như ức gà xào hạt điều kiểu Thái, đùi gà nướng cam kiểu châu Âu, lườn gà xiên rau củ nướng kiểu Nhật...', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/02/08/g12-1612784375-8528-1612784749.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9mCPuTsU1LcsRn47Nrz4Pg', 0, 0, 'MEDIUM', 'Cùng thử nấu Chế biến một con gà thành 10 món kiểu Á-Âu');
INSERT INTO public.post VALUES (619, '2025-11-20 17:11:55.539593', '2025-11-20 17:11:55.539593', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 621, 'Tai heo chua ngọt, trắng giòn - MÓN NGON mà DỄ LÀM', 'Tai heo trắng giòn, nước trong, đậm đà vị chua cay mặn ngọt rất thích hợp trong mâm cỗ ngày Tết.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/02/04/nh2-1612411478-9653-1612412204.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EgpPqVB2RZ613RQMn4Ms9Q', 45, 45, 'HARD', 'Cùng thử nấu Tai heo chua ngọt, trắng giòn - MÓN NGON mà DỄ LÀM');
INSERT INTO public.post VALUES (620, '2025-11-20 17:11:56.547234', '2025-11-20 17:11:56.547234', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 622, '[Chia sẻ] Cách làm cơm gà Hội An nhanh chóng - chuẩn vị', 'Cơm gà Hội An là một trong những đặc sản nổi tiếng của ẩm thực đất Quảng Nam. Từng hạt cơm vàng ươm kết hợp thịt gà, gỏi đu đủ, ớt rim tỏi khiến ai cũng mê mẩn.', 'Hội An, Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/01/29/com2-1611892464-7028-1611892596.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=fSiuKQfCjNiGoPz8k46N-Q', 60, 60, 'HARD', 'Cùng thử nấu [Chia sẻ] Cách làm cơm gà Hội An nhanh chóng - chuẩn vị');
INSERT INTO public.post VALUES (621, '2025-11-20 17:11:57.206597', '2025-11-20 17:11:57.206597', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 623, '[Chia sẻ] cách làm Phở chiên phồng NGON như NGOÀI HÀNG', 'Nếu như phở bò gây thương nhớ bởi nước dùng tinh túy, phở xào mềm mại, thì phở chiên phồng khiến nhiều người ngỡ ngàng bởi sự kết hợp hài hòa các vị.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/01/21/pho2-1611220356-5332-1611220646.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=slVxcdIUWhxrJ6RhM3fnvg', 0, 0, 'HARD', 'Cùng thử nấu [Chia sẻ] cách làm Phở chiên phồng NGON như NGOÀI HÀNG');
INSERT INTO public.post VALUES (622, '2025-11-20 17:11:58.188787', '2025-11-20 17:11:58.188787', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 624, 'Hướng dẫn cách làm cá nướng riềng mẻ đơn giản, nhanh chóng', 'Cá nướng riềng mẻ là món ăn quen thuộc ở miền Bắc. Đây cũng là món được nhiều nhà hàng đưa vào thực đơn để ''''giải ngán'''' ngày Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/01/21/ca2-1611218570-8644-1611218952.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3tUZNz4RGQHG95OtrFeYUw', 0, 0, 'HARD', 'Cùng thử nấu Hướng dẫn cách làm cá nướng riềng mẻ đơn giản, nhanh chóng');
INSERT INTO public.post VALUES (636, '2025-11-20 17:12:01.689814', '2025-11-20 17:12:01.689814', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 638, 'Cách làm cà pháo muối mặn, món truyền thống xứ Nghệ', 'Từng quả cà pháo trắng giòn, đượm vị mặn như câu ca: ''''Ai ơi cà xứ Nghệ, càng mặn lại càng giòn/Nước chè xanh xứ Nghệ, càng chát lại càng ngon''''.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2022/08/07/Thnhphm11-1659842899-9827-1659843047.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=G889UB-zdz6iz9ZaqmPtlw', 20, 20, 'EASY', 'Cùng thử nấu Cách làm cà pháo muối mặn, món truyền thống xứ Nghệ');
INSERT INTO public.post VALUES (637, '2025-11-20 17:12:01.924079', '2025-11-20 17:12:01.924079', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 639, 'Chè cốm - dịu mát hương vị mùa thu', 'Chè cốm ngọt dịu, thoảng hương thơm thanh tao của cốm khiến ai một lần thưởng thức đều lưu luyến nét đặc trưng của mùa thu Hà Nội.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/02/checom-1633158312-1863-1633159045.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=PLkYk2lxPViLw_t7m3XVWw', 10, 10, 'MEDIUM', 'Cùng thử nấu Chè cốm - dịu mát hương vị mùa thu');
INSERT INTO public.post VALUES (651, '2025-11-20 17:12:05.57724', '2025-11-20 17:12:05.57724', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 653, 'Cách làm nước rau má, đậu xanh giải nhiệt, làm đẹp', 'Rau má kết hợp với đậu xanh được ví là "vitamin trẻ trung" giúp làm đẹp và thanh nhiệt cơ thể.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/06/23/Thnhphm1-1655957356-5670-1655957395.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gNfPBblEJnNA1eVBRU14wQ', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm nước rau má, đậu xanh giải nhiệt, làm đẹp');
INSERT INTO public.post VALUES (652, '2025-11-20 17:12:05.714473', '2025-11-20 17:12:05.714473', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 654, 'Hai cách làm nước sấu ngâm đường chua ngọt thêm cay nhẹ từ gừng', 'Quả sấu giòn róc hạt, ngấm đường, nước chua dịu ngọt, thơm mùi sấu đặc trưng quyện với chút the cay từ gừng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/06/18/Thnhphm11-1655538951-2272-1655539037.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=AGqzH74T9Ay5xvz3ZNhrJg', 30, 30, 'EASY', 'Cùng thử nấu Hai cách làm nước sấu ngâm đường chua ngọt thêm cay nhẹ từ gừng');
INSERT INTO public.post VALUES (666, '2025-11-20 17:12:08.817981', '2025-11-20 17:12:08.817981', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 668, 'Chè nha đam', 'Nha đam nấu cùng củ sen, nhãn nhục... là món chè thanh mát và bổ dưỡng.', 'Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2021/10/14/chedauxanhnhadam-1634184845-3124-1634184900.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=xPO6PVqKn3dapSY92ISWCQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Chè nha đam');
INSERT INTO public.post VALUES (667, '2025-11-20 17:12:09.007379', '2025-11-20 17:12:09.007379', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 669, 'Bánh gatô hoa quả', 'Một chút kỳ công bạn sẽ có đĩa bánh ga tô ngon tuyệt do mình tự làm lấy.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/13/banh-1634094474-5015-1634094485.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=6JkLRaKzYueoBVTsjzF7_Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Bánh gatô hoa quả');
INSERT INTO public.post VALUES (681, '2025-11-20 17:12:12.478112', '2025-11-20 17:12:12.478112', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 683, 'Bánh pudding xoài ngọt mát', 'Bánh pudding là loại thức ăn tráng miệng hấp dẫn. Bánh có vị béo ngậy và thơm, ăn mát ngọt nơi đầu lưỡi, rất thích hợp cho những ngày hè nóng nực.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2021/09/09/Puddingxoai-1631151278-8263-1631151316.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MgMylqYL5G64HFeGN385SQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Bánh pudding xoài ngọt mát');
INSERT INTO public.post VALUES (682, '2025-11-20 17:12:12.555184', '2025-11-20 17:12:12.555184', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 684, 'Sinh tố dâu tây', 'Dâu tây đang vào mùa với những trái chín đỏ mọng mang mùi hương ngọt ngào. Món sinh tố dâu tây do bạn đọc có nickname Bé Su gửi dưới đây cũng rất hấp dẫn, lại dễ làm.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/03/sinhto-1633237613-9885-1633237702.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Sn-ojhzTw-mRSWaxJL0GfA', 0, 0, 'EASY', 'Cùng thử nấu Sinh tố dâu tây');
INSERT INTO public.post VALUES (696, '2025-11-20 17:12:16.817169', '2025-11-20 17:12:16.817169', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 698, 'Cách làm chè bí đỏ nhân đậu xanh đơn giản, đẹp mắt tại nhà', 'Chè bí đỏ nhân đậu xanh là món tráng miệng hoặc ăn chơi trong ngày nắng nóng, cung cấp nguồn vitamin dồi dào, thanh lọc cơ thể, phù hợp với mọi lứa tuổi.', 'Sóc Trăng', 'https://i1-giadinh.vnecdn.net/2021/07/02/4298529-1625217928-4343-1625217932.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=dkp9X6gzY6dOOhg0Kc9ffw', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm chè bí đỏ nhân đậu xanh đơn giản, đẹp mắt tại nhà');
INSERT INTO public.post VALUES (697, '2025-11-20 17:12:17.095306', '2025-11-20 17:12:17.095306', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 699, 'Chè cam tào phớ giải nhiệt mùa hè', 'Chè cam tào phớ là một món giải khát dễ làm, giúp đẹp da, lại không béo ngậy như các loại chè khác.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/07/02/4298530-1625217953-6288-1625217957.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=XprXQjfRuq1e9zrAF4f06w', 0, 0, 'MEDIUM', 'Cùng thử nấu Chè cam tào phớ giải nhiệt mùa hè');
INSERT INTO public.post VALUES (710, '2025-11-20 17:12:21.787195', '2025-11-20 17:12:21.787195', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 712, 'Cách làm caramel (bánh flan) cực đơn giản', 'Đây là món ăn ngọt, mát và rất hấp dẫn, nhất là đối với các bé trong mùa hè này. Với cách làm rất đơn giản, mời bạn cùng trổ tài dưới sự hướng dẫn của VnExpress.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/08/26/caramel-1629980617-1982-1629980622.png?w=0&h=0&q=100&dpr=2&fit=crop&s=N_UefU4Y_2ZypRb_z_neEw', 0, 0, 'EASY', 'Cùng thử nấu Cách làm caramel (bánh flan) cực đơn giản');
INSERT INTO public.post VALUES (736, '2025-11-20 17:12:29.93505', '2025-11-20 17:12:29.93505', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 738, 'Bí quyết làm lạc rang tỏi ớt để lâu vẫn giòn', 'Lạc vàng giòn, tỏi ớt bám đều mặt, vị mặn ngọt cay hài hòa, vỏ không bị bong. Món này dùng ăn xôi, cơm trắng hay nhâm nhi tụ họp cùng bạn bè cũng rất hao.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/04/24/Thnhphm11-1650795306-4940-1650795412.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=8BHS50ZfswClXhrSL1Fagg', 17, 18, 'MEDIUM', 'Cùng thử nấu Bí quyết làm lạc rang tỏi ớt để lâu vẫn giòn');
INSERT INTO public.post VALUES (623, '2025-11-20 17:11:58.84977', '2025-11-20 17:11:58.84977', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 625, 'Miến ''ma thuật'' đổi màu: Món ngon lạ cuối tuần', 'Bạn sẽ cảm giác ''phiêu'' và chơi cùng món ăn đầy thú vị, tươi mát mà nguyên liệu lại rất gần gũi này.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2020/11/13/mien2-1605259676-2280-1605259897.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=TkTJrWHqWBLEqIAx4grbxA', 0, 0, 'HARD', 'Cùng thử nấu Miến ''ma thuật'' đổi màu: Món ngon lạ cuối tuần');
INSERT INTO public.post VALUES (624, '2025-11-20 17:11:59.289146', '2025-11-20 17:11:59.289146', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 626, 'Hướng dẫn nấu Phở gà Hà Nội đơn giản ngay tại nhà', 'Một tô phở gà nóng hổi, nước dùng ngọt thanh, thịt gà vàng nhẹ, điểm xuyết lá chanh thái nhỏ... nhanh chóng xua tan giá rét.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/01/15/pho1-1610692656-2291-1610693117.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=nTN85xw2x3Vntk16OyVGLQ', 0, 0, 'HARD', 'Cùng thử nấu Hướng dẫn nấu Phở gà Hà Nội đơn giản ngay tại nhà');
INSERT INTO public.post VALUES (625, '2025-11-20 17:11:59.564358', '2025-11-20 17:11:59.564358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 627, 'Cách làm gà nướng mật ong đúng chuẩn nhà hàng', 'Thịt gà ta khi nướng với mật ong sẽ chín mềm vừa phải; da giòn, thơm; màu sắc bắt mắt; ngon hơn khi dùng nóng.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2020/09/21/118540771-3590916234260493-577-1499-5412-1600660257.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9uer1uKJsdczGfQJopegTg', 0, 0, 'EASY', 'Cùng thử nấu Cách làm gà nướng mật ong đúng chuẩn nhà hàng');
INSERT INTO public.post VALUES (633, '2025-11-20 17:12:01.14134', '2025-11-20 17:12:01.14134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 635, 'Cách làm Giả cầy miền Tây dậy mùi thơm béo ngậy', 'Khác với giả cầy miền Bắc thoảng vị chua, màu vàng sậm hay giả cầy miền Trung đượm vị ngọt, giả cầy miền Tây lại dậy mùi thơm béo ngậy từ chao.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2022/08/18/Thnhphm1-1660810110-2126-1660810238.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=l5kNsfs6SjeOcoeZEDGDqg', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm Giả cầy miền Tây dậy mùi thơm béo ngậy');
INSERT INTO public.post VALUES (638, '2025-11-20 17:12:02.148265', '2025-11-20 17:12:02.148265', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 640, 'Cách làm chả ốc Tây Hồ ngọt bùi, sần sật và béo thơm vị ốc', 'Từng miếng chả ốc giòn sần sật, hương vị đặc trưng. Khi ăn chấm nước mắm gừng cay cay khiến mọi giác quan thức dậy.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/05/12/Thnhphm1-1652347612-5961-1652347643.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5Odxs6Htonwwytm2yA7L1w', 27, 28, 'HARD', 'Cùng thử nấu Cách làm chả ốc Tây Hồ ngọt bùi, sần sật và béo thơm vị ốc');
INSERT INTO public.post VALUES (639, '2025-11-20 17:12:02.417348', '2025-11-20 17:12:02.417348', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 641, 'Cách làm nem thính chuẩn vị Thái Bình', 'Nem thịt vừa chín vừa độ ngọt thơm quyện bì sần sật, thêm mỡ béo mà không khô, dậy mùi thơm của thính chấm nước mắm chua ngọt rất hấp dẫn.', 'Thái Bình', 'https://i1-giadinh.vnecdn.net/2022/02/11/Bc111-1644563971-5219-1644564171.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=fKMLtg9iWbFyFsL2bAXP_Q', 60, 60, 'MEDIUM', 'Cùng thử nấu Cách làm nem thính chuẩn vị Thái Bình');
INSERT INTO public.post VALUES (640, '2025-11-20 17:12:02.704929', '2025-11-20 17:12:02.704929', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 642, 'Cách làm bánh nghệ Thái Bình', 'Có vị dẻo bùi tự gạo tẻ nóng hổi quyện với sắc vàng tươi từ nghệ, vị béo ngậy của thịt mỡ... bánh nghệ là món dễ gây nghiện cho nhiều người.', 'Thái Bình', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/12/cach-lam-banh-nghe-thai-binh-1620813247.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=RIqKhoL5l1ZvqSFDOMmBqA', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm bánh nghệ Thái Bình');
INSERT INTO public.post VALUES (648, '2025-11-20 17:12:05.021205', '2025-11-20 17:12:05.021205', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 650, 'Chẻo lạc - món ngon dân dã miền Tây xứ Nghệ', 'Chẻo lạc sánh vàng, béo bùi, vị mặn - ngọt đậm đà, dậy mùi thơm của sả. Món này ăn cùng xôi, hoặc chấm chuối xanh, rau sống rất ngon.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/08/27/monla-1630054857-4476-1630054869.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EMCNXgoAYZeHKHjiHuz1GA', 22, 23, 'MEDIUM', 'Cùng thử nấu Chẻo lạc - món ngon dân dã miền Tây xứ Nghệ');
INSERT INTO public.post VALUES (653, '2025-11-20 17:12:06.134538', '2025-11-20 17:12:06.134538', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 655, 'Cách làm sữa hạt sen không cần máy', 'Vào mùa, hạt sen rất rẻ, giá trị dinh dưỡng mang lại cao nên mọi người thường mua nhiều và trữ đông để dùng dần. Ngoài nấu hầm cháo, nấu chè, thì hạt sen còn được lựa chọn để làm sữa.', 'Huế', 'https://i1-giadinh.vnecdn.net/2023/08/03/1jpg-1691053575-1691053591-8937-1691053688.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VqA619ZkVeZYIPX46KhHUA', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm sữa hạt sen không cần máy');
INSERT INTO public.post VALUES (654, '2025-11-20 17:12:06.300985', '2025-11-20 17:12:06.300985', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 656, 'Cách làm chè nhãn lồng hạt sen kiểu Hà Nội xưa', 'Từng trái nhãn mọng nước, bọc hạt sen bên trong bùi bùi, nước chè ngọt thanh. Đây là món để giải khát ngày hè của người Hà Nội xưa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2023/08/01/anhdaidien-1690872134-8234-1690872376.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=tLVKo9hNVSlONJglmBdL0g', 25, 25, 'EASY', 'Cùng thử nấu Cách làm chè nhãn lồng hạt sen kiểu Hà Nội xưa');
INSERT INTO public.post VALUES (655, '2025-11-20 17:12:06.484245', '2025-11-20 17:12:06.484245', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 657, 'Cách làm siro mận giải khát ngày hè', 'Mận đang vào chính vụ, khá nhiều và rẻ nên với cách làm đơn giản, bạn sẽ có ô mai mận dẻo và siro mận óng đỏ, làm đồ uống giải khát hiệu quả ngày hè.', 'Lào Cai', 'https://i1-giadinh.vnecdn.net/2023/06/05/Bc77-1685953457-4030-1685953466.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Q65kE0zOB54gEfTTEtPuNg', 27, 28, 'EASY', 'Cùng thử nấu Cách làm siro mận giải khát ngày hè');
INSERT INTO public.post VALUES (663, '2025-11-20 17:12:08.197243', '2025-11-20 17:12:08.197243', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 665, 'Thơm ngon sữa đậu nành tự chế', 'Sữa đậu nành có giá trị dinh dưỡng cao nhưng rất dễ chế biến. Hướng dẫn của chuyên gia Rosa dưới đây sẽ giúp bạn làm món sữa này.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/26/suadaunanh-1635221402-2499-1635221406.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=B34KpXq0L7gNCnQzCQoRUA', 0, 0, 'EASY', 'Cùng thử nấu Thơm ngon sữa đậu nành tự chế');
INSERT INTO public.post VALUES (668, '2025-11-20 17:12:09.266726', '2025-11-20 17:12:09.266726', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 670, 'Cách làm trà tắc giải khát với công thức đơn giản ngay tại nhà', 'Trà tắc (trái quất) luôn là ''siêu phẩm'' giải khát trong mùa hè được nhiều bạn trẻ yêu thích.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/05/04/Bc44-1651654668-6311-1651654805.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=On5D1RzDQT_jjcXC2UO6GA', 10, 10, 'MEDIUM', 'Cùng thử nấu Cách làm trà tắc giải khát với công thức đơn giản ngay tại nhà');
INSERT INTO public.post VALUES (626, '2025-11-20 17:11:59.702289', '2025-11-20 17:11:59.702289', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 628, 'Cách làm vịt nấu giả cầy chuẩn vị Bắc', 'Thịt vịt mềm mà không bở, nước sóng sánh màu vàng mơ, vị chua thanh từ mẻ, đậm đà từ mắm tôm, dậy mùi thơm của riềng kích thích vị giác. Món này ăn cùng cơm trắng hay bún đều đưa miệng.', 'Bắc Ninh', 'https://i1-giadinh.vnecdn.net/2023/02/24/Thnhphm11-1677217140-6735-1677217170.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=FfoUJ37QUL1WNXAR5bEJLg', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm vịt nấu giả cầy chuẩn vị Bắc');
INSERT INTO public.post VALUES (630, '2025-11-20 17:12:00.692411', '2025-11-20 17:12:00.692411', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 632, 'Cách nấu mì Quảng gà đậm vị tại nhà', 'Đây là món ăn đặc trưng ẩm thực của người dân Quảng Nam - Đà Nẵng.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2022/10/07/-1238-1665132014.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=iSjcWkw3oPKDCzfgB3MXYg', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách nấu mì Quảng gà đậm vị tại nhà');
INSERT INTO public.post VALUES (634, '2025-11-20 17:12:01.288922', '2025-11-20 17:12:01.288922', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 636, 'Cách làm Cá linh kho lạt - đặc sản mùa nước nổi miền Tây', 'Thịt cá mềm béo, nước dừa tươi ngọt thanh quyện với vị chua nhẹ từ me, ăn cùng bông điên điển đậm hương đồng cỏ nội miền Tây.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2022/08/23/Thnhphm11-1661240688-7894-1661240794.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=XYXW-MCJn08joVcZ_oE9NA', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm Cá linh kho lạt - đặc sản mùa nước nổi miền Tây');
INSERT INTO public.post VALUES (641, '2025-11-20 17:12:03.125567', '2025-11-20 17:12:03.125567', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 643, 'Công thức và cách làm bánh Katka Hải Phòng dễ thực hiện, đảm bảo thành công', 'Bánh Katka Hải Phòng thực chất là món bánh bông lan bơ (pound cake) nhưng "gây thương nhớ" không chỉ người dân mà cho cả du khách đến thăm thành phố này.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2020/07/05/katka4-1593885333-4950-1593885601.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=IJF2mB7Jqay9_E-FRJzE5Q', 30, 30, 'MEDIUM', 'Cùng thử nấu Công thức và cách làm bánh Katka Hải Phòng dễ thực hiện, đảm bảo thành công');
INSERT INTO public.post VALUES (645, '2025-11-20 17:12:04.360231', '2025-11-20 17:12:04.360231', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 647, 'Gỏi bưởi Biên Hòa', 'Món gỏi có vị chua ngọt của bưởi, thơm của mè, hành phi, ngọt đậm của tôm, thịt.', 'Biên Hòa, Đồng Nai', 'https://i1-giadinh.vnecdn.net/2021/10/09/GoiBuoiTanTrieu02-1633777017-3350-1633777142.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=iJmlqmXa57Yf9Ozt3UbQSA', 0, 0, 'MEDIUM', 'Cùng thử nấu Gỏi bưởi Biên Hòa');
INSERT INTO public.post VALUES (649, '2025-11-20 17:12:05.178049', '2025-11-20 17:12:05.178049', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 651, 'Cách làm bánh bèo Nghệ An đơn giản tại nhà', 'Vỏ bánh dẻo trong, nhân tôm thịt ngọt thơm, chan ngập nước mắm chua cay mặn ngọt hài hòa làm nên món ăn vặt hấp dẫn trong thời kỳ giãn cách.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/08/12/banhbeo-1628742059-7704-1628742129.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=076Wzlv1eTGY5XT1fizrMA', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm bánh bèo Nghệ An đơn giản tại nhà');
INSERT INTO public.post VALUES (656, '2025-11-20 17:12:06.623237', '2025-11-20 17:12:06.623237', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 658, 'Cách làm nước tía tô, vải ngâm giải nhiệt', 'Một ly trà tía tô, vải ngâm với màu đỏ bắt mắt, vị chua ngọt hài hòa, topping vải ngâm giòn giọt, thanh mát. Đồ uống này vừa giúp giải nhiệt, trị cảm, trị nám, làm đẹp vừa cải thiện tiêu hóa hiệu quả.', 'Bắc Giang', 'https://i1-giadinh.vnecdn.net/2023/06/10/Bc6Thnhphm6-1686385782-5706-1686385806.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=i77pvPpXzy-c1h_ULYq1rA', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm nước tía tô, vải ngâm giải nhiệt');
INSERT INTO public.post VALUES (660, '2025-11-20 17:12:07.680755', '2025-11-20 17:12:07.680755', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 662, 'Cách làm vải ngâm đường phèn để quanh năm', 'Thịt vải giòn giọt mà không gắt, thanh mát. Từ vải ngâm, chế biến được nhiều món giải khát thơm ngon như trà vải truyền thống, trà mận vải, trà vải hoa đậu biếc, trà thạch vải...', 'Bắc Giang', 'https://i1-giadinh.vnecdn.net/2022/07/06/Thnhphm11-1657098445-3332-1657098449.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=DS8JPgKdSHKjMXZ75UjtOw', 25, 25, 'EASY', 'Cùng thử nấu Cách làm vải ngâm đường phèn để quanh năm');
INSERT INTO public.post VALUES (664, '2025-11-20 17:12:08.401161', '2025-11-20 17:12:08.401161', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 666, 'Sinh tố khoai môn', 'Sinh tố khoai môn rất thơm ngon và bỗ dưỡng. Bạn cũng không phải mất nhiều thời gian để làm món này.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2021/10/15/sinhtokhoaimon20210728153052at-5823-5657-1634297744.gif?w=0&h=0&q=100&dpr=2&fit=crop&s=juah17MjJV_rCAQp3z3EoQ&t=image', 0, 0, 'EASY', 'Cùng thử nấu Sinh tố khoai môn');
INSERT INTO public.post VALUES (671, '2025-11-20 17:12:09.936059', '2025-11-20 17:12:09.936059', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 673, 'Tự làm chè chuối', 'Bằng các nguyên liệu dễ tìm, bạn có thể chế ngay món chè ngon này cho người thân trong những ngày ấm áp.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/11/04/chchuoi-1635999154-4206-1635999168.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=cVoMsUgF4lx5aFyMdjIe6Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Tự làm chè chuối');
INSERT INTO public.post VALUES (675, '2025-11-20 17:12:10.818798', '2025-11-20 17:12:10.818798', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 677, 'Cocktail hoa quả tươi', 'Rượu vang trắng kết hợp với các loại quả tươi mọng nước sẽ cho bạn cảm giác mát lạnh và sảng khoái. Bạn hãy làm ngay cocktail hoa quả tươi để cả nhà thưởng thức nhé.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/19/cooktai-1634618494-1793-1634618607.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=IsMplWtuSprqdU2QoZ1KKQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Cocktail hoa quả tươi');
INSERT INTO public.post VALUES (679, '2025-11-20 17:12:11.814415', '2025-11-20 17:12:11.814415', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 681, 'Thạch trái cam mát lạnh', 'Hương vị mùa hè thơm mát tỏa ra từ những miếng thạch trái cây vàng rực rỡ. Mời bạn trổ tài và thưởng thức.', 'Vĩnh Long', 'https://i1-giadinh.vnecdn.net/2021/09/10/Thachtraicam-1631266847-2884-1631266924.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gkuVu9J_0Y0l70WQm0LQOg', 0, 0, 'EASY', 'Cùng thử nấu Thạch trái cam mát lạnh');
INSERT INTO public.post VALUES (686, '2025-11-20 17:12:13.852887', '2025-11-20 17:12:13.852887', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 688, 'Chè bưởi', 'Món chè bưởi thơm ngon do chính tay bạn làm sẽ khiến cả nhà bất ngờ.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/26/chebuoi-1635241230-2905-1635241277.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=oA2r6cQUMZUe8N40foldrQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Chè bưởi');
INSERT INTO public.post VALUES (690, '2025-11-20 17:12:15.086424', '2025-11-20 17:12:15.086424', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 692, 'Cách làm hồng trà sữa đơn giản tại nhà', 'Hồng trà sữa nổi bật hương vị đặc trưng của trà, quyện với vị ngọt béo của sữa, chút dai mềm của trân châu hấp dẫn như ngoài tiệm.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/09/17/trasua-1631877552-5110-1631877591.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gunMgvvGet_q3wpsPfU1cA', 25, 25, 'EASY', 'Cùng thử nấu Cách làm hồng trà sữa đơn giản tại nhà');
INSERT INTO public.post VALUES (627, '2025-11-20 17:11:59.964903', '2025-11-20 17:11:59.964903', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 629, 'Cách làm chả cá Hà Nội hương vị xưa', 'Món ăn Hà thành được CNN ca ngợi là một trong những món Việt ngon nhất thế giới và từng được đưa vào cuốn sách "1.000 nơi nên biết trước khi chết".', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2023/02/23/Bc9Thnhphm9-1677138455-9744-1677138711.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=U7uDXu87vxtbAQErDdBwcQ', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm chả cá Hà Nội hương vị xưa');
INSERT INTO public.post VALUES (628, '2025-11-20 17:12:00.227156', '2025-11-20 17:12:00.227156', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 630, 'Cách làm xáo lòng bánh mướt - đặc sản xứ Nghệ', 'Gắp miếng bánh mướt trắng muốt chấm đẫm bát xáo lòng với tiết đậm vị, nước dùng màu huyết dụ, ngọt tự nhiên, chút the cay nhanh chóng xua tan cái lạnh đầu đông.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2022/10/28/-2509-1666941814.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=rTIDyzriTSoDR5tW6Fk63A', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm xáo lòng bánh mướt - đặc sản xứ Nghệ');
INSERT INTO public.post VALUES (629, '2025-11-20 17:12:00.366301', '2025-11-20 17:12:00.366301', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 631, 'Cách làm món cá rô kho tộ kiểu Nam bộ', 'Vào mùa mưa tháng 9, cá rô đồng béo tròn, thịt thơm. Món cá rô kho tộ luôn đưa cơm bởi đậm vị mặn ngọt cay.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2022/09/14/-7458-1663147518.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=PjZgiALRG0Sam8lTEnMqBQ', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm món cá rô kho tộ kiểu Nam bộ');
INSERT INTO public.post VALUES (632, '2025-11-20 17:12:00.981234', '2025-11-20 17:12:00.981234', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 634, 'Cách làm cơm chiên lá é - đặc sản Nha Trang', 'Cơm chiên màu xanh bắt mắt, tơi hạt, dậy mùi thơm đặc trưng của lá é, chút the cay từ ớt xiêm khiến ai một lần thưởng thức đều lưu luyến.', 'Nha Trang, Khánh Hòa', 'https://i1-giadinh.vnecdn.net/2022/09/13/-9952-1663058196.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uFEp9Qfxij45t2SypF-K8w', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm cơm chiên lá é - đặc sản Nha Trang');
INSERT INTO public.post VALUES (635, '2025-11-20 17:12:01.599055', '2025-11-20 17:12:01.599055', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 637, 'Canh bầu nấu hến', 'Bầu nấu hến là một trong những món canh đặc sản của xứ Huế với vị ngọt của nước hến, vị cay thơm của ớt màu, hòa lẫn với mùi thơm của hành ngò, tiêu xay.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/13/canhbau-1634096619-1238-1634096793.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=sbbTS4Q79P57tBbowRNaFw', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh bầu nấu hến');
INSERT INTO public.post VALUES (642, '2025-11-20 17:12:03.418789', '2025-11-20 17:12:03.418789', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 644, 'Bánh canh giò heo', 'Bánh canh giò heo là món ăn ngon rất đặc trưng ở miền Tây Nam bộ.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2021/10/09/thumbcmscn1200x6764-1633776890-8038-1633776949.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=xLsM4L8BTyw7D8MG3E7ehg', 0, 0, 'MEDIUM', 'Cùng thử nấu Bánh canh giò heo');
INSERT INTO public.post VALUES (643, '2025-11-20 17:12:03.666376', '2025-11-20 17:12:03.666376', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 645, 'Canh chua cá Nam bộ', 'Món canh chua cay nấu theo kiểu miền trong, với vị ngọt mặn, cay và mùi thơm nổi bật của rau ngổ sẽ khiến cả gia đình bạn khen ngon trong những ngày nóng nực này.', 'Tiền Giang', 'https://i1-giadinh.vnecdn.net/2021/10/09/canhchua-1633752004-6896-1633752039.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=X6Y1C_4VhBGwa4b2JmoM0A', 0, 0, 'HARD', 'Cùng thử nấu Canh chua cá Nam bộ');
INSERT INTO public.post VALUES (644, '2025-11-20 17:12:03.86481', '2025-11-20 17:12:03.86481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 646, 'Cá bạc má kho mật mía kiểu xứ Nghệ', 'Thịt cá săn chắc, đẫm trong nước sốt keo lại vị mặn ngọt cay rất ''''đưa cơm'''' trong ngày nắng.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/08/27/anhca-1630053418-4330-1630053483.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=RudGabpCQX60EMsAhmCxvQ', 30, 30, 'MEDIUM', 'Cùng thử nấu Cá bạc má kho mật mía kiểu xứ Nghệ');
INSERT INTO public.post VALUES (647, '2025-11-20 17:12:04.760168', '2025-11-20 17:12:04.760168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 649, 'Phá lấu là gì? Cách làm Phá lấu lòng bò giòn, thơm, hương vị nồng ấm', 'Đây là món ăn có nguồn gốc Trung Quốc, du nhập vào Việt Nam và trở thành món ăn đường phố được người Sài Gòn ưa chuộng.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/07/02/4298511-1625216834-4586-1625216838.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=1RZ-zrB9Jz9bL4nQLNkhEg', 60, 60, 'MEDIUM', 'Cùng thử nấu Phá lấu là gì? Cách làm Phá lấu lòng bò giòn, thơm, hương vị nồng ấm');
INSERT INTO public.post VALUES (650, '2025-11-20 17:12:05.361797', '2025-11-20 17:12:05.361797', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 652, 'Cách làm nước tía tô vừa giải nhiệt ngày hè vừa đẹp da', 'Nước tía tô không chỉ có tác dụng giải cảm, thanh nhiệt mà còn giúp đẹp da, trị nám, mụn, chống lão hóa, chữa mề đay, dạ dày, người bị bệnh gout, nhuận tràng...', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/06/13/Bc44-1655100739-8491-1655100842.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=vtptfj73GhKUoRQFzY48Wg', 7, 8, 'EASY', 'Cùng thử nấu Cách làm nước tía tô vừa giải nhiệt ngày hè vừa đẹp da');
INSERT INTO public.post VALUES (657, '2025-11-20 17:12:06.861558', '2025-11-20 17:12:06.861558', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 659, 'Bốn loại bánh ngọt ngào mát lạnh', 'Sau bữa ăn, một chiếc bánh lạnh giúp cân bằng vị giác. Bạn thử trổ tài với bốn kiểu bánh thật lạ và dễ làm dưới đây, chắc cả nhà sẽ phải trầm trồ.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/11/04/raucau-1635998728-9497-1635998843.png?w=0&h=0&q=100&dpr=2&fit=crop&s=CNk5wnmHpOZX8pyCxqBhtg', 0, 0, 'MEDIUM', 'Cùng thử nấu Bốn loại bánh ngọt ngào mát lạnh');
INSERT INTO public.post VALUES (658, '2025-11-20 17:12:07.155467', '2025-11-20 17:12:07.155467', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 660, 'Cách nấu chè đỗ đen kiểu Hà Nội', 'Hạt đậu mềm bùi, đượm vị ngọt kết hợp trân châu mềm dẻo sần sật, thạch đen mát lành, tinh dầu chuối thơm rất hấp dẫn. Đây là món ăn giải nhiệt ngày hè truyền thống của người Hà thành.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/07/15/Thnhphm11-1657866442-7335-1657866566.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=u5JkUTFGXN-m4afsjy7-yg', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách nấu chè đỗ đen kiểu Hà Nội');
INSERT INTO public.post VALUES (659, '2025-11-20 17:12:07.555948', '2025-11-20 17:12:07.555948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 661, 'Cách làm đào ngâm, trà đào cam sả giải nhiệt ngày hè', 'Từng miếng đào giòn ngon, nước trà thoảng vị đặc trưng từ đào, sả, màu ánh nâu đỏ đẹp mắt. Đây là thức uống mát lành, dễ làm để dùng dần hàng tháng.', 'Sơn La', 'https://i1-giadinh.vnecdn.net/2022/07/26/Bc7Trocams1-1658823424-9856-1658823435.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=3rLuoJawDRMkRJdKKGm5nQ', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm đào ngâm, trà đào cam sả giải nhiệt ngày hè');
INSERT INTO public.post VALUES (662, '2025-11-20 17:12:07.971055', '2025-11-20 17:12:07.971055', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 664, 'Sinh tố từ rau quả', 'Ngon, có lợi cho sức khỏe là công dụng của các loại thức uống dưới đây. Bạn hãy bắt tay vào làm để cùng thưởng thức nhé.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/26/sinhto-1635221904-5141-1635221922.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Nr6g2AvQpXisXACBfGqKlg', 0, 0, 'MEDIUM', 'Cùng thử nấu Sinh tố từ rau quả');
INSERT INTO public.post VALUES (631, '2025-11-20 17:12:00.861887', '2025-11-20 17:12:00.861887', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 633, 'Cách làm món ốc hấp lá gừng - cỗ mặn trông trăng Hà Nội xưa', 'Ăn ốc ngắm trăng là một trong những nét văn hóa ẩm thực của người Hà thành xưa. Tuy nhiên, cách làm món này cũng khá cầu kỳ, không nhiều người còn biết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/09/05/Thnhphm1-1662371338-9626-1662371451.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_JQ0IAJR6VithKFuqDr0uQ', 42, 43, 'MEDIUM', 'Cùng thử nấu Cách làm món ốc hấp lá gừng - cỗ mặn trông trăng Hà Nội xưa');
INSERT INTO public.post VALUES (646, '2025-11-20 17:12:04.508979', '2025-11-20 17:12:04.508979', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 648, 'Vả trộn tôm thịt', 'Đây là món ăn đặc trưng của người Huế với nguyên liệu chính là trái vả (cùng họ với sung nhưng lớn hơn). Món ăn này có ưu điểm là không ngán, ít chất béo nên rất thích hợp trong ngày Tết.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/02/va-1633145669-6790-1633145705.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=lj40KOLcw7b4bxnDasd3Og', 0, 0, 'EASY', 'Cùng thử nấu Vả trộn tôm thịt');
INSERT INTO public.post VALUES (661, '2025-11-20 17:12:07.881175', '2025-11-20 17:12:07.881175', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 663, 'Chè sữa chua nếp cẩm', 'Vị dẻo thơm của nếp cẩm, ngọt ngào man mát của lá nếp trộn lẫn với vị béo bùi của sữa chua sẽ khiến cho cốc chè đậm đà khó quên.', 'Điện Biên', 'https://i1-giadinh.vnecdn.net/2021/10/26/suachua-1635240956-7932-1635241063.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MELPBGnMxDLqA7WOE7ji5w', 0, 0, 'MEDIUM', 'Cùng thử nấu Chè sữa chua nếp cẩm');
INSERT INTO public.post VALUES (676, '2025-11-20 17:12:11.049363', '2025-11-20 17:12:11.049363', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 678, 'Chè ngô cốm', 'Vị bùi, dẻo của ngô, mùi thơm ngậy của cốm và thanh mát của dừa cùng quện lại sẽ cho bạn cảm giác rất đặc biệt khi thưởng thức chè ngô cốm.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/09/11200x67611-1633777472-7824-1633777550.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=HFIV95xaLUbS-9bv1eYIjg', 0, 0, 'EASY', 'Cùng thử nấu Chè ngô cốm');
INSERT INTO public.post VALUES (691, '2025-11-20 17:12:15.226835', '2025-11-20 17:12:15.226835', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 693, 'Chè ngô cốm', 'Bát chè mát lạnh với vị thơm, dẻo của cốm cùng vị ngọt, mát của ngô sẽ vô cùng hấp dẫn trong thời tiết mùa này.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/30/Chengocom-1632938052-3242-1632938065.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=xmMTvmtHn09TLMPRy2MOeQ', 0, 0, 'EASY', 'Cùng thử nấu Chè ngô cốm');
INSERT INTO public.post VALUES (705, '2025-11-20 17:12:19.881627', '2025-11-20 17:12:19.881627', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 707, 'Hướng dẫn làm bánh bò hấp ngon mềm, đơn giản tại nhà', 'Bánh bò có vị ngọt dịu, dai dai hòa quyện với nước cốt dừa beo béo, tất cả tạo nên một món ăn vặt hoàn hảo.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/03/19/banh3-1616127495-1464-1616127907.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=cVy7tZzpy6hXZzSxvB4ffg', 65, 65, 'MEDIUM', 'Cùng thử nấu Hướng dẫn làm bánh bò hấp ngon mềm, đơn giản tại nhà');
INSERT INTO public.post VALUES (720, '2025-11-20 17:12:24.616283', '2025-11-20 17:12:24.616283', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 722, 'Cách làm canh ghẹ nấu rau muống đơn giản, thanh mát', 'Bát canh ghẹ nóng hổi, ghẹ đỏ hồng xen lẫn màu xanh mướt của rau muống, nước canh ngon ngọt tự nhiên, giàu giá trị dinh dưỡng.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/07/09/Canhgheraumuong5-1625836787-7199-1625836922.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qqNPPZkH3ojQ7CK9UtlwiA', 15, 15, 'EASY', 'Cùng thử nấu Cách làm canh ghẹ nấu rau muống đơn giản, thanh mát');
INSERT INTO public.post VALUES (735, '2025-11-20 17:12:29.713672', '2025-11-20 17:12:29.713672', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 737, 'Bí quyết làm ngô chiên bơ giòn thơm', 'Từng hạt ngô vàng ươm, giòn rụm, thơm mùi bơ và cốt dừa, không khác gì ngoài hàng. Món làm đồ nhâm nhi cùng bạn bè rất vừa miệng, nhất là vào ngày mưa gió.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2023/02/04/Thnhphm11-1675483490-1924-1675483496.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kKu0EOn4bmoRdJnJ_dgCXw', 22, 23, 'MEDIUM', 'Cùng thử nấu Bí quyết làm ngô chiên bơ giòn thơm');
INSERT INTO public.post VALUES (750, '2025-11-20 17:12:33.322405', '2025-11-20 17:12:33.322405', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 752, 'Kem Rhum và nho khô', 'Trong những ngày hè oi nóng, bạn thử trổ tài để cả nhà được thưởng thức những ly kem thơm ngon, mát lạnh với hương vị độc đáo được làm từ kem Rhum và nho khô.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/18/Untitled31200x6761-1634550349-5089-1634550456.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=frasouMEZe3rMnokb0L5lw', 0, 0, 'MEDIUM', 'Cùng thử nấu Kem Rhum và nho khô');
INSERT INTO public.post VALUES (765, '2025-11-20 17:12:37.47549', '2025-11-20 17:12:37.47549', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 767, 'Khoai tây chiên bơ - món ngon cho bữa sáng đơn giản', 'Khoai tây chín mềm, dậy mùi bơ và hành tây. Món này có thể dùng cho bữa sáng hoặc làm món ăn vặt đều thích hợp.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/08/02/khoaitaychienbo-1627903280-4666-1627903355.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Iba86PP6R5RUZGoKyJUOLg', 0, 0, 'EASY', 'Cùng thử nấu Khoai tây chiên bơ - món ngon cho bữa sáng đơn giản');
INSERT INTO public.post VALUES (780, '2025-11-20 17:12:41.909308', '2025-11-20 17:12:41.909308', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 782, 'Biến cơm nguội thành bánh phô mai đút lò', 'Bạn có thể tận dụng cơm nguội làm thành cơm phô mai đút lò có hình chiếc bánh, vừa béo vừa thơm mà không tốn công.', 'Hồ Chí Minh', 'https://iv1.vnecdn.net/ngoisao/images/web/2021/06/20/bien-com-nguoi-thanh-banh-pho-mai-dut-lo-1624177833.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=xc-eytcRaAXChA314m_0sw', 15, 15, 'MEDIUM', 'Cùng thử nấu Biến cơm nguội thành bánh phô mai đút lò');
INSERT INTO public.post VALUES (665, '2025-11-20 17:12:08.606985', '2025-11-20 17:12:08.606985', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 667, 'Cách nấu chè đỗ xanh bình dân kiểu Hà Nội xưa', 'Chè đỗ xanh hay còn gọi chè đỗ đãi, chè đánh... là thức quà bình dân vào mùa nóng của người Hà Nội.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/08/22/Bc77-1661154304-1455-1661154462.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=cVwtr4tv5_i--Og2NMk-9A', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách nấu chè đỗ xanh bình dân kiểu Hà Nội xưa');
INSERT INTO public.post VALUES (672, '2025-11-20 17:12:10.01034', '2025-11-20 17:12:10.01034', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 674, 'Rau câu chanh dây', 'Từ quả chanh dây với mùi thơm quyến rũ và vị chua thanh, chúng ta có thể chế biến được nhiều món ngon, trong đó, rau câu chanh dây rất lý tưởng trong dịp hè này.', 'Gia Lai', 'https://i1-giadinh.vnecdn.net/2021/10/07/raucau-1633580450-3435-1633580519.png?w=0&h=0&q=100&dpr=2&fit=crop&s=EplAspdavcr1k2PG5t_Mog', 0, 0, 'EASY', 'Cùng thử nấu Rau câu chanh dây');
INSERT INTO public.post VALUES (677, '2025-11-20 17:12:11.494962', '2025-11-20 17:12:11.494962', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 679, 'Tự làm kem dừa', 'Không quá cầu kỳ như bạn tưởng, chỉ cần có chiếc máy làm kem và khéo tay một chút, bạn có thể làm được các món kem mát lành.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/09/kem-1633775966-2264-1633776072.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gc3FsVB2cWJMWzVeKcOn6Q', 0, 0, 'MEDIUM', 'Cùng thử nấu Tự làm kem dừa');
INSERT INTO public.post VALUES (680, '2025-11-20 17:12:12.158353', '2025-11-20 17:12:12.158353', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 682, 'Bánh ngọt cà rốt', 'Loại bánh dưới đây hấp dẫn từ mùi thơm đến vị ngọt, vị bùi và cả hình thức bắt mắt.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/02/Rueblitorte-1633166229-6222-1633166299.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=nSHgMG6rsRFHXfSmUpPDTQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Bánh ngọt cà rốt');
INSERT INTO public.post VALUES (687, '2025-11-20 17:12:14.204259', '2025-11-20 17:12:14.204259', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 689, 'Cách làm chè nấm tuyết táo đỏ giúp giải nhiệt mùa hè', 'Nấm tuyết được ví như "tổ yến của người nghèo" vì có làm lượng collagen tương đương tổ yến. Nó không chỉ ngon miệng mà còn làm đẹp da, giảm nóng bức và giải độc gan.', 'Lào Cai', 'https://i1-giadinh.vnecdn.net/2021/06/02/2-1622629227-2619-1622629838.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=FSt31fuIAlG_8SiNMiJYCg', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm chè nấm tuyết táo đỏ giúp giải nhiệt mùa hè');
INSERT INTO public.post VALUES (692, '2025-11-20 17:12:15.414881', '2025-11-20 17:12:15.414881', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 694, 'Món sữa trà ''ngược đời'' dễ làm', 'Thay vì làm trà sữa, bạn có thể làm món sữa uống kèm với thạch trà để giải nhiệt trong những ngày hè oi bức.', 'Hồ Chí Minh', 'https://iv1.vnecdn.net/ngoisao/images/web/2021/07/11/mon-sua-tra-nguoc-doi-de-lam-1625982893.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=CiKXvoG9jwB_2obpJuVFIw', 0, 0, 'EASY', 'Cùng thử nấu Món sữa trà ''ngược đời'' dễ làm');
INSERT INTO public.post VALUES (695, '2025-11-20 17:12:16.5058', '2025-11-20 17:12:16.5058', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 697, 'Chè vải nấm tuyết', 'Ngày hè, bạn hãy thưởng thức một bát chè vải nấm tuyết để giúp làm đẹp da cũng như giải nhiệt cơ thể hiệu quả.', 'Bắc Giang', 'https://i1-ngoisao.vnecdn.net/2021/06/20/194221882-827074244612456-2120-4841-4706-1624194678.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=trlpf8jPpBd9MPocxK7bAQ', 0, 0, 'EASY', 'Cùng thử nấu Chè vải nấm tuyết');
INSERT INTO public.post VALUES (701, '2025-11-20 17:12:18.16442', '2025-11-20 17:12:18.16442', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 703, 'Cách làm chè hạt sen long nhãn thanh mát', 'Long nhãn giòn tươi, hạt sen mềm, bùi bùi, nước chè ngọt thanh làm từ đường phèn làm nên món ăn bổ dưỡng vào mùa hè.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2021/08/12/hatsen-1628742593-6051-1628742608.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=4787B6GK8oKoqv4EppSpOA', 22, 23, 'EASY', 'Cùng thử nấu Cách làm chè hạt sen long nhãn thanh mát');
INSERT INTO public.post VALUES (706, '2025-11-20 17:12:20.448703', '2025-11-20 17:12:20.448703', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 708, 'Công thức làm bánh táo nướng - Món ăn nhẹ không thể bò qua', 'Bánh táo nướng là món đồ ăn nhẹ thơm ngon, dễ làm. Chỉ cần mất chút thời gian là có thể hoàn thành món ngon này.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/03/10/banh5-1615348690-4127-1615349138.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=sni3it_-dazSeNtsJYvx6g', 0, 0, 'HARD', 'Cùng thử nấu Công thức làm bánh táo nướng - Món ăn nhẹ không thể bò qua');
INSERT INTO public.post VALUES (709, '2025-11-20 17:12:21.693252', '2025-11-20 17:12:21.693252', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 711, 'Cách nấu bầu xào trứng - món đơn giản mà đưa cơm ngày hè', 'Bầu giòn, thanh mát quyện với trừng bùi bùi, dậy mùi thơm của hành lá, tỏi. Món ăn làm phong phú thực đơn ngày hè.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/07/21/Thnhphm22-1658390932-8201-1658390935.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ZPsxSiqBkccWzRYGvd52Gg', 7, 8, 'MEDIUM', 'Cùng thử nấu Cách nấu bầu xào trứng - món đơn giản mà đưa cơm ngày hè');
INSERT INTO public.post VALUES (716, '2025-11-20 17:12:23.703063', '2025-11-20 17:12:23.703063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 718, 'Kimbap cá thu sốt mayonnaise', 'Kimbap cá thu chấm mayonnaise là gợi ý cho những buổi trưa hè nóng nực ngán cơm, cách làm đơn giản nhưng khá đủ chất.', 'Hồ Chí Minh', 'https://i1-ngoisao.vnecdn.net/2021/06/28/201375487-499079661206980-5614-1235-5429-1624867976.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=rvtgy9CIUW47HE0T7o90Pg', 0, 0, 'MEDIUM', 'Cùng thử nấu Kimbap cá thu sốt mayonnaise');
INSERT INTO public.post VALUES (721, '2025-11-20 17:12:24.94621', '2025-11-20 17:12:24.94621', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 723, 'Cách làm nem cá rô giòn, ngon đổi vị ngày hè', 'Nem cá rô có vỏ vàng ruộm, giòn tan, nhân nem với cá mềm ngọt quyện chút béo ngậy của thịt và tôm, nhân không bị khô, dậy mùi thơm của thì là.', 'Hải Dương', 'https://iv1.vnecdn.net/giadinh/images/web/2021/06/12/cach-lam-nem-ca-ro-doi-vi-ngay-he-1623484348.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=hrBHvI90N7G53fz9cUeecg', 35, 35, 'MEDIUM', 'Cùng thử nấu Cách làm nem cá rô giòn, ngon đổi vị ngày hè');
INSERT INTO public.post VALUES (724, '2025-11-20 17:12:25.541174', '2025-11-20 17:12:25.541174', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 726, 'Cách làm Tép đồng rang khế - món ngon cho ngày hè nóng nực', 'Tép đồng rang khế là món giàu giá trị dinh dưỡng, đặc biệt là canxi, trong 100gr tép đồng cung cấp 910 mg canxi.', 'An Giang', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/21/cach-lam-tep-dong-rang-khe-hao-com-1621563696.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=PwMzfnsWdF1SLNW2RhuYuQ', 17, 18, 'EASY', 'Cùng thử nấu Cách làm Tép đồng rang khế - món ngon cho ngày hè nóng nực');
INSERT INTO public.post VALUES (731, '2025-11-20 17:12:28.552643', '2025-11-20 17:12:28.552643', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 733, 'Cách làm khoai lang ngào đường kiểu Nhật nhâm nhi cùng người thân', 'Vỏ khoai giòn vàng, bám sốt caramel đều, ánh lên màu hổ phách đẹp mắt, vị mặn ngọt hài hòa. Đây là món ăn được nhiều bạn trẻ xứ hoa anh đào yêu thích.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2022/05/21/Thnhphm1-1653126458-1483-1653126539.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=k2oVu3ubcHSUHn_LGZNK9Q', 22, 23, 'EASY', 'Cùng thử nấu Cách làm khoai lang ngào đường kiểu Nhật nhâm nhi cùng người thân');
INSERT INTO public.post VALUES (669, '2025-11-20 17:12:09.486561', '2025-11-20 17:12:09.486561', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 671, 'Tự làm chanh muối', 'Tuy có hơi mất thời gian, nhưng bạn sẽ hoàn toàn yên tâm về chất lượng của loại nước giải khát hữu hiệu trong mùa hè nóng bức này.', 'Ninh Thuận', 'https://i1-giadinh.vnecdn.net/2021/11/22/chanhmuoi-1637551727-1594-1637551731.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=023wEPRRYs0aWxeqx4N3pg', 0, 0, 'EASY', 'Cùng thử nấu Tự làm chanh muối');
INSERT INTO public.post VALUES (684, '2025-11-20 17:12:13.316808', '2025-11-20 17:12:13.316808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 686, 'Chè tuyết yến bát vị', 'Chè tuyết yến bát vị thơm lừng mùi của thảo mộc, vị ngọt thanh mát hoà quyện cùng các nguyên liệu thảo dược, rất tốt với sức khoẻ.', 'Huế', 'https://i1-ngoisao.vnecdn.net/2021/06/23/200099611-508229017184219-4799-9470-5406-1624434475.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=thRff5OrFHFbks_DAcSjEA', 0, 0, 'MEDIUM', 'Cùng thử nấu Chè tuyết yến bát vị');
INSERT INTO public.post VALUES (713, '2025-11-20 17:12:22.505915', '2025-11-20 17:12:22.505915', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 715, 'Canh hẹ thịt băm, đậu hũ', 'Lá hẹ với mùi thơm rất riêng không lẫn với hành, tỏi vừa làm rau gia vị vừa có thể là nguyên liệu chính của món ăn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/12/canhhethitbamthumbnail-1634030-7643-9281-1634030571.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=eFQpLZr8hcTNrFVaH5dHjQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Canh hẹ thịt băm, đậu hũ');
INSERT INTO public.post VALUES (728, '2025-11-20 17:12:27.070677', '2025-11-20 17:12:27.070677', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 730, 'Cách làm Gỏi bò bóp thấu chua ngọt, đậm đà', 'Khác với các món gỏi (nộm) thông thường, món gỏi bò bóp thấu có vị cay nóng của ớt và mùi thơm nồng tiết ra từ lá húng quế được bóp nhẹ.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2021/03/10/1-1615376668-7765-1615376985.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=yVjeatXC9Fe9jmsEC39kKQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm Gỏi bò bóp thấu chua ngọt, đậm đà');
INSERT INTO public.post VALUES (743, '2025-11-20 17:12:31.786637', '2025-11-20 17:12:31.786637', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 745, 'Sắn hấp nước cốt dừa - quà vặt chiều đông', 'Sắn mềm bở, quyện trong nước cốt dừa béo ngậy, lạc rang bùi bùi quyến rũ bao tín đồ ăn vặt Hà thành vào chiều đông.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/12/24/Thnhphm1-1640337680-2558-1640337747.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=wI-Z9bYYHOwoRKTo6n2d_A', 25, 25, 'MEDIUM', 'Cùng thử nấu Sắn hấp nước cốt dừa - quà vặt chiều đông');
INSERT INTO public.post VALUES (758, '2025-11-20 17:12:35.693509', '2025-11-20 17:12:35.693509', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 760, 'Chè trôi nước nhân tôm thịt', 'Không cần đặt chân đến Huế, bạn vẫn có thể trổ tài để cả nhà được thưởng thứcmón chè trôi nước nhân tôm thịt.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/10/18/12601200x67633-1634549156-6315-1634549391.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=LSXpXMP7xYlmGZ7foNSeEQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Chè trôi nước nhân tôm thịt');
INSERT INTO public.post VALUES (773, '2025-11-20 17:12:40.081592', '2025-11-20 17:12:40.081592', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 775, 'Bún mọc', 'Bạn có thể chọn món ăn nhẹ nhàng, hấp dẫn này cho ngày cuối tuần của gia đình mà không quá tốn thời gian.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/12/1200pxBunMocHaNoi-1634027758-2978-1634027980.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_Lv-S6fbE05AVRez5JI_3g', 0, 0, 'HARD', 'Cùng thử nấu Bún mọc');
INSERT INTO public.post VALUES (788, '2025-11-20 17:12:46.078868', '2025-11-20 17:12:46.078868', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 790, 'Cách làm bánh gối từ A tới Z tại nhà', 'Bánh có lớp vỏ vàng ruộm, giòn tan, phần nhân đầy đặn trứng, thịt, mộc nhĩ mềm, vừa vị, chấm nước mắm chua ngọt rất hấp dẫn.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/08/06/nh2-1628235250-5746-1628235416.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Im-aKuLY6zqMQ-_UeuxWlw', 45, 45, 'HARD', 'Cùng thử nấu Cách làm bánh gối từ A tới Z tại nhà');
INSERT INTO public.post VALUES (670, '2025-11-20 17:12:09.720976', '2025-11-20 17:12:09.720976', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 672, 'Chè bưởi', 'Từ tháng 8 âm lịch là mùa bưởi rộ. Chỉ cần một chút khéo tay, một chút kiên nhẫn, bạn có thể tận dụng vỏ bưởi để làm món chè bưởi thơm ngon đãi cả nhà.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/14/Untitled21200x67611-1634185301-7945-1634185481.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=sMlBnSZaEixQrUP-FZZUtw', 0, 0, 'MEDIUM', 'Cùng thử nấu Chè bưởi');
INSERT INTO public.post VALUES (685, '2025-11-20 17:12:13.433159', '2025-11-20 17:12:13.433159', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 687, 'Kem dâu', 'Ngoài sinh tố dâu, nước ép dâu, yaourt dâu... một món làm từ dâu rất ngon và có sức hấp dẫn đặc biệt với các bé và chị em là kem dâu. Mời bạn tham khảo cách làm dưới đây.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/07/kemdau-1633577762-1199-1633577882.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=W3XU2lQ0Fy-o4yC_x83PhA', 0, 0, 'EASY', 'Cùng thử nấu Kem dâu');
INSERT INTO public.post VALUES (699, '2025-11-20 17:12:17.775003', '2025-11-20 17:12:17.775003', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 701, 'Cách làm bánh da lợn lá dứa thanh mát, thơm ngon', 'Bánh da lợn lá dứa là món bánh thanh mát, thường được dùng tráng miệng hoặc ăn vặt, có mùi thơm của lá dứa, vị bùi ngọt của đậu xanh.', 'Trà Vinh', 'https://i1-giadinh.vnecdn.net/2021/07/02/4298474-1625217848-8124-1625217852.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=KjC0C2uIlz14vZ26Y5Mo6Q', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm bánh da lợn lá dứa thanh mát, thơm ngon');
INSERT INTO public.post VALUES (714, '2025-11-20 17:12:22.711531', '2025-11-20 17:12:22.711531', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 716, 'Nộm hoa chuối', 'Món nộm dễ làm, tỏa mùi thơm, chua, cay, mặn, ngọt cân đối, rất ngon miệng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/13/nomhoachuoi-1634112383-3141-1634112478.png?w=0&h=0&q=100&dpr=2&fit=crop&s=edJqP5VOwfq3BX31H5DgDg', 0, 0, 'MEDIUM', 'Cùng thử nấu Nộm hoa chuối');
INSERT INTO public.post VALUES (729, '2025-11-20 17:12:27.9975', '2025-11-20 17:12:27.9975', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 731, '4 món cháo thanh đạm ''chống ngấy'' ngày Tết', 'Cháo tôm, cháo hàu, cháo thịt bò, cháo sườn non vừa thơm ngon, dễ tiêu hóa, đủ chất dinh dưỡng lại ''chống ngấy'' hiệu quả trong ngày Tết.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/02/04/Chohu2-1612448995-5571-1612449427.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kk5Z0A4qZBQjX9vLKBQqwg', 0, 0, 'HARD', 'Cùng thử nấu 4 món cháo thanh đạm ''chống ngấy'' ngày Tết');
INSERT INTO public.post VALUES (744, '2025-11-20 17:12:32.064983', '2025-11-20 17:12:32.064983', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 746, 'Bánh bột lọc tôm', 'Tuy hơi mất thời gian và công sức nhưng bạn sẽ khiến cả nhà bất ngờ khi được thưởng thức những chiếc bánh bột lọc tôm thơm ngon, hấp dẫn do chính tay bạn làm.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2021/10/15/202103120025491032f38b-1634297-4432-2634-1634297316.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0tuNUq6l0aF3-48cBgrk0A', 0, 0, 'MEDIUM', 'Cùng thử nấu Bánh bột lọc tôm');
INSERT INTO public.post VALUES (759, '2025-11-20 17:12:35.824417', '2025-11-20 17:12:35.824417', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 761, 'Kem dâu tây', 'Ly kem vị dâu tây thơm ngon, mát lạnh sẽ hấp dẫn cả nhà. Bạn tham khảo cách làm dưới đây và trổ tài để mọi người thưởng thức nhé.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/18/1567004496dautaykemdalat8-1634-9613-2416-1634550139.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kmKitg_P6V-PB8IjpQRhfQ', 0, 0, 'EASY', 'Cùng thử nấu Kem dâu tây');
INSERT INTO public.post VALUES (774, '2025-11-20 17:12:40.562041', '2025-11-20 17:12:40.562041', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 776, 'Cách làm xíu mại chay cho mùa Vu Lan', 'Xíu mại có vị béo bùi từ đậu phụ, giòn ngọt từ củ đậu, sần sật từ mộc nhĩ quyện trong nước sốt sánh nhẹ, màu đỏ bắt mắt. Món này ăn cùng bánh mì, cơm trắng rất hợp trong mùa Vu Lan.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2023/08/24/Thnhphm11-1692862592-1762-1692862611.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=I6dNvjqDvMB8kPscHjsiOg', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm xíu mại chay cho mùa Vu Lan');
INSERT INTO public.post VALUES (789, '2025-11-20 17:12:46.749607', '2025-11-20 17:12:46.749607', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 791, 'Cách làm bánh gạo Tokbokki từ cơm nguội', 'Bánh gạo dẻo mềm, quyện đẫm trong nước sốt màu đỏ cam hấp dẫn, làm nên món ngon đơn giản trong thời kỳ giãn cách.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/08/20/nh2-1629451568-2958-1629451610.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5NaFvYExg8fiu4a11lgMYw', 22, 23, 'MEDIUM', 'Cùng thử nấu Cách làm bánh gạo Tokbokki từ cơm nguội');
INSERT INTO public.post VALUES (673, '2025-11-20 17:12:10.184425', '2025-11-20 17:12:10.184425', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 675, 'Món tráng miệng', 'Dưa hấu trộn mật ong và đào ngâm rượu vang là hai món tráng miệng vừa bổ mát, ngon miệng lại rất dễ làm.', 'Tiền Giang', 'https://i1-giadinh.vnecdn.net/2021/10/26/duahay-1635220816-3544-1635220898.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=gzmKGTmY-IFtsR3-kS72_w', 0, 0, 'EASY', 'Cùng thử nấu Món tráng miệng');
INSERT INTO public.post VALUES (688, '2025-11-20 17:12:14.46884', '2025-11-20 17:12:14.46884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 690, 'Cách làm trà sữa Thái xanh đơn giản tại nhà', 'Dù giãn cách, bạn vẫn tạo ra được các ly trà sữa thơm ngon đơn giản tại nhà với nguyên liệu đơn giản.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/09/11/Trasua1-1631341310-9389-1631341336.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-ieuk0GkuzyIw9JiWMuMOg', 37, 38, 'EASY', 'Cùng thử nấu Cách làm trà sữa Thái xanh đơn giản tại nhà');
INSERT INTO public.post VALUES (702, '2025-11-20 17:12:19.191028', '2025-11-20 17:12:19.191028', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 704, 'Cách làm trà sữa tại nhà cực dễ, ngon không kém cửa hàng', 'Trà sữa là thức uống đang thịnh hành, nhưng không hề khó nếu muốn tự làm. Bạn có thể dễ dàng mua nguyên liệu và chế biến tại nhà.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/03/09/11-1615280864-4489-1615281156.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=prYtIKgS0MPn1jkCvoNy7A', 0, 0, 'HARD', 'Cùng thử nấu Cách làm trà sữa tại nhà cực dễ, ngon không kém cửa hàng');
INSERT INTO public.post VALUES (717, '2025-11-20 17:12:23.913037', '2025-11-20 17:12:23.913037', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 719, 'Nộm xoài xanh tôm thịt', 'Món này khá đơn giản, từ khâu chọn nguyên liệu đến cách làm nhưng lại rất ngon. Mời bạn chế biến theo hướng dẫn của đầu bếp Ezcooking.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2021/10/02/nomxoaixanh-1633166804-6598-1633166810.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=PJ9c44RhBqO71nAU0SZxaQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Nộm xoài xanh tôm thịt');
INSERT INTO public.post VALUES (732, '2025-11-20 17:12:28.995601', '2025-11-20 17:12:28.995601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 734, 'Cách làm bánh mì chuối mềm xốp thơm mùi trái cây', 'Bánh mì chuối có nguồn gốc từ Mỹ, ra đời những năm 1870 khi kết hợp chuối chín và bột nở tạo nên món bánh ngon, tiết kiệm và nhanh gọn. Ngày 23/2 hàng năm được vinh danh là Ngày Bánh mì chuối.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/03/24/Bc55-1648118471-9983-1648118549.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=1X8QRKvN3-N0_3zu9hPWhQ', 32, 33, 'MEDIUM', 'Cùng thử nấu Cách làm bánh mì chuối mềm xốp thơm mùi trái cây');
INSERT INTO public.post VALUES (747, '2025-11-20 17:12:32.789989', '2025-11-20 17:12:32.789989', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 749, 'Ốc hấp lá gừng', 'Món ăn này có mùi thơm đặc trưng của ốc với lá gừng, vị chua cay, mặn ngọt cân đối, rất phù hợp để đãi khách.', 'Quảng Ninh', 'https://i1-giadinh.vnecdn.net/2021/10/12/ava1534093780583width640height-7474-7185-1634028472.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=tErIi30QUQeC_a_Phz2CEA', 0, 0, 'MEDIUM', 'Cùng thử nấu Ốc hấp lá gừng');
INSERT INTO public.post VALUES (762, '2025-11-20 17:12:36.652454', '2025-11-20 17:12:36.652454', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 764, 'Cách làm bánh tráng nướng bằng chảo', 'Vỏ bánh giòn rụm, nóng hổi, đa dạng màu sắc: màu vàng của trứng, màu đỏ của bò khô, hồng của xúc xích, xanh hành lá… rất hấp dẫn.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/07/21/nh2-1626861915-8195-1626861984.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=PTXgSAOZ69tQVQUIcu-JIA', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm bánh tráng nướng bằng chảo');
INSERT INTO public.post VALUES (777, '2025-11-20 17:12:41.137206', '2025-11-20 17:12:41.137206', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 779, 'Chỉ bột mì, hành lá làm nên bánh ngon cho bữa sáng', 'Từng miếng bánh giòn dai kết hợp với vị thơm của hành lá tạo nên một dư vị hấp dẫn ngay từ lần đầu tiên thưởng thức.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/08/06/banh1-1628236798-7895-1628236881.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ZInR7xoNm2lWE35SK8-agg', 20, 20, 'MEDIUM', 'Cùng thử nấu Chỉ bột mì, hành lá làm nên bánh ngon cho bữa sáng');
INSERT INTO public.post VALUES (792, '2025-11-20 17:12:48.533532', '2025-11-20 17:12:48.533532', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 794, 'Bữa sáng đơn giản với bún cá rô', 'Bún cá rô thực ra cũng không mất quá nhiều thời gian như bạn tưởng. Bạn có thể thực hiện các bước sơ chế từ tối hôm trước để chuẩn bị bữa sáng ngon lành, bổ dưỡng này cho gia đình.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2021/08/05/Buncaro-1628157106-1581-1628157114.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=6tH0Zk3LramCmY26kKaPig', 0, 0, 'MEDIUM', 'Cùng thử nấu Bữa sáng đơn giản với bún cá rô');
INSERT INTO public.post VALUES (674, '2025-11-20 17:12:10.495875', '2025-11-20 17:12:10.495875', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 3, 676, 'Chè thanh long', 'Thanh long là loại quả chứa nhiều chất dinh dưỡng, giúp thanh nhiệt. Không chỉ ăn tươi, loại quả "rồng xanh" này còn chế biến được rất nhiều món ngon, trong đó có món chè.', 'Bình Thuận', 'https://i1-giadinh.vnecdn.net/2021/10/01/ch1-1633082171-6139-1633082182.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_IClrg6nz68ZBwdYVb2EwA', 0, 0, 'MEDIUM', 'Cùng thử nấu Chè thanh long');
INSERT INTO public.post VALUES (689, '2025-11-20 17:12:14.880141', '2025-11-20 17:12:14.880141', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 691, 'Cách làm bánh đúc nóng ngon, đơn giảm mà chuẩn vị', 'Bánh đúc nóng mềm dẻo, thơm ngát mùi hành mùi, lạ miệng luôn là lựa chọn lý tưởng để lót dạ trong những ngày mát trời hoặc se lạnh.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/05/17/1-1621220538-7560-1621220858.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=EDwf9pueMN1T-yoS8wvH7g', 30, 30, 'HARD', 'Cùng thử nấu Cách làm bánh đúc nóng ngon, đơn giảm mà chuẩn vị');
INSERT INTO public.post VALUES (703, '2025-11-20 17:12:19.467601', '2025-11-20 17:12:19.467601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 705, 'GIẢI NHIỆT ngày hè cùng món chè sương sa hạt lựu', 'Chè sương sa hạt lựu có vị ngọt dịu, độ béo vừa phải. Khi thưởng thức, ta có cảm giác như đang uống một thức uống giải khát.', 'Thừa Thiên–Huế', 'https://i1-giadinh.vnecdn.net/2021/03/05/1-1614934247-2313-1614934256.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VODwHODgF8DDpum6Inx86A', 0, 0, 'MEDIUM', 'Cùng thử nấu GIẢI NHIỆT ngày hè cùng món chè sương sa hạt lựu');
INSERT INTO public.post VALUES (718, '2025-11-20 17:12:24.201194', '2025-11-20 17:12:24.201194', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 720, 'Rau củ kho chao', 'Món rau củ có vị béo ngậy và thơm đặc trưng của chao, vị ngọt của nước dừa tươi, thơm mùi sả.', 'Sóc Trăng', 'https://i1-ngoisao.vnecdn.net/2021/07/06/204193513-510468843613428-7371-9656-8973-1625563858.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=G68oqcnbbXw1Kc_8g2OBHQ', 0, 0, 'EASY', 'Cùng thử nấu Rau củ kho chao');
INSERT INTO public.post VALUES (733, '2025-11-20 17:12:29.253891', '2025-11-20 17:12:29.253891', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 735, 'Bánh sắn gợi nhớ tuổi thơ', 'Bánh sắn bên ngoài hơi sém vàng, bên trong mềm ngọt, dậy mùi thơm của nước cốt dừa, béo ngậy của sữa đặc, thơm thơm từ vừng rang. Đây là món bánh gắn liền với tuổi thơ nhiều người.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2022/10/27/-8927-1666864200.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=VfuBfrkDn5aliExCdAwSLw', 25, 25, 'MEDIUM', 'Cùng thử nấu Bánh sắn gợi nhớ tuổi thơ');
INSERT INTO public.post VALUES (748, '2025-11-20 17:12:32.945672', '2025-11-20 17:12:32.945672', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 750, 'Cách làm khoai tây đút lò ngon như ngoài hàng', 'Lớp vỏ ngoài giòn vàng, bên trong mềm, dậy mùi thơm của bơ tỏi và lá xạ hương. Món này ăn kèm với bò bít tết rất hấp dẫn, tạo nên bữa tiệc hoàn hảo nhân dịp năm mới.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/12/31/Khoaitay-1640946767-5665-1640946911.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ZAVEpU5cMVBc8HHWT-g09w', 35, 35, 'EASY', 'Cùng thử nấu Cách làm khoai tây đút lò ngon như ngoài hàng');
INSERT INTO public.post VALUES (763, '2025-11-20 17:12:36.864771', '2025-11-20 17:12:36.864771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 765, 'Cách làm bánh dứa', 'Bánh có mùi thơm của dứa, vị chua ngọt hấp dẫn, nguyên liệu làm lại rất dễ tìm.', 'Sóc Trăng', 'https://i1-giadinh.vnecdn.net/2021/09/22/bnhda-1632309427-2425-1632309512.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=veM5PB076cDNx-Q_sQMzxA', 0, 0, 'MEDIUM', 'Cùng thử nấu Cách làm bánh dứa');
INSERT INTO public.post VALUES (778, '2025-11-20 17:12:41.385684', '2025-11-20 17:12:41.385684', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 780, 'Cách nấu xôi đậu xanh bằng nồi cơm điện', 'Xôi dẻo thơm, không bị ướt, đậu xanh mềm bở, bùi bùi làm nên bữa sáng tiện dụng, nhanh gọn cho gia đình.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/07/30/nh2-1627637245-6005-1627637336.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=UkBSWsvK4zqxQt20anVhow', 20, 20, 'EASY', 'Cùng thử nấu Cách nấu xôi đậu xanh bằng nồi cơm điện');
INSERT INTO public.post VALUES (793, '2025-11-20 17:12:49.495185', '2025-11-20 17:12:49.495185', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 795, 'Cách làm bánh nướng nhân sữa dừa thơm ngon', 'Vỏ bánh mềm, nhân sữa dừa vừa béo ngậy vừa dẻo dai kéo sợi, vị ngọt vừa phải, dễ định hình sắc nét cho bánh. Nhân sữa dừa kéo sợi đang là hot trend trong mùa Trung thu năm nay.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2022/09/07/Bc8Thnhphm1-1662547041-8263-1662547091.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=vqtj35m0VOvWghl83bG89g', 42, 43, 'HARD', 'Cùng thử nấu Cách làm bánh nướng nhân sữa dừa thơm ngon');
INSERT INTO public.post VALUES (678, '2025-11-20 17:12:11.631866', '2025-11-20 17:12:11.631866', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 680, 'Bánh gato cuộn hình khúc củi', 'Tuy hơi cầu kỳ một chút, nhưng chắc chắn chiếc bánh gato thơm ngon, hấp dẫn do chính bạn làm sẽ khiến cả nhà trầm trồ và vui vẻ.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/03/DSCF8629copy-1633267224-8492-1633267325.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_q40ffzvQ8JbKIuJInMhxA', 0, 0, 'MEDIUM', 'Cùng thử nấu Bánh gato cuộn hình khúc củi');
INSERT INTO public.post VALUES (683, '2025-11-20 17:12:12.770894', '2025-11-20 17:12:12.770894', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 685, 'Cách làm sữa khoai lang tím đẹp, sánh mịn', 'Sữa có màu tím đẹp, vị bùi bùi của khoai lang quyện vị ngọt béo của sữa rất thơm ngon và bổ dưỡng.', 'Vĩnh Long', 'https://i1-giadinh.vnecdn.net/2021/10/02/khoailang-1633159335-9940-1633159376.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=1GqveQl0g7cQYmtKNR8dYw', 20, 20, 'EASY', 'Cùng thử nấu Cách làm sữa khoai lang tím đẹp, sánh mịn');
INSERT INTO public.post VALUES (693, '2025-11-20 17:12:15.580349', '2025-11-20 17:12:15.580349', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 695, 'Cách nấu chè bí đỏ đơn giản', 'Bí đỏ mềm dẻo, quyện trong nước cốt dừa sóng sánh béo ngậy, đậu phộng giòn thơm làm nên món ngon bổ dưỡng thời kỳ giãn cách.', 'Sóc Trăng', 'https://i1-giadinh.vnecdn.net/2021/08/20/bido-1629453554-5785-1629453623.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=PAL9_DE899BPjAN9gsjBUw', 25, 25, 'EASY', 'Cùng thử nấu Cách nấu chè bí đỏ đơn giản');
INSERT INTO public.post VALUES (698, '2025-11-20 17:12:17.43559', '2025-11-20 17:12:17.43559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 11, 700, 'Cách làm kem chuối dừa đậu phộng đơn giản tại nhà', 'Kem chuối mềm quyện với vị béo ngậy của nước cốt dừa, chút bùi bùi của đậu phộng quyện lại mát lành, xua tan cái nóng bức của mùa hè.', 'Bến Tre', 'https://iv1.vnecdn.net/giadinh/images/web/2021/06/04/cach-lam-kem-chuoi-dua-don-gian-1622796306.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=2Dlw5uFuVC3mOmMIYHv2Jg', 187, 188, 'MEDIUM', 'Cùng thử nấu Cách làm kem chuối dừa đậu phộng đơn giản tại nhà');
INSERT INTO public.post VALUES (707, '2025-11-20 17:12:21.006474', '2025-11-20 17:12:21.006474', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 709, 'Những món chế biến từ hoa bưởi', 'Mía ướp hoa bưởi, siro tinh dầu hoa bưởi, mật ong hương bưởi không chỉ giúp giải cảm, đau đầu mà còn giúp thư thái tinh thần.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/03/09/nhchung-1615254379-3660-1615254774.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=1YaG-HLh6BUuxCTPtHMJLw', 0, 0, 'MEDIUM', 'Cùng thử nấu Những món chế biến từ hoa bưởi');
INSERT INTO public.post VALUES (712, '2025-11-20 17:12:22.346268', '2025-11-20 17:12:22.346268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 714, 'Hướng dẫn làm Kimbap đơn giản, nhanh chóng trong ''Tích tắc''', 'Đơn giản, dễ dàng, ngon miệng, món ăn này nhanh chóng chiếm cảm tình của các tín đồ mê Kimbap của Hàn Quốc.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/02/19/nh3-1613719453-4477-1613719740.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=0wJ4hdFBx789y7hcz-qTvw', 10, 10, 'MEDIUM', 'Cùng thử nấu Hướng dẫn làm Kimbap đơn giản, nhanh chóng trong ''Tích tắc''');
INSERT INTO public.post VALUES (722, '2025-11-20 17:12:25.157609', '2025-11-20 17:12:25.157609', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 724, 'Hướng dẫn nấu cháo ngao đậu xanh món ngon giàu dinh dưỡng', 'Cháo ngao đậu xanh là món dễ ăn, cung cấp hàng loạt dưỡng chất cho cơ thể như protein, chất béo..., thích hợp để ăn sáng hoặc thưởng thức trong bữa phụ buổi chiều.', 'Nam Định', 'https://i1-giadinh.vnecdn.net/2021/07/02/4298547-1625217438-6456-1625217442.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=N_rWjgsixHWlTw9Uy1vqcw', 30, 30, 'EASY', 'Cùng thử nấu Hướng dẫn nấu cháo ngao đậu xanh món ngon giàu dinh dưỡng');
INSERT INTO public.post VALUES (727, '2025-11-20 17:12:26.781423', '2025-11-20 17:12:26.781423', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 729, 'Gỏi đu đủ kiểu Thái - Món ngon ngày Tết, ăn hoài không ngán', 'Món ăn ''quốc hồn quốc túy'' của xứ Chùa Vàng được bình chọn là món gỏi ngon nhất thế giới.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/01/29/gi2-1611891515-7093-1611891637.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=hvYZj47STO08O09QP3T1yg', 15, 15, 'HARD', 'Cùng thử nấu Gỏi đu đủ kiểu Thái - Món ngon ngày Tết, ăn hoài không ngán');
INSERT INTO public.post VALUES (737, '2025-11-20 17:12:30.295184', '2025-11-20 17:12:30.295184', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 739, 'Cách làm bánh dẻo nhân đậu xanh trứng muối', 'Bánh dẻo mềm mịn, vị ngọt vừa phải, nhân đậu xanh bùi bùi, trứng muối béo ngậy góp phần cho tiệc cỗ ngọt Trung Thu thêm phong phú.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/09/06/Bc6Thnhphm1-1662455219-2527-1662455241.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Hw0W0DNbE6rE1AVZHyFvXA', 32, 33, 'MEDIUM', 'Cùng thử nấu Cách làm bánh dẻo nhân đậu xanh trứng muối');
INSERT INTO public.post VALUES (742, '2025-11-20 17:12:31.562054', '2025-11-20 17:12:31.562054', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 744, 'Cách làm bánh rán mặn đúng chuẩn', 'Vỏ bánh vàng ruộm, vừa giòn lại vừa dẻo, nhân bên trong tách vỏ, mềm ngọt tự nhiên từ thịt, mộc nhĩ, chấm ngập nước chấm chua ngọt nhanh chóng xua tan giá lạnh.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/02/25/Thnhphm1-1645779437-2464-1645779545.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=qe24DF5iGH_7j4qCk03bbA', 0, 0, 'HARD', 'Cùng thử nấu Cách làm bánh rán mặn đúng chuẩn');
INSERT INTO public.post VALUES (752, '2025-11-20 17:12:33.933076', '2025-11-20 17:12:33.933076', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 754, 'Bánh khoai lang tím, nhân phô mai tan chảy', 'Khoai lang mềm ngọt quyện nhân phô mai tan chảy, béo ngậy làm nên món ăn vặt ngon cho các bạn nhỏ sau giờ học online tại nhà.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/09/24/nh2-1632480015-4295-1632480032.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=9VrArBPEADHnGCbzNkRhSw', 25, 25, 'MEDIUM', 'Cùng thử nấu Bánh khoai lang tím, nhân phô mai tan chảy');
INSERT INTO public.post VALUES (757, '2025-11-20 17:12:35.46159', '2025-11-20 17:12:35.46159', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 759, 'Cách luộc ốc giòn ngon, nước chấm đậm đà', 'Ốc chín vừa tới giòn dai, nước chấm ốc sánh, đậm đà tỏa mùi hương thơm của sả, lá chanh, ớt. Một món ăn bình dị gây thương nhớ vào mùa đông.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/01/06/Thnhphm2-1641477068-8454-1641477606.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=aR7gTZ7Lx6W3zofgazTbPw', 17, 18, 'MEDIUM', 'Cùng thử nấu Cách luộc ốc giòn ngon, nước chấm đậm đà');
INSERT INTO public.post VALUES (767, '2025-11-20 17:12:37.945936', '2025-11-20 17:12:37.945936', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 769, 'Cách làm pizza mỳ tôm đơn giản, ngon miệng', 'Với một chút biến tấu từ các nguyên liệu đơn giản, bạn sẽ có ngay món ăn ngon miệng cho các bé mùa giãn cách.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/07/30/nh3-1627637589-4738-1627637726.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=1cmCVL6mpwLhHW6kgtEMVw', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách làm pizza mỳ tôm đơn giản, ngon miệng');
INSERT INTO public.post VALUES (694, '2025-11-20 17:12:16.349099', '2025-11-20 17:12:16.349099', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 696, 'Công thức làm bánh bao thành công từ lần đầu', 'Bánh bao là món ăn của người Hoa, được nhiều người Việt ưa thích. Cách làm bánh đơn giản, mang lại lượng dinh dưỡng cần thiết cho bữa sáng của gia đình.', 'Hải Phòng', 'https://i1-giadinh.vnecdn.net/2021/07/02/4298477-1625217874-9591-1625217877.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ZdsMx-ziPGeWVENNPEB1wA', 60, 60, 'HARD', 'Cùng thử nấu Công thức làm bánh bao thành công từ lần đầu');
INSERT INTO public.post VALUES (700, '2025-11-20 17:12:17.907553', '2025-11-20 17:12:17.907553', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 702, 'Nước chanh việt quất giải khát mùa hè', 'Vị chua chua của chanh kết hợp với vị thanh mát lạ miệng của việt quất mang lại cảm giác sảng khoái trong ngày nóng bức.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/07/02/4298470-1625217821-9684-1625217825.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=4qX5dB-wAhU0SWwTDmszZw', 15, 15, 'EASY', 'Cùng thử nấu Nước chanh việt quất giải khát mùa hè');
INSERT INTO public.post VALUES (704, '2025-11-20 17:12:19.603522', '2025-11-20 17:12:19.603522', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 9, 706, 'Công thức làm Nước lá tía tô giải khát cho ngày nắng', 'Ngoài công dụng giải khát, uống nước lá tía tô mỗi ngày còn có tác dụng làm trắng da và giảm cân hiệu quả.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/03/15/tiato-1615786448-3754-1615786809.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=uhy3fYPnq_OOeAO2UykQdQ', 0, 0, 'EASY', 'Cùng thử nấu Công thức làm Nước lá tía tô giải khát cho ngày nắng');
INSERT INTO public.post VALUES (708, '2025-11-20 17:12:21.547631', '2025-11-20 17:12:21.547631', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 2, 710, 'Công thức nấu chè trôi nước ngon, dẻo, thanh mát', 'Chè trôi nước không chỉ có vị thanh mát, ngon miệng mà còn là nét đặc trưng trong ẩm thực truyền thống người Việt.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/03/12/che1-1615514890-9540-1615515615.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=C_7vXoMzDyz9tB_c44fO6Q', 60, 60, 'MEDIUM', 'Cùng thử nấu Công thức nấu chè trôi nước ngon, dẻo, thanh mát');
INSERT INTO public.post VALUES (715, '2025-11-20 17:12:23.205581', '2025-11-20 17:12:23.205581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 717, 'Rau câu hoa hồng', 'Rau củ tươi, chả quế... đổ khuôn với thạch rau câu. Món ăn dễ làm, không ngán.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/15/raucauhoahong-1634273160-7789-1634273373.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=DSRZT7O5toqnlO7cht0XYw', 0, 0, 'MEDIUM', 'Cùng thử nấu Rau câu hoa hồng');
INSERT INTO public.post VALUES (719, '2025-11-20 17:12:24.391807', '2025-11-20 17:12:24.391807', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 721, 'Cách làm bún sườn chua nấu sấu thanh mát mà nhanh, đơn giản', 'Bún sườn nấu sấu là món ăn này rất hợp với mùa hè bởi cách làm và nguyên liệu đơn giản nhưng lại hấp dẫn.', 'Hà Nội', 'https://iv1.vnecdn.net/giadinh/images/web/2021/06/12/cach-lam-bun-suon-nau-sau-thanh-mat-1623485785.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=3dLMoAz9dAbjhkGSyZaIpg', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm bún sườn chua nấu sấu thanh mát mà nhanh, đơn giản');
INSERT INTO public.post VALUES (723, '2025-11-20 17:12:25.359566', '2025-11-20 17:12:25.359566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 725, 'Cách làm Salad xoài kiểu Thái ngon khó cưỡng', 'Đang mùa xoài, bạn có thể dễ dàng trổ tài món salad hấp dẫn, lạ miệng dành cho bạn bè, gia đình.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2021/04/29/Untitled-1619667392-6755-1619668987.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ucDGnuHqXa9m14yPuajshw', 10, 10, 'MEDIUM', 'Cùng thử nấu Cách làm Salad xoài kiểu Thái ngon khó cưỡng');
INSERT INTO public.post VALUES (730, '2025-11-20 17:12:28.37298', '2025-11-20 17:12:28.37298', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 732, '[Kinh nghiệm] MẸO luộc thịt chân giò DA GIÒN, TRẮNG MỀM', 'Món ăn quen thuộc này sẽ trở nên hấp dẫn với một số bí quyết đơn giản, quen thuộc.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/02/18/thit1-1613645822-9125-1613646081.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=icMfmPn0-PRBtADCkZxwKw', 20, 20, 'MEDIUM', 'Cùng thử nấu [Kinh nghiệm] MẸO luộc thịt chân giò DA GIÒN, TRẮNG MỀM');
INSERT INTO public.post VALUES (734, '2025-11-20 17:12:29.52907', '2025-11-20 17:12:29.52907', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 736, 'Cách làm nộm xoài tai heo và cà rốt ngon giòn sần sật', 'Món ăn thu hút bởi vị chua - cay - mặn - ngọt hài hòa, tai heo trắng giòn, thích hợp làm món khai vị hoặc khi lai rai cùng bằng hữu.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/05/27/Thnhphm11-1653635648-2760-1653635733.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=n4p-oO59qvncXXKF1J57hA', 353, 353, 'MEDIUM', 'Cùng thử nấu Cách làm nộm xoài tai heo và cà rốt ngon giòn sần sật');
INSERT INTO public.post VALUES (738, '2025-11-20 17:12:30.474596', '2025-11-20 17:12:30.474596', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 740, 'Rau câu trái cây', 'Rau câu trái cây là món ăn bổ dưỡng và mát nhờ được kết hợp với các loại quả thập cẩm. Món ăn dùng lạnh sẽ ngon miệng hơn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/10/18/cachlamdongsuongtraicay-163455-7486-6450-1634551445.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=H6BbwFKqZZaAtd2G9biqFQ', 0, 0, 'EASY', 'Cùng thử nấu Rau câu trái cây');
INSERT INTO public.post VALUES (745, '2025-11-20 17:12:32.330838', '2025-11-20 17:12:32.330838', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 747, 'Cách làm bánh gà ''thần thánh'' Hà Nội', 'Vỏ bánh vàng ươm, giòn rụm, bên trong thịt gà mềm ngọt, mọng nước, phô mai kéo sợi hấp dẫn. Bánh gà được nhiều bạn trẻ yêu thích và ví như món ăn vặt ''''thần thánh'''' của Hà Nội.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/11/30/Thnhphm1-1638256859-7113-1638256874.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=RtjUT9JikrSZyfBfBuIezA', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm bánh gà ''thần thánh'' Hà Nội');
INSERT INTO public.post VALUES (749, '2025-11-20 17:12:33.083338', '2025-11-20 17:12:33.083338', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 14, 751, 'Bí quyết làm cốm xào dẻo thơm', 'Cốm xào dẻo ngọt, dậy mùi thơm của cốm quyện vị bùi béo của dừa nạo, thưởng thức bên tách trà sen tạo nên dư vị thu Hà Nội rất riêng.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/10/02/nh2-1633157290-5863-1633157305.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=rar1KZMOveugQxQIo6wUog', 12, 13, 'EASY', 'Cùng thử nấu Bí quyết làm cốm xào dẻo thơm');
INSERT INTO public.post VALUES (753, '2025-11-20 17:12:34.131889', '2025-11-20 17:12:34.131889', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 755, 'Làm bánh dày giò từ cơm nguội siêu nhanh', 'Bánh dày mềm mịn, dẻo dai, kẹp giò lụa làm nên bữa sáng nhanh gọn, thơm ngon ngày giãn cách.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/17/banh1-1631878055-3264-1631878063.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-O87JgikOvnrGY7_AdZeZw', 20, 20, 'MEDIUM', 'Cùng thử nấu Làm bánh dày giò từ cơm nguội siêu nhanh');
INSERT INTO public.post VALUES (760, '2025-11-20 17:12:35.96671', '2025-11-20 17:12:35.96671', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 762, 'Cách làm bánh ngào Nghệ An đơn giản', 'Bánh hình kén tằm dẻo mịn quyện trong mật mía sóng sánh, ngọt đậm đà và dậy mùi gừng rất hấp dẫn.', 'Nghệ An', 'https://i1-giadinh.vnecdn.net/2021/08/06/Anh3-1628236369-8615-1628236427.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=LkKegym35XVrt2xymE8R_w', 17, 18, 'EASY', 'Cùng thử nấu Cách làm bánh ngào Nghệ An đơn giản');
INSERT INTO public.post VALUES (711, '2025-11-20 17:12:22.008007', '2025-11-20 17:12:22.008007', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 713, 'Cách nấu cháo cá ám - món quà ẩm thực Hà Nội', 'Hạt cháo nở bung như hoa, khi ăn gắp 1 miếng thịt cá trắng ngần mềm ngọt, 1 miếng thịt ba chỉ béo ngậy, thêm rau thơm, gừng thái sợi thì bao thơm thảo, tinh tế từ đất trời quyến luyến vị giác.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/08/26/Bc44-1661503234-9269-1661503389.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=mFAiKUSa4HCjuceK47Jm0A', 27, 28, 'MEDIUM', 'Cùng thử nấu Cách nấu cháo cá ám - món quà ẩm thực Hà Nội');
INSERT INTO public.post VALUES (726, '2025-11-20 17:12:26.110922', '2025-11-20 17:12:26.110922', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 728, 'Thịt thăn hấp, rưới sốt nấm', 'Với thịt thăn, bạn có thể xào, nấu canh, nướng, đút lò hoặc hấp. Món thịt thăn hấp rưới sốt nấm, ớt chuông dưới đây rất ngon, lạ miệng mà cũng không quá cầu kỳ.', 'Lâm Đồng', 'https://i1-giadinh.vnecdn.net/2021/10/03/nacthan14532824-1633267394-5851-1633267544.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=r-472lH1FC4r9NPUfpdHoA', 0, 0, 'MEDIUM', 'Cùng thử nấu Thịt thăn hấp, rưới sốt nấm');
INSERT INTO public.post VALUES (741, '2025-11-20 17:12:31.311712', '2025-11-20 17:12:31.311712', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 743, 'Cách làm chuối nếp nướng - món quà vặt dân dã miền Tây', 'Vỏ nếp nóng giòn quyện chuối dẻo ngọt, nước cốt dừa béo ngậy, đậu phộng thơm bùi tựa như cả miền Tây giản dị ùa về.', 'Cần Thơ', 'https://i1-giadinh.vnecdn.net/2022/03/17/Thnhphm11-1647494610-2039-1647494727.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=dgpA9_RM5dZZuab3k_m_og', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm chuối nếp nướng - món quà vặt dân dã miền Tây');
INSERT INTO public.post VALUES (756, '2025-11-20 17:12:35.103212', '2025-11-20 17:12:35.103212', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 15, 758, 'Cách làm bánh mì mini thơm ngon tại nhà', 'Vỏ bánh mì bên ngoài vàng giòn tan, ruột mềm mại, không bị khô. Bánh mì chấm cùng sữa đặc, mứt trái cây hoặc phết pate, kẹp thịt rất ngon.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/09/04/Thnhphm2-1630736406-8412-1630736488.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MYokjO5dbrEgkP4ooXiR_Q', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm bánh mì mini thơm ngon tại nhà');
INSERT INTO public.post VALUES (771, '2025-11-20 17:12:39.189999', '2025-11-20 17:12:39.189999', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 773, 'Cách làm bánh trôi dẻo ngọt và đẹp mắt cho Tết Hàn thực', 'Món bánh truyền thống dịp Tết Hàn thực thu hút hơn bởi pha màu tự nhiên, tạo hình bông hoa.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/04/02/Bc66-1648900111-3454-1648900132.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=pCRohbUSNPCk3ioowds3pw', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm bánh trôi dẻo ngọt và đẹp mắt cho Tết Hàn thực');
INSERT INTO public.post VALUES (786, '2025-11-20 17:12:43.848876', '2025-11-20 17:12:43.848876', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 788, 'Cách làm bánh khoai tây nhân phô mai', 'Bánh khoai vỏ vàng ruộm, bùi bùi, vị ngọt vừa phải, nhân phô mai tan chảy, béo ngậy. Nguyên liệu, cách làm lại đơn giản, phù hợp thời kỳ giãn cách.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/08/27/nh3-1630054035-4780-1630054195.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=mw8F2sVYgu1wjwc33-aQGw', 25, 25, 'MEDIUM', 'Cùng thử nấu Cách làm bánh khoai tây nhân phô mai');
INSERT INTO public.post VALUES (725, '2025-11-20 17:12:25.80659', '2025-11-20 17:12:25.80659', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 727, 'Cách nấu canh trai nấu chua giải nhiệt mùa hè', 'Mùa hè, các bà nội trợ thường ưu tiên lựa chọn trai, ngao, hến đưa vào thực đơn với các món ăn phong phú để giải nhiệt, trong đó có món canh trai nấu chua.', 'Nam Định', 'https://iv1.vnecdn.net/giadinh/images/web/2021/05/15/canh-trai-nau-chua-giai-nhiet-mua-he-1621067925.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=7YLw2Pn5IZY-VRr6VG_fpQ', 15, 15, 'MEDIUM', 'Cùng thử nấu Cách nấu canh trai nấu chua giải nhiệt mùa hè');
INSERT INTO public.post VALUES (740, '2025-11-20 17:12:31.016279', '2025-11-20 17:12:31.016279', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 742, 'Cách làm khoai lang kén đúng chuẩn', 'Khoai lang kén bên ngoài giòn vàng, bên trong ngọt mềm, thơm mùi mè (vừng). Món ăn bình dị này được nhiều người yêu thích, nhất là các bé nhỏ.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/02/18/Thnhphm1-1645172134-2051-1645172246.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=pyztkCYLCbOiKAFgZ0q0XA', 45, 45, 'MEDIUM', 'Cùng thử nấu Cách làm khoai lang kén đúng chuẩn');
INSERT INTO public.post VALUES (755, '2025-11-20 17:12:34.872624', '2025-11-20 17:12:34.872624', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 757, 'Xôi cá rô phi', 'Vị thơm dẻo của nếp cái hoa vàng quyện với mùi thơm đặc trưng của hành khô và cá phi thơm rất thích hợp với những cơn gió se lạnh đầu mùa.', 'Đồng Tháp', 'https://i1-giadinh.vnecdn.net/2021/10/14/xoicaro20210725071346hbzgwm-16-5830-9998-1634184403.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5OC5et_u98EETKl1XU50gQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Xôi cá rô phi');
INSERT INTO public.post VALUES (770, '2025-11-20 17:12:38.862799', '2025-11-20 17:12:38.862799', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 4, 772, 'Cách làm bánh Trung thu ngàn lớp, nhân đậu đỏ trứng muối', 'Không cần khuôn, bạn có thể làm nên món bánh Trung thu thơm ngon cho dịp đoàn viên mùa trăng tròn đẹp nhất trong năm.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/17/nhthnhphm1-1631876793-4893-1631876875.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=2UykEUd8-4pC5a2x28HozA', 45, 45, 'HARD', 'Cùng thử nấu Cách làm bánh Trung thu ngàn lớp, nhân đậu đỏ trứng muối');
INSERT INTO public.post VALUES (785, '2025-11-20 17:12:43.561445', '2025-11-20 17:12:43.561445', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 787, 'Cách làm bánh tiêu cấp tốc trong 20 phút', 'Không men nở, không bột nở, không nhồi bột lâu, không ủ bột nhưng bạn vẫn có bánh tiêu ngon miệng trong thời kỳ giãn cách.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/08/27/nh4-1630052416-4930-1630052547.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=kciGHSbreuLSVAlqy9EDLQ', 10, 10, 'MEDIUM', 'Cùng thử nấu Cách làm bánh tiêu cấp tốc trong 20 phút');
INSERT INTO public.post VALUES (739, '2025-11-20 17:12:30.742031', '2025-11-20 17:12:30.742031', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 741, 'Cách làm nem tai thính thơm ngon tại nhà', 'Tai heo trắng hồng, giòn sần sật, nêm vị vừa đủ, dậy mùi thơm của thính gạo, cuốn cùng rau sống chấm nước chua ngọt đổi vị cho thực đơn ngày hè. Món này ăn chơi hay ăn cùng cơm trắng đều phù hợp.', 'Thanh Hóa', 'https://i1-giadinh.vnecdn.net/2022/06/11/Thnhphm1-1654924682-7551-1654924727.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=6omg1p_v8c-GsTVkblhFQA', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm nem tai thính thơm ngon tại nhà');
INSERT INTO public.post VALUES (746, '2025-11-20 17:12:32.544126', '2025-11-20 17:12:32.544126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 8, 748, 'Chè sắn mochi dẻo mềm, ấm nóng cho ngày đông', 'Từng viên mochi sắn dẻo bùi quyện trong nước đường gừng ấm nóng, dừa sợi sần sật, đậu phộng giòn thơm khiến các tín đồ ăn vặt mê mẩn.', 'Quảng Nam', 'https://i1-giadinh.vnecdn.net/2021/12/30/Thnhphm1-1640854623-8353-1640854839.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=MlioVw6RSn5HiIh1ktu4nQ', 27, 28, 'MEDIUM', 'Cùng thử nấu Chè sắn mochi dẻo mềm, ấm nóng cho ngày đông');
INSERT INTO public.post VALUES (751, '2025-11-20 17:12:33.59566', '2025-11-20 17:12:33.59566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 753, 'Cốm trộn dừa', 'Cốm trộn dừa là món cốm đặc trưng của miền Nam. Chưa cần ăn chỉ nghĩ thôi bạn đã như cảm nhận được mùi thơm dịu của lúa non xanh gói trong trong những tàu lá sen thơm ngát.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/15/unnamed3-1634297090-6172-1634297184.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=RoIG-GMd19HxPGMDjx0TDg', 0, 0, 'EASY', 'Cùng thử nấu Cốm trộn dừa');
INSERT INTO public.post VALUES (754, '2025-11-20 17:12:34.583638', '2025-11-20 17:12:34.583638', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 19, 756, 'Dưa góp kiểu miền Trung', 'Cũng làm từ các loai rau củ như cà rốt, củ cải, hành... nhưng món dưa góp của người Quảng Nam - Đà Nẵng được muối bằng nước mắm. Dưa có thể để cả tháng mà không bị chua.', 'Đà Nẵng', 'https://i1-giadinh.vnecdn.net/2021/10/12/Thumb1200x67615-1634028917-2345-1634029002.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=XT98Z3nBp1yz6V0T_F2vlg', 0, 0, 'MEDIUM', 'Cùng thử nấu Dưa góp kiểu miền Trung');
INSERT INTO public.post VALUES (761, '2025-11-20 17:12:36.150273', '2025-11-20 17:12:36.150273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 763, 'Bánh chuối hấp', 'Chuối làm được rất nhiều món tráng miệng. Ngoài chè chuối, chuối nướng, chuối xào dừa... thì bánh chuối hấp cũng là một món ngon dễ làm.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/10/09/P1070278001-1633777811-6476-1633777903.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=zM-c6vXbCFDd61f1jv7-3g', 0, 0, 'EASY', 'Cùng thử nấu Bánh chuối hấp');
INSERT INTO public.post VALUES (766, '2025-11-20 17:12:37.598699', '2025-11-20 17:12:37.598699', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 17, 768, 'Ba bước làm bánh khoai lang tím ''núng nính''', 'Chỉ với ba bước: hấp, nghiền khoai lang tím, thêm nguyên liệu và hấp bánh trong 30 phút là bạn đã có ngay món ăn vặt hấp dẫn, an toàn.', 'Huế', 'https://iv1.vnecdn.net/ngoisao/images/web/2021/06/27/banh-khoai-lang-tim-nung-ninh-1624788143.jpg?w=0&h=0&q=100&dpr=1&fit=crop&s=isBX1_uPtbJ6nf8PYrNsQg', 15, 15, 'EASY', 'Cùng thử nấu Ba bước làm bánh khoai lang tím ''núng nính''');
INSERT INTO public.post VALUES (769, '2025-11-20 17:12:38.42071', '2025-11-20 17:12:38.42071', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 771, 'Ngô chiên bơ', 'Món ăn vặt này làm rất đơn giản mà lại không kém phần hấp dẫn. Bạn thử tham khảo để làm cho gia đình thưởng thức vào cuối tuần nhé.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/07/26/Ngochienbo-1627295223-1896-1627295259.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=-vPnYyeIqZ0kgpDIneX_nA', 0, 0, 'EASY', 'Cùng thử nấu Ngô chiên bơ');
INSERT INTO public.post VALUES (776, '2025-11-20 17:12:40.947685', '2025-11-20 17:12:40.947685', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 7, 778, 'Cách làm nem thính chay đơn giản mà ngon', 'Nấm giòn dai, miến dẻo, dậy mùi thơm của thính gạo, lá chanh. Món này ăn kèm cuốn rau sống hoặc cùng chút bánh tráng và bún, chấm nước mắm chay chua ngọt hoặc nước tương đều ngon.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2023/08/29/Bc5Thnhphm15-1693298556-5405-1693298581.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=7z9Mc_ZitkZ5a1fxi3tlyw', 12, 13, 'MEDIUM', 'Cùng thử nấu Cách làm nem thính chay đơn giản mà ngon');
INSERT INTO public.post VALUES (781, '2025-11-20 17:12:42.307799', '2025-11-20 17:12:42.307799', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 783, 'Cách nộm rau muống, đậu phụ chay giòn thơm, vị chua cay mặn ngọt hài hòa', 'Rau muống xanh giòn, đậu phụ bùi béo, quyện với lạc rang giòn thơm, vị chua cay mặn ngọt hài hòa. Món chay dân dã này vừa đủ dinh dưỡng lại làm phong phú thêm thực đơn dịp Vu Lan.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2022/08/11/Thnhphm11-1660204620-6418-1660204726.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=O1-GnwRycfPizNs24DVd2Q', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách nộm rau muống, đậu phụ chay giòn thơm, vị chua cay mặn ngọt hài hòa');
INSERT INTO public.post VALUES (784, '2025-11-20 17:12:43.205067', '2025-11-20 17:12:43.205067', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 12, 786, 'Cách làm bánh ít trần dẻo mềm từ cơm nguội', 'Vỏ bánh mềm dẻo, nhân thịt quyện với mộc nhĩ sần sật cùng vị bùi bùi của đậu xanh, mùi thơm mỡ hành rất hấp dẫn. Một món ngon, tiết kiệm trong thời kỳ giãn cách.', 'Huế', 'https://i1-giadinh.vnecdn.net/2021/09/04/nh2-1630735967-5609-1630736036.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=zuuzuLMbRZkmR5w-aqAC1w', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm bánh ít trần dẻo mềm từ cơm nguội');
INSERT INTO public.post VALUES (791, '2025-11-20 17:12:48.244575', '2025-11-20 17:12:48.244575', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 793, 'Làm bánh cuốn ''cấp tốc'' từ bánh tráng', 'Bánh mềm dai kết hợp với nhân thịt mộc nhĩ thơm ngon, chấm nước mắm chua ngọt làm nên bữa sáng hoàn hảo trong thời kỳ giãn cách.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/08/06/nh1-1628234036-6076-1628234126.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=mk-HFWOlTksrJj0nFuoM9g', 20, 20, 'MEDIUM', 'Cùng thử nấu Làm bánh cuốn ''cấp tốc'' từ bánh tráng');
INSERT INTO public.post VALUES (764, '2025-11-20 17:12:37.237201', '2025-11-20 17:12:37.237201', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 13, 766, 'Cách làm bánh đúc nóng từ cơm nguội', 'Bánh mềm mượt, sánh dẻo quyện với thịt băm và mộc nhĩ giòn sần sật, đậu xanh bùi bùi... làm nên bữa sáng ngon tiết kiệm thời kỳ giãn cách.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/09/04/nh3-1630735650-6707-1630735743.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=ayED0knLRehOHXTGFA0hBA', 20, 20, 'MEDIUM', 'Cùng thử nấu Cách làm bánh đúc nóng từ cơm nguội');
INSERT INTO public.post VALUES (768, '2025-11-20 17:12:38.160259', '2025-11-20 17:12:38.160259', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 5, 770, 'Cách làm bim bim khoai tây giòn rụm tại nhà', 'Với nguyên liệu và cách làm đơn giản, bạn có thể làm món ăn vặt rất ngon cho các con thời gian nghỉ giãn cách tại nhà.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/07/30/nh2-1627635959-1183-1627636175.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=CYnkWjsIoK_GajfmwjroIA', 22, 23, 'EASY', 'Cùng thử nấu Cách làm bim bim khoai tây giòn rụm tại nhà');
INSERT INTO public.post VALUES (775, '2025-11-20 17:12:40.758036', '2025-11-20 17:12:40.758036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 10, 777, 'Cách nấu xôi lạc dẻo bùi từ nồi cơm điện', 'Từng hạt xôi căng bóng, mềm dẻo quyện với lạc mềm, bùi bùi tạo nên món ăn sáng thơm ngon, nhanh chóng trong thời kỳ giãn cách.', 'Hà Nội', 'https://i1-giadinh.vnecdn.net/2021/08/12/xoilac-1628753569-7242-1628753652.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_JGJiWp4uveUki2O1sdK8g', 22, 23, 'EASY', 'Cùng thử nấu Cách nấu xôi lạc dẻo bùi từ nồi cơm điện');
INSERT INTO public.post VALUES (779, '2025-11-20 17:12:41.515754', '2025-11-20 17:12:41.515754', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 781, 'Làm trứng cuộn kiểu Hàn Quốc', 'Chỉ 5 phút thôi bạn đã có món trứng rán thơm phức, cách làm khác này tạo cho cả nhà cảm giác mới khi ăn, lạ và ngon miệng hơn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2009/09/21/tr-1351752125.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=s0zFIW5nhOR4DkWE4CwUOw', 0, 0, 'EASY', 'Cùng thử nấu Làm trứng cuộn kiểu Hàn Quốc');
INSERT INTO public.post VALUES (783, '2025-11-20 17:12:42.844342', '2025-11-20 17:12:42.844342', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 16, 785, 'Bánh chuối', 'Với những nguyên liệu quen thuộc, dễ tìm trong mùa hè này, các bạn hãy cùng VnExpress trổ tài làm món bánh chuối nhé.', 'Bến Tre', 'https://i1-giadinh.vnecdn.net/2021/09/30/1banhchuoi-1632938282-2037-1632938310.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=Yuxh37hOlKDgsnNWPvfHxw', 0, 0, 'MEDIUM', 'Cùng thử nấu Bánh chuối');
INSERT INTO public.post VALUES (790, '2025-11-20 17:12:47.529576', '2025-11-20 17:12:47.529576', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 1, 792, 'Xôi bắp', 'Trong hơi thu se lạnh, được bắt đầu ngày mới với món xôi bắp thì còn gì bằng. Những hạt bắp dẻo khi hòa trộn với nếp, cùng hương vị thơm bùi của đậu xanh, béo béo của đậu phộng và mè… sẽ khiến bạn khó quên.', 'Sóc Trăng', 'https://i1-giadinh.vnecdn.net/2021/10/14/1991200x676-1634184996-6597-1634185228.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=sg2XJMv9FIvg0iS_PllKwA', 0, 0, 'MEDIUM', 'Cùng thử nấu Xôi bắp');
INSERT INTO public.post VALUES (794, '2025-11-20 17:12:49.961795', '2025-11-20 17:12:49.961795', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 796, 'Cháo sườn sụn giòn sần sật', 'Cháo sườn thơm lừng, ngọt nước, sườn sụn giòn sần sật, quẩy giòn tan. Món cháo dễ ăn, dễ nấu, thích hợp dùng làm bữa sáng cho cả gia đình.', 'Hà Nội', 'https://i1-ngoisao.vnecdn.net/2021/07/08/205053050-517248382660392-5023-7356-1317-1625736608.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=_gNKa4lYnETejs4e7pgUlA', 0, 0, 'MEDIUM', 'Cùng thử nấu Cháo sườn sụn giòn sần sật');
INSERT INTO public.post VALUES (772, '2025-11-20 17:12:39.562634', '2025-11-20 17:12:39.562634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 6, 774, 'Một số món ăn sáng ngon', 'Nhịp sống vội vã đôi khi làm bạn quên bữa ăn quan trọng nhất trong ngày. Dưới đây là một số món ăn sáng chế biến nhanh, đơn giản, lại đảm bảo dinh dưỡng mà bạn có thể tham khảo.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2021/11/22/comchientom-1637552361-3954-1637552409.png?w=0&h=0&q=100&dpr=2&fit=crop&s=jyfiU2C0-qyWQIS4oNlkUQ', 0, 0, 'MEDIUM', 'Cùng thử nấu Một số món ăn sáng ngon');
INSERT INTO public.post VALUES (782, '2025-11-20 17:12:42.597868', '2025-11-20 17:12:42.597868', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 18, 784, 'Cách làm cà tím kho tiêu thấm vị mặn ngọt hài hòa', 'Cà mềm dẻo, thấm vị mặn ngọt hài hòa, nước sốt sóng sánh màu hổ phách, ăn cùng cơm trắng rất hấp dẫn.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/08/11/Thnhphm22-1660205516-8056-1660205598.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=paIAoiW5XkFE7wwYSvZCvg', 10, 10, 'MEDIUM', 'Cùng thử nấu Cách làm cà tím kho tiêu thấm vị mặn ngọt hài hòa');
INSERT INTO public.post VALUES (787, '2025-11-20 17:12:45.304618', '2025-11-20 17:12:45.304618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 20, 789, 'Cách làm chả giò chay vàng thơm, giòn rụm', 'Chả giò vỏ vàng ươm, để lâu vẫn giòn rụm, nhân bên trong mềm ngọt, chấm nước mắm chay rất ngon.', 'Hồ Chí Minh', 'https://i1-giadinh.vnecdn.net/2022/08/10/Thnhphm11-1660102931-5859-1660102960.jpg?w=0&h=0&q=100&dpr=2&fit=crop&s=5p0SVa7VZSvAvg2yU9O0Iw', 30, 30, 'MEDIUM', 'Cùng thử nấu Cách làm chả giò chay vàng thơm, giòn rụm');
