INSERT INTO public.post_recipe_ingredient_keywords VALUES (707, 'Chỉ lấy cánh hoa (ngắt bỏ lá, cuống, nhụy vì phần này nhiều nước và đắng. Nếu ướp trà sẽ dễ bị thiu và làm siro đắng hơn)');
